function buildPersistableTickerRecordsMap(recordsMap = {}, options = {}){
  const includeLiteFields = options.includeLiteFields !== false;
  return Object.fromEntries(
    Object.entries(normalizeTickerRecordsMap(recordsMap || {})).map(([ticker, record]) => {
      const item = normalizeTickerRecord(record);
      const persistedRecord = {
        ticker:item.ticker,
        marketData:{
          price:item.marketData.price,
          asOf:item.marketData.asOf,
          source:item.marketData.source,
          ma20:item.marketData.ma20,
          ma50:item.marketData.ma50,
          ma200:item.marketData.ma200,
          rsi:item.marketData.rsi,
          avgVolume:item.marketData.avgVolume,
          volume:item.marketData.volume,
          perf1w:item.marketData.perf1w,
          perf1m:item.marketData.perf1m,
          perf3m:item.marketData.perf3m,
          perf6m:item.marketData.perf6m,
          perfYtd:item.marketData.perfYtd,
          currency:item.marketData.currency,
          history:Array.isArray(item.marketData.history) ? cloneData(item.marketData.history, []) : [],
          previousClose:item.marketData.previousClose
        },
        scan:{
          scanType:item.scan.scanType,
          scanSetupType:item.scan.scanSetupType,
          setupOrigin:item.scan.setupOrigin,
          score:item.scan.score,
          resolvedVerdict:item.scan.resolvedVerdict,
          verdict:item.scan.verdict,
          reasons:Array.isArray(item.scan.reasons) ? [...item.scan.reasons] : [],
          flags:item.scan.flags && typeof item.scan.flags === 'object' ? cloneData(item.scan.flags, {}) : {},
          summary:item.scan.summary,
          riskStatus:item.scan.riskStatus,
          trendStatus:item.scan.trendStatus,
          pullbackStatus:item.scan.pullbackStatus,
          pullbackType:item.scan.pullbackType,
          analysisProjection:item.scan.analysisProjection && typeof item.scan.analysisProjection === 'object'
            ? cloneData(item.scan.analysisProjection, null)
            : null,
          lastScannedAt:item.scan.lastScannedAt,
          updatedAt:item.scan.updatedAt
        },
        review:{
          notes:item.review.notes,
          savedVerdict:item.review.savedVerdict,
          savedSummary:item.review.savedSummary,
          savedScore:item.review.savedScore,
          savedProjectionSnapshot:item.review.savedProjectionSnapshot && typeof item.review.savedProjectionSnapshot === 'object'
            ? cloneData(item.review.savedProjectionSnapshot, null)
            : null,
          lastReviewedAt:item.review.lastReviewedAt,
          draft:item.review.draft && typeof item.review.draft === 'object' ? cloneData(item.review.draft, null) : null,
          manualReview:item.review.manualReview && typeof item.review.manualReview === 'object' ? cloneData(item.review.manualReview, null) : null,
          cardOpen:!!item.review.cardOpen,
          source:item.review.source,
          analysisState:item.review.analysisState && typeof item.review.analysisState === 'object'
            ? cloneData({
              normalized:item.review.analysisState.normalized || null,
              reviewedAt:item.review.analysisState.reviewedAt || ''
            }, null)
            : null,
          chartAnalysisPipeline:cloneData(item.review.chartAnalysisPipeline, null)
        },
        plan:{
          hasValidPlan:item.plan.hasValidPlan,
          entry:item.plan.entry,
          stop:item.plan.stop,
          firstTarget:item.plan.firstTarget,
          exitMode:item.plan.exitMode,
          targetReviewState:item.plan.targetReviewState,
          targetActionRecommendation:item.plan.targetActionRecommendation,
          targetAlert:item.plan.targetAlert && typeof item.plan.targetAlert === 'object' ? cloneData(item.plan.targetAlert, {}) : {},
          riskPerShare:item.plan.riskPerShare,
          rewardPerShare:item.plan.rewardPerShare,
          plannedRR:item.plan.plannedRR,
          positionSize:item.plan.positionSize,
          positionCost:item.plan.positionCost,
          positionCostGbp:item.plan.positionCostGbp,
          quoteCurrency:item.plan.quoteCurrency,
          maxLoss:item.plan.maxLoss,
          riskStatus:item.plan.riskStatus,
          capitalFit:item.plan.capitalFit,
          tradeability:item.plan.tradeability,
          capitalNote:item.plan.capitalNote,
          affordability:item.plan.affordability,
          status:item.plan.status,
          triggerState:item.plan.triggerState,
          planValidationState:item.plan.planValidationState,
          needsReplan:item.plan.needsReplan,
          missedState:item.plan.missedState,
          invalidatedState:item.plan.invalidatedState,
          firstTargetTooClose:item.plan.firstTargetTooClose,
          lastPlannedAt:item.plan.lastPlannedAt,
          source:item.plan.source,
          target:item.plan.target,
          authoritySource:item.plan.authoritySource,
          authorityVersion:item.plan.authorityVersion,
          authorityReason:item.plan.authorityReason,
          writtenBy:item.plan.writtenBy,
          writtenAt:item.plan.writtenAt,
          candidateSource:item.plan.candidateSource,
          submittedPaperTradeAt:item.plan.submittedPaperTradeAt
        },
        setup:{
          rawScore:item.setup.rawScore,
          score:item.setup.score,
          structureState:item.setup.structureState,
          structureEligibility:item.setup.structureEligibility,
          setupLocationState:item.setup.setupLocationState,
          pullbackZone:item.setup.pullbackZone,
          priceabilityState:item.setup.priceabilityState,
          stabilisationState:item.setup.stabilisationState,
          bounceState:item.setup.bounceState,
          volumeState:item.setup.volumeState,
          trendState:item.setup.trendState,
          convictionTier:item.setup.convictionTier,
          practicalSizeFlag:item.setup.practicalSizeFlag,
          verdict:item.setup.verdict,
          reasons:Array.isArray(item.setup.reasons) ? [...item.setup.reasons] : [],
          marketCaution:item.setup.marketCaution
        },
        watchlist:persistableWatchlistState(item.watchlist),
        lifecycle:item.lifecycle && typeof item.lifecycle === 'object' ? cloneData(item.lifecycle, {}) : {},
        diary:item.diary && typeof item.diary === 'object' ? cloneData({records:item.diary.records || []}, {}) : {},
        meta:persistableMetaState(item.meta),
        authority:(() => {
          const authority = item.authority && typeof item.authority === 'object' ? item.authority : {};
          const publication = authority.canonicalPublication && typeof authority.canonicalPublication === 'object'
            ? cloneData(authority.canonicalPublication, null)
            : null;
          const projection = authority.canonicalResolverProjection && typeof authority.canonicalResolverProjection === 'object'
            ? cloneData(authority.canonicalResolverProjection, null)
            : null;
          const recordIdentity = `${String(item.ticker || '').trim().toUpperCase()}:${String(item.meta && item.meta.createdAt || '')}`;
          return {
            version:Number.isFinite(Number(authority.version)) ? Number(authority.version) : 0,
            source:String(authority.source || ''),
            updatedAt:String(authority.updatedAt || ''),
            reason:String(authority.reason || ''),
            canonicalPublication:publication,
            canonicalResolverProjection:projection,
            canonicalPublicationPersistence:{
              schemaVersion:'canonical-publication-envelope-v1',
              publicationPersisted:!!publication,
              persistedPublicationId:String(publication && publication.publicationId || ''),
              persistedEvidenceId:String(publication && publication.evidenceId || ''),
              persistedCycleId:String(publication && publication.refreshCycleId || ''),
              recordIdentity
            }
          };
        })()
      };
      if(includeLiteFields !== true){
        delete persistedRecord.review.analysisState;
      }
      return [ticker, persistedRecord];
    })
  );
}

function buildRecordsLitePersistedState(sourceState, meta = {}){
  const baseState = sourceState && typeof sourceState === 'object' ? sourceState : {};
  const liteTickerRecords = buildPersistableTickerRecordsMap(baseState.tickerRecords || {});
  return withPersistMeta({
    tickerRecords:liteTickerRecords,
    watchlist:Array.isArray(baseState.watchlist) ? cloneData(baseState.watchlist, []) : [],
    tradeDiary:Array.isArray(baseState.tradeDiary) ? cloneData(baseState.tradeDiary, []) : [],
    symbolMeta:baseState.symbolMeta && typeof baseState.symbolMeta === 'object' ? cloneData(baseState.symbolMeta, {}) : {},
    paperTradeTesterSetupCompletedAt:baseState.paperTradeTesterSetupCompletedAt
  }, {
    ...meta,
    persistedFormat:'records_lite'
  });
}

