function tradeGatewayHealthModel(){
  if(trading212PaperSupported !== true){
    return {
      state:'unavailable',
      label:'Paper gateway unavailable',
      detail:'Trading 212 paper routing is not available in this build.',
      className:'warntext'
    };
  }
  if(trading212PaperAvailabilityChecked !== true){
    return {
      state:'checking',
      label:'Paper gateway checking',
      detail:'Review will enable paper-trade actions after the connection check finishes.',
      className:'tiny'
    };
  }
  if(trading212PaperEnabled === true){
    return {
      state:'ready',
      label:'Paper gateway ready',
      detail:String(trading212PaperAvailabilityMessage || 'Trading 212 paper trading is configured.'),
      className:'ok'
    };
  }
  return {
    state:'offline',
    label:'Paper gateway unavailable',
    detail:String(trading212PaperAvailabilityMessage || 'Paper trading gateway is unavailable.'),
    className:'warntext'
  };
}

function storedPaperTradeApiKey(){
  return String(state.paperTradeApiKey || '').trim();
}

function storedPaperTradeApiSecret(){
  return String(state.paperTradeApiSecret || '').trim();
}

function storedPaperTradeCredentialsReady(){
  return !!(storedPaperTradeApiKey() && storedPaperTradeApiSecret());
}

function paperTradeGatewayReady(){
  return trading212PaperSupported === true
    && trading212PaperAvailabilityChecked === true
    && trading212PaperEnabled === true;
}

function paperTradeCredentialsSourceReady(){
  return storedPaperTradeCredentialsReady() || paperTradeGatewayReady();
}

function paperTradeTesterSetupComplete(){
  const completedAt = String(state.paperTradeTesterSetupCompletedAt || '').trim();
  if(!completedAt) return false;
  if(trading212PaperSupported !== true) return false;
  return true;
}

function testerSetupHealthModel(){
  const completedAt = String(state.paperTradeTesterSetupCompletedAt || '').trim();
  const hasStoredKey = storedPaperTradeCredentialsReady();
  const gatewayReady = typeof paperTradeGatewayReady === 'function'
    ? paperTradeGatewayReady()
    : (trading212PaperEnabled === true && trading212PaperAvailabilityChecked === true);
  const credentialsSourceReady = typeof paperTradeCredentialsSourceReady === 'function'
    ? paperTradeCredentialsSourceReady()
    : hasStoredKey;
  const gatewayReadyOrPending = trading212PaperAvailabilityChecked !== true || trading212PaperEnabled === true;
  if(completedAt && trading212PaperSupported === true && trading212PaperAvailabilityChecked !== true){
    return {
      complete:true,
      label:'Tester setup completed',
      detail:`Completed ${formatLocalTimestamp(completedAt) || completedAt}. Waiting for Trading 212 demo gateway readiness check to finish.`,
      className:'ok'
    };
  }
  if(completedAt && credentialsSourceReady && gatewayReadyOrPending){
    return {
      complete:true,
      label:'Tester setup completed',
      detail:`Completed ${formatLocalTimestamp(completedAt) || completedAt}. Trading stays paper-only and still depends on Trading 212 demo gateway readiness.`,
      className:'ok'
    };
  }
  if(completedAt && !hasStoredKey){
    return {
      complete:false,
      label:'Tester setup requires local paper credentials',
      detail:'Local paper credentials were removed on this device. Re-enter them before tester setup can be treated as completed again.',
      className:'warntext'
    };
  }
  if(trading212PaperSupported !== true){
    return {
      complete:false,
      label:'Tester setup blocked',
      detail:'Paper routing is unavailable in this build, so tester setup cannot complete.',
      className:'warntext'
    };
  }
  if(!hasStoredKey && trading212PaperAvailabilityChecked !== true){
    return {
      complete:false,
      label:'Tester setup waiting on gateway check',
      detail:'The app can use either local Trading 212 API credentials for this tester or backend gateway credentials. Complete setup after the demo gateway finishes checking.',
      className:'tiny'
    };
  }
  if(hasStoredKey && trading212PaperAvailabilityChecked !== true){
    return {
      complete:false,
      label:'Tester setup waiting on gateway check',
      detail:'Read the guidance now. Complete setup after the Trading 212 demo gateway finishes checking.',
      className:'tiny'
    };
  }
  if(gatewayReady !== true){
    return {
      complete:false,
      label:'Tester setup waiting on paper gateway',
      detail:String(trading212PaperAvailabilityMessage || 'Paper gateway is unavailable.'),
      className:'warntext'
    };
  }
  return {
    complete:false,
    label:'Tester setup ready to confirm',
    detail:hasStoredKey
      ? 'Trading 212 demo gateway is ready. Complete tester setup to unlock paper-trade actions in Review.'
      : 'Trading 212 demo gateway is ready through backend configuration. Complete tester setup to unlock paper-trade actions in Review.',
    className:'tiny'
  };
}

