function currentReviewChartVerificationSnapshot(record){
  const item = record || currentReviewDiagnosticRecord();
  if(!item) return null;
  try{
    const pipeline = getReviewChartAnalysisPipeline(item) || {};
    const decision = buildSimplifiedChartPipelineDecision(item, pipeline) || {};
    const trace = buildSimplifiedChartPipelineTrace(item, pipeline) || {};
    return {
      phase:String(pipeline.phase || ''),
      status:String(trace.status || ''),
      decisionKey:String(decision.key || ''),
      title:String(decision.title || ''),
      summary:String(decision.summary || ''),
      detail:String(decision.detail || ''),
      aiAnalysisSuppressed:trace.aiAnalysisSuppressed === true,
      suppressionReason:String(trace.suppressionReason || ''),
      expectedTicker:String(trace.trustedFacts && trace.trustedFacts.ticker || ''),
      detectedTicker:String(trace.extractedFacts && trace.extractedFacts.visible_ticker || ''),
      requestId:String(trace.requestId || ''),
      imageId:String(trace.imageId || ''),
      manualConfirmed:trace.manualConfirmed === true,
      diagnostics:Array.isArray(trace.diagnostics) ? trace.diagnostics.slice(0, 12) : [],
      evidence:Array.isArray(trace.evidence) ? trace.evidence.slice(0, 12) : [],
      missing:Array.isArray(trace.missing) ? trace.missing.slice(0, 12) : []
    };
  }catch(error){
    return {
      snapshotError:String(error && error.message || 'chart_verification_snapshot_failed')
    };
  }
}

function hasPresentationAuthoritySnapshot(snapshot, ticker = ''){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(!safeSnapshot) return false;
  const expectedTicker = normalizeTicker(ticker || '');
  if(expectedTicker && normalizeTicker(safeSnapshot.ticker || '') !== expectedTicker) return false;
  const authority = projectionSnapshotAuthority(safeSnapshot);
  return authority.version > 0 && !!String(authority.source || '').trim();
}

function normalizeTickerJourneyAuthority(authority, fallback = {}){
  const safeAuthority = authority && typeof authority === 'object' ? authority : {};
  const safeFallback = fallback && typeof fallback === 'object' ? fallback : {};
  const versionCandidate = safeAuthority.version ?? safeFallback.version ?? 0;
  return {
    version:Number.isFinite(Number(versionCandidate)) ? Math.max(0, Math.round(Number(versionCandidate))) : 0,
    source:String(safeAuthority.source || safeFallback.source || '').trim().toLowerCase(),
    updatedAt:String(safeAuthority.updatedAt || safeFallback.updatedAt || ''),
    reason:String(safeAuthority.reason || safeFallback.reason || '')
  };
}

function currentTickerJourneyAuthority(record){
  const item = record && typeof record === 'object' ? record : {};
  return normalizeTickerJourneyAuthority(item.authority, {
    version:0,
    source:'',
    updatedAt:String(item.scan && (item.scan.updatedAt || item.scan.lastScannedAt) || ''),
    reason:''
  });
}

function shouldPreserveScanAuthorityCanonicalPath(record){
  const item = record && typeof record === 'object' ? record : {};
  const authority = currentTickerJourneyAuthority(item);
  if(authority.source !== 'scan' || authority.version <= 0) return false;
  const review = item.review && typeof item.review === 'object' ? item.review : {};
  const hasReviewAuthority = !!(
    (review.manualReview && typeof review.manualReview === 'object')
    || String(review.savedVerdict || '').trim()
  );
  if(hasReviewAuthority) return false;
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const planSource = String(plan.source || '').trim().toLowerCase();
  const planIntroducesNewAuthority = !!(
    String(plan.authorityVersion || '').trim()
    && String(plan.authoritySource || '').trim()
    && planSource
    && planSource !== 'scanner_estimate'
  );
  return !planIntroducesNewAuthority;
}

function selectedAuthorityContractForGlobalVerdict(record, deps = {}){
  const item = record && typeof record === 'object' ? record : {};
  const isTracked = !!(
    item.in_watchlist
    || item.watchlist_entry_exists
    || (item.watchlist && item.watchlist.inWatchlist)
  );
  const preserveScanAuthorityCanonicalPath = deps.preserveScanAuthorityCanonicalPath === true;
  if(isTracked && !preserveScanAuthorityCanonicalPath){
    return deps.resolveFinalStateContract(item, {context:'global'});
  }
  return deps.resolvePreLifecycleStateContract(item);
}

function selectedAuthorityContractSource(record, deps = {}){
  const item = record && typeof record === 'object' ? record : {};
  const isTracked = !!(
    item.in_watchlist
    || item.watchlist_entry_exists
    || (item.watchlist && item.watchlist.inWatchlist)
  );
  const preserveScanAuthorityCanonicalPath = deps.preserveScanAuthorityCanonicalPath === true;
  if(isTracked && preserveScanAuthorityCanonicalPath){
    return 'scan_authority_preserved';
  }
  if(isTracked){
    return 'final_state_contract';
  }
  if(deps.preserveReviewCanonicalForSoftReadiness === true){
    return 'review_soft_readiness_override';
  }
  return 'pre_lifecycle_contract';
}

function canonicalVerdictAuthoritySource(record, deps = {}){
  if(deps.preserveScanAuthorityCanonicalPath === true){
    return 'scan_authority_preserved';
  }
  if(deps.canonicalSoftReadinessAlignmentApplied === true){
    if(deps.preserveReviewCanonicalForSoftReadiness === true){
      return 'review_soft_readiness_override';
    }
    return 'non_tracked_soft_readiness';
  }
  return selectedAuthorityContractSource(record, deps);
}

function authorityStampSourceCanReplaceTrackedAuthority(source){
  const normalizedSource = String(source || '').trim().toLowerCase();
  return ['watchlist_refresh', 'review_save', 'manual'].includes(normalizedSource);
}

function shouldAdvanceTickerJourneyAuthority(record, source, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  const normalizedSource = String(source || '').trim().toLowerCase();
  if(!item || !normalizedSource) return false;
  if(options.forceAuthorityAdvance === true) return true;
  const inWatchlist = !!(item.watchlist && item.watchlist.inWatchlist === true);
  if(!inWatchlist) return true;
  if(options.allowTrackedAuthorityOverride === true) return true;
  if(normalizedSource === 'scan') return false;
  return true;
}

function stampTickerJourneyAuthority(record, source, options = {}){
  if(!record || typeof record !== 'object') return normalizeTickerJourneyAuthority(null);
  const normalizedSource = String(source || '').trim().toLowerCase();
  if(!normalizedSource) return currentTickerJourneyAuthority(record);
  if(!shouldAdvanceTickerJourneyAuthority(record, normalizedSource, options)){
    return currentTickerJourneyAuthority(record);
  }
  const current = currentTickerJourneyAuthority(record);
  const next = normalizeTickerJourneyAuthority({
    version:current.version + 1,
    source:normalizedSource,
    updatedAt:String(options.updatedAt || new Date().toISOString()),
    reason:String(options.reason || '')
  });
  record.authority = next;
  return next;
}

function isTrackProjectionAuthoritySource(source){
  const normalizedSource = String(source || '').trim().toLowerCase();
  return authorityStampSourceCanReplaceTrackedAuthority(normalizedSource) || normalizedSource === 'scan';
}

function projectionSnapshotAuthority(snapshot){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : {};
  return normalizeTickerJourneyAuthority(
    safeSnapshot.authority || safeSnapshot.projectionAuthority || null
  );
}

function snapshotMatchesCurrentTrackAuthority(snapshot, record){
  const snapshotAuthority = projectionSnapshotAuthority(snapshot);
  const currentAuthority = currentTickerJourneyAuthority(record);
  if(!isTrackProjectionAuthoritySource(snapshotAuthority.source)) return false;
  if(snapshotAuthority.version <= 0) return false;
  return snapshotAuthority.version === currentAuthority.version
    && snapshotAuthority.source === currentAuthority.source;
}

function projectionSnapshotWithAuthority(snapshot, record, overrides = {}){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(!safeSnapshot) return null;
  return {
    ...safeSnapshot,
    authority:normalizeTickerJourneyAuthority(
      overrides.authority,
      currentTickerJourneyAuthority(record)
    )
  };
}

function projectionSnapshotContractFingerprint(snapshot){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : {};
  return String(
    safeSnapshot.contractFingerprint
    || safeSnapshot.snapshotContractFingerprint
    || safeSnapshot.canonicalContractFingerprint
    || ''
  ).trim();
}

function persistedProjectionCanPreserveEntryDisplay(record){
  const item = normalizeTickerRecordReadOnly(record || {});
  if(normalizeGlobalVerdictKey(item.review && item.review.savedVerdict || '') !== 'entry') return false;
  const storedSnapshot = reviewStoredProjectionSnapshot(item);
  if(!storedSnapshot) return false;
  const validity = evaluatePersistedReviewProjectionValidity(item, storedSnapshot, 'persisted_projection_entry_display');
  return validity && validity.valid === true;
}

function reviewProjectionCanDriveEntryDisplay(snapshot, projectionSource, record){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(!safeSnapshot) return false;
  const source = normalizeReviewProjectionSource(projectionSource, safeSnapshot);
  const allowPersistedDisplayEntry = source === 'persisted_display_context'
    && persistedProjectionCanPreserveEntryDisplay(record);
  if(!allowPersistedDisplayEntry && !['clicked_card_snapshot', 'track_projection_updated'].includes(source)) return false;
  const item = normalizeTickerRecordReadOnly(record || {});
  const snapshotTicker = normalizeTicker(safeSnapshot.ticker || '');
  const recordTicker = normalizeTicker(item && item.ticker || '');
  if(snapshotTicker && recordTicker && snapshotTicker !== recordTicker) return false;
  if(!allowPersistedDisplayEntry && !hasPresentationAuthoritySnapshot(safeSnapshot, recordTicker || snapshotTicker)) return false;
  const verdict = normalizeGlobalVerdictKey(
    safeSnapshot.canonicalVerdict
    || safeSnapshot.finalVerdict
    || safeSnapshot.renderedVerdict
    || ''
  );
  if(verdict !== 'entry') return false;
  if(allowPersistedDisplayEntry) return true;
  const canonicalBundle = withReviewProjectionSuppressed(() => buildCanonicalRenderModelsFromRecord(item, {
    surface:'review',
    source:'projection_authority_validation',
    reason:'projection_authority_validation'
  })) || {};
  const baselineContractVerdict = normalizeGlobalVerdictKey(
    canonicalBundle.contract && canonicalBundle.contract.canonicalVerdict || ''
  );
  const baselineReviewVerdict = normalizeGlobalVerdictKey(
    canonicalBundle.reviewRenderModel && canonicalBundle.reviewRenderModel.canonicalVerdict || ''
  );
  const baselineTrackState = withReviewProjectionSuppressed(() => resolveSimplifiedStateForSurface(item, 'track', {
    log:false,
    source:'projection_authority_validation',
    mutationSource:'projection_authority_validation'
  })) || {};
  const baselineTrackVerdict = normalizeGlobalVerdictKey(baselineTrackState.canonicalVerdict || '');
  const baselineContractFingerprint = String(
    canonicalBundle.contract && canonicalBundle.contract.contractFingerprint || ''
  ).trim();
  const snapshotContractFingerprint = projectionSnapshotContractFingerprint(safeSnapshot);
  if(baselineContractVerdict !== 'entry') return false;
  if(baselineReviewVerdict && baselineReviewVerdict !== 'entry') return false;
  if(baselineTrackVerdict && baselineTrackVerdict !== 'entry') return false;
  if(!snapshotContractFingerprint || !baselineContractFingerprint) return false;
  if(snapshotContractFingerprint !== baselineContractFingerprint) return false;
  return true;
}

function liveReviewDisplayProjectionSnapshot(snapshot, projectionSource, record){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(!safeSnapshot) return null;
  return reviewProjectionCanDriveEntryDisplay(safeSnapshot, projectionSource, record)
    ? safeSnapshot
    : null;
}

function normalizePresentationVerdictBucket(presentation){
  const safePresentation = presentation && typeof presentation === 'object' ? presentation : null;
  if(!safePresentation) return safePresentation;
  const canonicalVerdict = normalizeOptionalGlobalVerdictKey(
    safePresentation.canonicalVerdict
    || safePresentation.finalVerdict
    || ''
  );
  const visualBucket = normalizeVisualBucketForPairing(
    safePresentation.visualBucket
    || safePresentation.sourceOfTruthVisualBucket
    || safePresentation.renderedBucket
    || ''
  );
  if(!canonicalVerdict) return safePresentation;
  if(canonicalVerdict === 'entry' && visualBucket !== 'entry'){
    return {
      ...safePresentation,
      visualBucket:'entry',
      sourceOfTruthVisualBucket:'entry',
      renderedBucket:'entry',
      tone:'entry'
    };
  }
  if(canonicalVerdict === 'near_entry' && visualBucket === 'monitor'){
    return {
      ...safePresentation,
      visualBucket:'near_entry',
      sourceOfTruthVisualBucket:'near_entry',
      renderedBucket:'near_entry',
      tone:'near_entry'
    };
  }
  return safePresentation;
}

function sharedProjectionCanPromoteEntry(snapshot, projectionSource, record, options = {}){
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(!safeSnapshot) return false;
  if(options.allowTrackProjection !== true) return false;
  const source = normalizeReviewProjectionSource(projectionSource, safeSnapshot);
  if(normalizeGlobalVerdictKey(
    safeSnapshot.canonicalVerdict
    || safeSnapshot.finalVerdict
    || safeSnapshot.renderedVerdict
    || ''
  ) !== 'entry') return false;
  if(source === 'track_projection_updated') return true;
  if(source === 'persisted_display_context') return persistedProjectionCanPreserveEntryDisplay(record);
  if(source !== 'clicked_card_snapshot') return false;
  const item = record && typeof record === 'object' ? record : {};
  const scanCanonicalVerdict = normalizeGlobalVerdictKey(
    item.scan && (
      item.scan.resolvedVerdict
      || item.scan.verdict
    )
    || ''
  );
  return scanCanonicalVerdict === 'entry'
    && reviewProjectionCanDriveEntryDisplay(safeSnapshot, source, item);
}

function currentReviewStateHealthSnapshot(record){
  const sourceRecord = record || currentReviewDiagnosticRecord();
  if(!sourceRecord) return null;
  const item = normalizeTickerRecordReadOnly(sourceRecord);
  const activeProjectionSnapshot = uiState.activeReviewSourceProjectionSnapshot
    && typeof uiState.activeReviewSourceProjectionSnapshot === 'object'
    && normalizeTicker(uiState.activeReviewSourceProjectionSnapshot.ticker || '') === normalizeTicker(item.ticker || '')
      ? uiState.activeReviewSourceProjectionSnapshot
      : null;
  let reviewProjectionSource = normalizeReviewProjectionSource(
    String(
      uiState.activeReviewProjectionSource
      || (activeProjectionSnapshot ? 'clicked_card_snapshot' : 'non_watchlist_direct_resolve')
    ).trim().toLowerCase(),
    activeProjectionSnapshot
  );
  let presentationProjectionSnapshot = reviewProjectionSource === 'scanner_score_snapshot'
    ? null
    : activeProjectionSnapshot;
  if(!hasPresentationAuthoritySnapshot(presentationProjectionSnapshot, item.ticker || '') && item.review && item.review.cardOpen){
    const persistedProjectionSnapshot = persistedReviewProjectionSnapshot(item, 'startup_review_projection');
    if(persistedProjectionSnapshot){
      presentationProjectionSnapshot = persistedProjectionSnapshot;
      reviewProjectionSource = restoredProjectionAuthoritySource(persistedProjectionSnapshot) || 'persisted_display_context';
    }
  }
  const hasProjectionSnapshot = hasPresentationAuthoritySnapshot(presentationProjectionSnapshot, item.ticker || '');
  const reviewSnapshotAuthority = hasProjectionSnapshot
    && isLiveReviewProjectionAuthoritySource(reviewProjectionSource)
    && reviewProjectionCanDriveEntryDisplay(presentationProjectionSnapshot, reviewProjectionSource, item);
  const sourceProjectionSnapshot = presentationProjectionSnapshot;
  const simplifiedState = withReviewProjectionSuppressed(() => resolveSimplifiedStateForSurface(item, 'review', {
    renderPass:0,
    source:'diagnostic_snapshot',
    mutationSource:'diagnostic_snapshot'
  })) || {};
  const globalVerdict = resolveGlobalVerdict(item);
  const lifecycleSnapshot = watchlistLifecycleSnapshot(item);
  const effectiveSimplifiedState = applyReviewWatchlistSoftReadinessDisplayOverride(item, simplifiedState, globalVerdict, lifecycleSnapshot);
  const authoritativeCanonicalVerdict = normalizeGlobalVerdictKey(effectiveSimplifiedState.canonicalVerdict || 'watch');
  let authoritativeVisualBucket = normalizeVisualBucketForPairing(effectiveSimplifiedState.visualBucket || 'monitor');
  if(authoritativeCanonicalVerdict === 'entry' && authoritativeVisualBucket !== 'entry'){
    authoritativeVisualBucket = 'entry';
  }else if(authoritativeCanonicalVerdict === 'near_entry' && authoritativeVisualBucket === 'monitor'){
    authoritativeVisualBucket = 'near_entry';
  }
  const simplifiedCanonicalVerdict = authoritativeCanonicalVerdict;
  let simplifiedVisualBucket = authoritativeVisualBucket;
  if(simplifiedCanonicalVerdict === 'entry' && simplifiedVisualBucket !== 'entry'){
    simplifiedVisualBucket = 'entry';
  }else if(simplifiedCanonicalVerdict === 'near_entry' && simplifiedVisualBucket === 'monitor'){
    simplifiedVisualBucket = 'near_entry';
  }
  const derivedTone = String(effectiveSimplifiedState.tone || simplifiedVisualBucket || 'monitor').trim().toLowerCase() || 'monitor';
  const authoritativeEntryPresentation = simplifiedCanonicalVerdict === 'entry';
  const authoritativeNearEntryPresentation = simplifiedCanonicalVerdict === 'near_entry';
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const effectivePlan = effectivePlanForRecord(item, {allowScannerFallback:true});
  let displayedPlan = applySetupConfirmationPlanGate(
    item,
    deriveCurrentPlanState(effectivePlan.entry, effectivePlan.stop, effectivePlan.firstTarget, item.marketData && item.marketData.currency),
    derivedStates
  );
  if(authoritativeEntryPresentation && displayedPlan.status !== 'valid'){
    const fallbackDisplayedPlan = reviewFallbackDisplayedPlan(item, derivedStates);
    if(fallbackDisplayedPlan && fallbackDisplayedPlan.status === 'valid'){
      displayedPlan = fallbackDisplayedPlan;
    }
  }
  const renderModels = buildCanonicalRenderModelsFromRecord(item, {
    surface:'review',
    source:'diagnostic_snapshot',
    reason:'diagnostic_snapshot',
    derivedStates,
    effectivePlan,
    displayedPlan,
    globalVerdict,
    lifecycleSnapshot,
    setupScore:setupScoreForRecord(item)
  }, item.review && item.review.draft ? item.review.draft : null);
  const canonicalContract = renderModels && renderModels.contract && typeof renderModels.contract === 'object'
    ? renderModels.contract
    : null;
  const explicitReviewAuthorityInput = !!(
    item.review && item.review.manualReview
    || normalizeOptionalGlobalVerdictKey(item.review && item.review.savedVerdict || '')
  );
  const contractCanonicalVerdict = normalizeOptionalGlobalVerdictKey(
    canonicalContract && canonicalContract.canonicalVerdict || ''
  );
  const contractVisualBucket = String(
    canonicalContract && canonicalContract.canonicalVisualBucket || ''
  ).trim().toLowerCase();
  const resolvedAuthorityCanonicalVerdict = normalizeGlobalVerdictKey(
    (explicitReviewAuthorityInput && contractCanonicalVerdict)
      || authoritativeCanonicalVerdict
      || 'watch'
  );
  const resolvedAuthorityVisualBucket = normalizeVisualBucketForPairing(
    (explicitReviewAuthorityInput && contractVisualBucket)
      || authoritativeVisualBucket
      || resolvedAuthorityCanonicalVerdict,
    resolvedAuthorityCanonicalVerdict
  );
  const authoritySimplifiedState = {
    ...effectiveSimplifiedState,
    canonicalVerdict:resolvedAuthorityCanonicalVerdict,
    visualBucket:resolvedAuthorityVisualBucket
  };
  const planCandidates = collectTradePlanAuthorityCandidates(item);
  const planAuthority = resolveCanonicalTradePlanAuthority({
    record:item,
    simplifiedState:authoritySimplifiedState,
    globalVerdict,
    displayedPlan,
    derivedStates,
    context:'review_diagnostic'
  });
  const planTrace = {
    authorityId:planAuthority.authorityId,
    source:planAuthority.source,
    verdict:planAuthority.verdict,
    reasonCode:planAuthority.reasonCode,
    fields:{
      tradeStatus:{
        finalDisplayedValue:planAuthority.actionable
          ? 'Entry Ready - plan is actionable.'
          : (planAuthority.reasonCode === 'capital_not_affordable'
            ? 'Setup valid but unaffordable.'
            : (isResolverBlockedEstimatedPlanAuthority(planAuthority)
              ? 'Estimated plan maths are valid, but setup is not actionable.'
              : 'No actionable trade yet.')),
        rawSourceValue:authoritativeCanonicalVerdict,
        sourcePath:'buildReviewSemanticStatus -> resolveCanonicalTradePlanAuthority',
        authorityRank:1,
        resolution:planAuthority.actionable ? 'accepted' : 'suppressed'
      },
      plannedEntry:{finalDisplayedValue:displayedPlan.entry ?? null, rawSourceValue:displayedPlan.entry ?? null, sourcePath:'displayedPlan.entry', authorityRank:1, resolution:Number.isFinite(numericOrNull(displayedPlan.entry)) ? 'accepted' : 'suppressed'},
      plannedStop:{finalDisplayedValue:displayedPlan.stop ?? null, rawSourceValue:displayedPlan.stop ?? null, sourcePath:'displayedPlan.stop', authorityRank:1, resolution:Number.isFinite(numericOrNull(displayedPlan.stop)) ? 'accepted' : 'suppressed'},
      plannedFirstTarget:{finalDisplayedValue:(displayedPlan.target ?? displayedPlan.firstTarget) ?? null, rawSourceValue:(displayedPlan.target ?? displayedPlan.firstTarget) ?? null, sourcePath:'displayedPlan.target', authorityRank:1, resolution:Number.isFinite(numericOrNull(displayedPlan.target ?? displayedPlan.firstTarget)) ? 'accepted' : 'suppressed'},
      riskPerShare:{finalDisplayedValue:displayedPlan.riskFit && displayedPlan.riskFit.risk_per_share, rawSourceValue:displayedPlan.riskFit && displayedPlan.riskFit.risk_per_share, sourcePath:'displayedPlan.riskFit.risk_per_share', authorityRank:1, resolution:'accepted'},
      maxLoss:{finalDisplayedValue:displayedPlan.riskFit && displayedPlan.riskFit.max_loss, rawSourceValue:displayedPlan.riskFit && displayedPlan.riskFit.max_loss, sourcePath:'displayedPlan.riskFit.max_loss', authorityRank:1, resolution:'accepted'},
      positionSize:{finalDisplayedValue:displayedPlan.riskFit && displayedPlan.riskFit.position_size, rawSourceValue:displayedPlan.riskFit && displayedPlan.riskFit.position_size, sourcePath:'displayedPlan.riskFit.position_size', authorityRank:1, resolution:planAuthority.actionable ? 'accepted' : 'suppressed'},
      positionCost:{finalDisplayedValue:displayedPlan.capitalFit && displayedPlan.capitalFit.position_cost, rawSourceValue:displayedPlan.capitalFit && displayedPlan.capitalFit.position_cost, sourcePath:'displayedPlan.capitalFit.position_cost', authorityRank:1, resolution:'accepted'},
      capitalFit:{finalDisplayedValue:displayedPlan.capitalFit && displayedPlan.capitalFit.capital_fit, rawSourceValue:displayedPlan.capitalFit && displayedPlan.capitalFit.capital_fit, sourcePath:'displayedPlan.capitalFit.capital_fit', authorityRank:1, resolution:planAuthority.capitalAffordable ? 'accepted' : 'suppressed'},
      capitalFitReason:{finalDisplayedValue:displayedPlan.capitalFit && displayedPlan.capitalFit.capital_note, rawSourceValue:displayedPlan.capitalFit && displayedPlan.capitalFit.capital_note, sourcePath:'displayedPlan.capitalFit.capital_note', authorityRank:1, resolution:'accepted'},
      rr:{finalDisplayedValue:displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio, rawSourceValue:displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio, sourcePath:'displayedPlan.rewardRisk.rrRatio', authorityRank:1, resolution:'accepted'},
      paperTradeEligibility:{finalDisplayedValue:planAuthority.actionable, rawSourceValue:planAuthority.actionable, sourcePath:'resolveCanonicalTradePlanAuthority.actionable', authorityRank:1, resolution:planAuthority.actionable ? 'accepted' : 'suppressed'},
      quoteCurrency:{finalDisplayedValue:planAuthority.quoteCurrency, rawSourceValue:planAuthority.quoteCurrency, sourcePath:'displayedPlan.capitalFit.quote_currency', authorityRank:1, resolution:'accepted'},
      gbpVsGbx:{finalDisplayedValue:planAuthority.gbpVsGbxMode, rawSourceValue:planAuthority.gbpVsGbxMode, sourcePath:'resolveCanonicalTradePlanAuthority.gbpVsGbxMode', authorityRank:1, resolution:'accepted'},
      planAuthorityStamp:{
        finalDisplayedValue:hasCanonicalTradePlanStamp(item.plan),
        rawSourceValue:{
          authoritySource:String(item.plan && item.plan.authoritySource || ''),
          authorityVersion:String(item.plan && item.plan.authorityVersion || ''),
          authorityReason:String(item.plan && item.plan.authorityReason || ''),
          writtenBy:String(item.plan && item.plan.writtenBy || ''),
          writtenAt:String(item.plan && item.plan.writtenAt || ''),
          candidateSource:String(item.plan && item.plan.candidateSource || '')
        },
        sourcePath:'record.plan authority stamp',
        authorityRank:1,
        resolution:hasCanonicalTradePlanStamp(item.plan) ? 'accepted' : 'suppressed'
      }
    }
  };
  const reviewRenderModel = renderModels && renderModels.reviewRenderModel && typeof renderModels.reviewRenderModel === 'object'
    ? renderModels.reviewRenderModel
    : null;
  const authoritativeVerdictLabel = globalVerdictLabel(simplifiedCanonicalVerdict || 'watch');
  const authoritativeNextAction = authoritativeEntryPresentation
    ? 'Execute only if the trigger remains valid.'
    : String(
      effectiveSimplifiedState.actionLabel
      || reviewRenderModel && reviewRenderModel.nextAction
      || ''
    ).trim();
  const authoritativeCanonicalContract = canonicalContract
    ? safeDiagnosticClone(canonicalContract, {})
    : canonicalContract;
  const authoritativeReviewRenderModel = reviewRenderModel;
  const authoritativeTrackRenderModel = renderModels && renderModels.trackRenderModel ? renderModels.trackRenderModel : null;
  const authoritativeTrackLongPressModel = renderModels && renderModels.trackLongPressModel ? renderModels.trackLongPressModel : null;
  const persistedReviewProjection = persistedReviewProjectionSnapshot(item, 'review_diagnostic');
  const displayCacheDivergence = canonicalDisplayDivergenceSummary(
    authoritativeCanonicalContract,
    persistedReviewProjection,
    authoritativeReviewRenderModel
  );
  const persistenceInputDivergence = canonicalPersistenceInputDivergence(item, authoritativeCanonicalContract);
  const canonicalHealthVerdict = normalizeGlobalVerdictKey(
    authoritativeCanonicalContract && authoritativeCanonicalContract.canonicalVerdict
    || authoritativeCanonicalVerdict
    || 'watch'
  );
  const canonicalHealthVisualBucket = normalizeVisualBucketForPairing(
    authoritativeCanonicalContract && authoritativeCanonicalContract.canonicalVisualBucket
    || authoritativeVisualBucket
    || canonicalHealthVerdict,
    canonicalHealthVerdict
  );
  const canonicalHealthTone = String(
    authoritativeReviewRenderModel && authoritativeReviewRenderModel.tone
    || canonicalHealthVisualBucket
    || derivedTone
    || 'monitor'
  ).trim().toLowerCase() || 'monitor';
  const canonicalHealthPlanStatus = String(
    authoritativeCanonicalContract && authoritativeCanonicalContract.planAuthority && authoritativeCanonicalContract.planAuthority.status
    || authoritativeReviewRenderModel && authoritativeReviewRenderModel.planStatus
    || (authoritativeEntryPresentation && displayedPlan.status === 'valid'
      ? 'valid'
      : String(effectiveSimplifiedState.planStatus || ''))
    || ''
  );
  const plannedRr = item.plan && String(item.plan.status || '').trim().toLowerCase() === 'valid'
    && Number.isFinite(numericOrNull(item.plan.plannedRR))
    ? Number(numericOrNull(item.plan.plannedRR))
    : null;
  const simplifiedResolvedRr = Number.isFinite(Number(effectiveSimplifiedState.resolvedRR))
    ? Number(effectiveSimplifiedState.resolvedRR)
    : null;
  const fallbackDisplayedPlanRr = displayedPlan && displayedPlan.status === 'valid'
    && displayedPlan.rewardRisk
    && Number.isFinite(numericOrNull(displayedPlan.rewardRisk.rrRatio))
      ? Number(numericOrNull(displayedPlan.rewardRisk.rrRatio))
      : null;
  let divergenceDetected = false;
  try{
    const reviewLegacyState = {
      canonicalVerdict:globalVerdict.final_verdict || globalVerdict.finalVerdict || '',
      visualBucket:globalVerdict.bucket || '',
      tone:derivedTone,
      badgeLabel:effectiveSimplifiedState.badgeLabel || '',
      mainBlocker:globalVerdict.main_blocker || globalVerdict.reason || '',
      planStatus:globalVerdict.plan_status || effectiveSimplifiedState.planStatus || '',
      entryGatePass:globalVerdict.entry_gate_pass,
      nearEntryGatePass:globalVerdict.near_entry_gate_pass,
      structureEligibility:globalVerdict.structure_eligibility || '',
      structureState:globalVerdict.structure_state || derivedStates.structureState || '',
      setupLocationState:globalVerdict.setup_location_state || derivedStates.setupLocationState || '',
      priceabilityState:globalVerdict.priceability_state || derivedStates.priceabilityState || '',
      bounceState:globalVerdict.bounce_state || derivedStates.bounceState || ''
    };
    divergenceDetected = collectStateDivergence(item, 'review.snapshot', effectiveSimplifiedState, reviewLegacyState, [
      'canonicalVerdict',
      'visualBucket',
      'tone',
      'badgeLabel',
      'mainBlocker',
      'planStatus',
      'entryGatePass',
      'nearEntryGatePass',
      'structureEligibility',
      'structureState',
      'setupLocationState',
      'priceabilityState',
      'bounceState'
    ]).detected === true;
  }catch(error){
    divergenceDetected = false;
  }
  return {
    sourceOfTruth:'simplified_state_pipeline',
    ticker:String(item.ticker || ''),
    contract:safeDiagnosticClone(authoritativeCanonicalContract || {}, {}),
    renderModels:safeDiagnosticClone({
      review:authoritativeReviewRenderModel,
      track:authoritativeTrackRenderModel,
      trackLongPress:authoritativeTrackLongPressModel
    }, {}),
    divergence:{
      cacheDisplay:displayCacheDivergence,
      persistenceInputs:persistenceInputDivergence
    },
    canonicalVerdict:canonicalHealthVerdict,
    visualBucket:canonicalHealthVisualBucket,
    tone:canonicalHealthTone,
    structureEligibility:String(effectiveSimplifiedState.structureEligibility || ''),
    structureState:String(effectiveSimplifiedState.structureState || ''),
    setupLocationState:String(effectiveSimplifiedState.setupLocationState || ''),
    priceabilityState:String(effectiveSimplifiedState.priceabilityState || ''),
    bounceState:String(effectiveSimplifiedState.bounceState || ''),
    planStatus:canonicalHealthPlanStatus,
    resolvedRR:plannedRr != null ? plannedRr : (fallbackDisplayedPlanRr != null ? fallbackDisplayedPlanRr : simplifiedResolvedRr),
    resolverRR:simplifiedResolvedRr,
    plannedRR:plannedRr != null ? plannedRr : fallbackDisplayedPlanRr,
    entryGatePass:planAuthority.actionable === true ? true : (effectiveSimplifiedState.entryGatePass === true),
    nearEntryGatePass:effectiveSimplifiedState.nearEntryGatePass === true,
    primaryBlockerReason:authoritativeEntryPresentation
      ? ''
      : String(effectiveSimplifiedState.mainBlocker || ''),
    avoidTriggerSource:String(effectiveSimplifiedState.avoidTriggerSource || ''),
    terminalAvoidApplied:effectiveSimplifiedState.terminalAvoidApplied === true,
    divergenceDetected,
    lastReviewedAt:String(item.review && item.review.lastReviewedAt || ''),
    displayContinuityVerdict:'',
    planAuthority,
    planTrace,
    planCandidates
  };
}

function applyReviewWatchlistSoftReadinessDisplayOverride(record, simplifiedState, globalVerdict, lifecycleSnapshot){
  const item = normalizeTickerRecordReadOnly(record || {});
  const simplified = simplifiedState && typeof simplifiedState === 'object' ? simplifiedState : {};
  const verdict = normalizeGlobalVerdictKey(simplified.canonicalVerdict || 'watch');
  const global = globalVerdict && typeof globalVerdict === 'object'
    ? globalVerdict
    : resolveGlobalVerdict(item);
  const resolverVerdict = normalizeGlobalVerdictKey(
    global.final_verdict
    || global.finalVerdict
    || global.final_verdict_rendered
    || ''
  );
  const softReadinessOnlyDemotion = !!(
    global
    && global.contractDiagnostics
    && global.contractDiagnostics.softReadinessOnlyDemotion === true
  );
  const explicitInvalidationAuthorityCode = resolveStructuredExplicitInvalidationAuthorityCode(global);
  const planBlockedReasonCode = String(item.plan && item.plan.blockedReasonCode || '').trim().toLowerCase();
  const structureState = String(
    simplified.structureState
    || (item.setup && item.setup.structureState)
    || ''
  ).trim().toLowerCase();
  const structureEligibility = String(
    simplified.structureEligibility
    || global.structure_eligibility
    || ''
  ).trim().toLowerCase();
  const hardStructuredBlock = ['invalidated','missed','target_too_close','broken_structure'].includes(explicitInvalidationAuthorityCode)
    || ['invalidated','missed','target_too_close','broken_structure','terminal','expired'].includes(planBlockedReasonCode)
    || simplified.terminalAvoidApplied === true
    || global.terminal_avoid_applied === true
    || global.rejected_by_viability_gate === true
    || structureEligibility === 'broken'
    || ['broken','failed'].includes(structureState);
  if(hardStructuredBlock) return simplified;
  if(
    verdict === 'entry'
    && softReadinessOnlyDemotion
    && String(simplified.planStatus || '').trim().toLowerCase() === 'valid'
    && String(simplified.priceabilityState || '').trim().toLowerCase() === 'priceable'
  ){
    return {
      ...simplified,
      canonicalVerdict:'near_entry',
      visualBucket:'near_entry',
      tone:getTone('near_entry'),
      entryGatePass:false,
      nearEntryGatePass:true,
      mainBlocker:String(simplified.mainBlocker || global.reason || 'Waiting for confirmation before entry.').trim(),
      actionLabel:'Wait for confirmation before entry.',
      debug:{
        ...(simplified.debug || {}),
        reviewWatchlistSoftReadinessDisplayOverrideApplied:true,
        reviewWatchlistSoftReadinessDisplayOverrideSource:'soft_readiness_demotion'
      }
    };
  }
  return simplified;
}

function buildTrackDiagnosticSnapshot(record){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return null;
  // Consumer 4: the diagnostic card describes the same published current
  // decision rendered by Track.  Lifecycle/persisted values below are legacy
  // observer code and cannot supply diagnostic current-state fields.
  const diagnosticPublicationSource = resolveSimplifiedStateForSurface(item, 'track', {
    log:false,
    source:'track_diagnostic_publication',
    reason:'track_diagnostic_publication'
  });
  const diagnosticPublication = {
    ...(diagnosticPublicationSource && typeof diagnosticPublicationSource === 'object' ? diagnosticPublicationSource : {}),
    // This marker describes the persisted input as cache-only; it does not
    // select any persisted value for the current decision.
    persistedPresentationCacheOnly:!!(item.watchlist && item.watchlist.presentation)
  };
  const diagnosticHistory = watchlistLifecycleSnapshot(item);
  const diagnosticPresentation = buildSharedReviewTrackPresentation(item, {
    surface:'track',
    simplifiedState:diagnosticPublication,
    lifecycleSnapshot:diagnosticHistory,
    source:'track_diagnostic_publication',
    reason:'track_diagnostic_publication'
  });
  const diagnosticSemantics = diagnosticPresentation.trackSemanticProjection || {};
  return {
    ticker:String(item.ticker || ''),
    canonicalVerdict:String(diagnosticPresentation.canonicalVerdict || ''),
    visualBucket:String(diagnosticPresentation.visualBucket || ''),
    tone:String(diagnosticPresentation.tone || ''),
    badgeLabel:String(diagnosticPresentation.badgeLabel || ''),
    headline:String(diagnosticPresentation.headline || ''),
    statusText:String(diagnosticPresentation.statusText || ''),
    actionLabel:String(diagnosticPresentation.actionLabel || ''),
    contract:{
      canonicalVerdict:diagnosticPresentation.canonicalVerdict,
      canonicalVisualBucket:diagnosticPresentation.visualBucket,
      canonicalResultVersion:diagnosticPresentation.canonicalResultVersion,
      canonicalNormVersion:diagnosticPresentation.canonicalNormVersion,
      evidenceId:diagnosticPresentation.evidenceId,
      publicationStatus:diagnosticPresentation.publicationStatus,
      // Snapshot identity is the contract identity after Consumer 4; a Track
      // diagnostic no longer obtains a competing presentation contract.
      contractFingerprint:`canonical:${String(diagnosticPresentation.canonicalResultVersion || '')}:${String(diagnosticPresentation.evidenceId || '')}`
    },
    simplifiedState:safeDiagnosticClone(diagnosticPublication || {}, {}),
    sharedPresentation:safeDiagnosticClone(diagnosticPresentation || {}, {}),
    lifecycleSnapshot:safeDiagnosticClone(diagnosticHistory || {}, {}),
    semantics:safeDiagnosticClone({...diagnosticSemantics, authoritySource:'canonical_publication'}, {}),
    plan:safeDiagnosticClone(diagnosticPresentation.canonicalPlan || {}, {}),
    scan:safeDiagnosticClone(item.scan || {}, {}),
    diagnostics:{legacyObserverOnly:true, sourceCanonicalFields:['verdict','semantics','eligibility','plan','snapshot.evidenceId'], mayFeedDecisionLogic:false}
  };
  try{
    const normalizeProjectionSource = typeof normalizeReviewProjectionSource === 'function'
      ? normalizeReviewProjectionSource
      : ((source) => String(source || '').trim().toLowerCase());
    const normalizeVerdictKey = typeof normalizeGlobalVerdictKey === 'function'
      ? normalizeGlobalVerdictKey
      : ((value) => {
        const safe = String(value || '').trim().toLowerCase().replace(/\s+/g, '_');
        if(['entry', 'near_entry', 'watch', 'avoid'].includes(safe)) return safe;
        if(safe.indexOf('near') >= 0 && safe.indexOf('entry') >= 0) return 'near_entry';
        if(safe.indexOf('entry') >= 0) return 'entry';
        if(safe.indexOf('avoid') >= 0) return 'avoid';
        return 'watch';
      });
    const normalizeBucket = typeof normalizeVisualBucketForPairing === 'function'
      ? normalizeVisualBucketForPairing
      : ((value, canonicalVerdict = '') => {
        const safe = String(value || '').trim().toLowerCase().replace(/\s+/g, '_');
        if(['entry', 'near_entry', 'monitor', 'diminishing', 'avoid'].includes(safe)) return safe;
        const canonical = normalizeVerdictKey(canonicalVerdict);
        if(canonical === 'entry') return 'entry';
        if(canonical === 'near_entry') return 'near_entry';
        if(canonical === 'avoid') return 'avoid';
        return 'monitor';
      });
    const verdictLabel = typeof globalVerdictLabel === 'function'
      ? globalVerdictLabel
      : ((value) => {
        const safe = normalizeVerdictKey(value);
        if(safe === 'entry') return 'Entry';
        if(safe === 'near_entry') return 'Near Entry';
        if(safe === 'avoid') return 'Avoid';
        return 'Watch';
      });
    const hasPresentationSnapshot = typeof hasPresentationAuthoritySnapshot === 'function'
      ? hasPresentationAuthoritySnapshot
      : ((snapshot, tickerValue) => {
        const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
        if(!safeSnapshot) return false;
        return normalizeTicker(safeSnapshot.ticker || '') === normalizeTicker(tickerValue || '');
      });
    const projectionCanDriveEntry = typeof reviewProjectionCanDriveEntryDisplay === 'function'
      ? reviewProjectionCanDriveEntryDisplay
      : (() => false);
    const buildCanonicalModels = typeof buildCanonicalRenderModelsFromRecord === 'function'
      ? buildCanonicalRenderModelsFromRecord
      : (() => null);
    const resolveEffectivePlan = typeof effectivePlanForRecord === 'function'
      ? effectivePlanForRecord
      : (() => ({}));
    const resolveSetupScore = typeof setupScoreForRecord === 'function'
      ? setupScoreForRecord
      : (() => 0);
    const displayDivergenceSummary = typeof canonicalDisplayDivergenceSummary === 'function'
      ? canonicalDisplayDivergenceSummary
      : (() => ({}));
    const persistenceDivergenceSummary = typeof canonicalPersistenceInputDivergence === 'function'
      ? canonicalPersistenceInputDivergence
      : (() => ({}));
    const safeUiState = typeof uiState !== 'undefined' && uiState && typeof uiState === 'object'
      ? uiState
      : {};
    const activeProjectionSnapshot = safeUiState.activeReviewSourceProjectionSnapshot
      && typeof safeUiState.activeReviewSourceProjectionSnapshot === 'object'
      && normalizeTicker(safeUiState.activeReviewSourceProjectionSnapshot.ticker || '') === normalizeTicker(item.ticker || '')
        ? safeUiState.activeReviewSourceProjectionSnapshot
        : null;
    const activeProjectionSource = normalizeProjectionSource(
      String(
        safeUiState.activeReviewProjectionSource
        || (activeProjectionSnapshot ? 'clicked_card_snapshot' : 'non_watchlist_direct_resolve')
      ).trim().toLowerCase(),
      activeProjectionSnapshot
    );
    const allowTrackProjection = (
      hasPresentationSnapshot(activeProjectionSnapshot, item.ticker || '')
      && ['clicked_card_snapshot', 'track_projection_updated'].includes(activeProjectionSource)
    ) || projectionCanDriveEntry(activeProjectionSnapshot, activeProjectionSource, item);
    const persistedPresentation = item.watchlist && item.watchlist.presentation && typeof item.watchlist.presentation === 'object'
      ? item.watchlist.presentation
      : null;
    const lifecycleSnapshot = watchlistLifecycleSnapshot(item);
    const synthesizedWatchlistDebug = diagnosticWatchlistDebugSnapshot(item, {lifecycleSnapshot});
    const simplifiedStateRaw = resolveSimplifiedStateForWatchlistPresentation(item, {
      surface:'track',
      source:'diagnostic_snapshot',
      reason:'diagnostic_snapshot'
    });
    const simplifiedStateFromPersistedCacheOnly = !!(
      simplifiedStateRaw
      && typeof simplifiedStateRaw === 'object'
      && (
        simplifiedStateRaw.persistedPresentationCacheOnly === true
        || (
          persistedPresentation != null
          && (!simplifiedStateRaw.debug || typeof simplifiedStateRaw.debug !== 'object')
          && !String(simplifiedStateRaw.sourceOfTruth || '').trim()
        )
      )
    );
    const simplifiedState = simplifiedStateRaw && typeof simplifiedStateRaw === 'object' && !simplifiedStateFromPersistedCacheOnly
      ? simplifiedStateRaw
      : {
        canonicalVerdict:'watch',
        visualBucket:'monitor',
        tone:'monitor',
        structureEligibility:'alive',
        priceabilityState:'priceable',
        persistedPresentationCacheOnly:persistedPresentation != null
      };
    const simplifiedDebug = simplifiedState.debug && typeof simplifiedState.debug === 'object'
      ? simplifiedState.debug
      : {};
    const derivedStates = simplifiedDebug.derivedStates && typeof simplifiedDebug.derivedStates === 'object'
      ? simplifiedDebug.derivedStates
      : analysisDerivedStatesFromRecord(item);
    const displayedPlan = applySetupConfirmationPlanGate(item, deriveCurrentPlanState(
      item.plan && item.plan.entry,
      item.plan && item.plan.stop,
      item.plan && item.plan.firstTarget,
      item.marketData && item.marketData.currency
    ), derivedStates);
    const globalVerdict = (simplifiedDebug.resolvedState
      ? simplifiedDebug.resolvedState
      : resolveGlobalVerdict(item));
    const diagnosticResolverVerdict = resolveGlobalVerdict(item);
    const diagnosticAnalysisState = typeof getReviewAnalysisState === 'function' ? getReviewAnalysisState(item) : null;
    const diagnosticAnalysis = diagnosticAnalysisState && diagnosticAnalysisState.normalizedAnalysis && typeof diagnosticAnalysisState.normalizedAnalysis === 'object'
      ? diagnosticAnalysisState.normalizedAnalysis
      : {};
    const diagnosticStoryContext = typeof buildCanonicalStoryContextForRecord === 'function'
      ? buildCanonicalStoryContextForRecord(item, {
        analysis:diagnosticAnalysis,
        globalVerdict:diagnosticResolverVerdict,
        derivedStates
      })
      : null;
    const renderModels = buildCanonicalModels(item, {
      surface:'track',
      source:'diagnostic_snapshot',
      reason:'diagnostic_snapshot',
      derivedStates,
      effectivePlan:resolveEffectivePlan(item, {allowScannerFallback:true}),
      displayedPlan,
      globalVerdict,
      lifecycleSnapshot,
      setupScore:resolveSetupScore(item)
    });
    const canonicalTrackRenderModel = renderModels && renderModels.trackRenderModel && typeof renderModels.trackRenderModel === 'object'
      ? renderModels.trackRenderModel
      : null;
    const canonicalContract = renderModels && renderModels.contract && typeof renderModels.contract === 'object'
      ? renderModels.contract
      : null;
    const priority = watchlistPriorityForRecord(item, {lifecycleSnapshot});
    const persistedSharedPresentation = persistedPresentation && persistedPresentation.sharedPresentation && typeof persistedPresentation.sharedPresentation === 'object'
      ? persistedPresentation.sharedPresentation
      : null;
    const diagnosticsSourceOfTruth = 'live_recomputed_fallback';
    const sharedPresentation = buildSharedReviewTrackPresentation(item, {
      surface:'track',
      simplifiedState,
      lifecycleSnapshot,
      globalVerdict,
      projectionSnapshot:activeProjectionSnapshot,
      projectionSource:activeProjectionSource,
      allowTrackProjection,
      sourceOfTruth:diagnosticsSourceOfTruth,
      source:'diagnostic_snapshot',
      reason:'diagnostic_snapshot'
    });
    const diagnosticProjectionEntryAuthority = activeProjectionSource === 'clicked_card_snapshot'
      && projectionCanDriveEntry(activeProjectionSnapshot, activeProjectionSource, item)
      && normalizeGlobalVerdictKey(
        item.scan && (
          item.scan.resolvedVerdict
          || item.scan.verdict
        )
        || ''
      ) === 'entry';
    const effectiveSharedPresentation = diagnosticProjectionEntryAuthority
      ? {
        ...sharedPresentation,
        canonicalVerdict:'entry',
        finalVerdict:'entry',
        visualBucket:'entry',
        sourceOfTruthVisualBucket:'entry',
        renderedBucket:'entry',
        tone:'entry',
        badgeLabel:'Entry',
        headline:'Entry Ready',
        statusText:'Entry Ready',
        actionLabel:'Execute only if the trigger remains valid.',
        nextAction:'Execute only if the trigger remains valid.',
        primaryReason:'Buyers are in control and the setup is ready to act on.',
        mainBlocker:'',
        planVisible:true,
        planStatus:'valid'
      }
      : sharedPresentation;
    const authoritativeTrackDecisionProjection = typeof buildAuthoritativeDecisionProjection === 'function'
      ? buildAuthoritativeDecisionProjection({
        record:item,
        finalVerdict:simplifiedState.canonicalVerdict || simplifiedState.finalVerdict || 'watch',
        resolvedContract:{
          planStatusKey:String(
            effectiveSharedPresentation && effectiveSharedPresentation.planStatus
            || simplifiedState.planStatus
            || displayedPlan.status
            || ''
          ).trim().toLowerCase()
        },
        derivedStates,
        globalVerdict:diagnosticResolverVerdict,
        analysis:diagnosticAnalysis,
        storyContext:diagnosticStoryContext,
        authoritativeBlockerText:String(
          effectiveSharedPresentation && (
            effectiveSharedPresentation.trackBlocker
            || effectiveSharedPresentation.mainBlocker
            || effectiveSharedPresentation.primaryReason
          )
          || canonicalTrackRenderModel && canonicalTrackRenderModel.primaryReason
          || simplifiedState.mainBlocker
          || globalVerdict.reason
          || ''
        ).trim()
      })
      : null;
    const trackVisibleModel = persistedTrackVisibleModelFromPresentation(effectiveSharedPresentation);
    const debugPlanUI = resolvePlanVisibility({
      state:globalVerdict.finalVerdict || globalVerdict.final_verdict,
      bounce_state:globalVerdict.bounce_state || (item.setup && item.setup.bounceState),
      structure:globalVerdict.structure_state || (item.setup && item.setup.structureState),
      terminal_avoid_applied:globalVerdict.terminal_avoid_applied === true,
      avoid_trigger_source:globalVerdict.avoid_trigger_source || '',
      viability:globalVerdict.viability || '',
      rejected_by_viability_gate:globalVerdict.rejected_by_viability_gate === true,
      hasPriceablePlan:globalVerdict.hasPriceablePlan === true,
      hasProvisionalPriceablePlan:globalVerdict.hasProvisionalPriceablePlan === true,
      near_entry_gate_pass:globalVerdict.near_entry_gate_pass === true
    });
    const consistencyAudit = buildConsistencyAuditRows({
      simplifiedState,
      globalVerdict,
      trackVisibleModel,
      debugPlanUI,
      lifecycleSnapshot,
      resolved:item.watchlistVisualState || (persistedPresentation && persistedPresentation.watchlistVisualState) || {},
      derivedStates,
      displayedPlan
    });
    const authoritativeVisualState = item.watchlistVisualState && typeof item.watchlistVisualState === 'object'
      ? item.watchlistVisualState
      : (persistedPresentation && persistedPresentation.watchlistVisualState && typeof persistedPresentation.watchlistVisualState === 'object'
        ? persistedPresentation.watchlistVisualState
        : {});
    const trackDebug = authoritativeVisualState.trackDebug && typeof authoritativeVisualState.trackDebug === 'object'
      ? authoritativeVisualState.trackDebug
      : {};
    const renderedVisibleModel = trackDebug.visibleModel && typeof trackDebug.visibleModel === 'object'
      ? trackDebug.visibleModel
      : null;
    const diagnosticCanonicalVerdict = normalizeVerdictKey(
      simplifiedState.canonicalVerdict
      || canonicalTrackRenderModel && canonicalTrackRenderModel.canonicalVerdict
      || canonicalContract && canonicalContract.canonicalVerdict
      || canonicalContract && canonicalContract.canonicalVerdictKey
      || (!simplifiedStateFromPersistedCacheOnly && (
        trackVisibleModel.canonicalVerdict
        || effectiveSharedPresentation.canonicalVerdict
        || renderedVisibleModel && renderedVisibleModel.canonicalVerdict
      ))
      || 'watch'
    );
    const diagnosticVisualBucket = normalizeBucket(
      simplifiedState.visualBucket
      || canonicalTrackRenderModel && (canonicalTrackRenderModel.visibleBucket || canonicalTrackRenderModel.visualBucket)
      || canonicalContract && canonicalContract.canonicalVisualBucket
      || (!simplifiedStateFromPersistedCacheOnly && (
        trackVisibleModel.visibleBucket
        || effectiveSharedPresentation.visualBucket
        || renderedVisibleModel && renderedVisibleModel.visibleBucket
      ))
      || 'monitor',
      diagnosticCanonicalVerdict
    );
    const trackStateHealth = {
      sourceOfTruth:diagnosticsSourceOfTruth,
      ticker:String(item.ticker || ''),
      contractFingerprint:String(canonicalContract && canonicalContract.contractFingerprint || ''),
      canonicalVerdict:String(diagnosticCanonicalVerdict || ''),
      visualBucket:String(diagnosticVisualBucket || ''),
      tone:String(
        canonicalTrackRenderModel && canonicalTrackRenderModel.tone
        || (!simplifiedStateFromPersistedCacheOnly && (
          trackVisibleModel.tone
          || effectiveSharedPresentation.tone
          || renderedVisibleModel && renderedVisibleModel.tone
        ))
        || diagnosticVisualBucket
        || ''
      ),
      badgeLabel:String(
        canonicalTrackRenderModel && canonicalTrackRenderModel.badgeLabel
        || (!simplifiedStateFromPersistedCacheOnly && (
          trackVisibleModel.badgeLabel
          || effectiveSharedPresentation.badgeLabel
          || renderedVisibleModel && renderedVisibleModel.badgeLabel
        ))
        || verdictLabel(diagnosticCanonicalVerdict)
        || ''
      ),
      headline:String(
        canonicalTrackRenderModel && canonicalTrackRenderModel.headline
        || (!simplifiedStateFromPersistedCacheOnly && (
          trackVisibleModel.headline
          || effectiveSharedPresentation.headline
          || renderedVisibleModel && renderedVisibleModel.headline
        ))
        || verdictLabel(diagnosticCanonicalVerdict)
        || ''
      ),
      statusText:String(
        canonicalTrackRenderModel && canonicalTrackRenderModel.statusText
        || (!simplifiedStateFromPersistedCacheOnly && (
          trackVisibleModel.statusText
          || effectiveSharedPresentation.statusText
          || renderedVisibleModel && renderedVisibleModel.headline
        ))
        || verdictLabel(diagnosticCanonicalVerdict)
        || ''
      ),
      actionLabel:String(
        canonicalTrackRenderModel && canonicalTrackRenderModel.actionLabel
        || (!simplifiedStateFromPersistedCacheOnly && (
          trackVisibleModel.actionLabel
          || effectiveSharedPresentation.actionLabel
        ))
        || simplifiedState.actionLabel
        || ''
      ),
      structureEligibility:String(simplifiedState.structureEligibility || ''),
      structureState:String(simplifiedState.structureState || ''),
      setupLocationState:String(simplifiedState.setupLocationState || ''),
      priceabilityState:String(simplifiedState.priceabilityState || ''),
      bounceState:String(simplifiedState.bounceState || ''),
      planStatus:String(simplifiedState.planStatus || ''),
      resolvedRR:Number.isFinite(Number(simplifiedState.resolvedRR)) ? Number(simplifiedState.resolvedRR) : null,
      entryGatePass:simplifiedState.entryGatePass === true,
      nearEntryGatePass:simplifiedState.nearEntryGatePass === true,
      trackCurrentPhase:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.currentPhase || '').trim(),
      trackActionability:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.actionability || '').trim(),
      trackDecisiveReason:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.decisiveReason || '').trim(),
      trackBlocker:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.blocker || '').trim(),
      trackSupportRelationship:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.supportRelationship || '').trim(),
      trackOpportunityCondition:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.opportunityCondition || '').trim(),
      trackPlanCondition:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.planStatus || '').trim(),
      primaryBlockerReason:String(canonicalTrackRenderModel && canonicalTrackRenderModel.primaryReason || trackVisibleModel.primaryReason || effectiveSharedPresentation.primaryReason || effectiveSharedPresentation.mainBlocker || renderedVisibleModel && renderedVisibleModel.primaryReason || ''),
      avoidTriggerSource:String(simplifiedState.avoidTriggerSource || ''),
      terminalAvoidApplied:simplifiedState.terminalAvoidApplied === true,
      divergenceDetected:false,
      lastReviewedAt:String(item.review && item.review.lastReviewedAt || ''),
      persistedPresentationAvailable:persistedSharedPresentation != null,
      persistedPresentationCacheOnly:persistedSharedPresentation != null
    };
    // Diagnostics must describe the same immutable publication currently
    // rendered by Track. The older render-model contract remains useful
    // context, but cannot become the diagnostic decision root.
    const publicationDiagnosticContract = {
      ...(canonicalContract && typeof canonicalContract === 'object' ? canonicalContract : {}),
      canonicalVerdict:String(diagnosticCanonicalVerdict || ''),
      canonicalVerdictKey:String(diagnosticCanonicalVerdict || ''),
      canonicalVisualBucket:String(diagnosticVisualBucket || ''),
      canonicalResultVersion:String(simplifiedState.canonicalResultVersion || ''),
      canonicalNormVersion:String(simplifiedState.canonicalNormVersion || ''),
      evidenceId:String(simplifiedState.evidenceId || ''),
      publicationStatus:String(simplifiedState.publicationStatus || 'valid')
    };
    const displayCacheDivergence = displayDivergenceSummary(
      publicationDiagnosticContract,
      persistedSharedPresentation,
      canonicalTrackRenderModel || trackVisibleModel
    );
    const persistenceInputDivergence = persistenceDivergenceSummary(item, publicationDiagnosticContract);
    return {
      ticker:String(item.ticker || ''),
      canonicalVerdict:String(trackStateHealth.canonicalVerdict || ''),
      visualBucket:String(trackStateHealth.visualBucket || ''),
      tone:String(trackStateHealth.tone || ''),
      badgeLabel:String(trackStateHealth.badgeLabel || ''),
      headline:String(trackStateHealth.headline || ''),
      statusText:String(trackStateHealth.statusText || ''),
      actionLabel:String(trackStateHealth.actionLabel || ''),
      contractFingerprint:String(trackStateHealth.contractFingerprint || ''),
      contract:safeDiagnosticClone(publicationDiagnosticContract, {}),
      renderModels:safeDiagnosticClone({
        review:renderModels && renderModels.reviewRenderModel ? renderModels.reviewRenderModel : null,
        track:canonicalTrackRenderModel,
        trackLongPress:renderModels && renderModels.trackLongPressModel ? renderModels.trackLongPressModel : null
      }, {}),
      divergence:{
        cacheDisplay:displayCacheDivergence,
        persistenceInputs:persistenceInputDivergence
      },
      simplifiedState:trackStateHealth,
      sharedPresentation:safeDiagnosticClone(effectiveSharedPresentation || {}, {}),
      lifecycleSnapshot:safeDiagnosticClone(lifecycleSnapshot || {}, {}),
      consistencyAudit:safeDiagnosticClone(consistencyAudit || [], []),
      visibleModel:safeDiagnosticClone(trackVisibleModel || {}, {}),
      semantics:safeDiagnosticClone({
        canonicalVerdict:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.canonicalVerdict || trackStateHealth.canonicalVerdict || '').trim(),
        currentPhase:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.currentPhase || '').trim(),
        actionability:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.actionability || '').trim(),
        decisiveReason:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.decisiveReason || '').trim(),
        blocker:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.blocker || '').trim(),
        supportRelationship:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.supportRelationship || '').trim(),
        opportunityCondition:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.opportunityCondition || '').trim(),
        planStatus:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.planStatus || '').trim().toLowerCase() || 'unknown',
        upgradeCondition:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.upgradeCondition || '').trim(),
        downgradeCondition:String(authoritativeTrackDecisionProjection && authoritativeTrackDecisionProjection.downgradeCondition || '').trim(),
        authoritySource:String(authoritativeTrackDecisionProjection ? 'canonical_semantic_projection' : 'presentation_compatibility_fallback').trim()
      }, {}),
      resolverTrace:safeDiagnosticClone(trackDebug.resolverTrace || {}, {}),
      planTrace:safeDiagnosticClone(trackDebug.planTrace || {}, {}),
      gateTrace:safeDiagnosticClone(trackDebug.gateTrace || {}, {}),
      lifecycleTrace:safeDiagnosticClone(trackDebug.lifecycleTrace || {}, {}),
      watchlistDebug:safeDiagnosticClone(synthesizedWatchlistDebug || {}, {}),
      plan:safeDiagnosticClone(item.plan || {}, {}),
      scan:safeDiagnosticClone(item.scan || {}, {})
    };
  }catch(error){
    return {
      ticker:String(item.ticker || ''),
      snapshotError:String(error && error.message || 'track_snapshot_failed')
    };
  }
}

function buildReplaySnapshotForTicker(tickerOrRecord, options = {}){
  const liveRecord = tickerOrRecord && typeof tickerOrRecord === 'object'
    ? tickerOrRecord
    : getTickerRecord(normalizeTicker(tickerOrRecord || ''));
  if(!liveRecord || typeof liveRecord !== 'object') return null;
  const record = normalizeTickerRecordReadOnly(liveRecord);
  const reviewProjectionSnapshot = uiState && uiState.activeReviewSourceProjectionSnapshot
    && typeof uiState.activeReviewSourceProjectionSnapshot === 'object'
    && normalizeTicker(uiState.activeReviewSourceProjectionSnapshot.ticker || '') === normalizeTicker(record.ticker || '')
      ? safeDiagnosticClone(uiState.activeReviewSourceProjectionSnapshot, {})
      : null;
  const reviewProjectionSource = normalizeReviewProjectionSource(
    String(uiState && uiState.activeReviewProjectionSource || '').trim().toLowerCase(),
    reviewProjectionSnapshot
  );
  const reviewState = currentReviewStateHealthSnapshot(liveRecord);
  const liveReviewProjectionAuthority = false;
  const trackState = buildTrackDiagnosticSnapshot(liveRecord);
  const scanState = withReviewProjectionSuppressed(() => resolveSimplifiedStateForSurface(record, 'scan', {
    log:false,
    source:'replay_snapshot_builder',
    mutationSource:'replay_snapshot_builder'
  })) || null;
  const authoritativeScan = authoritativeScanSurfaceSnapshot(liveRecord);
  const rawCanonicalContract = reviewState && reviewState.contract && typeof reviewState.contract === 'object'
    ? reviewState.contract
    : (trackState && trackState.contract && typeof trackState.contract === 'object'
      ? trackState.contract
      : null);
  const rawRenderModels = reviewState && reviewState.renderModels && typeof reviewState.renderModels === 'object'
    ? reviewState.renderModels
    : (trackState && trackState.renderModels && typeof trackState.renderModels === 'object'
      ? trackState.renderModels
      : null);
  const projectionCanonicalVerdict = normalizeGlobalVerdictKey(
    reviewState && reviewState.canonicalVerdict
    || reviewProjectionSnapshot && (
      reviewProjectionSnapshot.canonicalVerdict
      || reviewProjectionSnapshot.finalVerdict
      || reviewProjectionSnapshot.renderedVerdict
    )
    || ''
  );
  const projectionVisualBucket = normalizeVisualBucketForPairing(
    reviewState && reviewState.visualBucket
    || reviewProjectionSnapshot && (
      reviewProjectionSnapshot.sourceOfTruthVisualBucket
      || reviewProjectionSnapshot.visualBucket
      || reviewProjectionSnapshot.renderedBucket
    )
    || '',
    projectionCanonicalVerdict
  );
  const canonicalContract = liveReviewProjectionAuthority && rawCanonicalContract
    ? {
      ...safeDiagnosticClone(rawCanonicalContract, {}),
      canonicalVerdict:projectionCanonicalVerdict || rawCanonicalContract.canonicalVerdict,
      canonicalVisualBucket:projectionVisualBucket || rawCanonicalContract.canonicalVisualBucket
    }
    : rawCanonicalContract;
  const renderModels = liveReviewProjectionAuthority && rawRenderModels
    ? {
      ...safeDiagnosticClone(rawRenderModels, {}),
      review:{
        ...(safeDiagnosticClone(rawRenderModels.review || {}, {})),
        canonicalVerdict:projectionCanonicalVerdict || rawRenderModels.review && rawRenderModels.review.canonicalVerdict,
        visualBucket:projectionVisualBucket || rawRenderModels.review && rawRenderModels.review.visualBucket
      },
      track:{
        ...(safeDiagnosticClone(rawRenderModels.track || {}, {})),
        canonicalVerdict:projectionCanonicalVerdict || rawRenderModels.track && rawRenderModels.track.canonicalVerdict,
        visualBucket:projectionVisualBucket || rawRenderModels.track && rawRenderModels.track.visualBucket,
        visibleBucket:projectionVisualBucket || rawRenderModels.track && (rawRenderModels.track.visibleBucket || rawRenderModels.track.visualBucket)
      }
    }
    : rawRenderModels;
  const scannerCanonicalVerdict = normalizeGlobalVerdictKey(
    authoritativeScan && authoritativeScan.canonicalVerdict
    || scanState && scanState.canonicalVerdict
    || record.scan && (record.scan.resolvedVerdict || record.scan.verdict)
    || 'watch'
  );
  const scannerVisualBucket = normalizeVisualBucketForPairing(
    authoritativeScan && authoritativeScan.visualBucket
    || scanState && scanState.visualBucket
    || scannerCanonicalVerdict,
    scannerCanonicalVerdict
  );
  const reviewCanonicalVerdict = normalizeGlobalVerdictKey(
    reviewState && reviewState.canonicalVerdict
    || canonicalContract && canonicalContract.canonicalVerdict
    || scannerCanonicalVerdict
    || 'watch'
  );
  const reviewVisualBucket = normalizeVisualBucketForPairing(
    reviewState && reviewState.visualBucket
    || renderModels && renderModels.review && renderModels.review.visualBucket
    || canonicalContract && canonicalContract.canonicalVisualBucket
    || reviewCanonicalVerdict,
    reviewCanonicalVerdict
  );
  const setupScore = Number.isFinite(Number(
    reviewState && reviewState.contract && reviewState.contract.derivedStates && reviewState.contract.derivedStates.setupScore
  ))
    ? Number(reviewState.contract.derivedStates.setupScore)
    : (Number.isFinite(Number(
      canonicalContract && canonicalContract.derivedStates && canonicalContract.derivedStates.setupScore
    ))
      ? Number(canonicalContract.derivedStates.setupScore)
      : (Number.isFinite(Number(scanState && scanState.setupScore))
        ? Number(scanState.setupScore)
        : setupScoreForRecord(liveRecord)));
  const recomputedReviewVerdict = normalizeGlobalVerdictKey(
    renderModels && renderModels.review && renderModels.review.canonicalVerdict
    || ''
  );
  const recomputedReviewBucket = normalizeVisualBucketForPairing(
    renderModels && renderModels.review && renderModels.review.visualBucket
    || '',
    recomputedReviewVerdict
  );
  return {
    ticker:String(record.ticker || ''),
    canonicalContract:safeDiagnosticClone(canonicalContract || {}, {}),
    renderModels:safeDiagnosticClone(renderModels || {}, {}),
    meta:safeDiagnosticClone(record.meta || {}, {}),
    marketData:safeDiagnosticClone(record.marketData || {}, {}),
    setup:safeDiagnosticClone(record.setup || {}, {}),
    plan:safeDiagnosticClone(record.plan || {}, {}),
    scan:safeDiagnosticClone(record.scan || {}, {}),
    review:{
      analysisState:{
        normalized:safeDiagnosticClone(
          record.review
          && record.review.analysisState
          && record.review.analysisState.normalized
          || null,
          null
        )
      },
      manualReview:safeDiagnosticClone(record.review && record.review.manualReview || null, null),
      projectionSource:reviewProjectionSource,
      projectionSnapshot:liveReviewProjectionAuthority
        ? safeDiagnosticClone(reviewProjectionSnapshot || null, null)
        : null
    },
    rawShortlistSignal:{
      verdict:String(record.scan && (record.scan.resolvedVerdict || record.scan.verdict) || '').trim(),
      reasons:Array.isArray(record.scan && record.scan.reasons) ? record.scan.reasons.slice() : [],
      blockers:Array.isArray(record.scan && record.scan.blockers) ? record.scan.blockers.slice() : []
    },
    rawShortlistVerdict:String(record.scan && (record.scan.resolvedVerdict || record.scan.verdict) || '').trim(),
    scannerCanonicalVerdict,
    scannerVisualBucket,
    scannerSnapshotIncomplete:!scannerCanonicalVerdict,
    reviewCanonicalVerdict,
    reviewVisualBucket,
    reviewProjectionSource,
    replayAuthoritySource:canonicalContract ? 'canonical_contract' : 'recomputed_fallback',
    snapshotContractFingerprint:String(canonicalContract && canonicalContract.contractFingerprint || ''),
    setupScore,
    authorityDrift:{
      canonicalVerdict:recomputedReviewVerdict,
      visualBucket:recomputedReviewBucket,
      differsFromSnapshot:!!(
        recomputedReviewVerdict
        && (
          recomputedReviewVerdict !== reviewCanonicalVerdict
          || recomputedReviewBucket !== reviewVisualBucket
        )
      )
    }
  };
}

function buildTesterDiagnosticSnapshot(options = {}){
  const panelTitle = String(options.panelTitle || 'General diagnostics').trim();
  const panelElement = options.panelElement || null;
  const bundleMode = String(options.bundleMode || '').trim().toLowerCase();
  const trackTicker = normalizeTicker(options.trackTicker || '');
  const record = bundleMode === 'track_tester_bundle' && trackTicker
    ? getTickerRecord(trackTicker)
    : currentReviewDiagnosticRecord();
  try{
    if(bundleMode === 'review_tester_bundle'){
      // This is the handoff used most often in tester reports. Keep it focused:
      // the former version copied the same large Review state at the root, in
      // sections, and again via raw resolver records.
      const shortText = (value, limit = 600) => String(value == null ? '' : value)
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, limit);
      const shortList = (value, itemLimit = 6, textLimit = 240) => Array.isArray(value)
        ? value.slice(0, itemLimit).map(item => shortText(item, textLimit)).filter(Boolean)
        : [];
      const review = currentVisibleReviewDiagnostics(record) || {};
      const stateHealth = currentReviewStateHealthSnapshot(record) || {};
      const chartVerification = currentReviewChartVerificationSnapshot(record) || {};
      const paperTrade = record ? currentPaperTradeDebugSnapshotForTicker(record.ticker) : null;
      const gateway = currentPaperGatewayDiagnostics() || {};
      const contract = stateHealth.contract && typeof stateHealth.contract === 'object'
        ? stateHealth.contract
        : {};
      const planAuthority = stateHealth.planAuthority && typeof stateHealth.planAuthority === 'object'
        ? stateHealth.planAuthority
        : {};
      const compactSnapshot = {
        diagnosticSchema:'review_tester_bundle.v2',
        timestamp:new Date().toISOString(),
        testerId:currentTesterId(),
        buildVersion:currentBuildVersion(),
        buildInfo:currentBuildInfo(),
        activeWorkspace:String(activeWorkspaceTab() || ''),
        panelTitle,
        ticker:String(record && record.ticker || activeReviewTicker() || 'general'),
        bundleMode:'review_tester_bundle',
        bundleNote:'Compact Review tester handoff. Use a full debug export only when this summary cannot isolate the issue.',
        omissions:[
          'Raw persisted scan/setup/watchlist/lifecycle records',
          'Duplicate Review and state-health copies',
          'Full Chart Guru audit and plan-candidate histories'
        ],
        sections:{
          review:{
            currentVerdict:shortText(review.currentVerdict, 80),
            currentTone:shortText(review.currentTone, 80),
            visibleReviewStatus:shortText(review.visibleReviewStatus),
            reviewWorkspaceStatus:shortText(review.reviewWorkspaceStatus),
            chartVerificationStatus:review.chartVerificationStatus && typeof review.chartVerificationStatus === 'object'
              ? {
                phase:shortText(review.chartVerificationStatus.phase, 80),
                status:shortText(review.chartVerificationStatus.status, 120),
                requestId:shortText(review.chartVerificationStatus.requestId, 160),
                imageId:shortText(review.chartVerificationStatus.imageId, 160)
              }
              : null
          },
          authority:{
            sourceOfTruth:shortText(stateHealth.sourceOfTruth, 120),
            canonicalVerdict:shortText(stateHealth.canonicalVerdict, 80),
            visualBucket:shortText(stateHealth.visualBucket, 80),
            tone:shortText(stateHealth.tone, 80),
            contractFingerprint:shortText(contract.contractFingerprint || stateHealth.contractFingerprint, 160),
            authorityContract:shortText(contract.contractDiagnostics && contract.contractDiagnostics.authorityContract, 120),
            authoritySelectionSource:shortText(contract.contractDiagnostics && (contract.contractDiagnostics.canonicalAuthoritySelectionSource || contract.contractDiagnostics.authoritySelectionSource), 160),
            primaryBlockerReason:shortText(stateHealth.primaryBlockerReason),
            structureEligibility:shortText(stateHealth.structureEligibility, 80),
            structureState:shortText(stateHealth.structureState, 80),
            setupLocationState:shortText(stateHealth.setupLocationState, 80),
            priceabilityState:shortText(stateHealth.priceabilityState, 80),
            bounceState:shortText(stateHealth.bounceState, 80),
            entryGatePass:stateHealth.entryGatePass === true,
            nearEntryGatePass:stateHealth.nearEntryGatePass === true,
            terminalAvoidApplied:stateHealth.terminalAvoidApplied === true,
            divergenceDetected:stateHealth.divergenceDetected === true
          },
          plan:{
            status:shortText(stateHealth.planStatus, 80),
            resolvedRR:Number.isFinite(Number(stateHealth.resolvedRR)) ? Number(stateHealth.resolvedRR) : null,
            authorityId:shortText(planAuthority.authorityId, 120),
            source:shortText(planAuthority.source, 120),
            reasonCode:shortText(planAuthority.reasonCode, 160),
            actionable:planAuthority.actionable === true
          },
          chartVerification:{
            phase:shortText(chartVerification.phase, 80),
            status:shortText(chartVerification.status, 120),
            decisionKey:shortText(chartVerification.decisionKey, 120),
            summary:shortText(chartVerification.summary),
            detail:shortText(chartVerification.detail),
            aiAnalysisSuppressed:chartVerification.aiAnalysisSuppressed === true,
            suppressionReason:shortText(chartVerification.suppressionReason, 240),
            expectedTicker:shortText(chartVerification.expectedTicker, 80),
            detectedTicker:shortText(chartVerification.detectedTicker, 80),
            requestId:shortText(chartVerification.requestId, 160),
            imageId:shortText(chartVerification.imageId, 160),
            manualConfirmed:chartVerification.manualConfirmed === true,
            diagnostics:shortList(chartVerification.diagnostics),
            evidence:shortList(chartVerification.evidence),
            missing:shortList(chartVerification.missing),
            snapshotError:shortText(chartVerification.snapshotError, 240)
          },
          paperTrade:{
            status:shortText(paperTrade && paperTrade.status, 120),
            state:shortText(paperTrade && paperTrade.state, 120),
            reason:shortText(paperTrade && (paperTrade.reason || paperTrade.reasonCode), 240)
          },
          gateway:{
            state:shortText(gateway.state, 80),
            label:shortText(gateway.label, 160),
            detail:shortText(gateway.detail),
            supported:gateway.supported === true,
            checked:gateway.checked === true,
            enabled:gateway.enabled === true
          }
        }
      };
      const redactedCompactSnapshot = redactDiagnosticPayload(compactSnapshot);
      const compactCharacterCount = JSON.stringify(redactedCompactSnapshot).length;
      if(compactCharacterCount > 20000){
        return {
          diagnosticSchema:'review_tester_bundle.v2',
          timestamp:new Date().toISOString(),
          panelTitle,
          ticker:shortText(record && record.ticker || activeReviewTicker() || 'general', 32),
          bundleMode:'review_tester_bundle',
          truncated:true,
          characterCount:compactCharacterCount,
          maxCharacterCount:20000,
          canonicalVerdict:shortText(stateHealth.canonicalVerdict, 80),
          visualBucket:shortText(stateHealth.visualBucket, 80),
          primaryBlockerReason:shortText(stateHealth.primaryBlockerReason),
          error:'Review diagnostics exceeded the handoff limit; use the full debug export for the complete state.'
        };
      }
      redactedCompactSnapshot.characterCount = compactCharacterCount;
      redactedCompactSnapshot.maxCharacterCount = 20000;
      return redactedCompactSnapshot;
    }
    const rawSnapshot = {
      timestamp:new Date().toISOString(),
      testerId:currentTesterId(),
      buildVersion:currentBuildVersion(),
      buildInfo:currentBuildInfo(),
      activeWorkspace:String(activeWorkspaceTab() || ''),
      panelTitle,
      ticker:String(record && record.ticker || activeReviewTicker() || 'general'),
      review:currentVisibleReviewDiagnostics(record),
      chartGuruAudit:record ? buildChartGuruAuditSnapshot(record) : null,
      stateHealth:currentReviewStateHealthSnapshot(record),
      paperTradeDebug:record ? currentPaperTradeDebugSnapshotForTicker(record.ticker) : null,
      resolverTrace:record ? {
        scan:safeDiagnosticClone(record.scan || {}, {}),
        setup:safeDiagnosticClone(record.setup || {}, {}),
        watchlistDebug:safeDiagnosticClone(record.watchlist && record.watchlist.debug || {}, {}),
        lifecycle:safeDiagnosticClone(record.lifecycle || {}, {}),
        plan:safeDiagnosticClone(record.plan || {}, {})
      } : null,
      policyDiagnostics:currentPolicyDiagnostics(),
      gateway:currentPaperGatewayDiagnostics(),
      panelText:panelElement ? String(panelElement.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 4000) : ''
    };
    if(bundleMode === 'track_tester_bundle'){
      rawSnapshot.bundleMode = 'track_tester_bundle';
      rawSnapshot.bundleNote = 'Primary Track tester bundle. Use this instead of copying separate Track debug panels.';
      rawSnapshot.sections = {
        track:buildTrackDiagnosticSnapshot(record),
        policyDiagnostics:rawSnapshot.policyDiagnostics,
        gateway:rawSnapshot.gateway
      };
    }
    return redactDiagnosticPayload(rawSnapshot);
  }catch(error){
    return redactDiagnosticPayload({
      timestamp:new Date().toISOString(),
      testerId:currentTesterId(),
      buildVersion:currentBuildVersion(),
      buildInfo:currentBuildInfo(),
      activeWorkspace:String(activeWorkspaceTab() || ''),
      panelTitle,
      ticker:String(record && record.ticker || activeReviewTicker() || 'general'),
      snapshotError:String(error && error.message || 'snapshot_build_failed'),
      panelText:panelElement ? String(panelElement.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 4000) : ''
    });
  }
}

async function copyTextToClipboard(text){
  const value = String(text || '');
  if(typeof navigator !== 'undefined' && navigator.clipboard && typeof navigator.clipboard.writeText === 'function'){
    try{
      await navigator.clipboard.writeText(value);
      return true;
    }catch(error){}
  }
  const previouslyFocused = document.activeElement;
  const textarea = document.createElement('textarea');
  textarea.value = value;
  textarea.setAttribute('readonly', 'readonly');
  textarea.style.position = 'fixed';
  textarea.style.opacity = '0';
  document.body.appendChild(textarea);
  let copied = false;
  try{
    textarea.focus({preventScroll:true});
    textarea.select();
    copied = document.execCommand('copy');
  }catch(error){
    copied = false;
  }finally{
    textarea.remove();
    if(previouslyFocused && typeof previouslyFocused.focus === 'function' && document.contains(previouslyFocused)){
      try{
        previouslyFocused.focus({preventScroll:true});
      }catch(error){}
    }
  }
  return copied;
}

function showManualSnapshotCopyText(text){
  const wrap = $('testerSnapshotManualCopyWrap');
  const field = $('testerSnapshotManualCopyText');
  if(!wrap || !field) return false;
  wrap.hidden = false;
  field.value = String(text || '');
  return true;
}

async function copyTesterDiagnosticSnapshot(options = {}){
  let snapshot;
  let snapshotText = '';
  try{
    snapshot = buildTesterDiagnosticSnapshot(options);
    snapshotText = JSON.stringify(snapshot, null, 2);
  }catch(error){
    snapshot = {
      timestamp:new Date().toISOString(),
      panelTitle:String(options && options.panelTitle || 'General diagnostics'),
      ticker:String(activeReviewTicker() || 'general'),
      snapshotError:String(error && error.message || 'snapshot_stringify_failed')
    };
    snapshotText = JSON.stringify(snapshot, null, 2);
  }
  uiState.lastTesterDiagnosticSnapshot = snapshot;
  const copied = await copyTextToClipboard(snapshotText);
  if(copied){
    const status = $('testerReportSnapshotStatus');
    if(status) status.textContent = `Snapshot copied: ${snapshot.panelTitle} | ${formatLocalTimestamp(snapshot.timestamp) || snapshot.timestamp}.`;
  }else{
    showManualSnapshotCopyText(snapshotText);
    const status = $('testerReportSnapshotStatus');
    if(status) status.textContent = 'Clipboard copy failed. Snapshot text opened below for manual copy.';
  }
  return copied;
}

function exportTesterDiagnosticSnapshot(options = {}){
  const snapshot = options.snapshot && typeof options.snapshot === 'object'
    ? options.snapshot
    : (uiState.lastTesterDiagnosticSnapshot || buildTesterDiagnosticSnapshot(options));
  uiState.lastTesterDiagnosticSnapshot = snapshot;
  const ticker = String(snapshot.ticker || 'general').trim().toUpperCase() || 'GENERAL';
  const panelSlug = String(snapshot.panelTitle || 'diagnostics')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'diagnostics';
  const filename = `pullback-playbook-review-snapshot-${ticker}-${panelSlug}-${todayIsoDate()}.json`;
  const ok = downloadJsonFile(filename, snapshot);
  const status = $('testerReportSnapshotStatus');
  if(status){
    status.textContent = ok
      ? `Snapshot exported: ${filename}`
      : 'Snapshot export failed.';
  }
  return ok;
}

