function normalizeTickerRecordsMap(records){
  const out = {};
  if(!records || typeof records !== 'object') return out;
  Object.entries(records).forEach(([ticker, record]) => {
    const normalized = normalizeTickerRecordReadOnly({...record, ticker});
    if(normalized.ticker) out[normalized.ticker] = normalized;
  });
  return out;
}

function normalizeDetachedTickerRecord(record){
  return normalizeTickerRecordReadOnly(record && typeof record === 'object' ? record : {});
}

function buildCanonicalPlanVerdictContract(record, context = {}){
  const item = normalizeDetachedTickerRecord(record);
  if(window.PlanVerdictContract && typeof window.PlanVerdictContract.buildPlanVerdictContract === 'function'){
    return window.PlanVerdictContract.buildPlanVerdictContract(item, context);
  }
  const fallbackVerdict = normalizeGlobalVerdictKey(
    context && context.resolvedContract && (
      context.resolvedContract.canonical_final_verdict
      || context.resolvedContract.final_verdict_rendered
      || context.resolvedContract.final_verdict
      || context.resolvedContract.finalVerdict
    )
    || context && context.globalVerdict && (
      context.globalVerdict.final_verdict
      || context.globalVerdict.finalVerdict
    )
    || item.review && item.review.savedVerdict
    || item.scan && (item.scan.resolvedVerdict || item.scan.verdict)
    || 'watch'
  );
  return {
    schemaVersion:'plan-verdict-contract-fallback-v1',
    ticker:String(item.ticker || '').trim().toUpperCase(),
    canonicalVerdict:fallbackVerdict,
    canonicalVisualBucket:normalizeVisualBucketForPairing(fallbackVerdict, fallbackVerdict),
    derivedStates:{
      setupScore:setupScoreForRecord(item),
      planReady:recordPlanHasConcreteValues(item),
      planStatus:String(context && context.displayedPlan && context.displayedPlan.status || '').trim().toLowerCase() || 'missing',
      inWatchlist:!!(item.watchlist && item.watchlist.inWatchlist)
    },
    planAuthority:{
      entry:numericOrNull(context && context.effectivePlan && context.effectivePlan.entry || item.plan && item.plan.entry),
      stop:numericOrNull(context && context.effectivePlan && context.effectivePlan.stop || item.plan && item.plan.stop),
      firstTarget:numericOrNull(context && context.effectivePlan && context.effectivePlan.firstTarget || item.plan && item.plan.firstTarget),
      source:String(context && context.effectivePlan && context.effectivePlan.source || item.plan && item.plan.source || '').trim().toLowerCase() || 'none',
      stamped:hasCanonicalTradePlanStamp(item.plan)
    },
    lifecycleAuthority:{
      stage:String(context && context.lifecycleSnapshot && context.lifecycleSnapshot.stage || item.lifecycle && item.lifecycle.stage || '').trim().toLowerCase(),
      status:String(context && context.lifecycleSnapshot && context.lifecycleSnapshot.status || item.lifecycle && item.lifecycle.status || '').trim().toLowerCase(),
      state:String(context && context.lifecycleSnapshot && context.lifecycleSnapshot.state || fallbackVerdict).trim().toLowerCase()
    },
    paperTradeAuthority:{
      submittedTrades:[]
    },
    diagnostics:{
      source:String(context.source || '').trim().toLowerCase(),
      surface:String(context.surface || '').trim().toLowerCase(),
      reason:String(context.reason || '').trim()
    },
    contractFingerprint:`fallback_${String(item.ticker || '').trim().toUpperCase()}`
  };
}

function buildCanonicalRenderModelsFromRecord(record, context = {}, uiDraftState = null){
  const contract = buildCanonicalPlanVerdictContract(record, context);
  if(window.PlanVerdictContract){
    return {
      contract,
      reviewRenderModel:typeof window.PlanVerdictContract.buildReviewRenderModel === 'function'
        ? window.PlanVerdictContract.buildReviewRenderModel(contract, uiDraftState)
        : null,
      trackRenderModel:typeof window.PlanVerdictContract.buildTrackRenderModel === 'function'
        ? window.PlanVerdictContract.buildTrackRenderModel(contract)
        : null,
      trackLongPressModel:typeof window.PlanVerdictContract.buildTrackLongPressModel === 'function'
        ? window.PlanVerdictContract.buildTrackLongPressModel(contract)
        : null
    };
  }
  const fallbackVerdict = normalizeGlobalVerdictKey(contract && contract.canonicalVerdict || 'watch');
  const fallbackBucket = normalizeVisualBucketForPairing(contract && contract.canonicalVisualBucket || fallbackVerdict);
  const fallbackLabel = globalVerdictLabel(fallbackVerdict || 'watch');
  const fallbackNextAction = fallbackVerdict === 'entry'
    ? 'Execute only if the trigger remains valid.'
    : 'Wait for stronger confirmation before considering entry.';
  const fallbackPrimaryReason = fallbackVerdict === 'entry'
    ? 'Buyers are in control and the setup is ready to act on.'
    : (fallbackVerdict === 'near_entry'
      ? 'The setup is close, but confirmation still needs to improve.'
      : 'Confirmation is still developing, so the setup stays on watch.');
  const reviewRenderModel = {
    ticker:String(contract && contract.ticker || ''),
    canonicalVerdict:fallbackVerdict,
    visualBucket:fallbackBucket,
    tone:fallbackBucket,
    badgeLabel:fallbackLabel,
    headline:fallbackVerdict === 'entry' ? 'Entry Ready' : fallbackLabel,
    nextAction:fallbackNextAction,
    primaryReason:fallbackPrimaryReason,
    planVisible:fallbackVerdict === 'entry',
    planStatus:String(contract && contract.derivedStates && contract.derivedStates.planStatus || 'missing').trim().toLowerCase(),
    setupScore:numericOrNull(contract && contract.derivedStates && contract.derivedStates.setupScore),
    actionable:fallbackVerdict === 'entry' && !!(contract && contract.planAuthority && contract.planAuthority.stamped),
    draftState:cloneData(uiDraftState, null),
    contractFingerprint:String(contract && contract.contractFingerprint || '')
  };
  const trackRenderModel = {
    ...reviewRenderModel,
    visibleBucket:reviewRenderModel.visualBucket,
    statusText:reviewRenderModel.headline,
    actionLabel:reviewRenderModel.nextAction,
    mainBlocker:reviewRenderModel.primaryReason,
    planSummary:reviewRenderModel.planVisible ? 'Trade plan available.' : 'No actionable trade plan yet.',
    inWatchlist:contract && contract.derivedStates && contract.derivedStates.inWatchlist === true
  };
  return {
    contract,
    reviewRenderModel,
    trackRenderModel,
    trackLongPressModel:{
      ticker:reviewRenderModel.ticker,
      canonicalVerdict:reviewRenderModel.canonicalVerdict,
      header:reviewRenderModel.headline,
      actionable:reviewRenderModel.actionable === true,
      nextAction:reviewRenderModel.nextAction,
      primaryReason:reviewRenderModel.primaryReason,
      visualBucket:reviewRenderModel.visualBucket,
      contractFingerprint:reviewRenderModel.contractFingerprint
    }
  };
}

function cloneData(value, fallback = null){
  return safeJsonParse(JSON.stringify(value == null ? fallback : value), fallback);
}

function safeDiagnosticClone(value, fallback = null){
  const seen = new WeakSet();
  try{
    const json = JSON.stringify(value == null ? fallback : value, (key, currentValue) => {
      if(typeof currentValue === 'bigint') return Number(currentValue);
      if(typeof currentValue === 'function') return '[Function]';
      if(currentValue && typeof currentValue === 'object'){
        if(seen.has(currentValue)) return '[Circular]';
        seen.add(currentValue);
      }
      return currentValue;
    });
    return safeJsonParse(json, fallback);
  }catch(error){
    return fallback;
  }
}

function canonicalDisplayDivergenceSummary(contract, persistedPresentation, renderModel){
  const safeContract = contract && typeof contract === 'object' ? contract : {};
  const safePresentation = persistedPresentation && typeof persistedPresentation === 'object' ? persistedPresentation : null;
  const safeRenderModel = renderModel && typeof renderModel === 'object' ? renderModel : {};
  const persistedVerdict = normalizeGlobalVerdictKey(
    safePresentation && (
      safePresentation.canonicalVerdict
      || safePresentation.finalVerdict
      || safePresentation.renderedVerdict
    )
    || ''
  );
  const persistedBucket = normalizeVisualBucketForPairing(
    safePresentation && (
      safePresentation.sourceOfTruthVisualBucket
      || safePresentation.visualBucket
      || safePresentation.renderedBucket
    )
    || '',
    persistedVerdict
  );
  const canonicalVerdict = normalizeGlobalVerdictKey(safeContract.canonicalVerdict || safeRenderModel.canonicalVerdict || 'watch');
  const canonicalBucket = normalizeVisualBucketForPairing(
    safeContract.canonicalVisualBucket
    || safeRenderModel.visibleBucket
    || safeRenderModel.visualBucket
    || canonicalVerdict,
    canonicalVerdict
  );
  return {
    persistedPresentationAvailable:!!safePresentation,
    contractFingerprint:String(safeContract.contractFingerprint || ''),
    canonicalVerdict,
    canonicalVisualBucket:canonicalBucket,
    persistedVerdict,
    persistedVisualBucket:persistedBucket,
    verdictConflict:!!(safePresentation && persistedVerdict && canonicalVerdict && persistedVerdict !== canonicalVerdict),
    bucketConflict:!!(safePresentation && persistedBucket && canonicalBucket && persistedBucket !== canonicalBucket)
  };
}

function canonicalPersistenceInputDivergence(record, contract){
  const item = record && typeof record === 'object' ? record : {};
  const safeContract = contract && typeof contract === 'object' ? contract : {};
  const inputs = safeContract.authoritativeInputs && typeof safeContract.authoritativeInputs === 'object'
    ? safeContract.authoritativeInputs
    : {};
  const reviewInputs = inputs.reviewAuthority && typeof inputs.reviewAuthority === 'object'
    ? inputs.reviewAuthority
    : {};
  const planInputs = inputs.planAuthority && typeof inputs.planAuthority === 'object'
    ? inputs.planAuthority
    : {};
  const review = item.review && typeof item.review === 'object' ? item.review : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const savedVerdict = normalizeOptionalGlobalVerdictKey(review.savedVerdict || '');
  const canonicalVerdict = normalizeGlobalVerdictKey(safeContract.canonicalVerdict || 'watch');
  return {
    contractFingerprint:String(safeContract.contractFingerprint || ''),
    savedReviewVerdict:String(reviewInputs.savedVerdict || '').trim(),
    canonicalVerdict,
    savedReviewConflict:!!(savedVerdict && canonicalVerdict && savedVerdict !== canonicalVerdict),
    planStamped:!!(planInputs.authoritySource && planInputs.authorityVersion),
    rawPlanHasConcreteValues:recordPlanHasConcreteValues(plan),
    unstampedConcretePlan:recordPlanHasConcreteValues(plan) && !(planInputs.authoritySource && planInputs.authorityVersion),
    persistedProjectionSnapshotPresent:!!persistedReviewProjectionSnapshot(item, 'diagnostic_divergence'),
    submittedPaperTradeAt:String(planInputs.submittedPaperTradeAt || '').trim()
  };
}

function chartImageDimensionsFromRef(ref){
  const safe = ref && typeof ref === 'object' ? ref : {};
  const width = numericOrNull(safe.width);
  const height = numericOrNull(safe.height);
  return {
    width:Number.isFinite(width) ? width : null,
    height:Number.isFinite(height) ? height : null
  };
}

function chartImageDimensionsLabel(ref){
  const dims = chartImageDimensionsFromRef(ref);
  return Number.isFinite(dims.width) && Number.isFinite(dims.height)
    ? `${Math.round(dims.width)}x${Math.round(dims.height)}`
    : 'unknown';
}

function simpleStableHash(value){
  const text = String(value || '');
  let hash = 2166136261;
  for(let index = 0; index < text.length; index++){
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `img_${(hash >>> 0).toString(16)}_${text.length}`;
}

function chartImageIdForReview(review = {}){
  const safe = review && typeof review === 'object' ? review : {};
  const explicit = safe.chartImageVerificationSource && safe.chartImageVerificationSource.imageId
    || safe.chartImageOriginal && safe.chartImageOriginal.imageId
    || safe.chartRef && safe.chartRef.imageId
    || safe.chartImagePreview && safe.chartImagePreview.imageId;
  if(explicit) return String(explicit);
  const dataUrl = safe.chartRef && safe.chartRef.dataUrl || safe.chartImagePreview && safe.chartImagePreview.dataUrl || '';
  return dataUrl ? simpleStableHash(dataUrl) : '';
}

function logChartVerificationLifecycle(event, payload = {}){
  if(typeof console === 'undefined' || !console.info) return;
  console.info('[CHART_VERIFICATION_LIFECYCLE]', {
    event,
    ...payload
  });
}

function logChartRequestIdMutation({oldRequestId = '', newRequestId = '', reason = '', caller = '', ticker = '', imageId = ''} = {}){
  const previous = String(oldRequestId || '');
  const next = String(newRequestId || '');
  if(previous === next) return;
  if(typeof console === 'undefined' || !console.info) return;
  console.info('[CHART_REQUEST_ID_MUTATION]', {
    oldRequestId:previous,
    newRequestId:next,
    reason:String(reason || ''),
    caller:String(caller || ''),
    ticker:normalizeTicker(ticker || ''),
    imageId:String(imageId || '')
  });
}

function buildChartImageSourceTrace(review = {}){
  const safe = review && typeof review === 'object' ? review : {};
  const chartRef = safe.chartRef && typeof safe.chartRef === 'object' ? safe.chartRef : null;
  const originalMeta = safe.chartImageOriginal && typeof safe.chartImageOriginal === 'object' ? safe.chartImageOriginal : null;
  const previewMeta = safe.chartImagePreview && typeof safe.chartImagePreview === 'object' ? safe.chartImagePreview : null;
  const explicitVerification = safe.chartImageVerificationSource && typeof safe.chartImageVerificationSource === 'object'
    ? safe.chartImageVerificationSource
    : null;
  const originalAvailable = !!(originalMeta && (originalMeta.dataUrl || (originalMeta.dataUrlField && chartRef && chartRef.dataUrl)));
  const sourceRef = originalAvailable
    ? {...(chartRef || {}), ...originalMeta}
    : (chartRef || previewMeta || null);
  const sourceKind = originalAvailable
    ? 'chartImageOriginal'
    : (chartRef && chartRef.dataUrl ? 'legacy_chartRef_fallback' : (previewMeta ? 'chartImagePreview_fallback' : 'none'));
  const originalDimensions = originalMeta || chartRef || null;
  const previewDimensions = previewMeta || chartRef || null;
  const verificationDimensions = explicitVerification || sourceRef || null;
  const originalDims = chartImageDimensionsFromRef(originalDimensions);
  const previewDims = chartImageDimensionsFromRef(previewDimensions);
  const verificationDims = chartImageDimensionsFromRef(verificationDimensions);
  const previewHasIndependentData = !!(previewMeta && previewMeta.dataUrl && chartRef && chartRef.dataUrl && previewMeta.dataUrl !== chartRef.dataUrl);
  const resizedPreview = Number.isFinite(originalDims.width)
    && Number.isFinite(originalDims.height)
    && Number.isFinite(previewDims.width)
    && Number.isFinite(previewDims.height)
    && (Math.round(originalDims.width) !== Math.round(previewDims.width) || Math.round(originalDims.height) !== Math.round(previewDims.height));
  const fallbackUsed = sourceKind !== 'chartImageOriginal' && sourceKind !== 'none';
  const sourceField = sourceKind === 'chartImageOriginal'
    ? (originalMeta && originalMeta.dataUrlField || 'chartRef.dataUrl')
    : (sourceKind === 'legacy_chartRef_fallback'
      ? 'chartRef.dataUrl'
      : (sourceKind === 'chartImagePreview_fallback' ? 'chartImagePreview.dataUrl' : ''));
  return {
    sourceKind,
    originalAvailable,
    fallbackUsed,
    limited:!!fallbackUsed,
    sourceField,
    imageId:chartImageIdForReview(safe),
    originalDimensions:chartImageDimensionsLabel(originalDimensions),
    previewDimensions:chartImageDimensionsLabel(previewDimensions),
    verificationSourceDimensions:chartImageDimensionsLabel(verificationDimensions),
    cropOrResizeOccurred:!!(previewHasIndependentData || resizedPreview),
    objectFit:'cover (preview only)',
    displayMode:previewMeta && previewMeta.displayMode || 'thumb_object_fit_cover',
    verificationUsesCroppedPreview:false,
    debug:{
      originalDims,
      previewDims,
      verificationDims,
      previewHasIndependentData,
      resizedPreview,
      explicitVerificationSource:explicitVerification && explicitVerification.source || ''
    }
  };
}

function hasVerifiableReviewChartSource(review = {}){
  return buildChartImageSourceTrace(review).originalAvailable === true;
}

function chartImageForAnalysis(review = {}){
  const safe = review && typeof review === 'object' ? review : {};
  const sourceTrace = buildChartImageSourceTrace(safe);
  const chartRef = safe.chartRef && typeof safe.chartRef === 'object' ? safe.chartRef : null;
  const originalMeta = safe.chartImageOriginal && typeof safe.chartImageOriginal === 'object' ? safe.chartImageOriginal : null;
  const originalDataUrl = originalMeta && typeof originalMeta.dataUrl === 'string'
    ? originalMeta.dataUrl
    : (chartRef && typeof chartRef.dataUrl === 'string' ? chartRef.dataUrl : '');
  const previewMeta = safe.chartImagePreview && typeof safe.chartImagePreview === 'object' ? safe.chartImagePreview : null;
  const previewDataUrl = previewMeta && typeof previewMeta.dataUrl === 'string' ? previewMeta.dataUrl : '';
  const dataUrl = originalDataUrl || previewDataUrl;
  if(debugFlagEnabled('PP_DEBUG_CHART_TRACE') && typeof console !== 'undefined' && console.info){
    console.info('[CHART_EXTRACTION_INPUT]', {
      ticker:String(safe.ticker || '').trim(),
      imageSource:sourceTrace.sourceKind || '',
      hasOriginal:!!originalMeta,
      hasPreview:!!previewMeta,
      hasChartImageForAnalysis:!!dataUrl,
      originalDimensions:sourceTrace.originalDimensions || 'unknown',
      verificationDimensions:sourceTrace.verificationSourceDimensions || 'unknown'
    });
  }
  return {
    chartRef:dataUrl ? {
      name:String((originalMeta && originalMeta.name) || (chartRef && chartRef.name) || 'chart.png'),
      type:String((originalMeta && originalMeta.type) || (chartRef && chartRef.type) || 'image/png'),
      dataUrl,
      width:chartImageDimensionsFromRef(originalMeta || chartRef).width,
      height:chartImageDimensionsFromRef(originalMeta || chartRef).height,
      verificationSource:sourceTrace.sourceKind
    } : null,
    sourceTrace
  };
}

function clearReviewChartImageSources(review){
  if(!review || typeof review !== 'object') return;
  if(typeof closeReviewChartLightbox === 'function'){
    closeReviewChartLightbox();
  }
  const currentImageId = String(chartImageIdForReview(review) || '');
  const currentTicker = normalizeTicker(review.ticker || review.expectedTicker || '');
  const pipelineRequestId = String(review.chartAnalysisPipeline && review.chartAnalysisPipeline.requestId || '');
  if(pipelineRequestId){
    logChartRequestIdMutation({
      oldRequestId:pipelineRequestId,
      newRequestId:'',
      reason:'clear_review_chart_image_sources_pipeline',
      caller:'clearReviewChartImageSources',
      ticker:currentTicker,
      imageId:currentImageId
    });
  }
  review.chartRef = null;
  review.chartImageOriginal = null;
  review.chartImagePreview = null;
  review.chartImageVerificationSource = null;
  review.chartAttachmentContext = null;
  review.chartAnalysisPipeline = null;
  review.chartAvailable = false;
}

function reviewDisplayedChartContext(review = {}){
  const safe = review && typeof review === 'object' ? review : {};
  const previewRef = (safe.chartImagePreview && safe.chartImagePreview.dataUrl)
    ? safe.chartImagePreview
    : (safe.chartImageOriginal && safe.chartImageOriginal.dataUrl
      ? safe.chartImageOriginal
      : safe.chartRef);
  const attachmentContext = safe.chartAttachmentContext && typeof safe.chartAttachmentContext === 'object'
    ? safe.chartAttachmentContext
    : null;
  return {
    imageId:String(previewRef && previewRef.imageId || chartImageIdForReview(safe) || ''),
    filename:String(previewRef && previewRef.name || attachmentContext && attachmentContext.name || safe.chartRef && safe.chartRef.name || ''),
    ticker:normalizeTicker(previewRef && previewRef.ticker || attachmentContext && attachmentContext.expectedTicker || ''),
    requestId:String(previewRef && previewRef.requestId || attachmentContext && attachmentContext.requestId || '')
  };
}

function currentReviewChartContext(record = {}, review = null){
  const item = record && typeof record === 'object' ? record : {};
  const safeReview = review && typeof review === 'object'
    ? review
    : (item.review && typeof item.review === 'object' ? item.review : {});
  const attachmentContext = safeReview.chartAttachmentContext && typeof safeReview.chartAttachmentContext === 'object'
    ? safeReview.chartAttachmentContext
    : null;
  const pipeline = safeReview.chartAnalysisPipeline && typeof safeReview.chartAnalysisPipeline === 'object'
    ? safeReview.chartAnalysisPipeline
    : null;
  const runtime = getReviewAiRuntime();
  const ticker = normalizeTicker(item.ticker || safeReview.ticker || attachmentContext && attachmentContext.expectedTicker || pipeline && pipeline.ticker || '');
  const imageId = String(
    chartImageIdForReview(safeReview)
    || attachmentContext && attachmentContext.imageId
    || pipeline && pipeline.imageId
    || ''
  );
  let requestId = String(
    attachmentContext && attachmentContext.requestId
    || pipeline && pipeline.requestId
    || ''
  );
  if(!requestId && runtime && normalizeTicker(runtime.ticker || '') === ticker){
    const runtimeImageId = String(runtime.chartImageId || '');
    if(!imageId || !runtimeImageId || runtimeImageId === imageId){
      requestId = String(runtime.requestId || '');
    }
  }
  return {
    ticker,
    imageId,
    requestId
  };
}

function getReviewChartAnalysisPipeline(record = {}){
  const item = record && typeof record === 'object' ? record : {};
  const review = item.review && typeof item.review === 'object' ? item.review : null;
  if(!review || !review.chartAnalysisPipeline || typeof review.chartAnalysisPipeline !== 'object') return null;
  return review.chartAnalysisPipeline;
}

function clearLegacyChartAnalysisState(review = {}){
  const safe = review && typeof review === 'object' ? review : null;
  if(!safe) return;
  safe.pendingChartAiSummary = null;
  safe.rawChartFactExtraction = null;
  safe.aiAnalysisRaw = '';
  safe.normalizedAnalysis = null;
}

function buildChartPipelineExpectedFacts(record = {}){
  const item = record && typeof record === 'object' ? record : {};
  return {
    ticker:normalizeTicker(item.ticker || ''),
    timeframe:'1D',
    price:chartVerificationNumberOrNull((item.marketData && item.marketData.price) ?? item.price),
    ma20:chartVerificationNumberOrNull(item.marketData && item.marketData.ma20),
    ma50:chartVerificationNumberOrNull(item.marketData && item.marketData.ma50),
    ma200:chartVerificationNumberOrNull(item.marketData && item.marketData.ma200)
  };
}

function buildChartPipelineReadFacts(source = {}){
  const safe = source && typeof source === 'object' ? source : {};
  return {
    ticker:normaliseVisibleTicker(safe.ticker || safe.extractedTicker || safe.visible_ticker || ''),
    timeframe:String(safe.timeframe || safe.extractedTimeframe || safe.visible_timeframe || '').trim(),
    price:chartVerificationNumberOrNull(safe.price ?? safe.extractedPrice ?? safe.visible_latest_price),
    ma20:chartVerificationNumberOrNull(safe.ma20 ?? safe.extractedMa20 ?? safe.visible_ma20),
    ma50:chartVerificationNumberOrNull(safe.ma50 ?? safe.extractedMa50 ?? safe.visible_ma50),
    ma200:chartVerificationNumberOrNull(safe.ma200 ?? safe.extractedMa200 ?? safe.visible_ma200)
  };
}

function chartPipelineHasAnyReadFacts(read = {}){
  const safe = read && typeof read === 'object' ? read : {};
  return !!(
    String(safe.ticker || '').trim()
    || String(safe.timeframe || '').trim()
    || chartVerificationNumberOrNull(safe.price) !== null
    || chartVerificationNumberOrNull(safe.ma20) !== null
    || chartVerificationNumberOrNull(safe.ma50) !== null
    || chartVerificationNumberOrNull(safe.ma200) !== null
  );
}

function chartPipelineStatusFromPhase(phase = ''){
  switch(String(phase || '').trim()){
    case 'uploading':
    case 'verifying':
      return 'source_checking';
    case 'verified':
    case 'analysis_running':
    case 'analysis_complete':
      return 'verified_match';
    case 'possible_mismatch':
      return 'chart_mismatch';
    case 'cant_read':
      return 'manual_confirmation_required';
    case 'analysis_failed':
      // Intentionally blank here. Do not use chartPipelineStatusFromPhase() alone
      // to derive Review chart status for failed AI analysis.
      // analysis_failed is resolved in buildSimplifiedChartPipelineTrace() so
      // chart verification can remain matched while AI failure is shown separately.
      return '';
    default:
      return '';
  }
}

function chartPipelineAllowsAi(phase = ''){
  return ['verified', 'analysis_running', 'analysis_complete'].includes(String(phase || '').trim());
}

function chartPipelineHasVerifiedIdentity(pipeline = {}){
  const safe = pipeline && typeof pipeline === 'object' ? pipeline : {};
  const readFacts = safe.readFacts && typeof safe.readFacts === 'object' ? safe.readFacts : {};
  const verifiedReadTicker = normaliseVisibleTicker(readFacts.ticker || '');
  return safe.manualConfirmed === true || (!!verifiedReadTicker && safe.verifiedMatch === true);
}

function chartPipelineHasDetectedTickerMatch(pipeline = {}){
  const safe = pipeline && typeof pipeline === 'object' ? pipeline : {};
  const readFacts = safe.readFacts && typeof safe.readFacts === 'object' ? safe.readFacts : {};
  const detectedTicker = normaliseVisibleTicker(readFacts.ticker || '');
  return !!(detectedTicker && safe.verifiedMatch === true);
}

function chartPipelineHasManualConfirmedMismatch(pipeline = {}, expectedTicker = ''){
  const safe = pipeline && typeof pipeline === 'object' ? pipeline : {};
  const readFacts = safe.readFacts && typeof safe.readFacts === 'object' ? safe.readFacts : {};
  const expected = normaliseVisibleTicker(expectedTicker || safe.ticker || safe.expectedFacts && safe.expectedFacts.ticker || '');
  const detectedTicker = normaliseVisibleTicker(readFacts.ticker || '');
  return !!(
    safe.manualConfirmed === true
    && detectedTicker
    && expected
    && detectedTicker !== expected
  );
}

function mergeChartPipelineReadFacts(primary = {}, fallback = {}){
  const first = primary && typeof primary === 'object' ? primary : {};
  const second = fallback && typeof fallback === 'object' ? fallback : {};
  return {
    ticker:String(first.ticker || second.ticker || '').trim(),
    timeframe:String(first.timeframe || second.timeframe || '').trim(),
    price:chartVerificationNumberOrNull(first.price) !== null
      ? chartVerificationNumberOrNull(first.price)
      : chartVerificationNumberOrNull(second.price),
    ma20:chartVerificationNumberOrNull(first.ma20) !== null
      ? chartVerificationNumberOrNull(first.ma20)
      : chartVerificationNumberOrNull(second.ma20),
    ma50:chartVerificationNumberOrNull(first.ma50) !== null
      ? chartVerificationNumberOrNull(first.ma50)
      : chartVerificationNumberOrNull(second.ma50),
    ma200:chartVerificationNumberOrNull(first.ma200) !== null
      ? chartVerificationNumberOrNull(first.ma200)
      : chartVerificationNumberOrNull(second.ma200)
  };
}

function preserveManualConfirmIdentityReadFacts(existingReadFacts = {}, promotedReadFacts = {}, expectedTicker = ''){
  const existing = existingReadFacts && typeof existingReadFacts === 'object' ? existingReadFacts : {};
  const promoted = promotedReadFacts && typeof promotedReadFacts === 'object' ? promotedReadFacts : {};
  const expected = normaliseVisibleTicker(expectedTicker || '');
  const existingTicker = normaliseVisibleTicker(existing.ticker || '');
  const promotedTicker = normaliseVisibleTicker(promoted.ticker || '');
  const merged = mergeChartPipelineReadFacts(promoted, existing);
  const existingMismatch = !!(existingTicker && expected && existingTicker !== expected);
  const promotedMismatch = !!(promotedTicker && expected && promotedTicker !== expected);
  if(existingMismatch && !promotedMismatch){
    merged.ticker = String(existing.ticker || '').trim();
    if(!String(merged.timeframe || '').trim() && String(existing.timeframe || '').trim()){
      merged.timeframe = String(existing.timeframe || '').trim();
    }
    if(chartVerificationNumberOrNull(merged.price) === null && chartVerificationNumberOrNull(existing.price) !== null){
      merged.price = chartVerificationNumberOrNull(existing.price);
    }
  }
  return merged;
}

function chartPipelineContextMatches(record = {}, pipeline = {}, source = {}){
  const item = record && typeof record === 'object' ? record : {};
  const safePipeline = pipeline && typeof pipeline === 'object' ? pipeline : {};
  const safeSource = source && typeof source === 'object' ? source : {};
  const pipelineImageId = String(safePipeline.imageId || chartImageIdForReview(item.review || {}) || '').trim();
  const pipelineRequestId = String(safePipeline.requestId || '').trim();
  const sourceImageId = String(safeSource.imageId || safeSource.chartImageId || '').trim();
  const sourceRequestId = String(safeSource.requestId || safeSource.verificationRequestId || '').trim();
  if(pipelineImageId && sourceImageId && pipelineImageId !== sourceImageId) return false;
  if(pipelineRequestId && sourceRequestId && pipelineRequestId !== sourceRequestId) return false;
  return !!(pipelineImageId || sourceImageId || pipelineRequestId || sourceRequestId);
}

function recoverChartPipelineReadFacts(record = {}, pipeline = {}){
  const safePipeline = pipeline && typeof pipeline === 'object' ? pipeline : {};
  return buildChartPipelineReadFacts(safePipeline.readFacts || {});
}

function normalizeChartPipelineForRender(record = {}, pipeline = {}){
  const safe = pipeline && typeof pipeline === 'object' ? pipeline : {};
  const normalized = cloneData(safe, {});
  normalized.readFacts = recoverChartPipelineReadFacts(record, normalized);
  const expectedTicker = normaliseVisibleTicker(
    normalized.expectedFacts && normalized.expectedFacts.ticker
      || record && record.ticker
      || ''
  );
  const recoveredTicker = normaliseVisibleTicker(normalized.readFacts && normalized.readFacts.ticker || '');
  if(recoveredTicker && expectedTicker){
    normalized.observedTicker = recoveredTicker;
    if(recoveredTicker === expectedTicker){
      normalized.verifiedMatch = true;
      normalized.mismatch = false;
      if(['cant_read', 'possible_mismatch', 'uploading', 'verifying'].includes(String(normalized.phase || '').trim())){
        normalized.phase = 'verified';
      }
    }else{
      normalized.verifiedMatch = false;
      normalized.mismatch = true;
      if(normalized.manualConfirmed === true){
        if(!String(normalized.phase || '').trim()){
          normalized.phase = 'verified';
        }
      }else{
        normalized.phase = 'possible_mismatch';
      }
    }
  }
  normalized.aiAllowed = chartPipelineAllowsAi(normalized.phase) && chartPipelineHasVerifiedIdentity(normalized);
  const hasVerifiedIdentity = chartPipelineHasVerifiedIdentity(normalized);
  if(!hasVerifiedIdentity && normalized.manualConfirmed !== true){
    if(!normalized.mismatch && ['verified', 'analysis_running', 'analysis_complete'].includes(String(normalized.phase || '').trim())){
      normalized.phase = 'cant_read';
    }
  }
  normalized.aiAllowed = chartPipelineAllowsAi(normalized.phase) && chartPipelineHasVerifiedIdentity(normalized);
  return normalized;
}

function ensureSimplifiedChartPipelineForRender(record = {}, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const review = item.review && typeof item.review === 'object' ? item.review : null;
  if(!review) return null;
  const chartImageSource = buildChartImageSourceTrace(review);
  if(chartImageSource.originalAvailable !== true) return null;
  const currentImageId = String(chartImageIdForReview(review) || '').trim();
  const currentContext = currentReviewChartContext(item, review);
  const currentRequestId = String(currentContext.requestId || '').trim();
  const existing = getReviewChartAnalysisPipeline(item);
  const currentTicker = normalizeTicker(item.ticker || '');
  const existingTicker = normalizeTicker(existing && existing.ticker || '');
  const existingImageId = String(existing && existing.imageId || '').trim();
  const existingRequestId = String(existing && existing.requestId || '').trim();
  const existingMatchesCurrentImage = !!(
    existing
    && currentImageId
    && existingTicker === currentTicker
    && existingImageId === currentImageId
  );
  const existingMatchesCurrentRequest = !!(
    existingMatchesCurrentImage
    && (
      (currentRequestId && existingRequestId && currentRequestId === existingRequestId)
      || (!currentRequestId && ['uploading', 'verifying'].includes(String(existing && existing.phase || '').trim()))
    )
  );
  const reusedExistingRequestId = existingMatchesCurrentRequest ? existingRequestId : '';
  if(existingMatchesCurrentImage && !existingMatchesCurrentRequest && typeof console !== 'undefined' && console.warn){
    console.warn('[REVIEW_CHART_PIPELINE_STALE_REQUEST_IGNORED]', {
      ticker:currentTicker,
      imageId:currentImageId,
      oldRequestId:existingRequestId,
      currentRequestId,
      oldPhase:String(existing && existing.phase || ''),
      recoveryAction:'rebuild_or_reset'
    });
  }
  const expectedFacts = buildChartPipelineExpectedFacts(item);
  const recoveredReadFacts = recoverChartPipelineReadFacts(item, {
    imageId:currentImageId,
    requestId:currentRequestId,
    expectedFacts,
    readFacts:existingMatchesCurrentImage && existingMatchesCurrentRequest && existing && existing.readFacts || {}
  });
  const expectedTicker = normaliseVisibleTicker(expectedFacts.ticker || '');
  const recoveredTicker = normaliseVisibleTicker(recoveredReadFacts.ticker || '');
  const mismatch = !!(recoveredTicker && expectedTicker && recoveredTicker !== expectedTicker);
  const verifiedMatch = !!(recoveredTicker && expectedTicker && recoveredTicker === expectedTicker);
  const existingPhase = String(existing && existing.phase || '').trim();
  const existingHasVerifiedIdentity = chartPipelineHasVerifiedIdentity(existing || {});
  const shouldReuseExistingCurrentRequest = !!(
    existingMatchesCurrentRequest
    && !(
      ['uploading', 'verifying'].includes(existingPhase)
      && (verifiedMatch || mismatch)
    )
  );
  if(shouldReuseExistingCurrentRequest){
    return normalizeChartPipelineForRender(item, existing);
  }
  const shouldPreserveExistingVerifiedPipeline = !!(
    existingMatchesCurrentImage
    && existingHasVerifiedIdentity
    && ['verified', 'analysis_running', 'analysis_complete', 'analysis_failed'].includes(existingPhase)
    && (
      !currentRequestId
      || !existingRequestId
      || currentRequestId !== existingRequestId
    )
  );
  if(shouldPreserveExistingVerifiedPipeline){
    if(typeof console !== 'undefined' && console.info){
      console.info('[REVIEW_CHART_PIPELINE_VERIFIED_STATE_PRESERVED]', {
        ticker:currentTicker,
        imageId:currentImageId,
        existingRequestId,
        currentRequestId,
        existingPhase
      });
    }
    const preservedPipeline = {
      ...existing,
      imageId:currentImageId,
      requestId:existingRequestId || currentRequestId || '',
      source:String(options.source || existing.source || 'chart_pipeline_verified_state_preserved'),
      updatedAt:String(existing && existing.updatedAt || new Date().toISOString())
    };
    return normalizeChartPipelineForRender(item, preservedPipeline);
  }
  const nextPipeline = {
    version:1,
    ticker:normalizeTicker(item.ticker || expectedFacts.ticker || ''),
    imageId:currentImageId,
    requestId:currentRequestId || reusedExistingRequestId || '',
    source:String(options.source || 'chart_pipeline_render_recovery'),
    phase:mismatch ? 'possible_mismatch' : (verifiedMatch ? 'verified' : 'cant_read'),
    reason:!currentRequestId && !reusedExistingRequestId ? 'pipeline_recovered_without_request' : '',
    expectedFacts,
    readFacts:recoveredReadFacts,
    missing:recoveredTicker ? [] : ['visible ticker'],
    diagnostics:[
      !String(recoveredReadFacts.timeframe || '').trim() ? 'timeframe unreadable' : '',
      chartVerificationNumberOrNull(recoveredReadFacts.price) === null ? 'price unreadable' : '',
      chartVerificationNumberOrNull(recoveredReadFacts.ma20) === null && chartVerificationNumberOrNull(expectedFacts.ma20) === null ? '20 MA unreadable' : '',
      chartVerificationNumberOrNull(recoveredReadFacts.ma50) === null && chartVerificationNumberOrNull(expectedFacts.ma50) === null ? '50 MA unreadable' : '',
      chartVerificationNumberOrNull(recoveredReadFacts.ma200) === null && chartVerificationNumberOrNull(expectedFacts.ma200) === null ? '200 MA unreadable' : ''
    ].filter(Boolean),
    evidence:mismatch
      ? [`Expected ${expectedTicker || 'ticker'} but read ${recoveredTicker || 'n/a'}.`]
      : (verifiedMatch
        ? [`Read ticker ${recoveredTicker || expectedTicker} from the chart image.`]
        : ['Chart verification state was unavailable. Please confirm this is the correct chart.']),
    aiAllowed:verifiedMatch,
    manualConfirmed:false,
    verifiedMatch,
    mismatch,
    hasFacts:chartPipelineHasAnyReadFacts(recoveredReadFacts),
    chartAssessorInput:null,
    chartImageSource,
    updatedAt:new Date().toISOString()
  };
  upsertReviewChartAnalysisPipeline(item, nextPipeline);
  return normalizeChartPipelineForRender(item, nextPipeline);
}

function buildChartPipelineFromVerification(record = {}, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const expected = buildChartPipelineExpectedFacts(item);
  const analysisReadFacts = buildChartPipelineReadFacts(options.analysis || {});
  const assessorReadFacts = buildChartPipelineReadFacts(options.chartAssessorInput || {});
  const read = {
    ticker:String(analysisReadFacts.ticker || '').trim(),
    timeframe:String(analysisReadFacts.timeframe || '').trim(),
    price:chartVerificationNumberOrNull(analysisReadFacts.price),
    ma20:chartVerificationNumberOrNull(analysisReadFacts.ma20) !== null
      ? chartVerificationNumberOrNull(analysisReadFacts.ma20)
      : chartVerificationNumberOrNull(assessorReadFacts.ma20),
    ma50:chartVerificationNumberOrNull(analysisReadFacts.ma50) !== null
      ? chartVerificationNumberOrNull(analysisReadFacts.ma50)
      : chartVerificationNumberOrNull(assessorReadFacts.ma50),
    ma200:chartVerificationNumberOrNull(analysisReadFacts.ma200) !== null
      ? chartVerificationNumberOrNull(analysisReadFacts.ma200)
      : chartVerificationNumberOrNull(assessorReadFacts.ma200)
  };
  const readTicker = normaliseVisibleTicker(read.ticker || '');
  const expectedTicker = normaliseVisibleTicker(expected.ticker || '');
  const tickerMismatch = !!(readTicker && expectedTicker && readTicker !== expectedTicker);
  const verifiedMatch = !!(readTicker && expectedTicker && readTicker === expectedTicker);
  const hasFacts = chartPipelineHasAnyReadFacts(read);
  const phase = tickerMismatch
    ? 'possible_mismatch'
    : (verifiedMatch ? 'verified' : 'cant_read');
  const missing = [];
  if(!read.ticker) missing.push('visible ticker');
  const diagnostics = [];
  if(!read.timeframe) diagnostics.push('timeframe unreadable');
  if(chartVerificationNumberOrNull(read.price) === null) diagnostics.push('price unreadable');
  if(chartVerificationNumberOrNull(read.ma20) === null && chartVerificationNumberOrNull(expected.ma20) === null) diagnostics.push('20 MA unreadable');
  if(chartVerificationNumberOrNull(read.ma50) === null && chartVerificationNumberOrNull(expected.ma50) === null) diagnostics.push('50 MA unreadable');
  if(chartVerificationNumberOrNull(read.ma200) === null && chartVerificationNumberOrNull(expected.ma200) === null) diagnostics.push('200 MA unreadable');
  const evidence = [];
  if(phase === 'possible_mismatch'){
    evidence.push(`Expected ${expectedTicker || 'ticker'} but read ${readTicker || 'n/a'}.`);
    if(chartVerificationNumberOrNull(read.price) !== null){
      evidence.push(`Read latest price ${chartVerificationDisplayValue(read.price)} from the chart image.`);
    }
  }else if(phase === 'verified'){
    evidence.push(`Read ticker ${readTicker || expectedTicker} from the chart image.`);
  }else{
    evidence.push('Unable to read the chart ticker.');
    if(hasFacts){
      if(!read.timeframe) evidence.push('Visible timeframe could not be verified from the chart image.');
      if(chartVerificationNumberOrNull(read.price) === null) evidence.push('Visible price could not be verified from the chart image.');
    }
  }
  return {
    version:1,
    ticker:expectedTicker,
    imageId:String(options.imageId || ''),
    requestId:String(options.requestId || ''),
    source:String(options.source || 'chart_pipeline_quick_check'),
    phase,
    expectedFacts:expected,
    readFacts:read,
    missing,
    diagnostics,
    evidence,
    aiAllowed:chartPipelineAllowsAi(phase) && chartPipelineHasVerifiedIdentity({
      manualConfirmed:false,
      verifiedMatch
    }),
    manualConfirmed:false,
    verifiedMatch,
    mismatch:tickerMismatch,
    hasFacts,
    chartAssessorInput:cloneData(options.chartAssessorInput || null, null),
    chartImageSource:cloneData(options.chartImageSource || null, null),
    updatedAt:new Date().toISOString()
  };
}

function mergePromotedChartPipelineIdentity(record = {}, existingPipeline = {}, promotedPipeline = {}, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const existing = existingPipeline && typeof existingPipeline === 'object' ? existingPipeline : {};
  const promoted = promotedPipeline && typeof promotedPipeline === 'object' ? promotedPipeline : {};
  const requestId = String(options.requestId || promoted.requestId || existing.requestId || '').trim();
  const imageId = String(options.imageId || promoted.imageId || existing.imageId || '').trim();
  const updatedAt = new Date().toISOString();
  if(existing.manualConfirmed === true){
    const existingPhase = String(existing.phase || '').trim();
    const preservedReadFacts = preserveManualConfirmIdentityReadFacts(
      existing.readFacts || {},
      promoted.readFacts || {},
      item.ticker || ''
    );
    const preservedTicker = normaliseVisibleTicker(preservedReadFacts.ticker || '');
    const expectedTicker = normaliseVisibleTicker(item.ticker || '');
    const preservedMismatch = !!(preservedTicker && expectedTicker && preservedTicker !== expectedTicker);
    const preservedVerifiedMatch = !!(preservedTicker && expectedTicker && preservedTicker === expectedTicker);
    const preservedEvidence = preservedMismatch && Array.isArray(existing.evidence) && existing.evidence.length
      ? existing.evidence.slice()
      : (Array.isArray(promoted.evidence) ? promoted.evidence.slice() : []);
    return {
      ...existing,
      imageId:String(imageId || existing.imageId || ''),
      requestId:String(requestId || existing.requestId || ''),
      source:String(existing.source || 'chart_pipeline_manual_confirm'),
      phase:existingPhase || 'verified',
      readFacts:preservedReadFacts,
      missing:Array.isArray(promoted.missing) ? promoted.missing.slice() : [],
      diagnostics:Array.isArray(promoted.diagnostics) ? promoted.diagnostics.slice() : [],
      evidence:preservedEvidence,
      chartAssessorInput:cloneData(promoted.chartAssessorInput || existing.chartAssessorInput || null, null),
      chartImageSource:cloneData(promoted.chartImageSource || existing.chartImageSource || null, null),
      hasFacts:promoted.hasFacts === true || existing.hasFacts === true,
      mismatch:preservedMismatch,
      verifiedMatch:preservedVerifiedMatch,
      aiAllowed:chartPipelineAllowsAi(existingPhase || 'verified'),
      manualConfirmed:true,
      updatedAt,
      debug:promoted.debug
    };
  }
  const existingHasVerifiedIdentity = chartPipelineHasVerifiedIdentity(existing);
  const promotedHasVerifiedIdentity = chartPipelineHasVerifiedIdentity(promoted);
  if(existingHasVerifiedIdentity && (!promotedHasVerifiedIdentity || promoted.mismatch === true || promoted.verifiedMatch !== true)){
    const existingPhase = String(existing.phase || '').trim();
    const preservedEvidence = Array.isArray(existing.evidence) && existing.evidence.length
      ? existing.evidence.slice()
      : (Array.isArray(promoted.evidence) ? promoted.evidence.slice() : []);
    return {
      ...existing,
      imageId:String(imageId || existing.imageId || ''),
      requestId:String(requestId || existing.requestId || ''),
      source:String(existing.source || promoted.source || 'chart_pipeline_verified_identity_preserved'),
      phase:existingPhase || 'verified',
      missing:Array.isArray(promoted.missing) ? promoted.missing.slice() : (Array.isArray(existing.missing) ? existing.missing.slice() : []),
      diagnostics:Array.isArray(promoted.diagnostics) ? promoted.diagnostics.slice() : (Array.isArray(existing.diagnostics) ? existing.diagnostics.slice() : []),
      evidence:preservedEvidence,
      chartAssessorInput:cloneData(promoted.chartAssessorInput || existing.chartAssessorInput || null, null),
      chartImageSource:cloneData(promoted.chartImageSource || existing.chartImageSource || null, null),
      hasFacts:promoted.hasFacts === true || existing.hasFacts === true,
      mismatch:false,
      verifiedMatch:true,
      aiAllowed:chartPipelineAllowsAi(existingPhase || 'verified'),
      manualConfirmed:false,
      updatedAt,
      debug:promoted.debug
    };
  }
  return promoted;
}

function buildSimplifiedTickerGateAnalysis(record = {}, sanitizedAnalysis = null, rawAnalysis = null, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const sanitized = sanitizedAnalysis && typeof sanitizedAnalysis === 'object'
    ? {...sanitizedAnalysis}
    : {};
  const raw = rawAnalysis && typeof rawAnalysis === 'object'
    ? rawAnalysis
    : {};
  const expectedTicker = normaliseVisibleTicker(item.ticker || '');
  const sanitizedTicker = normaliseVisibleTicker(sanitized.visible_ticker || '');
  const rawTicker = normaliseVisibleTicker(raw.visible_ticker || '');
  if(sanitizedTicker || !rawTicker || !expectedTicker || rawTicker !== expectedTicker){
    return sanitized;
  }
  const gateAnalysis = {
    ...sanitized,
    visible_ticker:rawTicker,
    visible_ticker_source:String(
      sanitized.visible_ticker_source
      || sanitized.ticker_extraction_source
      || raw.visible_ticker_source
      || raw.ticker_extraction_source
      || 'simplified_ticker_gate_raw_match'
    ).trim(),
    ticker_extraction_source:String(
      sanitized.ticker_extraction_source
      || sanitized.visible_ticker_source
      || raw.ticker_extraction_source
      || raw.visible_ticker_source
      || 'simplified_ticker_gate_raw_match'
    ).trim(),
    __simplifiedTickerGateMatched:true
  };
  if(typeof console !== 'undefined' && console.info){
    console.info('[CHART_PIPELINE_TICKER_GATE_OVERRIDE]', {
      ticker:normalizeTicker(item.ticker || ''),
      requestId:String(options.requestId || ''),
      imageId:String(options.imageId || ''),
      expectedTicker,
      rawVisibleTicker:rawTicker,
      sanitizedTicker
    });
  }
  return gateAnalysis;
}

function upsertReviewChartAnalysisPipeline(record = {}, nextPipeline = {}){
  const item = record && typeof record === 'object' ? record : {};
  if(!item.review || typeof item.review !== 'object') item.review = {};
  const existing = getReviewChartAnalysisPipeline(item) || {};
  const merged = {
    ...existing,
    ...cloneData(nextPipeline, {}),
    version:1
  };
  item.review.chartAnalysisPipeline = merged;
  return merged;
}

function buildSimplifiedChartPipelineTrace(record = {}, pipeline = {}){
  const item = record && typeof record === 'object' ? record : {};
  const safe = normalizeChartPipelineForRender(item, pipeline);
  const expected = safe.expectedFacts && typeof safe.expectedFacts === 'object' ? safe.expectedFacts : buildChartPipelineExpectedFacts(item);
  const read = safe.readFacts && typeof safe.readFacts === 'object' ? safe.readFacts : {};
  const phase = String(safe.phase || '').trim();
  const reason = String(safe.reason || '').trim();
  const expectedTicker = normalizeTicker(item.ticker || expected.ticker || '');
  const hasVerifiedIdentity = chartPipelineHasVerifiedIdentity(safe);
  const hasDetectedTickerMatch = chartPipelineHasDetectedTickerMatch(safe);
  const status = phase === 'analysis_failed'
    ? (hasVerifiedIdentity
      ? (safe.manualConfirmed === true ? 'user_confirmed_match' : 'verified_match')
      : 'analysis_failed')
    : chartPipelineStatusFromPhase(phase);
  const diagnostics = Array.isArray(safe.diagnostics) ? safe.diagnostics.slice() : [];
  const detailText = reason === 'chart_context_mismatch'
    ? 'The displayed chart and verification context are out of sync. Confirm this chart manually or upload it again.'
    : (phase === 'possible_mismatch'
      ? `AI analysis has been skipped because the uploaded chart does not appear to match ${expectedTicker || 'this review'}.`
      : (phase === 'analysis_failed' && hasVerifiedIdentity
        ? 'Chart verified, but AI analysis failed. Try again.'
        : (phase === 'analysis_failed'
          ? (Array.isArray(safe.evidence) && safe.evidence.length
            ? String(safe.evidence[0] || '').trim()
            : 'Chart verification could not run. Try again.')
        : ((phase === 'verified' || phase === 'analysis_running' || phase === 'analysis_complete')
          ? (safe.manualConfirmed === true && !hasDetectedTickerMatch
            ? 'Chart was manually confirmed for this review. AI analysis can continue.'
            : `Quick chart verification matched the uploaded chart to ${expectedTicker || 'the selected ticker'}.`)
          : 'Unable to read the chart ticker. Please confirm this is the correct chart.'))));
  return {
    visible:true,
    status,
    renderedStatus:status,
    mergedStatus:status,
    title:reason === 'chart_context_mismatch'
      ? 'Chart check needs attention'
      : (phase === 'possible_mismatch'
        ? 'Wrong chart detected'
        : (phase === 'analysis_failed' && hasVerifiedIdentity
          ? (safe.manualConfirmed === true && !hasDetectedTickerMatch
            ? 'Chart manually confirmed'
            : `Chart matched ${expectedTicker || 'selected ticker'}`)
          : (phase === 'analysis_failed'
            ? 'Chart verification unavailable'
          : (phase === 'verified' || phase === 'analysis_running' || phase === 'analysis_complete'
            ? (safe.manualConfirmed === true && !hasDetectedTickerMatch
              ? 'Chart manually confirmed'
              : `Chart matched ${expectedTicker || 'selected ticker'}`)
            : 'Unable to read chart ticker')))),
    summary:detailText,
    detail:detailText,
    reviewTicker:expectedTicker,
    ticker:expectedTicker,
    requestId:String(safe.requestId || ''),
    verificationRequestId:String(safe.requestId || ''),
    imageId:String(safe.imageId || ''),
    chartImageId:String(safe.imageId || ''),
    extractedFacts:{
      visible_ticker:String(read.ticker || ''),
      visible_timeframe:String(read.timeframe || ''),
      visible_latest_price:chartVerificationNumberOrNull(read.price),
      visible_ma20:chartVerificationNumberOrNull(read.ma20),
      visible_ma50:chartVerificationNumberOrNull(read.ma50),
      visible_ma200:chartVerificationNumberOrNull(read.ma200)
    },
    trustedFacts:{
      ticker:expectedTicker,
      expected_timeframe:String(expected.timeframe || ''),
      latest_price:chartVerificationNumberOrNull(expected.price),
      ma20:chartVerificationNumberOrNull(expected.ma20),
      ma50:chartVerificationNumberOrNull(expected.ma50),
      ma200:chartVerificationNumberOrNull(expected.ma200)
    },
    missing:Array.isArray(safe.missing) ? safe.missing.slice() : [],
    diagnostics,
    evidence:Array.isArray(safe.evidence) ? safe.evidence.slice() : [],
    unreadableReasons:Array.isArray(safe.evidence) ? safe.evidence.slice() : [],
    sources:[String(safe.source || 'chart_pipeline_quick_check')],
    source:String(safe.source || 'chart_pipeline_quick_check'),
    chartImageSource:cloneData(safe.chartImageSource || buildChartImageSourceTrace(item.review || {}), null),
    aiAnalysisSuppressed:!(chartPipelineAllowsAi(phase) && chartPipelineHasVerifiedIdentity(safe)),
    suppressionReason:(chartPipelineAllowsAi(phase) && chartPipelineHasVerifiedIdentity(safe)) ? '' : detailText,
    chartUserConfirmed:safe.manualConfirmed === true,
    manualConfirmed:safe.manualConfirmed === true,
    finalized:phase !== 'verifying' && phase !== 'uploading'
  };
}

function buildSimplifiedChartPipelineDecision(record = {}, pipeline = {}) {
  const safe = normalizeChartPipelineForRender(record, pipeline);
  const trace = buildSimplifiedChartPipelineTrace(record, safe);
  const phase = String(safe.phase || '').trim();
  const reason = String(safe.reason || '').trim();
  const expectedTicker = normalizeTicker(record && record.ticker || trace.ticker || '');
  const hasVerifiedIdentity = chartPipelineHasVerifiedIdentity(safe);
  const hasDetectedTickerMatch = chartPipelineHasDetectedTickerMatch(safe);
  if(phase === 'verifying' || phase === 'uploading'){
    return {
      key:'source_checking',
      title:'Chart uploaded - checking details',
      summary:'Quick chart verification is running.',
      detail:'',
      visible:true,
      trace
    };
  }
  if(phase === 'possible_mismatch'){
    return {
      key:'chart_mismatch',
      title:'Wrong chart detected',
      summary:`Expected: ${expectedTicker || 'n/a'} | Found: ${trace.extractedFacts && trace.extractedFacts.visible_ticker || 'n/a'}`,
      detail:'AI analysis has been skipped because the uploaded chart does not appear to match this review.',
      visible:true,
      trace
    };
  }
  if(reason === 'chart_context_mismatch'){
    return {
      key:'chart_context_mismatch',
      title:'Chart check needs attention',
      summary:'The displayed chart and verification context are out of sync. Confirm this chart manually or upload it again.',
      detail:'',
      visible:true,
      trace
    };
  }
  if(phase === 'analysis_failed' && hasVerifiedIdentity){
    return {
      key:safe.manualConfirmed === true ? 'user_confirmed_match' : 'verified_match',
      title:safe.manualConfirmed === true && !hasDetectedTickerMatch ? 'Chart manually confirmed.' : 'Chart looks correct.',
      summary:'AI analysis failed. Try again.',
      detail:'',
      visible:true,
      trace
    };
  }
  if(phase === 'analysis_failed'){
    return {
      key:'analysis_failed',
      title:'Chart verification unavailable',
      summary:Array.isArray(trace.evidence) && trace.evidence.length
        ? String(trace.evidence[0] || '').trim()
        : 'Chart verification failed. Try again.',
      detail:'',
      visible:true,
      trace
    };
  }
  if(chartPipelineAllowsAi(phase) && hasVerifiedIdentity){
    const summary = safe.manualConfirmed === true && !hasDetectedTickerMatch
      ? 'This chart was manually confirmed. AI analysis can continue.'
      : (trace.extractedFacts && trace.extractedFacts.visible_ticker
        ? `Ticker detected: ${trace.extractedFacts.visible_ticker}.${Array.isArray(trace.diagnostics) && trace.diagnostics.length ? ' Some chart details were not readable, but analysis can continue.' : ''}`
        : 'Ticker detected and chart verification passed.');
    return {
      key:safe.manualConfirmed === true ? 'user_confirmed_match' : 'verified_match',
      title:safe.manualConfirmed === true && !hasDetectedTickerMatch ? 'Chart manually confirmed.' : 'Chart looks correct.',
      summary,
      detail:'',
      visible:true,
      trace
    };
  }
  return {
    key:'cant_read',
    title:'Unable to read the chart ticker',
    summary:'Please confirm this is the correct chart.',
    detail:'',
    visible:true,
    trace
  };
}

function renderSimplifiedChartPipelineMarkup(record = {}, pipeline = {}){
  const normalizedPipeline = normalizeChartPipelineForRender(record, pipeline);
  const decision = buildSimplifiedChartPipelineDecision(record, normalizedPipeline);
  const trace = decision.trace;
  const decisionKey = String(decision && decision.key || '').trim();
  const isFailurePanel = ['chart_mismatch', 'cant_read', 'chart_context_mismatch', 'analysis_failed'].includes(decisionKey)
    && !chartPipelineHasVerifiedIdentity(normalizedPipeline);
  const detailsOpen = !!(uiState.reviewChartDetailsOpen && uiState.reviewChartDetailsOpen[normalizeTicker(record && record.ticker || '')]);
  const detailsOpenAttr = detailsOpen ? ' open' : '';
  const facts = trace.extractedFacts || {};
  const trusted = trace.trustedFacts || {};
  const diagnostics = Array.isArray(trace.diagnostics) ? trace.diagnostics : [];
  const readTickerDisplay = String(facts.visible_ticker || '').trim() || 'Unknown';
  const expectedTickerDisplay = String(trusted.ticker || '').trim() || 'n/a';
  const evidenceLine = Array.isArray(trace.evidence) && trace.evidence.length
    ? `<div class="tiny badtext">${escapeHtml(`Evidence: ${trace.evidence.join(' | ')}`)}</div>`
    : '';
  const missingLine = !chartPipelineHasVerifiedIdentity(normalizedPipeline) && Array.isArray(trace.missing) && trace.missing.length
    ? `<div class="tiny">Missing context: ${escapeHtml(trace.missing.join(', '))}</div>`
    : '';
  const diagnosticsLine = diagnostics.length
    ? `<div class="tiny">Chart details: ${escapeHtml(diagnostics.join(' | '))}</div>`
    : '';
  const extracted = `<div class="tiny">Extracted: ticker ${escapeHtml(facts.visible_ticker || 'n/a')} | timeframe ${escapeHtml(facts.visible_timeframe || 'n/a')} | price ${escapeHtml(chartVerificationDisplayValue(facts.visible_latest_price))} | 20 ${escapeHtml(chartVerificationDisplayValue(facts.visible_ma20))} | 50 ${escapeHtml(chartVerificationDisplayValue(facts.visible_ma50))} | 200 ${escapeHtml(chartVerificationDisplayValue(facts.visible_ma200))}</div>`;
  const trustedFacts = `<div class="tiny">Trusted: ticker ${escapeHtml(trusted.ticker || 'n/a')} | timeframe ${escapeHtml(trusted.expected_timeframe || 'n/a')} | price ${escapeHtml(chartVerificationDisplayValue(trusted.latest_price))} | 20 ${escapeHtml(chartVerificationDisplayValue(trusted.ma20))} | 50 ${escapeHtml(chartVerificationDisplayValue(trusted.ma50))} | 200 ${escapeHtml(chartVerificationDisplayValue(trusted.ma200))}</div>`;
  const imageSource = trace.chartImageSource && typeof trace.chartImageSource === 'object'
    ? `<div class="tiny">Image source: ${escapeHtml(trace.chartImageSource.sourceKind || 'unknown')} | original ${escapeHtml(trace.chartImageSource.originalDimensions || 'unknown')} | preview ${escapeHtml(trace.chartImageSource.previewDimensions || 'unknown')} | verification ${escapeHtml(trace.chartImageSource.verificationSourceDimensions || 'unknown')}</div>`
    : '';
  const extraEvidence = Array.isArray(trace.evidence) && trace.evidence.length
    ? trace.evidence.map(item => `<div class="tiny">${escapeHtml(item)}</div>`).join('')
    : '';
  const sources = `<div class="tiny">Sources: ${escapeHtml((trace.sources || []).join(', ') || 'chart_pipeline_quick_check')}</div>`;
  const details = `${missingLine}${diagnosticsLine}${extracted}${trustedFacts}${imageSource}${extraEvidence}${sources}`;
  const markup = isFailurePanel
    ? `<div class="summary tiny ai-summary-message ${escapeHtml(chartDecisionClassName(decision))}"><strong>Chart Verification Failed</strong><div class="tiny"><strong>Expected:</strong> ${escapeHtml(expectedTickerDisplay)}</div><div class="tiny"><strong>Read:</strong> ${escapeHtml(readTickerDisplay)}</div><div>AI analysis is blocked until the chart is confirmed or replaced.</div><details class="compact-details" id="reviewChartDetails"${detailsOpenAttr}><summary>Show details</summary>${details}</details></div>`
    : `<div class="summary tiny ai-summary-message ${escapeHtml(chartDecisionClassName(decision))}"><strong>${escapeHtml(decision.title || 'Chart verification')}</strong><div>${escapeHtml(decision.summary || '')}</div><div class="tiny"><strong>Read from chart:</strong> ${escapeHtml([facts.visible_ticker || 'n/a', facts.visible_timeframe || 'n/a', chartVerificationDisplayValue(facts.visible_latest_price)].join(' | '))} <strong>Expected:</strong> ${escapeHtml([trusted.ticker || 'n/a', trusted.expected_timeframe || 'n/a', chartVerificationDisplayValue(trusted.latest_price)].join(' | '))}</div><div class="tiny">20MA ${escapeHtml(chartVerificationDisplayValue(facts.visible_ma20))} | 50MA ${escapeHtml(chartVerificationDisplayValue(facts.visible_ma50))} | 200MA ${escapeHtml(chartVerificationDisplayValue(facts.visible_ma200))}</div>${evidenceLine}<details class="compact-details" id="reviewChartDetails"${detailsOpenAttr}><summary>Show details</summary>${details}</details></div>`;
  return {
    decision,
    trace,
    markup,
    manualActionsMarkup:['possible_mismatch', 'cant_read'].includes(String(normalizedPipeline && normalizedPipeline.phase || '').trim())
      ? `<div class="actions chart-verification-actions" style="margin-top:8px">
          <button class="primary compactbutton" type="button" data-act="confirm-chart-match">${escapeHtml(isFailurePanel ? 'Confirm Chart' : `Confirm this chart matches ${record && record.ticker || ''}`)}</button>
          <button class="secondary compactbutton" type="button" data-act="reject-chart-upload">${escapeHtml(isFailurePanel ? 'Upload New Chart' : 'Reject and upload another chart')}</button>
        </div>`
      : ''
  };
}

function buildChartContextMismatchPipeline(record = {}, pipeline = {}, contextSnapshot = {}){
  const item = record && typeof record === 'object' ? record : {};
  const safePipeline = pipeline && typeof pipeline === 'object' ? pipeline : {};
  const expectedFacts = safePipeline.expectedFacts && typeof safePipeline.expectedFacts === 'object'
    ? safePipeline.expectedFacts
    : buildChartPipelineExpectedFacts(item);
  const readFacts = safePipeline.readFacts && typeof safePipeline.readFacts === 'object'
    ? safePipeline.readFacts
    : {};
  return {
    ...safePipeline,
    ticker:normalizeTicker(item.ticker || safePipeline.ticker || ''),
    imageId:String(chartImageIdForReview(item.review || {}) || safePipeline.imageId || ''),
    requestId:String(currentReviewChartContext(item, item.review || {}).requestId || safePipeline.requestId || ''),
    phase:'cant_read',
    reason:'chart_context_mismatch',
    expectedFacts,
    readFacts,
    missing:['visible ticker'],
    diagnostics:Array.isArray(safePipeline.diagnostics) ? safePipeline.diagnostics.slice() : [],
    evidence:['Displayed chart and verification context are out of sync.'],
    aiAllowed:false,
    manualConfirmed:false,
    verifiedMatch:false,
    mismatch:false,
    chartImageSource:cloneData(safePipeline.chartImageSource || buildChartImageSourceTrace(item.review || {}), null),
    debug:{
      ...(safePipeline.debug && typeof safePipeline.debug === 'object' ? safePipeline.debug : {}),
      chartContextMismatch:true,
      displayedImageId:String(contextSnapshot.displayedImageId || ''),
      verificationImageId:String(contextSnapshot.verificationImageId || '')
    },
    updatedAt:new Date().toISOString()
  };
}

async function runSimplifiedChartAnalysis(record = {}, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  if(!item || !item.review) return null;
  const ticker = normalizeTicker(item.ticker || '');
  const resolveLiveRecord = () => getTickerRecord(ticker) || item;
  const liveRecord = resolveLiveRecord();
  const imageId = String(chartImageIdForReview(item.review || {}) || '');
  if(!ticker || !imageId) return null;
  const existing = getReviewChartAnalysisPipeline(liveRecord) || {};
  const requestId = String(options.requestId || existing.requestId || nextReviewAiAnalysisRequestId());
  const source = String(options.source || 'chart_upload');
  const chartImageSource = buildChartImageSourceTrace(liveRecord.review || {});
  const card = tickerRecordToLegacyCard(liveRecord);
  if(options.phase){
    upsertReviewChartAnalysisPipeline(liveRecord, {
      imageId,
      requestId,
      source,
      phase:String(options.phase || 'verifying'),
      expectedFacts:buildChartPipelineExpectedFacts(liveRecord),
      readFacts:existing.readFacts || {},
      evidence:Array.isArray(existing.evidence) ? existing.evidence.slice() : [],
      missing:Array.isArray(existing.missing) ? existing.missing.slice() : ['visible ticker', 'visible timeframe', 'latest price'],
      aiAllowed:false,
      manualConfirmed:existing.manualConfirmed === true,
      chartImageSource,
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_phase', requestedTicker:ticker});
  }
  const endpoints = analysisEndpoints();
  if(!endpoints.length){
    upsertReviewChartAnalysisPipeline(liveRecord, {
      imageId,
      requestId,
      source,
      phase:'analysis_failed',
      expectedFacts:buildChartPipelineExpectedFacts(liveRecord),
      readFacts:{},
      missing:['visible ticker', 'visible timeframe', 'latest price'],
      evidence:['AI analysis endpoint is not configured.'],
      aiAllowed:false,
      chartImageSource,
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_no_endpoint', requestedTicker:ticker});
    return getReviewChartAnalysisPipeline(resolveLiveRecord());
  }
  const chartPayload = chartImageForAnalysis(liveRecord.review || {});
  if(!chartPayload.chartRef){
    return null;
  }
  const previousTickerState = normalizeCard(card);
  let result = null;
  try{
    result = await analysisService.requestAnalysisFromEndpoints({
      endpoints,
      timeoutMs:ANALYSIS_TIMEOUT_MS,
      buildRequestBody:() => ({
        payload:buildVerificationOnlyPayload(card),
        prompt:buildVerificationOnlyPrompt(card),
        chartRef:chartPayload.chartRef,
        verificationOnly:true
      }),
      buildErrorMessage:(status, data, fallback) => buildAnalysisErrorMessage(status, data, fallback)
    });
  }catch(error){
    const currentRecord = resolveLiveRecord();
    upsertReviewChartAnalysisPipeline(currentRecord, {
      imageId,
      requestId,
      source,
      phase:'analysis_failed',
      expectedFacts:buildChartPipelineExpectedFacts(currentRecord),
      readFacts:{},
      missing:['visible ticker', 'visible timeframe', 'latest price'],
      evidence:[String(error && error.message || 'Chart verification failed.')],
      aiAllowed:false,
      chartImageSource,
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_verify_exception', requestedTicker:ticker});
    return getReviewChartAnalysisPipeline(resolveLiveRecord());
  }
  const currentRecord = resolveLiveRecord();
  const currentImageId = String(chartImageIdForReview(currentRecord.review || {}) || '');
  if(currentImageId !== imageId){
    return null;
  }
  if(result.status !== 'ok'){
    upsertReviewChartAnalysisPipeline(currentRecord, {
      imageId,
      requestId,
      source,
      phase:'analysis_failed',
      expectedFacts:buildChartPipelineExpectedFacts(currentRecord),
      readFacts:{},
      missing:['visible ticker', 'visible timeframe', 'latest price'],
      evidence:[String(result.errorMessage || 'Chart verification failed.')],
      aiAllowed:false,
      chartImageSource,
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_verify_failed', requestedTicker:ticker});
    return getReviewChartAnalysisPipeline(resolveLiveRecord());
  }
  try{
    const verifiedRecord = resolveLiveRecord();
    const data = result.data && typeof result.data === 'object' ? result.data : {};
    if(typeof console !== 'undefined' && console.info){
      console.info('[CHART_PIPELINE_QUICK_RAW_RESULT]', {
        ticker,
        imageId,
        requestId,
        source,
        sourceKind:String(chartImageSource.sourceKind || ''),
        originalDimensions:String(chartImageSource.originalDimensions || ''),
        previewDimensions:String(chartImageSource.previewDimensions || ''),
        verificationDimensions:String(chartImageSource.verificationSourceDimensions || ''),
        rawVisibleTicker:String((data.analysis && data.analysis.visible_ticker) || ''),
        rawVisibleTimeframe:String((data.analysis && data.analysis.visible_timeframe) || ''),
        rawVisiblePrice:chartVerificationNumberOrNull(data.analysis && data.analysis.visible_latest_price),
        rawVisibleMa20:chartVerificationNumberOrNull(data.analysis && data.analysis.visible_ma20),
        rawVisibleMa50:chartVerificationNumberOrNull(data.analysis && data.analysis.visible_ma50),
        rawVisibleMa200:chartVerificationNumberOrNull(data.analysis && data.analysis.visible_ma200)
      });
    }
    const normalized = normalizeAnalysisResult(data.analysis && typeof data.analysis === 'object' ? data.analysis : {}, previousTickerState);
    if(typeof console !== 'undefined' && console.info){
      console.info('[CHART_PIPELINE_QUICK_NORMALIZED_RESULT]', {
        ticker,
        imageId,
        requestId,
        source,
        sourceKind:String(chartImageSource.sourceKind || ''),
        originalDimensions:String(chartImageSource.originalDimensions || ''),
        previewDimensions:String(chartImageSource.previewDimensions || ''),
        verificationDimensions:String(chartImageSource.verificationSourceDimensions || ''),
        normalizedVisibleTicker:String(normalized.visible_ticker || ''),
        normalizedVisibleTimeframe:String(normalized.visible_timeframe || ''),
        normalizedVisiblePrice:chartVerificationNumberOrNull(normalized.visible_latest_price),
        normalizedVisibleMa20:chartVerificationNumberOrNull(normalized.visible_ma20),
        normalizedVisibleMa50:chartVerificationNumberOrNull(normalized.visible_ma50),
        normalizedVisibleMa200:chartVerificationNumberOrNull(normalized.visible_ma200),
        normalizedVisibleTickerSource:String(normalized.visible_ticker_source || normalized.ticker_extraction_source || ''),
        normalizedVisibleTimeframeSource:String(normalized.visible_timeframe_source || normalized.timeframe_extraction_source || ''),
        normalizedVisiblePriceSource:String(normalized.visible_price_source || normalized.price_extraction_source || ''),
        normalizedProvenanceVersion:Number.isFinite(Number(normalized.chartIdentityProvenanceVersion))
          ? Number(normalized.chartIdentityProvenanceVersion)
          : null
      });
    }
    const normalizedVisibleTicker = normaliseVisibleTicker(normalized.visible_ticker || '');
    const expectedVisibleTicker = normaliseVisibleTicker(verifiedRecord.ticker || '');
    if(normalizedVisibleTicker && expectedVisibleTicker && normalizedVisibleTicker !== expectedVisibleTicker){
      const mismatchGateAnalysis = {
        ...normalized,
        visible_ticker:normalizedVisibleTicker,
        __simplifiedTickerMismatchDetected:true
      };
      const chartAssessorInput = buildChartAssessorInput(verifiedRecord, mismatchGateAnalysis, chartImageSource, requestId);
      const nextPipeline = buildChartPipelineFromVerification(verifiedRecord, {
        imageId,
        requestId,
        source:'chart_pipeline_quick_check',
        analysis:mismatchGateAnalysis,
        chartAssessorInput,
        chartImageSource
      });
      nextPipeline.debug = {
        mismatchGateOverride:true,
        rawReadFacts:buildChartPipelineReadFacts(data.analysis && typeof data.analysis === 'object' ? data.analysis : {}),
        normalizedReadFacts:buildChartPipelineReadFacts(normalized)
      };
      if(typeof console !== 'undefined' && console.info){
        console.info('[CHART_PIPELINE_MISMATCH_GATE_OVERRIDE]', {
          ticker,
          imageId,
          requestId,
          expectedTicker:expectedVisibleTicker,
          normalizedVisibleTicker,
          phase:String(nextPipeline.phase || '')
        });
      }
      upsertReviewChartAnalysisPipeline(verifiedRecord, nextPipeline);
      commitTickerState();
      renderReviewWorkspace({source:'chart_pipeline_mismatch_verified', requestedTicker:ticker});
      return getReviewChartAnalysisPipeline(resolveLiveRecord());
    }
    const sanitized = sanitizeChartAssessorVisibleIdentity(
      verifiedRecord,
      normalized,
      chartImageSource,
      requestId,
      {caller:'chart_pipeline_quick'}
    );
    if(typeof console !== 'undefined' && console.info){
      console.info('[CHART_PIPELINE_QUICK_SANITIZED_RESULT]', {
        ticker,
        imageId,
        requestId,
        source,
        sourceKind:String(chartImageSource.sourceKind || ''),
        originalDimensions:String(chartImageSource.originalDimensions || ''),
        previewDimensions:String(chartImageSource.previewDimensions || ''),
        verificationDimensions:String(chartImageSource.verificationSourceDimensions || ''),
        visibleTicker:String(sanitized.visible_ticker || ''),
        visibleTimeframe:String(sanitized.visible_timeframe || ''),
        visiblePrice:chartVerificationNumberOrNull(sanitized.visible_latest_price),
        visibleMa20:chartVerificationNumberOrNull(sanitized.visible_ma20),
        visibleMa50:chartVerificationNumberOrNull(sanitized.visible_ma50),
        visibleMa200:chartVerificationNumberOrNull(sanitized.visible_ma200),
        chartIdentityProvenanceVersion:Number.isFinite(Number(sanitized.chartIdentityProvenanceVersion))
          ? Number(sanitized.chartIdentityProvenanceVersion)
          : null
      });
    }
    const simplifiedGateAnalysis = buildSimplifiedTickerGateAnalysis(
      verifiedRecord,
      sanitized,
      data.analysis && typeof data.analysis === 'object' ? data.analysis : {},
      {requestId, imageId}
    );
    const chartAssessorInput = buildChartAssessorInput(verifiedRecord, simplifiedGateAnalysis, chartImageSource, requestId);
    const nextPipeline = buildChartPipelineFromVerification(verifiedRecord, {
      imageId,
      requestId,
      source:'chart_pipeline_quick_check',
      analysis:simplifiedGateAnalysis,
      chartAssessorInput,
      chartImageSource
    });
    nextPipeline.debug = {
      rawReadFacts:buildChartPipelineReadFacts(data.analysis && typeof data.analysis === 'object' ? data.analysis : {}),
      normalizedReadFacts:buildChartPipelineReadFacts(normalized),
      sanitizedReadFacts:buildChartPipelineReadFacts(sanitized),
      chartIdentityProvenanceVersion:Number.isFinite(Number(sanitized.chartIdentityProvenanceVersion))
        ? Number(sanitized.chartIdentityProvenanceVersion)
        : null
    };
    upsertReviewChartAnalysisPipeline(verifiedRecord, nextPipeline);
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_verified', requestedTicker:ticker});
    if(nextPipeline.phase === 'verified'){
      runSimplifiedChartFullAnalysis(verifiedRecord, {
        source:'chart_pipeline_auto',
        requestId,
        manualConfirmed:false
      }).catch(() => {});
    }
    return getReviewChartAnalysisPipeline(resolveLiveRecord());
  }catch(error){
    if(typeof console !== 'undefined' && console.error){
      console.error('[CHART_PIPELINE_QUICK_RESOLUTION_FAILED]', {
        ticker,
        imageId,
        requestId,
        source,
        message:String(error && error.message || 'Chart verification resolution failed.')
      });
    }
    const failedRecord = resolveLiveRecord();
    upsertReviewChartAnalysisPipeline(failedRecord, {
      imageId,
      requestId,
      source,
      phase:'analysis_failed',
      expectedFacts:buildChartPipelineExpectedFacts(failedRecord),
      readFacts:recoverChartPipelineReadFacts(failedRecord, getReviewChartAnalysisPipeline(failedRecord) || {}),
      missing:['visible ticker'],
      evidence:[String(error && error.message || 'Chart verification resolution failed.')],
      aiAllowed:false,
      manualConfirmed:false,
      chartImageSource,
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_resolution_failed', requestedTicker:ticker});
    return getReviewChartAnalysisPipeline(resolveLiveRecord());
  }
}

async function runSimplifiedChartFullAnalysis(record = {}, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  if(!item || !item.review) return false;
  const ticker = normalizeTicker(item.ticker || '');
  const resolveLiveRecord = () => getTickerRecord(ticker) || item;
  const liveRecord = resolveLiveRecord();
  const pipeline = getReviewChartAnalysisPipeline(liveRecord);
  if(!ticker || !pipeline) return false;
  if(!chartPipelineHasVerifiedIdentity(pipeline)){
    renderReviewWorkspace({source:'chart_pipeline_analysis_blocked', requestedTicker:ticker});
    return false;
  }
  const imageId = String(chartImageIdForReview(liveRecord.review || {}) || '');
  upsertReviewChartAnalysisPipeline(liveRecord, {
    ...pipeline,
    imageId,
    requestId:String(options.requestId || pipeline.requestId || ''),
    phase:'analysis_running',
    aiAllowed:true,
    manualConfirmed:options.manualConfirmed === true || pipeline.manualConfirmed === true,
    source:String(options.source || pipeline.source || 'chart_pipeline_auto'),
    updatedAt:new Date().toISOString()
  });
  commitTickerState();
  renderReviewWorkspace({source:'chart_pipeline_analysis_running', requestedTicker:ticker});
  try{
    await analyseSetup(ticker, {
      source:String(options.source || 'chart_pipeline_auto'),
      skipVerificationGate:true,
      requestId:String(options.requestId || pipeline.requestId || '')
    });
    const refreshedRecord = resolveLiveRecord();
    const analysisState = getReviewAnalysisState(refreshedRecord);
    upsertReviewChartAnalysisPipeline(refreshedRecord, {
      phase:analysisState && analysisState.normalizedAnalysis ? 'analysis_complete' : 'verified',
      aiAllowed:true,
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_analysis_complete', requestedTicker:ticker});
    return true;
  }catch(error){
    upsertReviewChartAnalysisPipeline(resolveLiveRecord(), {
      phase:'analysis_failed',
      aiAllowed:false,
      evidence:[String(error && error.message || 'AI analysis failed.')],
      updatedAt:new Date().toISOString()
    });
    commitTickerState();
    renderReviewWorkspace({source:'chart_pipeline_analysis_failed', requestedTicker:ticker});
    return false;
  }
}

function shouldLogAiSummaryQuickRunningWait(record, guard = {}){
  const item = record && typeof record === 'object' ? record : {};
  const key = [
    normalizeTicker(item.ticker || ''),
    String(guard.currentImageId || ''),
    String(guard.currentRequestId || guard.summaryRequestId || ''),
    'quick_running'
  ].join('|');
  uiState.aiSummaryQuickRunningWaitLogKey = String(uiState.aiSummaryQuickRunningWaitLogKey || '');
  if(uiState.aiSummaryQuickRunningWaitLogKey === key) return false;
  uiState.aiSummaryQuickRunningWaitLogKey = key;
  return true;
}

function confirmReviewChartMatchesCurrentTicker(ticker){
  const symbol = normalizeTicker(ticker || '');
  if(!symbol) return false;
  const record = getTickerRecord(symbol);
  if(!record || !record.review) return false;
  const currentImageId = chartImageIdForReview(record.review || {});
  if(!currentImageId) return false;
  const currentPipeline = getReviewChartAnalysisPipeline(record) || {};
  const currentRequestId = String(currentPipeline.requestId || nextReviewAiAnalysisRequestId());
  const previousPhase = String(currentPipeline.phase || '').trim();
  upsertReviewChartAnalysisPipeline(record, {
    ...currentPipeline,
    ticker:symbol,
    imageId:currentImageId,
    requestId:currentRequestId,
    phase:'verified',
    aiAllowed:true,
    manualConfirmed:true,
    expectedFacts:currentPipeline.expectedFacts || buildChartPipelineExpectedFacts(record),
    readFacts:currentPipeline.readFacts || {},
    source:'chart_pipeline_manual_confirm',
    updatedAt:new Date().toISOString()
  });
  if(typeof console !== 'undefined' && console.info){
    console.info('[REVIEW_CHART_MANUAL_CONFIRM_PIPELINE]', {
      ticker:symbol,
      imageId:String(currentImageId || ''),
      previousPhase,
      nextPhase:'verified',
      renderSource:'simplified_pipeline',
      aiStartRequested:true
    });
  }
  commitTickerState();
  renderReviewWorkspace({source:'manual_chart_confirm'});
  renderCards();
  // Legacy compatibility contract retained for assertion harness:
  // analyseSetup(symbol, {source:'manual_chart_confirm'}).catch(() => {});
  runSimplifiedChartFullAnalysis(record, {
    source:'chart_pipeline_manual_confirm',
    requestId:currentRequestId,
    manualConfirmed:true
  }).catch(() => {});
  return true;
}

function rejectReviewChartAndUploadAnother(ticker){
  const symbol = normalizeTicker(ticker || '');
  if(!symbol) return false;
  const record = getTickerRecord(symbol);
  if(!record || !record.review) return false;
  clearReviewChartImageSources(record.review);
  clearLegacyChartAnalysisState(record.review);
  commitTickerState();
  renderReviewWorkspace({source:'reject_chart_upload'});
  const fileInput = $('reviewChartFile');
  if(fileInput && typeof fileInput.click === 'function'){
    fileInput.click();
  }
  renderCards();
  return true;
}

function chartDecisionClassName(decision){
  const key = String(decision && decision.key || '');
  if(['verified_match', 'likely_match', 'user_confirmed_match', 'manually_verified'].includes(key)) return 'ai-summary-message--success';
  if(key === 'chart_mismatch') return 'ai-summary-message--failed';
  if(key === 'user_confirmed_match' || key === 'manually_confirmed') return 'ai-summary-message--success';
  return 'ai-summary-message--warning';
}

function renderReviewChartStatusLine(record = {}, pipeline = null){
  const item = record && typeof record === 'object' ? record : {};
  const safePipeline = pipeline && typeof pipeline === 'object' ? normalizeChartPipelineForRender(item, pipeline) : null;
  if(!safePipeline){
    return '<span class="warntext">No chart attached yet.</span>';
  }
  const decision = buildSimplifiedChartPipelineDecision(item, safePipeline);
  const phase = String(safePipeline.phase || '').trim();
  const body = String(decision.summary || decision.detail || '').trim();
  if(phase === 'verifying' || phase === 'uploading'){
    return '<span class="warntext">Checking chart details...</span>';
  }
  if(chartPipelineHasVerifiedIdentity(safePipeline)){
    return `<span class="ok">${escapeHtml(decision.title || 'Chart looks correct.')}${body ? ` ${escapeHtml(body)}` : ''}</span>`;
  }
  if(phase === 'possible_mismatch'){
    return `<span class="badtext">${escapeHtml(decision.title || 'Wrong chart detected')}${body ? ` ${escapeHtml(body)}` : ''}</span>`;
  }
  return `<span class="warntext">${escapeHtml(decision.title || 'Chart check needs attention')}${body ? ` ${escapeHtml(body)}` : ''}</span>`;
}

function ensureReviewChartLightboxShell(){
  if(typeof document === 'undefined' || !document.body) return null;
  let shell = document.getElementById('reviewChartLightbox');
  if(shell) return shell;
  shell = document.createElement('div');
  shell.id = 'reviewChartLightbox';
  shell.className = 'review-chart-lightbox';
  shell.hidden = true;
  shell.innerHTML = '<div class="review-chart-lightbox__backdrop" data-act="close-review-chart-lightbox"></div><div class="review-chart-lightbox__panel" role="dialog" aria-modal="true"><button class="review-chart-lightbox__close" type="button" data-act="close-review-chart-lightbox">Close</button><div class="review-chart-lightbox__content"></div></div>';
  document.body.appendChild(shell);
  shell.addEventListener('click', event => {
    const target = event.target && event.target.closest ? event.target.closest('[data-act="close-review-chart-lightbox"]') : null;
    if(target){
      closeReviewChartLightbox();
      return;
    }
    if(event.target === shell || (event.target && event.target.classList && event.target.classList.contains('review-chart-lightbox__backdrop'))){
      closeReviewChartLightbox();
    }
  });
  return shell;
}

function closeReviewChartLightbox(){
  if(typeof uiState === 'object'){
    uiState.reviewChartLightbox = null;
  }
  const shell = typeof document !== 'undefined' ? document.getElementById('reviewChartLightbox') : null;
  if(shell){
    shell.hidden = true;
    shell.classList.remove('is-open');
    const content = shell.querySelector('.review-chart-lightbox__content');
    if(content) content.innerHTML = '';
  }
  if(typeof document !== 'undefined' && document.body){
    document.body.classList.remove('review-chart-lightbox-open');
  }
}

function openReviewChartLightbox(record){
  const item = normalizeTickerRecord(record);
  const review = item.review && typeof item.review === 'object' ? item.review : {};
  const attachmentContext = review.chartAttachmentContext && typeof review.chartAttachmentContext === 'object'
    ? review.chartAttachmentContext
    : null;
  const source = review.chartImageOriginal && review.chartImageOriginal.dataUrl
    ? review.chartImageOriginal
    : (review.chartRef && review.chartRef.dataUrl ? review.chartRef : review.chartImagePreview);
  if(!source || !source.dataUrl) return false;
  const modalTicker = normalizeTicker(source.ticker || (attachmentContext && attachmentContext.expectedTicker) || item.ticker || '');
  const modalName = String(source.name || (attachmentContext && attachmentContext.name) || (review.chartRef && review.chartRef.name) || 'chart image');
  const modalImageId = String(source.imageId || (attachmentContext && attachmentContext.imageId) || chartImageIdForReview(review) || '');
  if(typeof console !== 'undefined' && console.info){
    console.info('[CHART_MODAL_CONTEXT]', {
      recordTicker:normalizeTicker(item.ticker || ''),
      modalTicker,
      imageId:modalImageId,
      name:modalName,
      activeReviewTicker:activeReviewTicker() || '',
      attachmentExpectedTicker:String(attachmentContext && attachmentContext.expectedTicker || ''),
      attachmentRequestId:String(attachmentContext && attachmentContext.requestId || '')
    });
  }
  if((modalTicker && normalizeTicker(item.ticker || '') && modalTicker !== normalizeTicker(item.ticker || ''))
    || (modalName && review.chartRef && review.chartRef.name && modalName !== String(review.chartRef.name || ''))){
    if(typeof console !== 'undefined' && console.warn){
      console.warn('[CHART_UPLOAD_METADATA_MISMATCH]', {
        recordTicker:normalizeTicker(item.ticker || ''),
        modalTicker,
        imageId:modalImageId,
        modalName,
        chartRefName:String(review.chartRef && review.chartRef.name || ''),
        attachmentExpectedTicker:String(attachmentContext && attachmentContext.expectedTicker || '')
      });
    }
  }
  if(typeof uiState === 'object'){
    uiState.reviewChartLightbox = {
      ticker:modalTicker,
      imageId:modalImageId,
      dataUrl:source.dataUrl,
      name:modalName,
      open:true
    };
  }
  const shell = ensureReviewChartLightboxShell();
  if(!shell) return false;
  const content = shell.querySelector('.review-chart-lightbox__content');
  if(content){
    content.innerHTML = `
      <div class="review-chart-lightbox__figure">
        <img class="review-chart-lightbox__image" src="${escapeHtml(source.dataUrl)}" alt="Expanded chart preview for ${escapeHtml(modalTicker || item.ticker)}" />
        <div class="review-chart-lightbox__caption">
          <strong>${escapeHtml(modalTicker || item.ticker)}</strong>
          <div class="tiny">${escapeHtml(modalName)}</div>
        </div>
      </div>
    `;
  }
  shell.hidden = false;
  shell.classList.add('is-open');
  if(typeof document !== 'undefined' && document.body){
    document.body.classList.add('review-chart-lightbox-open');
  }
  return true;
}

function appendLifecycleHistory(record, entry){
  if(!record || !entry) return;
  record.lifecycle.history = [
    ...(record.lifecycle.history || []),
    {
      stage:String(entry.stage || record.lifecycle.stage || ''),
      status:String(entry.status || record.lifecycle.status || ''),
      changedAt:String(entry.changedAt || new Date().toISOString()),
      reason:String(entry.reason || ''),
      source:String(entry.source || 'system')
    }
  ].slice(-24);
}

function writeLifecycleState(record, payload = {}, context = {}){
  if(!record) return;
  const mode = String(context.mode || 'set').trim().toLowerCase();
  if(mode === 'refresh'){
    refreshLifecycleStage(
      record,
      payload.stage,
      payload.tradingDays,
      payload.reason,
      payload.source
    );
    return;
  }
  setLifecycleStage(record, payload);
}

function setLifecycleStage(record, {stage, status, changedAt, expiresAt, expiryReason, reason, source, forceHistory = false, lockReason}){
  if(!record) return;
  const nextStage = String(stage || record.lifecycle.stage || '');
  const nextStatus = String(status || record.lifecycle.status || 'inactive');
  const nextChangedAt = String(changedAt || new Date().toISOString());
  const stageChanged = record.lifecycle.stage !== nextStage || record.lifecycle.status !== nextStatus;
  record.lifecycle.stage = nextStage;
  record.lifecycle.status = nextStatus;
  record.lifecycle.lockReason = lockReason == null ? String(record.lifecycle.lockReason || '') : String(lockReason || '');
  record.lifecycle.stageUpdatedAt = nextChangedAt;
  record.lifecycle.expiresAt = expiresAt == null ? String(record.lifecycle.expiresAt || '') : String(expiresAt || '');
  record.lifecycle.expiryReason = expiryReason == null ? String(record.lifecycle.expiryReason || '') : String(expiryReason || '');
  if(stageChanged || forceHistory){
    appendLifecycleHistory(record, {
      stage:nextStage,
      status:nextStatus,
      changedAt:nextChangedAt,
      reason:String(reason || expiryReason || ''),
      source:String(source || 'system')
    });
  }
}

function refreshLifecycleStage(record, stage, tradingDays, reason, source){
  if(!record) return;
  const expiresAt = (record.lifecycle.stage === String(stage || '') && record.lifecycle.status === 'active' && record.lifecycle.expiresAt)
    ? record.lifecycle.expiresAt
    : (tradingDays > 0 ? businessDaysFromNow(tradingDays) : '');
  setLifecycleStage(record, {
    stage,
    status:'active',
    changedAt:new Date().toISOString(),
    expiresAt,
    expiryReason:'',
    reason,
    source,
    forceHistory:true
  });
}

function hasLockedLifecycle(record){
  return !!(record && record.lifecycle && record.lifecycle.lockReason === 'manual_expired');
}

function maybeExpireTickerRecord(record){
  if(!record || !record.lifecycle || !record.lifecycle.expiresAt) return false;
  if(['entered','exited'].includes(String(record.lifecycle.stage || ''))) return false;
  if(String(record.lifecycle.status || '') === 'closed') return false;
  const remaining = countTradingDaysBetween(todayIsoDate(), record.lifecycle.expiresAt);
  if(remaining > 0) return false;
  setLifecycleStage(record, {
    stage:'expired',
    status:'stale',
    changedAt:new Date().toISOString(),
    expiresAt:record.lifecycle.expiresAt,
    expiryReason:record.lifecycle.expiryReason || 'Aged out without progressing.',
    reason:record.lifecycle.expiryReason || 'Aged out without progressing.',
    source:'system'
  });
  return true;
}

function hasAuthoritativeLifecyclePlan(record){
  const item = record && typeof record === 'object' ? record : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const source = String(plan.source || '').trim().toLowerCase();
  return plan.hasValidPlan === true
    && String(plan.status || '').trim().toLowerCase() === 'valid'
    && Number.isFinite(numericOrNull(plan.entry))
    && Number.isFinite(numericOrNull(plan.stop))
    && Number.isFinite(numericOrNull(plan.firstTarget))
    && Number.isFinite(numericOrNull(plan.plannedRR))
    && source !== 'scanner_estimate';
}

function hasAuthoritativeStopBreach(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const currentPrice = Number.isFinite(Number(options.currentPrice))
    ? Number(options.currentPrice)
    : numericOrNull(item.marketData && item.marketData.price);
  const stopPrice = Number.isFinite(Number(options.stopPrice))
    ? Number(options.stopPrice)
    : numericOrNull(plan.stop);
  const thresholdMultiplier = Number.isFinite(Number(options.thresholdMultiplier))
    ? Number(options.thresholdMultiplier)
    : 1;
  const source = String(plan.source || '').trim().toLowerCase();
  const triggerState = String(plan.triggerState || '').trim().toLowerCase();
  const planValidationState = String(plan.planValidationState || '').trim().toLowerCase();
  const reviewedNonScannerPlan = source !== 'scanner_estimate'
    && Number.isFinite(numericOrNull(plan.entry))
    && Number.isFinite(stopPrice);
  const authoritativePlan = hasAuthoritativeLifecyclePlan(item);
  const invalidatedReviewedPlan = reviewedNonScannerPlan
    && (plan.invalidatedState === true || String(plan.invalidatedState || '').trim() !== '');
  const triggeredReviewedPlan = reviewedNonScannerPlan
    && triggerState === 'triggered'
    && ['valid', 'invalidated'].includes(planValidationState);
  const confirmedReviewedPlan = reviewedNonScannerPlan
    && planValidationState === 'valid';
  const breached = Number.isFinite(currentPrice)
    && Number.isFinite(stopPrice)
    && currentPrice < (stopPrice * thresholdMultiplier);
  return breached && (
    authoritativePlan
    || invalidatedReviewedPlan
    || triggeredReviewedPlan
    || confirmedReviewedPlan
  );
}

function applyLifecycleStageFromPlan(record, source = 'plan'){
  if(!record) return;
  if(hasAuthoritativeLifecyclePlan(record)){
    writeLifecycleState(record, {
      stage:'planned',
      tradingDays:PLAN_EXPIRY_TRADING_DAYS,
      reason:'Valid explicit trade plan saved.',
      source
    }, {mode:'refresh'});
    return;
  }
  if(record.review.manualReview){
    writeLifecycleState(record, {
      stage:'reviewed',
      tradingDays:REVIEW_EXPIRY_TRADING_DAYS,
      reason:'Review saved without a valid plan yet.',
      source:'review'
    }, {mode:'refresh'});
  }
}

function lifecycleLabel(record){
  const item = normalizeTickerRecordReadOnly(record);
  const globalVerdict = resolveGlobalVerdict(item);
  const lifecycleState = (globalVerdict.allow_watchlist || globalVerdict.allow_plan) ? 'active' : 'dropped';
  const expiry = item.watchlist && item.watchlist.expiryAt ? ` | Expires ${item.watchlist.expiryAt}` : '';
  return `${globalVerdict.final_verdict || 'watch'} | ${lifecycleState}${expiry}`;
}

function reevaluateTickerProgress(record){
  if(!record || typeof record !== 'object') return null;
  if(hasLockedLifecycle(record)){
    record.plan.triggerState = 'stale';
    if(!['invalidated','missed'].includes(String(record.plan.planValidationState || ''))){
      record.plan.planValidationState = 'stale';
    }
    record.action = {stage:'watch', priority:actionPriority('watch')};
    return record;
  }
  const evaluated = normalizeTickerRecord(record);
  record.plan.triggerState = String(evaluated.plan.triggerState || 'waiting_for_trigger');
  record.plan.planValidationState = String(evaluated.plan.planValidationState || '');
  record.plan.needsReplan = !!evaluated.plan.needsReplan;
  record.plan.missedState = String(evaluated.plan.missedState || '');
  record.plan.invalidatedState = String(evaluated.plan.invalidatedState || '');
  if(String(record.lifecycle.status || '') === 'stale' && !record.plan.invalidatedState && !record.plan.missedState && record.plan.triggerState !== 'triggered'){
    record.plan.triggerState = 'stale';
    if(!['missed','invalidated'].includes(record.plan.planValidationState)){
      record.plan.planValidationState = 'stale';
    }
  }
  if(record.plan.invalidatedState){
    writeLifecycleState(record, {
      stage:'avoided',
      status:'inactive',
      changedAt:new Date().toISOString(),
      expiresAt:'',
      expiryReason:'',
      reason:'Setup invalidated during trigger reevaluation.',
      source:'trigger'
    });
  }else if(record.plan.missedState){
    writeLifecycleState(record, {
      stage:'expired',
      status:'stale',
      changedAt:new Date().toISOString(),
      expiresAt:todayIsoDate(),
      expiryReason:'Setup missed after trigger progression.',
      reason:'Setup missed after trigger progression.',
      source:'trigger'
    });
  }else if(record.plan.triggerState === 'triggered' && record.plan.planValidationState === 'valid' && record.plan.status === 'valid' && !(record.lifecycle.stage === 'planned' && record.lifecycle.status === 'active' && record.lifecycle.expiresAt)){
    writeLifecycleState(record, {
      stage:'planned',
      status:'active',
      changedAt:new Date().toISOString(),
      expiresAt:businessDaysFromNow(PLAN_EXPIRY_TRADING_DAYS),
      expiryReason:'',
      reason:'Trigger confirmed and reviewed plan still validates.',
      source:'trigger'
    });
  }
  record.action = cloneData(evaluated.action, {stage:'watch', priority:3});
  return record;
}

function getTickerRecord(ticker){
  const symbol = normalizeTicker(ticker);
  return getTickerRecordImpl(symbol, { normalizeTicker, state });
}

function upsertTickerRecord(ticker){
  return upsertTickerRecordImpl(ticker, {
    normalizeTicker,
    state,
    normalizeTickerRecord,
    createBaseTickerRecord: symbol => baseTickerRecord(symbol)
  });
}

function formatPlanFieldValue(value, fallback = ''){
  const numeric = numericOrNull(value);
  if(Number.isFinite(numeric)) return numeric.toFixed(2);
  return String(fallback || '');
}

function planValuesEqual(left, right){
  const fields = ['entry','stop','firstTarget'];
  return fields.every(field => {
    const l = numericOrNull(left && left[field]);
    const r = numericOrNull(right && right[field]);
    if(!Number.isFinite(l) && !Number.isFinite(r)) return true;
    if(Number.isFinite(l) !== Number.isFinite(r)) return false;
    return Math.abs(l - r) < 0.000001;
  });
}

function aiPlanCandidateForRecord(record){
  return null;
}

function resolvePlanSource(record, planCandidate = {}, requestedSource = ''){
  const source = String(requestedSource || '').trim().toLowerCase();
  if(source === 'analysis') return 'scanner_estimate';
  if(source === 'scanner') return 'scanner';
  const normalizedCandidate = {
    entry:numericOrNull(planCandidate.entry),
    stop:numericOrNull(planCandidate.stop),
    firstTarget:numericOrNull(planCandidate.firstTarget)
  };
  const currentPlan = {
    entry:record && record.plan ? record.plan.entry : null,
    stop:record && record.plan ? record.plan.stop : null,
    firstTarget:record && record.plan ? record.plan.firstTarget : null
  };
  if(planValuesEqual(normalizedCandidate, currentPlan) && record && record.plan && record.plan.source){
    return String(record.plan.source);
  }
  if(source === 'review' || source === 'planner') return 'manual';
  return source || String(record && record.plan && record.plan.source || '');
}

function canonicalTradePlanAuthorityVersion(){
  return 'trade_plan_v1';
}

function hasCanonicalTradePlanStamp(plan){
  const safePlan = plan && typeof plan === 'object' ? plan : {};
  return String(safePlan.authorityVersion || '').trim() === canonicalTradePlanAuthorityVersion()
    && !!String(safePlan.authoritySource || '').trim()
    && !!String(safePlan.writtenBy || '').trim()
    && !!String(safePlan.writtenAt || '').trim();
}

function stampCanonicalTradePlan(record, context = {}){
  if(!(record && record.plan && typeof record.plan === 'object')) return;
  const candidateSource = String(context.source || record.plan.source || '').trim().toLowerCase();
  const writtenAt = String(context.updatedAt || context.lastPlannedAt || new Date().toISOString());
  record.plan.authoritySource = 'applyPlanCandidateToRecord';
  record.plan.authorityVersion = canonicalTradePlanAuthorityVersion();
  record.plan.authorityReason = String(context.reason || candidateSource || 'canonical_trade_plan_write');
  record.plan.writtenBy = String(context.writtenBy || 'applyPlanCandidateToRecord');
  record.plan.writtenAt = writtenAt;
  record.plan.candidateSource = candidateSource;
}

function writeSavedReviewAuthority(record, payload = {}, context = {}){
  if(!record) return;
  record.review = record.review && typeof record.review === 'object' ? record.review : {};
  const has = key => Object.prototype.hasOwnProperty.call(payload, key);
  if(has('manualReview')){
    record.review.manualReview = payload.manualReview && typeof payload.manualReview === 'object'
      ? cloneData(payload.manualReview, null)
      : null;
  }
  if(has('savedSummary')){
    record.review.savedSummary = String(payload.savedSummary || '');
  }
  if(has('savedScore')){
    const score = numericOrNull(payload.savedScore);
    record.review.savedScore = Number.isFinite(score) ? Number(score) : null;
  }
  if(has('savedVerdict')){
    const rawVerdict = String(payload.savedVerdict || '').trim();
    const normalizedVerdict = rawVerdict ? normalizeImportedStatus(rawVerdict, {preserveEmpty:true}) : '';
    record.review.savedVerdict = normalizedVerdict;
    if(context.clearProjectionWhenNonEntry !== false && normalizedVerdict && normalizedVerdict.trim().toLowerCase() !== 'entry' && !has('savedProjectionSnapshot')){
      record.review.savedProjectionSnapshot = null;
    }
  }
  if(has('savedProjectionSnapshot')){
    record.review.savedProjectionSnapshot = payload.savedProjectionSnapshot && typeof payload.savedProjectionSnapshot === 'object'
      ? cloneData(payload.savedProjectionSnapshot, null)
      : null;
  }
  if(has('lastReviewedAt')){
    record.review.lastReviewedAt = String(payload.lastReviewedAt || '');
  }
}

function writeSubmittedPaperTradeState(record, payload = {}, context = {}){
  if(!record) return;
  const submittedAt = String(payload.submittedAt || context.submittedAt || new Date().toISOString());
  record.plan = record.plan && typeof record.plan === 'object' ? record.plan : {};
  if(payload.displayedPlan && String(payload.displayedPlan.status || '').trim().toLowerCase() === 'valid'){
    applyPlanCandidateToRecord(record, {
      entry:payload.displayedPlan.entry,
      stop:payload.displayedPlan.stop,
      firstTarget:payload.displayedPlan.target != null
        ? payload.displayedPlan.target
        : payload.displayedPlan.firstTarget
    }, {
      source:String(context.source || 'paper_trade_submit'),
      reason:String(context.reason || 'preserve_submitted_paper_trade_plan'),
      writtenBy:String(context.writtenBy || 'writeSubmittedPaperTradeState'),
      updatedAt:submittedAt
    });
  }
  record.plan.triggerState = String(payload.triggerState || 'triggered');
  record.plan.planValidationState = String(payload.planValidationState || 'valid');
  record.plan.status = String(payload.status || 'valid');
  record.plan.tradeability = String(payload.tradeability || 'tradable');
  record.plan.riskStatus = String(payload.riskStatus || 'fits_risk');
  record.plan.submittedPaperTradeAt = submittedAt;
}

function applyPlanCandidateToRecord(record, planCandidate = {}, context = {}){
  if(!record) return;
  const previousFirstTarget = numericOrNull(record.plan && record.plan.firstTarget);
  const previousAlertLevel = numericOrNull(record.plan && record.plan.targetAlert && record.plan.targetAlert.level);
  const entry = numericOrNull(planCandidate.entry);
  const stop = numericOrNull(planCandidate.stop);
  const firstTarget = numericOrNull(planCandidate.firstTarget);
  const rewardRisk = evaluateRewardRisk(entry, stop, firstTarget);
  const riskFit = evaluateRiskFit({entry, stop, ...currentRiskSettings()});
  const quoteCurrency = normalizeQuoteCurrency(record.marketData && record.marketData.currency);
  const capitalFit = evaluateCapitalFit({
    entry,
    position_size:riskFit.position_size,
    account_size_gbp:currentAccountSizeGbp(),
    quote_currency:quoteCurrency
  });
  const hasAnyFields = [entry, stop, firstTarget].some(Number.isFinite);
  record.plan.hasValidPlan = rewardRisk.valid;
  record.plan.entry = entry;
  record.plan.stop = stop;
  record.plan.firstTarget = firstTarget;
  record.plan.riskPerShare = rewardRisk.valid ? rewardRisk.riskPerShare : null;
  record.plan.rewardPerShare = rewardRisk.valid ? rewardRisk.rewardPerShare : null;
  record.plan.plannedRR = rewardRisk.valid ? rewardRisk.rrRatio : null;
  record.plan.positionSize = rewardRisk.valid ? riskFit.position_size : null;
  record.plan.positionCost = rewardRisk.valid ? capitalFit.position_cost : null;
  record.plan.positionCostGbp = rewardRisk.valid ? capitalFit.position_cost_gbp : null;
  record.plan.quoteCurrency = quoteCurrency || '';
  record.plan.exitMode = normalizeExitMode(context.exitMode || record.plan.exitMode);
  record.plan.maxLoss = rewardRisk.valid ? riskFit.max_loss : currentMaxLoss();
  record.plan.riskStatus = rewardRisk.valid ? riskFit.risk_status : (hasAnyFields ? 'invalid_plan' : 'plan_missing');
  record.plan.capitalFit = rewardRisk.valid ? capitalFit.capital_fit : 'unknown';
  record.plan.tradeability = rewardRisk.valid ? deriveTradeability('valid', riskFit.risk_status, capitalFit.capital_fit) : 'invalid';
  record.plan.capitalNote = rewardRisk.valid ? String(capitalFit.capital_note || '') : '';
  record.plan.affordability = rewardRisk.valid ? deriveAffordability({
    ...capitalFit,
    account_size_gbp:currentAccountSizeGbp()
  }) : '';
  record.plan.status = !hasAnyFields ? 'missing' : (rewardRisk.valid ? 'valid' : 'invalid');
  record.plan.firstTargetTooClose = rewardRisk.valid ? rewardRisk.rewardPerShare < (1.5 * rewardRisk.riskPerShare) : false;
  record.plan.lastPlannedAt = String(context.lastPlannedAt || context.updatedAt || record.plan.lastPlannedAt || '');
  record.plan.source = String(resolvePlanSource(record, {entry, stop, firstTarget}, context.source) || record.plan.source || '');
  const targetAlertLevel = Number.isFinite(firstTarget)
    ? firstTarget
    : (Number.isFinite(previousAlertLevel) && previousAlertLevel !== previousFirstTarget ? previousAlertLevel : null);
  const executionState = deriveExecutionPlanState(record, {
    exitMode:record.plan.exitMode,
    targetLevel:targetAlertLevel,
    currentPrice:record.marketData && record.marketData.price
  });
  record.plan.targetReviewState = executionState.targetReviewState;
  record.plan.targetActionRecommendation = executionState.targetActionRecommendation;
  record.plan.targetAlert = {
    enabled:record.plan.exitMode === 'dynamic_exit' && (record.plan.targetAlert && typeof record.plan.targetAlert === 'object'
      ? record.plan.targetAlert.enabled !== false
      : true),
    level:executionState.targetAlertLevel,
    lastState:executionState.targetReviewState
  };
  stampCanonicalTradePlan(record, context);
  if(context.source && context.source !== 'scanner'){
    applyLifecycleStageFromPlan(record, context.source);
  }
}

function mergeMarketDataIntoRecord(record, card){
  if(!record || !card) return;
  const source = card.marketData && typeof card.marketData === 'object' ? card.marketData : card;
  const history = Array.isArray(source.history) ? source.history : (Array.isArray(record.marketData.history) ? record.marketData.history : []);
  record.marketData = {
    ...record.marketData,
    price:numericOrNull(source.price),
    asOf:String(source.fetchedAt || card.marketDataUpdatedAt || card.updatedAt || record.marketData.asOf || ''),
    source:String(source.sourceProvider || source.dataProvider || record.marketData.source || ''),
    ma20:numericOrNull(source.sma20),
    ma50:numericOrNull(source.sma50),
    ma200:numericOrNull(source.sma200),
    rsi:numericOrNull(source.rsi14),
    avgVolume:numericOrNull(source.avgVolume30d ?? source.avgVolume30),
    volume:numericOrNull(source.volume),
    currency:String(source.currency || record.marketData.currency || ''),
    perf1w:numericOrNull(source.perf1w),
    perf1m:numericOrNull(source.perf1m),
    perf3m:numericOrNull(source.perf3m),
    perf6m:numericOrNull(source.perf6m),
    perfYtd:numericOrNull(source.perfYtd),
    marketCap:numericOrNull(source.marketCap),
    history
  };
  record.meta.companyName = String(card.companyName || record.meta.companyName || '');
  record.meta.exchange = String(card.exchange || record.meta.exchange || '');
  record.meta.tradingViewSymbol = String(card.tradingViewSymbol || record.meta.tradingViewSymbol || '');
}

function mergeLegacyCardIntoRecord(record, legacyCard, options = {}){
  if(!record || !legacyCard) return;
  const card = normalizeCard(legacyCard);
  mergeMarketDataIntoRecord(record, card);
  const estimate = hasUsableScannerData(card.marketData || card) ? scannerEstimateForCard(card) : null;
  const resolvedScanType = normalizeScanType(card.scanType || card.scanSetupType || card.setupType || record.scan.scanSetupType || record.scan.scanType);
  record.scan.scanType = resolvedScanType;
  record.scan.scanSetupType = resolvedScanType;
  record.scan.setupOrigin = String(card.source || (options.fromScanner ? 'scanner' : (options.fromCards ? 'cards' : record.scan.setupOrigin || 'manual')));
  if(estimate){
    record.scan.estimatedEntryZone = numericOrNull(estimate.entry);
    record.scan.estimatedStopArea = numericOrNull(estimate.stop);
    record.scan.estimatedTargetArea = numericOrNull(estimate.target);
    record.scan.estimatedRR = numericOrNull(estimate.rr);
    const hasExistingPlanFields = hasAnyPlanFields(record);
    const currentPlanSource = String(record.plan && record.plan.source || '').trim().toLowerCase();
    if(!hasExistingPlanFields || currentPlanSource === 'scanner_estimate'){
      applyPlanCandidateToRecord(record, {
        entry:estimate.entry,
        stop:estimate.stop,
        firstTarget:estimate.target
      }, {
        source:'scanner_estimate',
        updatedAt:card.scannerUpdatedAt || card.updatedAt || new Date().toISOString(),
        lastPlannedAt:card.scannerUpdatedAt || card.updatedAt || new Date().toISOString()
      });
    }
  }
  record.scan.score = Number.isFinite(card.score) ? card.score : record.scan.score;
  record.scan.verdict = String(card.chartVerdict || card.status || record.scan.verdict || '');
  const scannerCycleReasons = uniqueStrings([
    card.summary,
    card.analysis && card.analysis.failedRule,
    ...(Array.isArray(card.analysis && card.analysis.risks) ? card.analysis.risks : [])
  ]);
  if(options.fromScanner){
    // Scanner refresh should reflect current-cycle reasons only to avoid stale carry-over.
    record.scan.reasons = scannerCycleReasons;
  }else{
    record.scan.reasons = uniqueStrings([card.summary, ...(record.scan.reasons || [])]);
  }
  record.scan.summary = String(card.summary || record.scan.summary || '');
  record.scan.flags = {
    ...(record.scan.flags || {}),
    checks:cloneData(card.checks || {}, {}),
    watchTracking:cloneData(card.watchTracking || null, null)
  };
  record.scan.riskStatus = String(card.riskStatus || record.scan.riskStatus || 'plan_missing');
  record.scan.trendStatus = String(card.trendStatus || record.scan.trendStatus || '');
  record.scan.pullbackStatus = String(card.pullbackStatus || record.scan.pullbackStatus || '');
  record.scan.pullbackType = String(card.pullbackType || record.scan.pullbackType || '');
  record.scan.analysisProjection = cloneData(card.analysis || record.scan.analysisProjection, null);
  const authoritativeScanCycleId = String(card.scannerUpdatedAt || card.updatedAt || new Date().toISOString());
  record.scan.lastScannedAt = String(card.scannerUpdatedAt || record.scan.lastScannedAt || authoritativeScanCycleId);
  record.scan.updatedAt = authoritativeScanCycleId;
  const resolvedScannerVerdict = normalizeAnalysisVerdict(
    card.chartVerdict
    || card.status
    || (card.analysis && card.analysis.chart_verdict)
    || record.scan.verdict
    || ''
  );
  record.scan.resolvedVerdict = resolvedScannerVerdict;
  if(String(options.authoritySource || '').trim()){
    stampTickerJourneyAuthority(record, options.authoritySource, {
      updatedAt:card.scannerUpdatedAt || card.updatedAt || new Date().toISOString(),
      reason:String(options.authorityReason || options.authoritySource || ''),
      allowTrackedAuthorityOverride:options.allowTrackedAuthorityOverride === true,
      forceAuthorityAdvance:options.forceAuthorityAdvance === true
    });
  }
  if(options.fromScanner && resolvedScannerVerdict){
    if(resolvedScannerVerdict === 'Avoid'){
      writeLifecycleState(record, {
        stage:'avoided',
        status:'inactive',
        changedAt:card.scannerUpdatedAt || new Date().toISOString(),
        expiresAt:'',
        expiryReason:'',
        reason:'Scanner or market-data review marked this setup as avoid.',
        source:'scan'
      });
    }else{
      writeLifecycleState(record, {
        stage:'shortlisted',
        tradingDays:WATCHLIST_EXPIRY_TRADING_DAYS,
        reason:'Scanner shortlisted this setup.',
        source:'scan'
      }, {mode:'refresh'});
    }
  }
  record.review.notes = String(card.notes || record.review.notes || '');
  record.review.chartRef = cloneData(card.chartRef || record.review.chartRef, null);
  record.review.chartImageOriginal = cloneData(card.chartImageOriginal || record.review.chartImageOriginal, null);
  record.review.chartImagePreview = cloneData(card.chartImagePreview || record.review.chartImagePreview, null);
  record.review.chartImageVerificationSource = cloneData(card.chartImageVerificationSource || record.review.chartImageVerificationSource, null);
  record.review.chartAvailable = !!(record.review.chartRef && record.review.chartRef.dataUrl);
  record.review.importedFromScreenshot = !!(record.review.importedFromScreenshot || (record.review.chartRef && /latest-chart/i.test(String(record.review.chartRef.name || ''))));
  record.review.analysisState = {
    raw:String(card.lastResponse || (record.review.analysisState && record.review.analysisState.raw) || record.review.aiAnalysisRaw || ''),
    normalized:cloneData(card.lastAnalysis || (record.review.analysisState && record.review.analysisState.normalized) || record.review.normalizedAnalysis, null),
    prompt:String(card.lastPrompt || (record.review.analysisState && record.review.analysisState.prompt) || record.review.lastPrompt || ''),
    error:String(card.lastError || (record.review.analysisState && record.review.analysisState.error) || record.review.lastError || ''),
    reviewedAt:String(card.updatedAt || (record.review.analysisState && record.review.analysisState.reviewedAt) || record.review.lastReviewedAt || '')
  };
  record.review.aiAnalysisRaw = String(card.lastResponse || record.review.aiAnalysisRaw || '');
  record.review.normalizedAnalysis = cloneData(card.lastAnalysis || record.review.normalizedAnalysis, null);
  record.review.lastReviewedAt = String(card.updatedAt || record.review.lastReviewedAt || '');
  record.review.lastPrompt = String(card.lastPrompt || record.review.lastPrompt || '');
  record.review.lastError = String(card.lastError || record.review.lastError || '');
  record.review.manualReview = card.manualReview && typeof card.manualReview === 'object' ? cloneData(card.manualReview, null) : record.review.manualReview;
  if(card.manualReview && typeof card.manualReview === 'object'){
    writeSavedReviewAuthority(record, {
      savedVerdict:String(record.review.savedVerdict || '').trim(),
      savedSummary:String(card.manualReview.summary || record.review.savedSummary || ''),
      savedScore:numericOrNull(card.manualReview.score ?? record.review.savedScore)
    }, {clearProjectionWhenNonEntry:false});
  }
  record.review.source = String(card.source || record.review.source || 'manual');
  record.review.cardOpen = options.cardOpen === true ? true : (options.cardOpen === false ? false : !!(record.review.cardOpen || options.fromCards));
  if(options.fromCards && record.review.cardOpen){
    writeLifecycleState(record, {
      stage:'reviewed',
      tradingDays:REVIEW_EXPIRY_TRADING_DAYS,
      reason:'Ticker opened in Setup Review.',
      source:'review'
    }, {mode:'refresh'});
  }
  record.meta.marketStatus = String(card.marketStatus || record.meta.marketStatus || state.marketStatus || '');
  record.meta.updatedAt = String(card.updatedAt || record.meta.updatedAt || new Date().toISOString());
  record.meta.pinned = !!(card.pinned || record.meta.pinned);
  if(card.lastAnalysis && card.lastAnalysis.plan_metrics_valid){
    record.aiObservation = record.aiObservation && typeof record.aiObservation === 'object'
      ? record.aiObservation
      : {};
    record.aiObservation.observationOnly = true;
    record.aiObservation.rawPlanOpinion = {
      source:'legacy_lastAnalysis',
      nonAuthoritative:true,
      entry:String(card.lastAnalysis.entry || ''),
      stop:String(card.lastAnalysis.stop || ''),
      first_target:String(card.lastAnalysis.first_target || ''),
      reward_risk:card.lastAnalysis.reward_risk == null ? null : String(card.lastAnalysis.reward_risk || ''),
      plan_metrics_valid:card.lastAnalysis.plan_metrics_valid === true
    };
  }
  if(card.manualReview && typeof card.manualReview === 'object'){
    applyPlanCandidateToRecord(record, {
      entry:card.manualReview.entry,
      stop:card.manualReview.stop,
      firstTarget:card.manualReview.target
    }, {
      source:'review',
      lastPlannedAt:card.manualReview.savedAt || card.updatedAt || new Date().toISOString()
    });
  }else if(options.fromCards && (card.entry || card.stop || card.target)){
    applyPlanCandidateToRecord(record, {
      entry:card.entry,
      stop:card.stop,
      firstTarget:card.target
    }, {
      source:'card',
      lastPlannedAt:card.updatedAt || new Date().toISOString()
    });
  }
  if(options.fromScanner){
    // One resolver call and one immutable publication for this ticker/cycle.
    // Subsequent Scan, Review, Track, lifecycle and reload reads reuse it.
    publishCanonicalPublicationForRecord(record);
  }
}

function mergeWatchlistIntoRecord(record, entry){
  if(!record || !entry) return;
  const normalized = normalizeWatchlistEntry(entry);
  if(!normalized) return;
  record.watchlist.inWatchlist = true;
  record.watchlist.addedAt = normalized.dateAdded;
  record.watchlist.addedScore = normalized.scoreWhenAdded;
  record.watchlist.status = normalized.verdictWhenAdded || '';
  record.watchlist.expiryAfterTradingDays = normalized.expiryAfterTradingDays;
  record.watchlist.expiryAt = tradingDaysFrom(normalized.dateAdded, normalized.expiryAfterTradingDays);
  record.watchlist.updatedAt = `${normalized.dateAdded}T12:00:00.000Z`;
  writeLifecycleState(record, {
    stage:'watchlist',
    status:'active',
    changedAt:`${normalized.dateAdded}T12:00:00.000Z`,
    expiresAt:record.watchlist.expiryAt,
    expiryReason:'Watchlist aged beyond the default 5 trading-day window.',
    reason:'Added to watchlist.',
    source:'review'
  });
}

function mergeDiaryRecordIntoRecord(record, tradeRecord){
  if(!record || !tradeRecord) return;
  const normalized = normalizeTradeRecord(tradeRecord);
  const existingIndex = record.diary.records.findIndex(item => item.id === normalized.id);
  if(existingIndex >= 0) record.diary.records.splice(existingIndex, 1, normalized);
  else record.diary.records.push(normalized);
  record.diary.records = record.diary.records
    .map(normalizeTradeRecord)
    .sort((a, b) => String(b.date || '').localeCompare(String(a.date || '')) || String(b.id).localeCompare(String(a.id)));
  record.diary.records = record.diary.records.slice(0, 100);
  record.diary.diaryIds = record.diary.records.map(item => item.id);
  record.diary.hasDiary = !!record.diary.records.length;
  record.diary.lastOutcomeAt = String(normalized.date || record.diary.lastOutcomeAt || '');
  const lifecycle = deriveDiaryLifecycleState(normalized);
  writeLifecycleState(record, {
    stage:lifecycle.stage,
    status:lifecycle.status,
    changedAt:lifecycle.changedAt,
    expiresAt:'',
    expiryReason:'',
    reason:lifecycle.reason,
    source:lifecycle.source
  });
  record.diary.tradeOutcome = buildTradeOutcomeSnapshot(normalized);
}

