  const text = String(label || '');
  if(/Near Entry/i.test(text)) return 'Near Entry';
  if(/Entry/i.test(text)) return 'Entry';
  if(/Broken/i.test(text) || /Avoid/i.test(text) || /Dead/i.test(text)) return 'Avoid';
