function renderScannerDecisionTraceContent(view){
  const markup = renderScannerDecisionTraceContentImpl(view, scannerDebugBridgeDeps());
  const simplified = view && view.simplifiedState && typeof view.simplifiedState === 'object' ? view.simplifiedState : null;
  if(!simplified || typeof markup !== 'string') return markup;
  const canonicalVerdict = String(simplified.canonicalVerdict || '').trim().toLowerCase();
  const visualBucket = String(simplified.visualBucket || '').trim().toLowerCase();
  const tone = String(simplified.tone || '').trim().toLowerCase();
  const badgeLabel = String(simplified.badgeLabel || '').trim();
  const planStatus = String(simplified.planStatus || '').trim().toLowerCase();
  if(!canonicalVerdict) return markup;
  const planBlocked = ['invalid','missing'].includes(planStatus) ? 'true' : 'false';
  if(typeof document === 'undefined') return markup;
  const host = document.createElement('div');
  host.innerHTML = markup;
  const replacements = {
    'Bucket Rendered':visualBucket || 'monitor',
    'Scanner Verdict':canonicalVerdict,
    'Final Verdict':canonicalVerdict,
    'Tone':tone || 'monitor',
    'Bucket':visualBucket || 'monitor',
    'Badge':badgeLabel || globalVerdictLabel(canonicalVerdict),
    'Plan Blocked':planBlocked
  };
  host.querySelectorAll('.watchlist-debug-grid > div').forEach(row => {
    const labelNode = row.querySelector('strong');
    const valueNode = labelNode ? labelNode.nextElementSibling : null;
    const label = labelNode ? String(labelNode.textContent || '').trim() : '';
    if(label && valueNode && Object.prototype.hasOwnProperty.call(replacements, label)){
      valueNode.textContent = replacements[label];
    }
  });
  const classification = simplified.classificationDiagnostics || simplified.debug && simplified.debug.classification;
  if(classification && typeof classification === 'object'){
    const rows = [
      ['displayedBucket', classification.displayedBucket],
      ['displayedSetupScore', classification.displayedSetupScore],
      ['canonicalBucket', classification.canonicalBucket],
      ['canonicalEntryEligibility', classification.canonicalEntryEligibility],
      ['canonicalNearEntryEligibility', classification.canonicalNearEntryEligibility],
      ['structureState', classification.structureState],
      ['supportState', classification.supportState],
      ['buyerControlState', classification.buyerControlState],
      ['confirmationState', classification.confirmationState],
      ['planValidity', classification.planValidity],
      ['scoreBreakdown', JSON.stringify(classification.scoreBreakdown || {})],
      ['bucketReason', classification.bucketReason],
      ['legacyFallbackUsed', classification.legacyFallbackUsed]
    ];
    host.innerHTML += `<div class="diagnostic-panel-shell watchlist-debug-block" data-diagnostic-panel="Canonical Setup Projection"><details class="compact-details diagnostic-panel-details"><summary>Canonical Setup Projection</summary><div class="watchlist-debug-grid tiny">${rows.map(([label, value]) => `<div><strong>${escapeHtml(label)}</strong><div>${escapeHtml(String(value == null ? '(none)' : value))}</div></div>`).join('')}</div></details></div>`;
  }
  const classProjection = view && view.projectionClassDiagnostics;
  if(classProjection && typeof classProjection === 'object'){
    const rows = ['previousAccentClass','projectedAccentClass','previousVisualTone','projectedVisualTone','previousVisualState','projectedVisualState','finalClassName']
      .map(label => [label, classProjection[label]]);
    host.innerHTML += `<div class="diagnostic-panel-shell watchlist-debug-block" data-diagnostic-panel="Projected Card Classes"><details class="compact-details diagnostic-panel-details"><summary>Projected Card Classes</summary><div class="watchlist-debug-grid tiny">${rows.map(([label, value]) => `<div><strong>${escapeHtml(label)}</strong><div>${escapeHtml(String(value == null ? '(none)' : value))}</div></div>`).join('')}</div></details></div>`;
  }
  return host.innerHTML;
}

function currentScanCardMenuState(ticker){
  const symbol = normalizeTicker(ticker);
  const menu = uiState.scanCardMenu || {ticker:'', menuOpen:false, activeSubmenu:null};
  if(!symbol || menu.ticker !== symbol) return {ticker:'', menuOpen:false, activeSubmenu:null};
  return {...menu};
}

function currentScanCardSecondaryUi(ticker){
  const menuState = currentScanCardMenuState(ticker);
  if(!menuState.menuOpen) return null;
  return menuState.activeSubmenu || 'menu';
}

function setScanCardSecondaryUi(ticker, mode){
  if(mode === 'menu'){
    toggleScanCardMenu(ticker);
  }else if(['details','trace','visual-debug'].includes(mode)){
    setScanCardActiveSubmenu(ticker, mode);
  }
}

function clearScanCardSecondaryUi(){
  closeScanCardMenu();
}

function toggleScanCardMenu(ticker){
  const symbol = normalizeTicker(ticker);
  if(!symbol) return;
  const state = currentScanCardMenuState(symbol);
  if(state.menuOpen){
    if(state.activeSubmenu){
      closeScanCardSubmenu();
    }else{
      closeScanCardMenu();
    }
    return;
  }
  openScanCardMenu(symbol);
}

function openScanCardMenu(ticker){
  const symbol = normalizeTicker(ticker);
  if(!symbol) return;
  uiState.scanCardMenu = {ticker:symbol, menuOpen:true, activeSubmenu:null};
}

