function renderCompactResultCardFromView(view){
  const item = view && view.item ? view.item : {};
  const setupStates = view && view.setupStates ? view.setupStates : analysisDerivedStatesFromRecord(item);
  const simplifiedState = view && view.simplifiedState ? view.simplifiedState : resolveSimplifiedStateForSurface(item, 'scan', {
    source:'scan_render',
    mutationSource:'scan_render'
  });
  if(simplifiedState.publicationStatus !== 'valid'){
    return `<div class="resultcompact result-card result-feed-card scan-card visual-state-card visual-state-unavailable visual-tone-unavailable card--unavailable" data-visual-tone="unavailable" data-visual-state="unavailable" data-ticker="${escapeHtml(item.ticker || '')}" data-source-verdict=""><div class="scan-card__header"><div class="scan-card__header-row"><div class="scan-card__ticker ticker">${escapeHtml(item.ticker || '')}</div></div><div class="scan-card__status badge-score-row result-feed-card__status"><span class="badge state-pill badge--unavailable">Not assessed</span></div></div><div class="scan-card__body"><div class="scan-card__decision resultreason decision-summary">Not assessed yet. Run an authoritative refresh to publish a decision.</div></div></div>`;
  }
  // Scan presentation is a pure projection of the freshly published
  // simplified state. Cached Scan snapshots are diagnostic/history only and
  // must never replace its canonical status, bucket, or tone.
  const canonicalVerdict = normalizeGlobalVerdictKey(
    simplifiedState.canonicalVerdict
    || 'watch'
  );
  const scanPresentation = view && view.scanPresentation
    ? view.scanPresentation
    : scanPresentationForView({
      ...view,
      simplifiedState
    });
  const scanPresentationCanonical = normalizeGlobalVerdictKey(scanPresentation.canonicalVerdict || '');
  const presentationBucketAligned = isAllowedCanonicalVisualPair(
    canonicalVerdict,
    scanPresentation.presentationBucket || scanPresentation.visualBucket || ''
  );
  const effectiveScanPresentation = (
    (scanPresentationCanonical && scanPresentationCanonical !== canonicalVerdict)
    || !presentationBucketAligned
  )
    ? {
      ...scanPresentation,
      canonicalVerdict,
      resolvedStatus:canonicalVerdict,
      visualBucket:String(
        simplifiedState.visualBucket
        || scanPresentation.visualBucket
        || 'monitor'
      ).trim().toLowerCase() || 'monitor',
      presentationBucket:String(
        simplifiedState.visualBucket
        || scanPresentation.presentationBucket
        || 'monitor'
      ).trim().toLowerCase() || 'monitor',
      tone:normalizeVisualBucketForPairing(
        simplifiedState.visualBucket
        || scanPresentation.presentationBucket
        || scanPresentation.visualBucket
        || 'monitor',
        canonicalVerdict
      ),
      badgeLabel:String(verdictPresentationLabelForKey(canonicalVerdict) || 'Watch').trim(),
      summary:String(
        simplifiedState.mainBlocker
        || simplifiedState.actionLabel
        || scanPresentation.summary
        || ''
      ).trim()
    }
    : scanPresentation;
  const renderedScanPresentationBucket = String(
    effectiveScanPresentation.presentationBucket
    || effectiveScanPresentation.visualBucket
    || ''
  ).trim().toLowerCase();
  const publicScanPresentationBucket = normalizeVisualBucketForPairing(
    simplifiedState.visualBucket
    || effectiveScanPresentation.presentationBucket
    || effectiveScanPresentation.visualBucket
    || simplifiedState.visualBucket
    || 'monitor',
    canonicalVerdict
  );
  const visualBucket = publicScanPresentationBucket;
  const tone = normalizeVisualBucketForPairing(visualBucket || 'monitor', canonicalVerdict);
  const badgeClass = simplifiedVisualBadgeClass(visualBucket);
  const cardClass = simplifiedVisualCardClass(visualBucket);
  const scanLegacyState = view && view.globalVerdict && typeof view.globalVerdict === 'object'
    ? view.globalVerdict
    : (view && typeof view === 'object' ? view : {});
  const scanStateDivergence = collectStateDivergence(item, 'scan.render', simplifiedState, {
    canonicalVerdict:scanLegacyState.final_verdict || scanLegacyState.finalVerdict || scanLegacyState.canonicalVerdict || '',
    visualBucket:scanLegacyState.visualBucket || scanLegacyState.presentationBucket || scanLegacyState.bucket || '',
    tone:scanLegacyState.tone || scanLegacyState.visual_tone || '',
    badgeLabel:scanLegacyState.badgeLabel || scanLegacyState.badge && scanLegacyState.badge.text || '',
    mainBlocker:scanLegacyState.main_blocker || scanLegacyState.reason || scanLegacyState.mainBlocker || '',
    planStatus:scanLegacyState.plan_status || scanLegacyState.planStatus || scanLegacyState.planStatusKey || '',
    entryGatePass:scanLegacyState.entry_gate_pass,
    nearEntryGatePass:scanLegacyState.near_entry_gate_pass,
    structureEligibility:scanLegacyState.structure_eligibility || '',
    structureState:scanLegacyState.structure_state || '',
    priceabilityState:scanLegacyState.priceability_state || '',
    bounceState:scanLegacyState.bounce_state || ''
  }, [
    'canonicalVerdict',
    'visualBucket',
    'tone',
    'badgeLabel',
    'mainBlocker',
    'planStatus',
    'entryGatePass',
    'nearEntryGatePass',
    'structureEligibility',
    'structureState',
    'priceabilityState',
    'bounceState'
  ]);
  const visualStateKey = presentationVisualStateForVerdict(canonicalVerdict);
  const className = `visual-state-card visual-state-${visualStateKey} visual-tone-${tone} ${cardClass}`;
  const sourceVerdict = globalVerdictLabel(canonicalVerdict);
  const scoreLabel = view && view.setupScoreDisplay ? view.setupScoreDisplay : 'Setup --/10';
  const menuState = currentScanCardMenuState(item.ticker);
  const renderView = {
    ...view,
    simplifiedState,
    scanPresentation:effectiveScanPresentation,
    canonicalVerdict,
    visualBucket,
    tone,
    badgeLabel:verdictPresentationLabelForKey(canonicalVerdict),
    actionLabel:simplifiedState.actionLabel,
    planVisible:simplifiedState.planVisible,
    planStatus:simplifiedState.planStatus,
    mainBlocker:simplifiedState.mainBlocker,
    entryGatePass:simplifiedState.entryGatePass,
    nearEntryGatePass:simplifiedState.nearEntryGatePass,
    blockers:simplifiedState.blockers,
    displayStage:globalVerdictLabel(canonicalVerdict),
    finalVerdict:globalVerdictLabel(canonicalVerdict)
  };
  const finalScanPresentationBucket = String(
    publicScanPresentationBucket
    || renderedScanPresentationBucket
    || visualBucket
    || ''
  ).trim().toLowerCase();
  const forceBucketSummaryIntoNarrative = ['diminishing', 'avoid'].includes(finalScanPresentationBucket);
  const scanNarrativeState = {
    ...simplifiedState,
    canonicalVerdict:effectiveScanPresentation.canonicalVerdict || canonicalVerdict || simplifiedState.canonicalVerdict,
    visualBucket:publicScanPresentationBucket || effectiveScanPresentation.presentationBucket || effectiveScanPresentation.visualBucket || visualBucket || simplifiedState.visualBucket,
    presentationBucket:publicScanPresentationBucket || effectiveScanPresentation.presentationBucket || effectiveScanPresentation.visualBucket || visualBucket || simplifiedState.presentationBucket,
    tone:effectiveScanPresentation.tone || tone || simplifiedState.tone,
    badgeLabel:effectiveScanPresentation.badgeLabel || simplifiedState.badgeLabel,
    actionLabel:forceBucketSummaryIntoNarrative ? (effectiveScanPresentation.summary || simplifiedState.actionLabel) : simplifiedState.actionLabel,
    mainBlocker:forceBucketSummaryIntoNarrative ? (effectiveScanPresentation.summary || simplifiedState.mainBlocker) : simplifiedState.mainBlocker
  };
  const sharedNarrative = buildSharedSetupNarrative({
    simplifiedState:scanNarrativeState,
    resolvedState:simplifiedState.debug && simplifiedState.debug.resolvedState,
    derivedStates:setupStates,
    globalVerdict:scanLegacyState
  });
  const secondaryUiMarkup = renderScanCardSecondaryUi(renderView);
  const companyLine = [item && item.meta && item.meta.companyName || '', item && item.meta && item.meta.exchange || ''].filter(Boolean).join(' | ');
  const technicalSummary = scanCardTechnicalSummaryForView(view);
  const scanPresentationSummary = String(effectiveScanPresentation.summary || '').trim();
  const scanPublicSummaryForPresentation = (() => {
    if(finalScanPresentationBucket === 'diminishing'){
      const diminishingReason = String(sharedNarrative.primaryReason || '').trim();
      if(diminishingReason && /diminishing|losing quality|weakening|stabilis/i.test(diminishingReason)){
        return `Diminishing Watch - ${diminishingReason}`;
      }
      return 'Diminishing Watch - The setup is losing quality, so wait for the chart to stabilise before considering an entry.';
    }
    if(finalScanPresentationBucket === 'avoid'){
      const avoidReason = String(sharedNarrative.primaryReason || '').trim();
      if(avoidReason && /avoid|not tradable|not actionable|broken|failed|blocking issue/i.test(avoidReason)){
        return `Avoid - ${avoidReason}`;
      }
      return 'Avoid - A blocking issue is active, so the setup is not tradable.';
    }
    return '';
  })();
  const sharedNarrativeStateLabel = String(sharedNarrative.stateLabel || '').trim();
  const sharedNarrativePrimaryReason = String(sharedNarrative.primaryReason || '').trim();
  const monitorNarrativeMismatched = finalScanPresentationBucket === 'monitor'
    && (
      /Diminishing Watch|^Avoid\b/i.test(sharedNarrativeStateLabel)
      || /losing quality|not tradable|blocking issue|structure rebuilds|avoid until/i.test(sharedNarrativePrimaryReason)
    );
  const monitorSafePrimaryReason = monitorNarrativeMismatched
    ? (scanPresentationSummary || simplifiedState.mainBlocker || simplifiedState.actionLabel || '')
    : sharedNarrativePrimaryReason;
  const monitorSafeStateLabel = monitorNarrativeMismatched
    ? 'Developing Watch'
    : sharedNarrativeStateLabel;
  let decisionSummary = String(
    scanPublicSummaryForPresentation
      ? scanPublicSummaryForPresentation
      : (
        monitorSafeStateLabel && !sameVisibleCopy(monitorSafeStateLabel, simplifiedState.badgeLabel || effectiveScanPresentation.badgeLabel || globalVerdictLabel(canonicalVerdict) || '')
          ? `${monitorSafeStateLabel} - ${monitorSafePrimaryReason || scanPresentationSummary || simplifiedState.mainBlocker || simplifiedState.actionLabel || ''}`
          : (monitorSafePrimaryReason || scanPresentationSummary || simplifiedState.mainBlocker || simplifiedState.actionLabel || '')
      )
  ).trim()
    || compactReasonLineForView(view, 3)
    || scanCardPrimaryActionLabel(view);
  if(
    tone === 'monitor'
    && /Diminishing Watch|^Avoid\b/i.test(String(decisionSummary || ''))
  ){
    const monitorSummary = String(
      scanPresentationSummary
      || simplifiedState.mainBlocker
      || simplifiedState.actionLabel
      || 'Wait for stronger confirmation before considering an entry.'
    ).trim();
    decisionSummary = `Developing Watch - ${monitorSummary}`.trim();
  }
  if(typeof console !== 'undefined' && console.info){
    console.info('[SCAN_PRESENTATION_GROUP]', {
      ticker:item.ticker || '',
      canonicalVerdict:effectiveScanPresentation.canonicalVerdict || canonicalVerdict,
      visualBucket:effectiveScanPresentation.visualBucket || simplifiedState.visualBucket || '',
      presentationBucket:effectiveScanPresentation.presentationBucket || visualBucket,
      scanSection:effectiveScanPresentation.scanSection || '',
      tone,
      badgeLabel:simplifiedState.badgeLabel || effectiveScanPresentation.badgeLabel || '',
      reasonCode:effectiveScanPresentation.reasonCode || '',
      sortPriority:effectiveScanPresentation.sortPriority
    });
  }
  if(typeof console !== 'undefined' && console.info){
    console.info('[SIMPLIFIED_SCAN_STATE]', {
      ticker:simplifiedState.ticker || item.ticker,
      canonicalVerdict:simplifiedState.canonicalVerdict,
      visualBucket:simplifiedState.visualBucket,
      tone:simplifiedState.tone,
      badgeLabel:simplifiedState.badgeLabel || effectiveScanPresentation.badgeLabel,
      mainBlocker:simplifiedState.mainBlocker,
      primaryBlockerSource:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.primary_blocker_source || '',
      projectionBundleAuthoritative:false,
      divergenceDetected:scanStateDivergence.detected
    });
  }
  debugTickerStateSources(item && item.ticker, 'scan', {
    source:'simplified_state_pipeline',
    sectionKey:'scan',
    canonicalVerdict,
    finalVerdict:canonicalVerdict,
    renderedVerdict:canonicalVerdict,
    visualBucket,
    presentationBucket:visualBucket,
    tone,
    badgeLabel:simplifiedState.badgeLabel || '',
    mainBlocker:simplifiedState.mainBlocker || '',
    primaryBlockerSource:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.primary_blocker_source || '',
    sourceOfTruthVisualBucket:visualBucket,
    divergenceDetected:scanStateDivergence.detected,
    divergenceFields:scanStateDivergence.fields,
    projectionBundleAuthoritative:false,
    className,
    cardClass,
    shellClass:'',
    accentClass:'',
    styleAttr:'',
    structure:setupStates.structureState || '',
    setupLocationState:setupStates.setupLocationState || '',
    priceabilityState:setupStates.priceabilityState || '',
    pullback:setupStates.pullbackZone || setupStates.pullbackState || '',
    bounce:setupStates.bounceState || '',
    viability:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.viability || '',
    viabilityReason:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.viability_reason || '',
    viabilityBranchId:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.viabilityBranchId || '',
    viabilityBranchLabel:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.viabilityBranchLabel || '',
    viabilityBranchReason:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.viabilityBranchReason || '',
    viabilityInputs:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.viabilityInputs || null,
    terminalAvoidApplied:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.terminal_avoid_applied === true,
    hardTerminalAvoid:false,
    explicitInvalidationReason:simplifiedState.debug && simplifiedState.debug.resolvedState && simplifiedState.debug.resolvedState.explicit_invalidation_reason || '',
    sourceFields:{
      badge:'simplifiedState.badgeLabel',
      headlineCopy:'simplifiedState.mainBlocker/actionLabel',
      actionGuidance:'simplifiedState.actionLabel',
      shellColour:'simplifiedState.visualBucket/tone',
      leftAccentColour:'simplifiedState.visualBucket/tone',
      sectionBucket:'simplifiedState.visualBucket'
    },
    fromStoredFields:false,
    fromResolvedStateBundleCache:false,
    fromFreshResolverOutput:true
  });
  return `<div class="resultcompact result-card result-feed-card scan-card ${escapeHtml(className)}" style="" data-visual-tone="${escapeHtml(tone)}" data-visual-state="${escapeHtml(visualStateKey)}" data-ticker="${escapeHtml(item.ticker || '')}" data-source-verdict="${escapeHtml(sourceVerdict)}"><div class="scan-card__header"><div class="scan-card__header-row"><div class="scan-card__ticker ticker">${escapeHtml(item.ticker || '')}</div></div><div class="scan-card__status badge-score-row result-feed-card__status"><span class="badge state-pill ${escapeHtml(badgeClass)}">${escapeHtml(verdictPresentationLabelForKey(canonicalVerdict) || 'Watch')}</span><span class="score visual-score scan-card__score">${escapeHtml(scoreLabel)}</span></div>${companyLine ? `<div class="scan-card__company tiny resultsupport">${escapeHtml(companyLine)}</div>` : ''}</div><div class="scan-card__body"><div class="scan-card__technical tiny">${escapeHtml(technicalSummary)}</div><div class="scan-card__decision resultreason decision-summary">${escapeHtml(decisionSummary)}</div></div><div class="scan-card__footer"><button class="card-overflow-button no-card-click" type="button" data-act="overflow-toggle" aria-label="Open card actions" aria-expanded="${menuState.menuOpen ? 'true' : 'false'}"><span class="dot"></span><span class="dot"></span><span class="dot"></span></button></div>${secondaryUiMarkup}</div>`;
}

