function downloadJsonFile(filename, data){
  try{
    const blob = new Blob([JSON.stringify(data, null, 2)], {type:'application/json'});
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return true;
  }catch(error){
    return false;
  }
}

function exportTradeDiary(){
  diaryFeature.exportTradeDiary();
}

function updateTickerSearchStatus(){
  const search = tickerSearchState();
  if(!currentProviderConfig().supportsSearch){
    setStatus('tickerSearchStatus', `<span class="tiny">${escapeHtml(currentProviderLabel())} search is not wired yet. Add tickers manually or from TradingView import.</span>`);
  }else if(!search.query){
    setStatus('tickerSearchStatus', `<span class="tiny">Add one ticker quickly, or search ${escapeHtml(currentProviderLabel())} symbols below.</span>`);
  }else if(!search.valid){
    setStatus('tickerSearchStatus', `<span class="badtext">${escapeHtml(search.query)} is not a valid ticker format.</span>`);
  }else if(search.inUniverse){
    setStatus('tickerSearchStatus', `<span class="warntext">${escapeHtml(search.query)} is already in the scanner universe.</span>`);
  }else{
    setStatus('tickerSearchStatus', `<span class="ok">${escapeHtml(search.query)} is ready to add.</span>`);
  }
  renderTickerQuickLists();
}

function renderTickerSuggestions(results){
  const box = $('tickerSuggestions');
  if(!box) return;
  const list = Array.isArray(results) ? results : [];
  if(!list.length){
    box.innerHTML = '';
    box.hidden = true;
    return;
  }
  box.hidden = false;
  box.innerHTML = list.map(item => (
    `<button class="suggestionitem" type="button" data-act="suggestion" data-ticker="${escapeHtml(item.ticker)}">
      <span><strong>${escapeHtml(item.ticker)}</strong> ${escapeHtml(item.companyName || '')}</span>
      <span class="tiny">${escapeHtml(item.exchange || '')}</span>
    </button>`
  )).join('');
  box.querySelectorAll('[data-act="suggestion"]').forEach(button => {
    button.onclick = () => {
      const ticker = button.getAttribute('data-ticker') || '';
      const selected = list.find(item => item.ticker === ticker);
      if(selected){
        rememberTickerMeta(selected);
        $('tickerSearch').value = selected.ticker;
        renderTickerSuggestions([]);
        updateTickerSearchStatus();
      }
    };
  });
}

async function updateTickerSuggestions(){
  const search = tickerSearchState();
  if(!currentProviderConfig().supportsSearch){
    renderTickerSuggestions([]);
    return;
  }
  if(!search.query || search.query.length < 1){
    renderTickerSuggestions([]);
    return;
  }
  const token = ++suggestionRequestToken;
  try{
    const results = await fetchTickerSuggestions(search.query);
    if(token !== suggestionRequestToken) return;
    renderTickerSuggestions(results);
  }catch(err){
    if(token !== suggestionRequestToken) return;
    renderTickerSuggestions([]);
  }
}

function queueTickerSuggestions(){
  clearTimeout(suggestionTimer);
  suggestionTimer = setTimeout(() => {
    updateTickerSuggestions().catch(() => {});
  }, SEARCH_DEBOUNCE_MS);
}

function setScanInProgress(next){
  uiState.scanInProgress = !!next;
  const button = $('buildBtn');
  if(button) button.disabled = uiState.scanInProgress;
}

async function buildCards(){
  if(uiState.scanInProgress){
    setStatus('apiStatus', '<span class="warntext">Scan already running...</span>');
    return {done:0, failed:0, rejected:0};
  }
  setScanInProgress(true);
  uiState.selectedScanner = {};
  try{
    const result = await runScannerWorkflow({force:true, syncInput:true});
    const resultsToggle = $('resultsToggle');
    const resultsSection = $('resultsSection');
    if(resultsToggle) resultsToggle.open = true;
    if(resultsSection){
      if(isTrackRestoreOrRevealPending()){
        traceScrollDriver('scroll-driver:scrollIntoView', {
          caller:'buildCards',
          target:'#resultsSection',
          behavior:'smooth',
          blocked:true
        });
      }else{
      traceScrollEvent('scrollIntoView:before', {
        caller:'buildCards',
        target:'#resultsSection',
        options:{behavior:'smooth', block:'start'}
      });
      suppressScrollMemoryForAppScroll('scroll_into_view_scan_results', 1000);
      resultsSection.scrollIntoView({behavior:'smooth', block:'start'});
      traceScrollEvent('scrollIntoView:after', {
        caller:'buildCards',
        target:'#resultsSection'
      });
      }
    }
    return result;
  }catch(err){
    pushRuntimeDebugEntry('buildCards.catch', {
      message:err && err.message ? err.message : 'buildCards failed',
      stack:err && err.stack ? err.stack : ''
    });
    setStatus('apiStatus', `<span class="badtext">${escapeHtml(err.message || 'Scanner failed.')}</span>`);
    return {done:0, failed:0, rejected:0};
  }finally{
    setScanInProgress(false);
  }
}

function addTicker(rawTicker, meta){
  const input = $('tickerSearch');
  const ticker = normalizeTicker(rawTicker || (input && input.value));
  if(!ticker){
    setStatus('tickerSearchStatus', '<span class="warntext">Enter a ticker first.</span>');
    return;
  }
  if(!validateTickerSymbol(ticker)){
    setStatus('tickerSearchStatus', `<span class="badtext">${escapeHtml(ticker)} is not a valid ticker format.</span>`);
    return;
  }
  if(state.tickers.includes(ticker)){
    setStatus('tickerSearchStatus', `<span class="warntext">${escapeHtml(ticker)} is already in the scanner universe.</span>`);
    if(input) input.select();
    return;
  }
  const scanType = normalizeScanType((meta && meta.scanType) || selectedQuickScanType());
  if(meta || scanType) rememberTickerMeta({...meta, ticker, scanType});
  state.tickers.push(ticker);
  upsertTickerRecord(ticker);
  updateRecentTickers([ticker]);
  updateTickerInputFromState();
  if(input) input.value = '';
  renderTickerSuggestions([]);
  commitTickerState();
  renderTickerQuickLists();
  renderScannerResults();
  renderCards();
  setStatus('tickerSearchStatus', `<span class="ok">${escapeHtml(ticker)} added to the scanner universe.</span>`);
  if(!meta || (!meta.companyName && !meta.exchange && !meta.tradingViewSymbol)){
    hydrateTickerMetaForManualAdd(ticker).catch(() => {});
  }
}

function addTickerFromSearch(){
  addTicker();
}

function removeTicker(ticker){
  state.tickers = state.tickers.filter(item => item !== ticker);
  state.scannerResults = state.scannerResults.filter(card => card.ticker !== ticker);
  state.cards = state.cards.filter(card => card.ticker !== ticker);
  state.watchlist = state.watchlist.filter(entry => entry.ticker !== ticker);
  state.tradeDiary = state.tradeDiary.filter(entry => entry.ticker !== ticker);
  delete state.tickerRecords[normalizeTicker(ticker)];
  delete uiState.selectedScanner[ticker];
  delete uiState.promptOpen[ticker];
  delete uiState.responseOpen[ticker];
  if(activeReviewTicker() === ticker) resetReview();
  updateTickerInputFromState();
  commitTickerState();
  renderTickerQuickLists();
  renderScannerResults();
  renderCards();
  updateTickerSearchStatus();
  scrollToScannerResults();
}

function scrollToScannerResults(){
  const target = $('resultsSection') || $('results');
  if(!target) return;
  if(isTrackRestoreOrRevealPending()){
    traceScrollDriver('scroll-driver:scrollIntoView', {
      caller:'scrollToScannerResults',
      target:target.id ? `#${target.id}` : 'scanner_results',
      behavior:'smooth',
      blocked:true
    });
    return;
  }
  traceScrollEvent('scrollIntoView:before', {
    caller:'scrollToScannerResults',
    target:target.id ? `#${target.id}` : 'scanner_results',
    options:{behavior:'smooth', block:'start'}
  });
  suppressScrollMemoryForAppScroll('scroll_into_view_scanner_results', 1000);
  target.scrollIntoView({behavior:'smooth', block:'start'});
  traceScrollEvent('scrollIntoView:after', {
    caller:'scrollToScannerResults',
    target:target.id ? `#${target.id}` : 'scanner_results'
  });
}

function removeCard(ticker){
  state.cards = state.cards.filter(card => card.ticker !== ticker);
  const record = getTickerRecord(ticker);
  if(record) record.review.cardOpen = false;
  delete uiState.promptOpen[ticker];
  delete uiState.responseOpen[ticker];
  if(activeReviewTicker() === ticker) resetReview();
  const normalized = normalizeTicker(ticker);
  if(normalized){
    uiState.scannerSessionTickers = uniqueTickers((uiState.scannerSessionTickers || []).filter(item => normalizeTicker(item) !== normalized));
  }
  commitTickerState();
  renderCards();
  renderScannerResults();
  renderFocusQueue();
}

function clampReviewChecklistScore(score){
  const numeric = Number(score);
  if(!Number.isFinite(numeric)) return 0;
  return Math.max(0, Math.min(10, Math.round(numeric)));
}

function setupQualityLabelForScore(score){
  const numeric = clampReviewChecklistScore(score);
  if(numeric <= 3) return 'Poor';
  if(numeric <= 5) return 'Weak';
  if(numeric <= 7) return 'Developing';
  if(numeric <= 8) return 'Constructive';
  return 'Strong';
}

function resolverAlignedSetupScore(score, checks, context = {}){
  const hasResolverContext = !!(context && typeof context === 'object' && Object.keys(context).length);
  const finalVerdict = String(context.canonicalVerdict || context.finalVerdict || '').trim().toLowerCase();
  const structureState = String(context.structureState || '').trim().toLowerCase();
  const bounceState = String(context.bounceState || '').trim().toLowerCase();
  const stabilisationState = String(context.stabilisationState || '').trim().toLowerCase();
  const planStatus = String(context.planStatus || '').trim().toLowerCase();
  const priceabilityState = String(context.priceabilityState || '').trim().toLowerCase();
  const mainBlocker = String(context.mainBlocker || context.unpriceableBlockReason || '').trim();
  const viabilityRejected = context.viability === 'reject' || context.rejectedByViabilityGate === true;
  const terminalAvoid = context.terminalAvoidApplied === true || context.terminal_avoid_applied === true;
  const planBlocked = context.planValid === false
    || context.planVisible === false
    || ['invalid','missing','blocked','not_generated'].includes(planStatus);
  const noReliableStop = context.hasClearInvalidationLevel === false
    || /no valid invalidation|no reliable stop|reliable stop|cannot be priced|not priceable/i.test(mainBlocker);
  const unpriceable = priceabilityState === 'unpriceable'
    || context.hasPriceablePlan === false
    || /unpriceable|not priceable|cannot be priced/i.test(mainBlocker);
  let cap = 10;
  if(['broken','dead','failed'].includes(structureState) || terminalAvoid){
    cap = Math.min(cap, finalVerdict === 'avoid' || viabilityRejected || terminalAvoid ? 2 : 3);
  }else if(finalVerdict === 'avoid' || viabilityRejected){
    cap = Math.min(cap, 3);
  }else if(['weak','weakening'].includes(structureState)){
    cap = Math.min(cap, 4);
  }
  if(planBlocked || noReliableStop || unpriceable){
    cap = Math.min(cap, 6);
  }
  if((!bounceState || bounceState === 'none') && (!stabilisationState || stabilisationState === 'none')){
    cap = Math.min(cap, 6);
  }
  if(hasResolverContext && finalVerdict !== 'entry' && context.entryGatePass !== true){
    cap = Math.min(cap, 9);
  }
  if(hasResolverContext && !['entry','near_entry'].includes(finalVerdict) && context.nearEntryGatePass !== true && context.entryGatePass !== true){
    cap = Math.min(cap, 8);
  }
  return Math.min(clampReviewChecklistScore(score), cap);
}

function scoreAndStatusFromChecks(checks, context = {}){
  const nearMA = !!(checks.near20 || checks.near50);
  const trendStrong = !!checks.trendStrong;
  const above50 = !!checks.above50;
  const above200 = !!checks.above200;
  const ma50gt200 = !!checks.ma50gt200;
  const stabilising = !!checks.stabilising;
  const bounce = !!checks.bounce;
  const volume = !!checks.volume;
  const tradePlan = !!(checks.entryDefined && checks.stopDefined && checks.targetDefined);
  const finalVerdict = String(context.canonicalVerdict || context.finalVerdict || '').trim().toLowerCase();
  const viabilityRejected = context.viability === 'reject' || context.rejectedByViabilityGate === true;
  const planInvalid = context.planValid === false || ['invalid','missing'].includes(String(context.planStatus || '').trim().toLowerCase());
  let score = 0;
  if(trendStrong) score += 2;
  if(above50) score += 1;
  if(above200) score += 1;
  if(ma50gt200) score += 1;
  if(nearMA) score += 2;
  if(stabilising) score += 1;
  if(bounce) score += 1;
  if(volume) score += 1;
  if(tradePlan) score += 1;
  let status = 'Watch';
  const hardFail = !above50 || !above200 || !nearMA || !trendStrong;
  if(hardFail) status = 'Avoid';
  else if(stabilising && bounce && tradePlan) status = 'Entry';
  else if(stabilising) status = 'Near Entry';
  if(finalVerdict === 'avoid' || viabilityRejected) status = 'Avoid';
  else if(planInvalid && status === 'Entry') status = 'Watch';
  if(status === 'Entry' && context.entryGatePass === false) status = 'Watch';
  if(status === 'Near Entry' && context.nearEntryGatePass === false && context.entryGatePass !== true) status = 'Watch';
  score = resolverAlignedSetupScore(score, checks, context);
  return {score, status, qualityLabel:setupQualityLabelForScore(score)};
}

function buildSummary(checks, status, context = {}){
  const nearMA = checks.near20 || checks.near50;
  const stabilising = !!checks.stabilising;
  const bounce = !!checks.bounce;
  const trendStrong = !!checks.trendStrong;
  const above50 = !!checks.above50;
  const above200 = !!checks.above200;
  const structureState = String(context.structureState || '').trim().toLowerCase();
  const bounceState = String(context.bounceState || '').trim().toLowerCase();
  const stabilisationState = String(context.stabilisationState || '').trim().toLowerCase();
  const planStatus = String(context.planStatus || '').trim().toLowerCase();
  const finalVerdict = String(context.canonicalVerdict || context.finalVerdict || '').trim().toLowerCase();
  const mainBlocker = String(context.mainBlocker || '').trim();
  const reviewEvidence = reviewCopyEvidence({
    structureState,
    structureEligibility:context.structureEligibility,
    bounceState,
    stabilisationState,
    pullbackState:context.pullbackZone,
    setupLocationState:context.setupLocationState,
    priceabilityState:context.priceabilityState,
    finalVerdict
  });
  const nonTerminalRecoveryBlocker = context.nonTerminalRecoveryBlocker === true;
  const viabilityRejected = context.viability === 'reject' || context.rejectedByViabilityGate === true;
  const planBlocked = context.planValid === false || ['invalid','missing'].includes(planStatus) || context.planVisible === false;
  if(reviewEvidence.consolidating){
    const copy = reviewConsolidationPresentationCopy();
    return planBlocked
      ? `${copy.untradable} ${copy.summary} ${copy.nextAction}`
      : `${copy.summary} ${copy.blocker} ${copy.nextAction}`;
  }
  if(nonTerminalRecoveryBlocker){
    return `${mainBlocker || 'Recovery attempt in progress. Wait for price to stabilise before considering entry.'} Entry, stop, and target cannot be priced reliably yet.`;
  }
  if(finalVerdict === 'avoid' || viabilityRejected || planBlocked || ['weak','weakening','broken'].includes(structureState) || bounceState === 'none'){
    if(finalVerdict === 'avoid' || viabilityRejected || ['weak','weakening','broken'].includes(structureState)){
      let reason = mainBlocker || (planBlocked ? 'No actionable plan is available yet.' : 'The setup is not actionable yet.');
      if(structureState === 'broken' && !mainBlocker){
        reason = 'Trend context may be strong, but the pullback structure is broken.';
      }
      if(['weak','weakening'].includes(structureState) && /broken/i.test(reason)){
        reason = planBlocked
          ? 'the pullback is too weak to price reliably and no actionable plan is available yet.'
          : 'the pullback is too weak to price reliably.';
      }
      return `Avoid for now — ${reason} No entry until price stabilises, a clear bounce forms, and a valid entry, stop, and target plan is available.`;
    }
    if(planBlocked){
      return `${mainBlocker || 'No actionable plan yet.'} Wait for a valid entry, stop, and first target before treating this as actionable.`;
    }
    if(bounceState === 'none'){
      return `${mainBlocker || 'Buyer control is not confirmed yet.'} Wait for price to stabilise, hold support, and show clearer buyer control before entry.`;
    }
  }
  if(!trendStrong || !above50 || !above200 || !nearMA){
    let reason = 'The stock does not meet the basic Quality Pullback rules.';
    if(!trendStrong) reason += ' Trend quality is not strong enough.';
    else if(!nearMA) reason += ' Pullback location is not close enough to the 20 MA or 50 MA.';
    else reason += ' The broader trend structure is not strong enough.';
    return reason;
  }
  let text = 'Strong uptrend.';
  text += checks.near20 ? ' Pullback is near the 20 MA.' : ' Pullback is near the 50 MA.';
  if(stabilising && bounce && status === 'Entry') return `${text} Price is stabilising and buyers are starting to take control. Setup is close to actionable if risk stays controlled.`;
  if(reviewEvidence.consolidating){
    const copy = reviewConsolidationPresentationCopy();
    return `${copy.summary} ${copy.blocker} ${copy.nextAction}`;
  }
  if(stabilising) return `${text} Price is stabilising, but buyer control still needs confirmation.`;
  return `${text} There is no clear stabilisation or buyer control yet.`;
}

function reviewChecklistContextForRecord(record, options = {}){
  const item = record && typeof record === 'object'
    ? normalizeTickerRecordReadOnly(record)
    : null;
  if(!item) return {};
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const effectivePlan = options.effectivePlan || effectivePlanForRecord(item, {allowScannerFallback:true});
  const rawPlan = options.displayedPlan || deriveCurrentPlanState(
    effectivePlan.entry,
    effectivePlan.stop,
    effectivePlan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const displayedPlan = options.displayedPlan || applySetupConfirmationPlanGate(item, rawPlan, derivedStates);
  const simplifiedState = options.simplifiedState || resolveSimplifiedStateForSurface(item, 'review_checklist', {
    log:false,
    mutationSource:'review_checklist'
  });
  const authoritativeState = simplifiedState && typeof simplifiedState === 'object'
    ? simplifiedState
    : {};
  return {
    ticker:item.ticker,
    canonicalVerdict:String(simplifiedState && simplifiedState.canonicalVerdict || '').trim().toLowerCase(),
    visualBucket:String(simplifiedState && simplifiedState.visualBucket || '').trim().toLowerCase(),
    mainBlocker:String((authoritativeState && authoritativeState.mainBlocker) || displayedPlan.planValidationState || displayedPlan.reason || '').trim(),
    planVisible:simplifiedState ? simplifiedState.planVisible === true : displayedPlan.status === 'valid',
    planStatus:String((simplifiedState && simplifiedState.planStatus) || displayedPlan.status || '').trim().toLowerCase(),
    planValid:displayedPlan.status === 'valid'
      && displayedPlan.rewardRisk
      && displayedPlan.rewardRisk.valid === true
      && Number.isFinite(displayedPlan.rewardRisk.rrRatio),
    entry:Number.isFinite(numericOrNull(displayedPlan.entry)) ? Number(numericOrNull(displayedPlan.entry)) : null,
    stop:Number.isFinite(numericOrNull(displayedPlan.stop)) ? Number(numericOrNull(displayedPlan.stop)) : null,
    target:Number.isFinite(numericOrNull(displayedPlan.target)) ? Number(numericOrNull(displayedPlan.target)) : null,
    structureState:String(derivedStates.structureState || derivedStates.structure_state || authoritativeState.structureState || '').trim().toLowerCase(),
    structureEligibility:String(authoritativeState.structureEligibility || authoritativeState.structure_eligibility || '').trim().toLowerCase(),
    bounceState:String(derivedStates.bounceState || derivedStates.bounce_state || authoritativeState.bounceState || '').trim().toLowerCase(),
    stabilisationState:String(derivedStates.stabilisationState || derivedStates.stabilisation_state || '').trim().toLowerCase(),
    pullbackZone:String(derivedStates.pullbackZone || derivedStates.pullback_zone || '').trim().toLowerCase(),
    setupLocationState:String(derivedStates.setupLocationState || derivedStates.setup_location_state || authoritativeState.setupLocationState || '').trim().toLowerCase(),
    priceabilityState:String(derivedStates.priceabilityState || derivedStates.priceability_state || authoritativeState.priceabilityState || '').trim().toLowerCase(),
    viability:String(authoritativeState.viability || '').trim().toLowerCase(),
    rejectedByViabilityGate:authoritativeState.rejectedByViabilityGate === true,
    terminalAvoidApplied:authoritativeState.terminalAvoidApplied === true,
    entryGatePass:simplifiedState && simplifiedState.entryGatePass === true
      || authoritativeState.entryGatePass === true,
    nearEntryGatePass:simplifiedState && simplifiedState.nearEntryGatePass === true
      || authoritativeState.nearEntryGatePass === true,
    hasClearInvalidationLevel:authoritativeState.hasClearInvalidationLevel === true
      ? true
      : (authoritativeState.hasClearInvalidationLevel === false ? false : undefined),
    hasPriceablePlan:authoritativeState.hasPriceablePlan === true
      ? true
      : (authoritativeState.hasPriceablePlan === false ? false : undefined),
    unpriceableBlockReason:String(authoritativeState.unpriceableBlockReason || '').trim(),
    nonTerminalRecoveryBlocker:authoritativeState.nonTerminalRecoveryBlocker === true,
    semanticBlockerCode:String(authoritativeState.semanticBlockerCode || '').trim(),
    semanticBlockerReason:String(authoritativeState.semanticBlockerReason || '').trim()
  };
}

function reviewChecklistContextForActiveTicker(options = {}){
  const ticker = activeReviewTicker();
  const record = ticker ? getTickerRecord(ticker) : null;
  return reviewChecklistContextForRecord(record, options);
}

function resolvedReviewChecksForDisplay(rawChecks, context = {}){
  const checks = {};
  checklistIds.forEach(id => {
    checks[id] = !!(rawChecks && rawChecks[id]);
  });
  const entry = numericOrNull(context.entry);
  const stop = numericOrNull(context.stop);
  const target = numericOrNull(context.target);
  const hasEntry = Number.isFinite(entry);
  const hasStop = hasEntry && Number.isFinite(stop) && entry > stop;
  const hasTarget = hasEntry && Number.isFinite(target) && target > entry;
  checks.entryDefined = hasEntry;
  checks.stopDefined = hasStop;
  checks.targetDefined = hasTarget && context.planValid === true;
  const structureState = String(context.structureState || '').trim().toLowerCase();
  const bounceState = String(context.bounceState || '').trim().toLowerCase();
  const stabilisationState = String(context.stabilisationState || '').trim().toLowerCase();
  if(['weak','weakening','broken'].includes(structureState)){
    checks.trendStrong = false;
  }
  if(bounceState === 'none'){
    checks.bounce = false;
    checks.stabilising = false;
  }else if(stabilisationState === 'none'){
    checks.stabilising = false;
  }
  return checks;
}

function statusClass(status){
  if(status === 'Too Wide') return 'near';
  if(status === '💀 Dead' || status === '⛔ Broken') return 'avoid';
  if(status === '🌱 Developing' || status === '🟠 Developing') return 'near';
  if(status === '🧐 Monitor' || status === '👀 Watch') return 'watch';
  if(status === '🚀 Entry') return 'ready';
  if(status === '✅ Plan valid') return 'ready';
  if(status === '🟠 Needs adjustment') return 'near';
  if(status === '❌ Invalid plan') return 'avoid';
  if(status === '🚫 Unrealistic R:R') return 'avoid';
  if(status === 'Strong Fit' || status === 'Entry' || status === 'Ready') return 'ready';
  if(status === 'Possible Fit' || status === 'Near Entry' || status === 'Near Pullback' || status === 'Near Setup') return 'near';
  if(status === 'Avoid') return 'avoid';
  return 'watch';
}

function riskStatusLabel(riskStatus){
  return riskStatusLabelImpl(riskStatus);
}

function rrBandForValue(rrValue){
  return rrBandForValueImpl(rrValue);
}

function rrStateLabel(rrValue){
  return rrStateLabelImpl(rrValue, { numericOrNull });
}

function rrStateShortLabel(rrValue){
  return rrStateShortLabelImpl(rrValue, { numericOrNull });
}

function rrStateClass(rrValue){
  return rrStateClassImpl(rrValue, { numericOrNull });
}

function setupUiLabel(setupState){
  if(setupState === 'broken') return '💀 Dead';
  if(setupState === 'developing') return '🌱 Developing';
  if(setupState === 'entry') return '🚀 Entry';
  return '🧐 Monitor';
}

function setupUiClass(setupState){
  if(setupState === 'broken') return 'avoid';
  if(setupState === 'developing') return 'near';
  if(setupState === 'entry') return 'ready';
  return 'watch';
}

function planUiLabel(planValidity){
  if(planValidity === 'missing') return 'No actionable plan yet';
  if(planValidity === 'valid') return '\u2705 Plan valid';
  if(planValidity === 'needs_adjustment') return '\uD83D\uDEE0\uFE0F Needs adjustment';
  if(planValidity === 'unrealistic_rr') return '\uD83D\uDEAB Unrealistic R:R';
  return '\u274C Invalid plan';
}

function planUiClass(planValidity){
  if(planValidity === 'valid') return 'ready';
  if(planValidity === 'missing') return 'watch';
  if(planValidity === 'needs_adjustment') return 'near';
  if(planValidity === 'unrealistic_rr') return 'avoid';
  return 'avoid';
}

// Re-declare the UI label helpers with explicit Unicode escapes so visible
// labels stay exact even if the source file previously picked up mojibake.
function setupUiLabel(setupState){
  if(setupState === 'broken') return '\uD83D\uDC80 Dead';
  if(setupState === 'developing') return '\uD83C\uDF31 Developing';
  if(setupState === 'entry') return '\uD83D\uDE80 Entry';
  return '\uD83E\uDDD0 Monitor';
}

function getPlanUiState(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const effectivePlan = options.effectivePlan || {
    entry:displayedPlan.entry,
    stop:displayedPlan.stop,
    firstTarget:displayedPlan.target
  };
  // Default to the persisted plan-check state here so normalization and action
  // derivation do not recurse back through planCheckStateForRecord().
  const planCheckState = String(
    options.planCheckState != null
      ? options.planCheckState
      : (item.plan && item.plan.planValidationState || '')
  ).trim();
  const rrRatio = actionableRrValueForPlan(displayedPlan);
  const positionSize = numericOrNull(displayedPlan.riskFit && displayedPlan.riskFit.position_size);
  let stateKey = 'invalid';

  if(displayedPlan.status === 'missing'){
    stateKey = hasAnyPlanFields(item) ? 'invalid' : 'missing';
  }else if(displayedPlan.status !== 'valid'){
    stateKey = 'invalid';
  }else if(!Number.isFinite(positionSize) || positionSize <= 0){
    stateKey = 'invalid';
  }else if(!Number.isFinite(rrRatio)){
    stateKey = 'invalid';
  }else if(rrRatio > 12){
    stateKey = 'unrealistic_rr';
  }else{
    stateKey = 'valid';
  }

  return {
    state:stateKey,
    label:planUiLabel(stateKey),
    className:planUiClass(stateKey),
    rrRatio
  };
}

function getSetupUiState(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const derived = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const displayStage = normalizeAnalysisVerdict(options.displayStage || displayStageForRecord(item));
  const planUiState = options.planUiState || null;
  const trendState = String(derived.trendState || '').toLowerCase();
  const pullbackZone = String(derived.pullbackZone || '').toLowerCase();
  const structureState = String(derived.structureState || '').toLowerCase();
  const stabilisationState = String(derived.stabilisationState || '').toLowerCase();
  const bounceState = String(derived.bounceState || '').toLowerCase();
  const price = numericOrNull(item.marketData && item.marketData.price);
  const ma50 = numericOrNull(item.marketData && item.marketData.ma50);
  const ma200 = numericOrNull(item.marketData && item.marketData.ma200);
  const brokenTrend = trendState === 'broken'
    || (Number.isFinite(price) && Number.isFinite(ma200) && price < ma200)
    || (Number.isFinite(ma50) && Number.isFinite(ma200) && ma50 < ma200);
  const validPullback = ['near_20ma','near_50ma'].includes(pullbackZone);
  const confirmedBounce = bounceState === 'confirmed';
  const improving = confirmedBounce || bounceState === 'attempt' || stabilisationState === 'clear' || stabilisationState === 'early';
  let stateKey = 'developing';

  if(brokenTrend || structureState === 'broken' || (!validPullback && displayStage === 'Avoid')){
    stateKey = 'broken';
  }else if(validPullback && confirmedBounce && (displayStage === 'Entry' || displayStage === 'Near Entry') && (!planUiState || planUiState.state === 'valid')){
    stateKey = 'entry';
  }else if(validPullback && (confirmedBounce || stabilisationState === 'clear' || displayStage === 'Near Entry' || displayStage === 'Watch')){
    stateKey = 'watch';
  }else if(validPullback && improving){
    stateKey = 'developing';
  }else if(displayStage === 'Avoid'){
    stateKey = 'broken';
  }

  const verdictBadge = primaryVerdictBadge(displayStage);

  return {
    state:stateKey,
    label:verdictBadge.label,
    className:verdictBadge.className,
    setupLabel:setupUiLabel(stateKey),
    setupClassName:setupUiClass(stateKey)
  };
}

function combinedStatusLabel(chartVerdict, riskStatus){
  const verdict = String(chartVerdict || 'Watch');
  if(!riskStatus) return verdict;
  return `${verdict} | ${riskStatusLabel(riskStatus)}`;
}

function bucketStatusForCard(card){
  const verdict = String(card && (card.chartVerdict || card.status) || 'Watch');
  const riskStatus = String(card && card.riskStatus || '');
  if(verdict === 'Entry' && riskStatus === 'too_wide') return 'Too Wide';
  return verdict;
}

function scoreClass(score){
  if(score > 10){
    if(score >= 75) return 's-hi';
    if(score >= 55) return 's-mid';
    return 's-low';
  }
  if(score >= 8) return 's-hi';
  if(score >= 5) return 's-mid';
  return 's-low';
}

function derivedStatesBaseScore(record, derivedStates = null){
  const item = record && typeof record === 'object' ? record : {};
  const derived = derivedStates || analysisDerivedStatesFromRecord(item);
  const trendState = String(derived.trendState || '').toLowerCase();
  const pullbackZone = String(derived.pullbackZone || '').toLowerCase();
  const structureState = String(derived.structureState || '').toLowerCase();
  const stabilisationState = String(derived.stabilisationState || '').toLowerCase();
  const bounceState = String(derived.bounceState || '').toLowerCase();
  const volumeState = String(derived.volumeState || '').toLowerCase();
  if(trendState === 'broken' || structureState === 'broken') return 0;
  let score = 0;
  if(trendState === 'strong') score += 3;
  else if(trendState === 'acceptable') score += 2;
  else if(trendState === 'weak') score += 1;
  if(pullbackZone === 'near_20ma' || pullbackZone === 'near_50ma') score += 2;
  if(structureState === 'intact') score += 2;
  else if(structureState && !['weakening','weak','broken'].includes(structureState)) score += 1;
  if(stabilisationState === 'clear') score += 1;
  else if(stabilisationState === 'early') score += 1;
  if(bounceState === 'confirmed') score += 1;
  else if(bounceState === 'attempt') score += 1;
  if(volumeState === 'supportive') score += 1;
  return clamp(Math.round(score), 0, 10);
}

function isTrueHardFailForRecord(record, derivedStates = null, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const derived = derivedStates || analysisDerivedStatesFromRecord(item);
  const marketData = item.marketData && typeof item.marketData === 'object' ? item.marketData : {};
  const price = numericOrNull(marketData.price);
  const ma50 = numericOrNull(marketData.ma50);
  const ma200 = numericOrNull(marketData.ma200);
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    marketData.currency
  );
  const trendBroken = String(derived.trendState || '').toLowerCase() === 'broken'
    || (Number.isFinite(price) && Number.isFinite(ma200) && price < ma200)
    || (Number.isFinite(ma50) && Number.isFinite(ma200) && ma50 < ma200);
  const brokenStructure = String(derived.structureState || '').toLowerCase() === 'broken';
  const invalidPlan = hasAnyPlanFields(item) && displayedPlan.status === 'invalid';
  const tooWidePlan = displayedPlan.status === 'valid'
    && (
      displayedPlan.riskFit.risk_status === 'too_wide'
      || numericOrNull(displayedPlan.riskFit.position_size) < 1
    );
  return trendBroken || brokenStructure || invalidPlan || tooWidePlan;
}

function computeBaseSetupScoreForRecord(record, options = {}){
  const safeRecord = record && typeof record === 'object' ? record : {};
  const manualChecks = safeRecord.review && safeRecord.review.manualReview && safeRecord.review.manualReview.checks && typeof safeRecord.review.manualReview.checks === 'object'
    ? safeRecord.review.manualReview.checks
    : null;
  if(manualChecks && Object.keys(manualChecks).length){
    return scoreAndStatusFromChecks(manualChecks).score;
  }
  const draftChecks = safeRecord.review && safeRecord.review.draft && safeRecord.review.draft.checks && typeof safeRecord.review.draft.checks === 'object'
    ? safeRecord.review.draft.checks
    : null;
  if(options.includeDraftChecks === true && draftChecks && Object.keys(draftChecks).length){
    return scoreAndStatusFromChecks(draftChecks).score;
  }
  const scanChecks = safeRecord.scan && safeRecord.scan.flags && safeRecord.scan.flags.checks && typeof safeRecord.scan.flags.checks === 'object'
    ? safeRecord.scan.flags.checks
    : null;
  if(scanChecks && Object.keys(scanChecks).length){
    return scoreAndStatusFromChecks(scanChecks).score;
  }
  const marketData = safeRecord.marketData && typeof safeRecord.marketData === 'object' ? safeRecord.marketData : null;
  if(marketData && [marketData.price, marketData.ma20, marketData.ma50, marketData.ma200].some(Number.isFinite)){
    return scoreMarketData({
      price:marketData.price,
      sma20:marketData.ma20,
      sma50:marketData.ma50,
      sma200:marketData.ma200,
      volume:marketData.volume,
      avgVolume30d:marketData.avgVolume,
      perf1m:marketData.perf1m,
      perf3m:marketData.perf3m,
      perf6m:marketData.perf6m,
      perfYtd:marketData.perfYtd,
      rsi14:marketData.rsi
    }).score;
  }
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(safeRecord);
  return derivedStatesBaseScore(safeRecord, derivedStates);
}

function fallbackBaseScoreForRecord(record, options = {}){
  const score = computeBaseSetupScoreForRecord(record, options);
  return Number.isFinite(score) ? score : null;
}

function canonicalBaseSetupScore(record, options = {}){
  const storedBaseScore = numericOrNull(record && record.setup && record.setup.baseScore);
  const storedRawScore = numericOrNull(record && record.setup && record.setup.rawScore);
  const fallbackScore = numericOrNull(fallbackBaseScoreForRecord(record, options));
  if(Number.isFinite(storedBaseScore)){
    if(storedBaseScore === 0 && Number.isFinite(fallbackScore) && fallbackScore > 0) return Math.max(0, Math.min(10, Math.round(fallbackScore)));
    return Math.max(0, Math.min(10, Math.round(storedBaseScore)));
  }
  if(Number.isFinite(storedRawScore)){
    if(storedRawScore === 0 && Number.isFinite(fallbackScore) && fallbackScore > 0) return Math.max(0, Math.min(10, Math.round(fallbackScore)));
    return Math.max(0, Math.min(10, Math.round(storedRawScore)));
  }
  if(Number.isFinite(fallbackScore)) return Math.max(0, Math.min(10, Math.round(fallbackScore)));
  return null;
}

function setupScoreTraceForRecord(record){
  const displayScore = numericOrNull(record && record.setup && record.setup.score);
  const setupScoreSource = String(record && record.setup && record.setup.scoreSource || '').trim();
  const setupScorePrevious = numericOrNull(record && record.setup && record.setup.scorePrevious);
  const setupScoreRecomputed = numericOrNull(record && record.setup && record.setup.scoreRecomputed);
  const setupScoreFallbackApplied = !!(record && record.setup && record.setup.scoreFallbackApplied);
  const setupScoreChangeReason = String(record && record.setup && record.setup.scoreChangeReason || '').trim();
  const reviewedScorePreserved = !!(record && record.setup && record.setup.reviewedScorePreserved);
  const refreshReplacedReviewedScore = !!(record && record.setup && record.setup.refreshReplacedReviewedScore);
  const canonicalBase = canonicalBaseSetupScore(record);
  const scanScore = numericOrNull(record && record.scan && record.scan.score);
  const recomputedScoreAuthoritative = setupScoreSource === 'recomputed.chartQuality'
    && Number.isFinite(setupScoreRecomputed)
    && (!Number.isFinite(displayScore) || Math.round(setupScoreRecomputed) !== Math.round(displayScore));
  if(recomputedScoreAuthoritative){
    return {
      score:Math.max(0, Math.min(10, Math.round(setupScoreRecomputed))),
      source:'setup.scoreRecomputed',
      detail:setupScoreChangeReason || 'Displayed setup score refreshed from full recomputation inputs.',
      inputs:{
        setup_score:displayScore,
        base_score:canonicalBase,
        scan_score:scanScore,
        previous_score:setupScorePrevious,
        recomputed_score:setupScoreRecomputed,
        fallback_applied:setupScoreFallbackApplied ? 1 : 0,
        reviewed_score_preserved:reviewedScorePreserved ? 1 : 0,
        refresh_replaced_reviewed:refreshReplacedReviewedScore ? 1 : 0
      },
      sourceMeta:{
        score_source_used:'setup.scoreRecomputed',
        previous_stored_score:setupScorePrevious,
        recomputed_score:setupScoreRecomputed,
        fallback_applied:setupScoreFallbackApplied,
        score_change_reason:setupScoreChangeReason || 'Recomputed setup score superseded a stale displayed score.',
        refresh_replaced_reviewed_state:refreshReplacedReviewedScore
      }
    };
  }
  if(Number.isFinite(displayScore)){
    return {
      score:Math.max(0, Math.min(10, Math.round(displayScore))),
      source:setupScoreSource || 'setup.score',
      detail:setupScoreChangeReason || 'Displayed setup score from normalized setup state.',
      inputs:{
        setup_score:displayScore,
        base_score:canonicalBase,
        scan_score:scanScore,
        previous_score:setupScorePrevious,
        recomputed_score:setupScoreRecomputed,
        fallback_applied:setupScoreFallbackApplied ? 1 : 0,
        reviewed_score_preserved:reviewedScorePreserved ? 1 : 0,
        refresh_replaced_reviewed:refreshReplacedReviewedScore ? 1 : 0
      },
      sourceMeta:{
        score_source_used:setupScoreSource || 'setup.score',
        previous_stored_score:setupScorePrevious,
        recomputed_score:setupScoreRecomputed,
        fallback_applied:setupScoreFallbackApplied,
        score_change_reason:setupScoreChangeReason || 'No score change.',
        refresh_replaced_reviewed_state:refreshReplacedReviewedScore
      }
    };
  }
  if(Number.isFinite(canonicalBase)){
    return {
      score:Math.max(0, Math.min(10, Math.round(canonicalBase))),
      source:'setup.baseScore',
      detail:'Canonical base setup score used because no display score was stored.',
      inputs:{
        setup_score:displayScore,
        base_score:canonicalBase,
        scan_score:scanScore
      }
    };
  }
  if(Number.isFinite(scanScore)){
    return {
      score:Math.max(0, Math.min(10, Math.round(scanScore))),
      source:'scan.score',
      detail:'Scanner score fallback used because setup scores were unavailable.',
      inputs:{
        setup_score:displayScore,
        base_score:canonicalBase,
        scan_score:scanScore
      }
    };
  }
  return {
    score:0,
    source:'default_zero',
    detail:'No setup or scanner score available; defaulted to zero.',
    inputs:{
      setup_score:displayScore,
      base_score:canonicalBase,
      scan_score:scanScore
    }
  };
}

function setupScoreForRecord(record){
  // This is deliberately an O(1) stored-score accessor. Scanner ranking calls
  // it repeatedly; canonical resolution happens once at the surface publication
  // boundary, where CanonicalSetupProjection constrains the displayed score.
  return setupScoreTraceForRecord(record).score;
}

function setupScoreDisplayForRecord(record){
  const score = setupScoreForRecord(record);
  return Number.isFinite(Number(score)) ? `Setup ${score}/10` : 'Setup unavailable';
}

function rawSetupScoreForRecord(record){
  const baseScore = canonicalBaseSetupScore(record);
  if(Number.isFinite(baseScore)) return Math.max(0, Math.min(10, Math.round(baseScore)));
  const scanScore = numericOrNull(record && record.scan && record.scan.score);
  if(Number.isFinite(scanScore)) return Math.max(0, Math.min(10, Math.round(scanScore)));
  return 0;
}

function practicalSizeFlagForPlan(plan){
  const safePlan = plan && typeof plan === 'object' ? plan : {};
  const positionSize = numericOrNull(safePlan.positionSize);
  const riskPerShare = numericOrNull(safePlan.riskPerShare);
  const maxLoss = numericOrNull(safePlan.maxLoss) || currentMaxLoss();
  if(Number.isFinite(positionSize) && positionSize <= 1) return 'tiny_size';
  if(Number.isFinite(positionSize) && Number.isFinite(riskPerShare) && Number.isFinite(maxLoss) && maxLoss > 0){
    const deployedRisk = positionSize * riskPerShare;
    if(deployedRisk > 0 && deployedRisk < (maxLoss * 0.4)) return 'low_impact';
  }
  return '';
}

function penaltyTraceSources(trace){
  return trace && typeof trace === 'object' && Array.isArray(trace.sources)
    ? trace.sources
    : [];
}

function appendCumulativePenaltyTrace(trace, entry){
  if(!trace || typeof trace !== 'object' || !entry || typeof entry !== 'object') return;
  trace.sources = Array.isArray(trace.sources) ? trace.sources : [];
  const sourceId = String(entry.sourceId || entry.id || '').trim();
  if(!sourceId) return;
  const existing = trace.sources.find(item => item && item.id === sourceId);
  if(existing){
    const mergedPossibleWhere = new Set([].concat(existing.possibleWhere || [], entry.possibleWhere || []).filter(Boolean));
    existing.category = existing.category || entry.category || 'soft_caution';
    existing.severity = existing.severity || entry.severity || 'low';
    existing.terminal = existing.terminal === true || entry.terminal === true;
    existing.present = existing.present !== false;
    existing.possibleWhere = Array.from(mergedPossibleWhere);
    existing.appliedWhere = Array.isArray(existing.appliedWhere) ? existing.appliedWhere : [];
    if(existing.skippedReason == null && entry.skippedReason) existing.skippedReason = entry.skippedReason;
    return;
  }
  trace.sources.push({
    id:sourceId,
    category:entry.category || 'soft_caution',
    severity:entry.severity || 'low',
    terminal:entry.terminal === true,
    present:entry.present !== false,
    possibleWhere:[].concat(entry.possibleWhere || []).filter(Boolean),
    appliedWhere:[].concat(entry.appliedWhere || []).filter(Boolean),
    canonicalImpact:entry.canonicalImpact === true,
    displayImpact:entry.displayImpact === true,
    skippedReason:entry.skippedReason || null
  });
}

function markPenaltyTraceApplied(trace, sourceId, where, options = {}){
  const entry = penaltyTraceSources(trace).find(item => item && item.id === sourceId);
  if(!entry || !where) return;
  entry.appliedWhere = Array.isArray(entry.appliedWhere) ? entry.appliedWhere : [];
  if(!entry.appliedWhere.includes(where)) entry.appliedWhere.push(where);
  if(options.canonicalImpact === true) entry.canonicalImpact = true;
  if(options.displayImpact === true) entry.displayImpact = true;
  if(options.clearSkippedReason === true) entry.skippedReason = null;
}

function markPenaltyTraceSkipped(trace, sourceId, reason){
  const entry = penaltyTraceSources(trace).find(item => item && item.id === sourceId);
  if(!entry || !reason) return;
  if(reason === 'terminal_short_circuit'){
    if(entry.canonicalImpact !== true) entry.skippedReason = reason;
    return;
  }
  if(reason === 'not_used_by_score_path'){
    if(entry.displayImpact !== true) entry.skippedReason = reason;
    return;
  }
  if(!entry.appliedWhere.length) entry.skippedReason = reason;
}

function penaltyReasonLabelFromSource(sourceId, options = {}){
  const practicalSizeFlag = String(options.practicalSizeFlag || '').toLowerCase();
  switch(String(sourceId || '').trim()){
    case 'broken_structure':
      return 'Structure broken';
    case 'broken_trend':
      return 'Trend broken';
    case 'stop_breach':
      return 'Price below stop';
    case 'no_bounce_confirmation':
      return 'No buyer control';
    case 'bounce_unconfirmed':
      return 'Buyer control unconfirmed';
    case 'early_stabilisation':
      return 'Early stabilisation only';
    case 'weak_volume':
      return 'Weak volume';
    case 'weak_market_tape':
      return options.emphasizeWeakRegime ? 'Weak market needs stronger confirmation' : 'Hostile market';
    case 'tiny_size':
      return 'Tiny size';
    case 'low_impact':
      return 'Low impact';
    case 'execution_quality':
      return practicalSizeFlag === 'tiny_size'
        ? 'Tiny size'
        : (options.tooWideForQualityPullback ? 'Wide stop for account size' : 'Lower control setup');
    case 'paper_rr_vs_confirmation':
      return 'Paper R:R looks better than confirmation';
    case 'borderline_setup_weak_market':
      return 'Borderline setup in weak market';
    default:
      return '';
  }
}

function cumulativePenaltyTraceForRecord(record, options = {}){
  const rawRecord = record && typeof record === 'object' ? record : {};
  const stopBreachApplies = (currentPriceValue, stopPriceValue, thresholdMultiplier = 1) => {
    if(typeof hasAuthoritativeStopBreach === 'function'){
      return hasAuthoritativeStopBreach(rawRecord, {
        currentPrice:currentPriceValue,
        stopPrice:stopPriceValue,
        thresholdMultiplier
      });
    }
    const plan = rawRecord.plan && typeof rawRecord.plan === 'object' ? rawRecord.plan : {};
    const source = String(plan.source || '').trim().toLowerCase();
    const triggerState = String(plan.triggerState || '').trim().toLowerCase();
    const planValidationState = String(plan.planValidationState || '').trim().toLowerCase();
    const reviewedNonScannerPlan = source !== 'scanner_estimate'
      && Number.isFinite(numericOrNull(plan.entry))
      && Number.isFinite(stopPriceValue);
    const authoritativePlan = typeof hasAuthoritativeLifecyclePlan === 'function'
      ? hasAuthoritativeLifecyclePlan(rawRecord)
      : (
        plan.hasValidPlan === true
        && String(plan.status || '').trim().toLowerCase() === 'valid'
        && Number.isFinite(numericOrNull(plan.entry))
        && Number.isFinite(numericOrNull(plan.stop))
        && Number.isFinite(numericOrNull(plan.firstTarget))
        && Number.isFinite(numericOrNull(plan.plannedRR))
        && source !== 'scanner_estimate'
      );
    const invalidatedReviewedPlan = reviewedNonScannerPlan
      && (plan.invalidatedState === true || String(plan.invalidatedState || '').trim() !== '');
    const triggeredReviewedPlan = reviewedNonScannerPlan
      && triggerState === 'triggered'
      && ['valid', 'invalidated'].includes(planValidationState);
    const confirmedReviewedPlan = reviewedNonScannerPlan
      && planValidationState === 'valid';
    const breached = Number.isFinite(currentPriceValue)
      && Number.isFinite(stopPriceValue)
      && currentPriceValue <= (stopPriceValue * thresholdMultiplier);
    return breached && (
      authoritativePlan
      || invalidatedReviewedPlan
      || triggeredReviewedPlan
      || confirmedReviewedPlan
    );
  };
  const derived = options.derivedStates || analysisDerivedStatesFromRecord(rawRecord);
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    rawRecord.plan && rawRecord.plan.entry,
    rawRecord.plan && rawRecord.plan.stop,
    rawRecord.plan && rawRecord.plan.firstTarget,
    rawRecord.marketData && rawRecord.marketData.currency
  );
  const baseVerdict = normalizeAnalysisVerdict(
    options.baseVerdict
    || options.displayStage
    || options.rawVerdict
    || resolverSeedVerdictForRecord(rawRecord)
  );
  const qualityAdjustments = options.qualityAdjustments || evaluateSetupQualityAdjustments(rawRecord, {
    derivedStates:derived,
    displayedPlan,
    displayStage:baseVerdict,
    baseVerdict
  });
  const safeAnalysis = options.analysis && typeof options.analysis === 'object' ? options.analysis : null;
  const trace = {sources:[]};
  const structureState = String(derived.structureState || '').toLowerCase();
  const trendState = String(derived.trendState || '').toLowerCase();
  const stabilisationState = String(derived.stabilisationState || '').toLowerCase();
  const bounceState = String(derived.bounceState || '').toLowerCase();
  const volumeState = String(derived.volumeState || '').toLowerCase();
  const hostileMarket = isHostileMarketStatus((rawRecord.meta && rawRecord.meta.marketStatus) || state.marketStatus);
  const practicalSizeFlag = practicalSizeFlagForPlan(rawRecord.plan);
  const rrRatio = numericOrNull(displayedPlan && displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio);
  const currentPrice = numericOrNull(rawRecord.marketData && rawRecord.marketData.price);
  const stopPrice = numericOrNull(rawRecord.plan && rawRecord.plan.stop);
  const brokenBelowStop = stopBreachApplies(currentPrice, stopPrice);
  const emphasizeWeakRegime = qualityAdjustments.weakRegimePenalty === true;

  if(structureState === 'broken'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'broken_structure',
      category:'terminal_blocker',
      severity:'high',
      terminal:true,
      possibleWhere:['terminal_dead_check', 'canonical_verdict', 'display_setup_score']
    });
  }
  if(trendState === 'broken'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'broken_trend',
      category:'terminal_blocker',
      severity:'high',
      terminal:true,
      possibleWhere:['terminal_dead_check', 'canonical_verdict']
    });
  }
  if(brokenBelowStop){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'stop_breach',
      category:'terminal_blocker',
      severity:'high',
      terminal:true,
      possibleWhere:['terminal_dead_check', 'canonical_verdict']
    });
  }
  if(bounceState !== 'confirmed'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:bounceState === 'none' ? 'no_bounce_confirmation' : 'bounce_unconfirmed',
      category:'soft_caution',
      severity:bounceState === 'none' ? 'medium' : 'low',
      terminal:false,
      possibleWhere:['warning_state', 'display_setup_score', 'canonical_verdict', 'entry_eligibility', 'near_entry_eligibility']
    });
  }
  if(stabilisationState === 'early'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'early_stabilisation',
      category:'soft_caution',
      severity:'low',
      terminal:false,
      possibleWhere:['warning_state', 'display_setup_score', 'canonical_verdict', 'near_entry_eligibility']
    });
  }
  if(volumeState === 'weak'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'weak_volume',
      category:'soft_caution',
      severity:'medium',
      terminal:false,
      possibleWhere:['warning_state', 'display_setup_score', 'canonical_verdict', 'entry_eligibility', 'near_entry_eligibility', 'display_tone']
    });
  }
  if(hostileMarket || emphasizeWeakRegime){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'weak_market_tape',
      category:'soft_caution',
      severity:emphasizeWeakRegime ? 'high' : 'medium',
      terminal:false,
      possibleWhere:['quality_adjustments', 'warning_state', 'display_setup_score', 'canonical_verdict', 'display_tone']
    });
  }
  if(practicalSizeFlag === 'tiny_size'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'tiny_size',
      category:'soft_caution',
      severity:'high',
      terminal:false,
      possibleWhere:['warning_state', 'display_setup_score', 'trade_quality_score']
    });
  }else if(practicalSizeFlag === 'low_impact'){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'low_impact',
      category:'soft_caution',
      severity:'low',
      terminal:false,
      possibleWhere:['warning_state', 'display_setup_score', 'trade_quality_score']
    });
  }
  if(qualityAdjustments.lowControlSetup || qualityAdjustments.tooWideForQualityPullback){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'execution_quality',
      category:'soft_caution',
      severity:qualityAdjustments.tooWideForQualityPullback ? 'high' : 'medium',
      terminal:false,
      possibleWhere:['quality_adjustments', 'warning_state', 'display_setup_score', 'trade_quality_score', 'display_tone']
    });
  }
  if(Number.isFinite(rrRatio) && rrRatio >= 3 && (bounceState !== 'confirmed' || ['weak','weakening','broken'].includes(structureState))){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'paper_rr_vs_confirmation',
      category:'display_only',
      severity:'low',
      terminal:false,
      possibleWhere:['warning_state', 'review_copy']
    });
  }
  if(
    safeAnalysis
    && normalizeAnalysisVerdict(safeAnalysis.final_verdict || safeAnalysis.verdict) !== 'Avoid'
    && hostileMarket
    && stabilisationState === 'early'
  ){
    appendCumulativePenaltyTrace(trace, {
      sourceId:'borderline_setup_weak_market',
      category:'display_only',
      severity:'low',
      terminal:false,
      possibleWhere:['warning_state', 'review_copy']
    });
  }
  const terminalSourceIds = penaltyTraceSources(trace)
    .filter(entry => entry && entry.terminal === true)
    .map(entry => entry.id);
  const canonicalSoftShortCircuited = terminalSourceIds.length > 0;
  penaltyTraceSources(trace).forEach(entry => {
    if(!entry || entry.present !== true) return;
    const id = entry.id;
    if(entry.terminal === true){
      markPenaltyTraceApplied(trace, id, 'terminal_dead_check', {clearSkippedReason:true});
      markPenaltyTraceApplied(trace, id, 'canonical_verdict', {canonicalImpact:true, clearSkippedReason:true});
      if(id === 'broken_structure'){
        markPenaltyTraceApplied(trace, id, 'display_setup_score', {displayImpact:true, clearSkippedReason:true});
      }
      return;
    }
    markPenaltyTraceApplied(trace, id, 'warning_state', {clearSkippedReason:true});
    if(['weak_market_tape', 'weak_volume', 'no_bounce_confirmation', 'bounce_unconfirmed', 'early_stabilisation', 'execution_quality', 'tiny_size', 'low_impact'].includes(id)){
      markPenaltyTraceApplied(trace, id, 'display_setup_score', {displayImpact:true, clearSkippedReason:true});
    }else{
      markPenaltyTraceSkipped(trace, id, 'not_used_by_score_path');
    }
    if(id === 'weak_market_tape'){
      markPenaltyTraceApplied(trace, id, 'quality_adjustments', {clearSkippedReason:true});
      if(canonicalSoftShortCircuited){
        markPenaltyTraceSkipped(trace, id, 'terminal_short_circuit');
      }else{
        markPenaltyTraceApplied(trace, id, 'canonical_verdict', {canonicalImpact:true, clearSkippedReason:true});
      }
      return;
    }
    if(['weak_volume', 'no_bounce_confirmation', 'bounce_unconfirmed', 'early_stabilisation'].includes(id)){
      if(canonicalSoftShortCircuited){
        markPenaltyTraceSkipped(trace, id, 'terminal_short_circuit');
      }else{
        markPenaltyTraceApplied(trace, id, 'canonical_verdict', {canonicalImpact:true, clearSkippedReason:true});
      }
      return;
    }
    if(['execution_quality', 'tiny_size', 'low_impact'].includes(id)){
      if(id === 'execution_quality') markPenaltyTraceApplied(trace, id, 'trade_quality_score', {clearSkippedReason:true});
      return;
    }
    if(['paper_rr_vs_confirmation', 'borderline_setup_weak_market'].includes(id)){
      markPenaltyTraceApplied(trace, id, 'review_copy', {clearSkippedReason:true});
    }
  });
  return trace;
}

function downgradeVerdict(verdict, steps = 1){
  const ladder = ['Entry','Near Entry','Watch','Avoid'];
  const start = ladder.indexOf(normalizeAnalysisVerdict(verdict));
  if(start === -1) return 'Watch';
  return ladder[Math.min(ladder.length - 1, start + Math.max(0, steps))];
}

function evaluateSetupQualityAdjustments(record, options = {}){
  const rawRecord = record && typeof record === 'object' ? record : {};
  const derived = options.derivedStates || analysisDerivedStatesFromRecord(rawRecord);
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    rawRecord.plan && rawRecord.plan.entry,
    rawRecord.plan && rawRecord.plan.stop,
    rawRecord.plan && rawRecord.plan.firstTarget,
    rawRecord.marketData && rawRecord.marketData.currency
  );
  const runtimeVerdictForRecord = typeof currentRuntimeVerdictForRecord === 'function'
    ? currentRuntimeVerdictForRecord
    : (() => '');
  const reviewVerdictForRecord = typeof savedReviewVerdictForRecord === 'function'
    ? savedReviewVerdictForRecord
    : (() => '');
  const nonRecursiveBaseVerdict = normalizeAnalysisVerdict(
    runtimeVerdictForRecord(rawRecord)
    || reviewVerdictForRecord(rawRecord)
    || String(rawRecord.watchlist && rawRecord.watchlist.status || '').trim()
    || ''
  );
  const baseVerdict = normalizeAnalysisVerdict(
    options.baseVerdict
    || options.displayStage
    || options.rawVerdict
    || nonRecursiveBaseVerdict
  );
  const entry = numericOrNull(displayedPlan.entry);
  const stop = numericOrNull(displayedPlan.stop);
  const rrRatio = numericOrNull(displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio);
  const positionSize = numericOrNull(displayedPlan.riskFit && displayedPlan.riskFit.position_size);
  const stopPercent = Number.isFinite(entry) && Number.isFinite(stop) && entry > 0
    ? Math.abs(entry - stop) / entry
    : null;
  const trendState = String(derived.trendState || '').toLowerCase();
  const pullbackZone = String(derived.pullbackZone || '').toLowerCase();
  const structureState = String(derived.structureState || '').toLowerCase();
  const bounceState = String(derived.bounceState || '').toLowerCase();
  const stabilisationState = String(derived.stabilisationState || '').toLowerCase();
  const hostileMarket = isHostileMarketStatus((rawRecord.meta && rawRecord.meta.marketStatus) || state.marketStatus);
  const is50maSetup = pullbackZone === 'near_50ma';
  const lowControlSetup = Number.isFinite(stopPercent) && stopPercent > 0.045
    || (Number.isFinite(positionSize) && positionSize <= 2)
    || (is50maSetup && Number.isFinite(rrRatio) && rrRatio < 1.75);
  const tooWideForQualityPullback = Number.isFinite(stopPercent) && stopPercent > 0.05
    || (Number.isFinite(positionSize) && positionSize < 2)
    || (is50maSetup && Number.isFinite(rrRatio) && rrRatio < 1.6 && bounceState !== 'confirmed');
  const strongBounceConfirmation = bounceState === 'confirmed';
  const strongStabilisation = stabilisationState === 'clear' && bounceState === 'confirmed';
  const structureClearlyStrong = trendState === 'strong' && !['weak','weakening','broken'].includes(structureState);
  const strongEnoughToSurviveWeakRegime = is50maSetup
    && structureClearlyStrong
    && strongBounceConfirmation
    && strongStabilisation
    && Number.isFinite(stopPercent) && stopPercent < 0.02
    && Number.isFinite(positionSize) && positionSize > 2
    && Number.isFinite(rrRatio) && rrRatio >= 1.75
    && !lowControlSetup
    && !tooWideForQualityPullback;
  const borderlineWeakMarketConfirmation = bounceState === 'attempt'
    || bounceState === 'none'
    || stabilisationState !== 'clear'
    || (stabilisationState === 'clear' && bounceState !== 'confirmed');
  const weakRegimePenalty = hostileMarket
    && is50maSetup
    && (
      tooWideForQualityPullback
      || lowControlSetup
      || borderlineWeakMarketConfirmation
      || (baseVerdict === 'Entry' && !strongEnoughToSurviveWeakRegime)
    );
  const widthPenalty = tooWideForQualityPullback ? 2 : (lowControlSetup ? 1 : 0);
  const controlQuality = tooWideForQualityPullback ? 'Loose' : (lowControlSetup ? 'Moderate' : 'Tight');
  const capitalEfficiency = tooWideForQualityPullback || (Number.isFinite(positionSize) && positionSize <= 2) || (Number.isFinite(rrRatio) && rrRatio < 1.75)
    ? 'Inefficient'
    : (lowControlSetup ? 'Acceptable' : 'Efficient');
  const planTechnicallyValid = displayedPlan.status === 'valid' && Number.isFinite(positionSize) && positionSize > 0;
  const adjustmentReasons = [];
  if(Number.isFinite(stopPercent) && stopPercent > 0.045) adjustmentReasons.push('Wide stop for account size');
  if(Number.isFinite(positionSize) && positionSize <= 2) adjustmentReasons.push(`${positionSize} shares at max risk`);
  if(weakRegimePenalty) adjustmentReasons.push('50MA setup in weak market needs stronger confirmation');
  if(lowControlSetup && planTechnicallyValid && !adjustmentReasons.includes('Technically valid plan, but lower control than ideal')) adjustmentReasons.push('Technically valid plan, but lower control than ideal');
  return {
    stopPercent,
    lowControlSetup:!!lowControlSetup,
    tooWideForQualityPullback:!!tooWideForQualityPullback,
    weakRegimePenalty:!!weakRegimePenalty,
    widthPenalty,
    capitalEfficiency,
    controlQuality,
    verdictAdjustment:widthPenalty + (weakRegimePenalty ? 1 : 0),
    adjustmentReasons:[...new Set(adjustmentReasons)].slice(0, 4)
  };
}

// LEGACY RESOLVER BLOCK DISABLED
// Shadowed by the canonical resolver block later in app.js.
