function diagnosticWatchlistDebugSnapshot(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const persistedDebug = item.watchlist && item.watchlist.debug && typeof item.watchlist.debug === 'object'
    ? item.watchlist.debug
    : null;
  const lifecycleSnapshot = options.lifecycleSnapshot && typeof options.lifecycleSnapshot === 'object'
    ? options.lifecycleSnapshot
    : null;
  const globalVerdict = options.globalVerdict && typeof options.globalVerdict === 'object'
    ? options.globalVerdict
    : null;
  const fallbackDebug = {
    downgradeReason:String(
      lifecycleSnapshot && lifecycleSnapshot.downgradeReason
      || globalVerdict && (globalVerdict.downgrade_reason || globalVerdict.reason)
      || ''
    ).trim(),
    baseVerdict:String(
      lifecycleSnapshot && lifecycleSnapshot.baseVerdict
      || globalVerdict && globalVerdict.base_verdict
      || ''
    ).trim(),
    finalVerdict:String(
      lifecycleSnapshot && lifecycleSnapshot.state
      || globalVerdict && (globalVerdict.final_verdict || globalVerdict.finalVerdict)
      || ''
    ).trim(),
    refresh_demote_reason:String(lifecycleSnapshot && lifecycleSnapshot.refresh_demote_reason || '').trim(),
    structural_alive_at_refresh:String(lifecycleSnapshot && lifecycleSnapshot.structural_alive_at_refresh || '').trim(),
    avoid_allowed_by_structure_gate:String(lifecycleSnapshot && lifecycleSnapshot.avoid_allowed_by_structure_gate || '').trim(),
    explicit_invalidation_reason:String(
      lifecycleSnapshot && lifecycleSnapshot.explicit_invalidation_reason
      || globalVerdict && globalVerdict.explicit_invalidation_reason
      || ''
    ).trim()
  };
  return persistedDebug
    ? {
      ...fallbackDebug,
      ...persistedDebug,
      downgradeReason:String(persistedDebug.downgradeReason || fallbackDebug.downgradeReason || '').trim(),
      baseVerdict:String(persistedDebug.baseVerdict || fallbackDebug.baseVerdict || '').trim(),
      finalVerdict:String(persistedDebug.finalVerdict || fallbackDebug.finalVerdict || '').trim(),
      refresh_demote_reason:String(persistedDebug.refresh_demote_reason || fallbackDebug.refresh_demote_reason || '').trim(),
      structural_alive_at_refresh:String(persistedDebug.structural_alive_at_refresh || fallbackDebug.structural_alive_at_refresh || '').trim(),
      avoid_allowed_by_structure_gate:String(persistedDebug.avoid_allowed_by_structure_gate || fallbackDebug.avoid_allowed_by_structure_gate || '').trim(),
      explicit_invalidation_reason:String(persistedDebug.explicit_invalidation_reason || fallbackDebug.explicit_invalidation_reason || '').trim()
    }
    : fallbackDebug;
}

function authoritativeScanSurfaceSnapshot(record){
  const item = normalizeTickerRecordReadOnly(record || {});
  const hasCanonicalReviewAuthority = !!(
    item.review && item.review.manualReview
    || normalizeOptionalGlobalVerdictKey(item.review && item.review.savedVerdict || '')
    || item.watchlist && item.watchlist.inWatchlist === true
    || item.lifecycle && (
      String(item.lifecycle.stage || '').trim()
      || String(item.lifecycle.status || '').trim()
      || String(item.lifecycle.state || '').trim()
    )
    || item.plan && String(item.plan.submittedPaperTradeAt || '').trim()
  );
  const cachedBundle = item && item.resolvedStateBundleCache && typeof item.resolvedStateBundleCache === 'object'
    ? item.resolvedStateBundleCache
    : null;
  const cachedBundleContext = cachedBundle
    ? {
      surface:String(cachedBundle.sourceSurface || cachedBundle.source || 'track'),
      source:String(cachedBundle.source || 'track'),
      reason:String(cachedBundle.reason || cachedBundle.source || 'track')
    }
    : null;
  const cachedBundleValid = !!(
    cachedBundle
    && cachedBundleContext
    && resolvedStateBundleCacheMatchesRecord(item, cachedBundle, cachedBundleContext)
  );
  const cachedCanonicalVerdict = normalizeOptionalGlobalVerdictKey(
    cachedBundleValid && cachedBundle && cachedBundle.canonicalContract && (
      cachedBundle.canonicalContract.canonicalVerdictKey
      || cachedBundle.canonicalContract.planVerdictContract && cachedBundle.canonicalContract.planVerdictContract.canonicalVerdict
    ) || ''
  );
  const sharedBundle = !cachedCanonicalVerdict && hasCanonicalReviewAuthority
    ? withReviewProjectionSuppressed(() => buildResolvedStateBundleFromRecord(cloneData(item), {
      source:'scan_surface_authority',
      sourceSurface:'review',
      reason:'scan_surface_authority'
    }))
    : null;
  const sharedBundleCanonicalVerdict = normalizeOptionalGlobalVerdictKey(
    sharedBundle && sharedBundle.canonicalContract && (
      sharedBundle.canonicalContract.canonicalVerdictKey
      || sharedBundle.canonicalContract.planVerdictContract && sharedBundle.canonicalContract.planVerdictContract.canonicalVerdict
    ) || ''
  );
  const bundleVisualBucket = bundle => normalizeVisualBucketForPairing(
    bundle && bundle.renderModels && bundle.renderModels.reviewRenderModel && bundle.renderModels.reviewRenderModel.visualBucket
    || bundle && bundle.renderModels && bundle.renderModels.trackRenderModel && (
      bundle.renderModels.trackRenderModel.visibleBucket
      || bundle.renderModels.trackRenderModel.visualBucket
    )
    || bundle && bundle.canonicalContract && (
      bundle.canonicalContract.bucket
      || bundle.canonicalContract.canonicalVisualBucket
      || bundle.canonicalContract.planVerdictContract && bundle.canonicalContract.planVerdictContract.canonicalVisualBucket
    )
    || '',
    normalizeOptionalGlobalVerdictKey(
      bundle && bundle.canonicalContract && (
        bundle.canonicalContract.canonicalVerdictKey
        || bundle.canonicalContract.planVerdictContract && bundle.canonicalContract.planVerdictContract.canonicalVerdict
      ) || ''
    )
  );
  const cachedVisualBucket = cachedBundleValid ? bundleVisualBucket(cachedBundle) : '';
  const sharedVisualBucket = sharedBundle ? bundleVisualBucket(sharedBundle) : '';
  const runtimeVerdictLabel = currentRuntimeVerdictForRecord(record);
  const contract = withReviewProjectionSuppressed(() => buildCanonicalPlanVerdictContract(item, {
    surface:'scan',
    source:'scan_surface_authority',
    reason:'scan_surface_authority'
  }));
  const contractCanonicalVerdict = normalizeOptionalGlobalVerdictKey(
    contract && contract.canonicalVerdict || ''
  );
  const authorityCanonicalVerdict = hasCanonicalReviewAuthority
    ? (
      cachedCanonicalVerdict
      || sharedBundleCanonicalVerdict
      || contractCanonicalVerdict
    )
    : (
      contractCanonicalVerdict
      || cachedCanonicalVerdict
      || sharedBundleCanonicalVerdict
    );
  const rawCanonicalVerdict = authorityCanonicalVerdict
    || withReviewProjectionSuppressed(() => normalizeGlobalVerdictKey(runtimeVerdictLabel || ''));
  if(!rawCanonicalVerdict) return null;
  const scoutingOnly = hasCanonicalReviewAuthority === true;
  const canonicalVerdict = scoutingOnly && rawCanonicalVerdict === 'entry'
    ? 'near_entry'
    : rawCanonicalVerdict;
  const score = currentRuntimeScoreForRecord(record);
  const authoritySummary = String(
    sharedBundle && sharedBundle.canonicalContract && sharedBundle.canonicalContract.reason
    || sharedBundle && sharedBundle.globalVerdict && sharedBundle.globalVerdict.reason
    || cachedBundleValid && cachedBundle && cachedBundle.canonicalContract && cachedBundle.canonicalContract.reason
    || cachedBundleValid && cachedBundle && cachedBundle.globalVerdict && cachedBundle.globalVerdict.reason
    || currentRuntimeSummaryForRecord(record)
    || ''
  ).trim();
  const authoritativeVisualBucket = hasCanonicalReviewAuthority
    ? (cachedVisualBucket || sharedVisualBucket || '')
    : '';
  let visualBucket = normalizeVisualBucketForPairing(
    authoritativeVisualBucket
    || (sharedBundle && sharedBundle.canonicalContract && sharedBundle.canonicalContract.bucket)
    || (rawCanonicalVerdict === 'watch'
      ? (contract && contract.canonicalVisualBucket)
      : '')
    || (rawCanonicalVerdict === 'dead' ? 'avoid' : rawCanonicalVerdict),
    rawCanonicalVerdict
  );
  if(scoutingOnly && rawCanonicalVerdict === 'entry'){
    visualBucket = 'near_entry';
  }else{
    visualBucket = normalizeVisualBucketForPairing(visualBucket, canonicalVerdict);
  }
  const scanUsesScoutingCap = scoutingOnly && ['entry', 'near_entry'].includes(canonicalVerdict);
  const scoutingActionLabel = scanUsesScoutingCap
    ? 'Scouting only - confirm in Review before treating this as actionable.'
    : (canonicalVerdict === 'entry'
      ? 'Execute only if the trigger remains valid.'
      : (canonicalVerdict === 'near_entry'
        ? 'Close to trigger - confirm in Review.'
        : 'Wait for stronger confirmation before considering an entry.'));
  const summary = scanUsesScoutingCap
    ? (
      rawCanonicalVerdict === 'entry'
        ? 'Scouting only - Review has the final authority before any trade-ready decision.'
        : (authoritySummary || 'Scouting only - use Review for the final decision.')
    )
    : authoritySummary;
  const intentionalScoutingDivergence = scanUsesScoutingCap && (
    rawCanonicalVerdict !== canonicalVerdict
    || visualBucket !== normalizeVisualBucketForPairing(rawCanonicalVerdict, rawCanonicalVerdict)
  );
  return {
    canonicalVerdict,
    contractCanonicalVerdict:rawCanonicalVerdict,
    visualBucket,
    tone:visualBucket,
    scoutingOnly,
    hasCanonicalReviewAuthority,
    actionLabel:scoutingActionLabel,
    score:Number.isFinite(score) ? Math.max(0, Math.min(10, Math.round(score))) : null,
    summary,
    diagnostics:{
      source:'scan_surface_authority',
      reviewProjectionAuthorityAllowed:false,
      intentionalScoutingDivergence,
      divergenceType:intentionalScoutingDivergence ? 'intentional_scouting_divergence' : '',
      divergenceReason:intentionalScoutingDivergence
        ? 'Scan remains a scouting surface after canonical review authority exists, so public scan readiness is capped below final trade authority.'
        : '',
      actionLabel:scoutingActionLabel
    }
  };
}

