function verdictPresentationLabelForKey(key){
  const normalized = normalizeGlobalVerdictKey(key);
  if(normalized === 'entry') return 'Entry';
  if(normalized === 'near_entry') return 'Near Entry';
  if(normalized === 'diminishing') return 'Diminishing';
  if(normalized === 'monitor') return 'Monitor';
  if(normalized === 'developing') return 'Developing';
  if(normalized === 'watch') return 'Watch';
  if(normalized === 'avoid') return 'Avoid';
  if(normalized === 'dead') return 'Dead';
  return 'Watch';
}

function presentationStatusLabelForVerdict(key){
  const normalized = normalizeGlobalVerdictKey(key);
  if(normalized === 'entry') return 'Entry Ready';
  return verdictPresentationLabelForKey(normalized);
}

function presentationVisualStateForVerdict(key){
  const normalized = normalizeGlobalVerdictKey(key);
  if(normalized === 'entry') return 'entry';
  if(normalized === 'near_entry') return 'near_entry';
  if(normalized === 'avoid') return 'avoid';
  return 'watch';
}

function debugStateLabel(value, options = {}){
  const raw = String(value || '').trim();
  if(!raw) return '(none)';
  const kind = String(options.kind || '').trim().toLowerCase();
  const normalizedVerdict = normalizeGlobalVerdictKey(raw);
  const recognizedVerdict = ['entry','near_entry','watch','avoid','dead'].includes(normalizedVerdict);
  if(kind === 'action') return formatActionState(raw);
  if(kind === 'bucket') return visualBucketLabel(raw, options.canonicalVerdict || '');
  if(kind === 'verdict') return recognizedVerdict ? verdictPresentationLabelForKey(normalizedVerdict) : raw;
  if(kind === 'lifecycle'){
    if(raw === 'expired') return 'Expired';
    if(raw === 'inactive') return 'Inactive';
    return recognizedVerdict ? verdictPresentationLabelForKey(normalizedVerdict) : raw;
  }
  if(raw === 'action_now') return 'Action Now';
  if(raw === 'needs_plan') return 'Needs Plan';
  if(raw === 'tradeable_entry') return 'Near Entry';
  const lower = raw.toLowerCase();
  if(['entry','near_entry','watch','avoid','dead','monitor','diminishing','developing'].includes(lower)){
    if(['monitor','diminishing','developing'].includes(lower)) return lower.charAt(0).toUpperCase() + lower.slice(1);
    return verdictPresentationLabelForKey(lower);
  }
  if(['expired','inactive'].includes(lower)){
    return lower.charAt(0).toUpperCase() + lower.slice(1);
  }
  if(lower.includes('_') || lower.includes('-')){
    return raw
      .replace(/[_-]+/g, ' ')
      .replace(/\b\w/g, match => match.toUpperCase());
  }
  return raw;
}

function resolveVisualBucketFromInputs(bucket, canonicalVerdict = ''){
  const raw = String(bucket || '').trim().toLowerCase();
  const canonical = normalizeGlobalVerdictKey(canonicalVerdict || '');
  const noCanonical = !canonical;
  const result = {
    key:'monitor',
    legacyInput:raw,
    remapped:false,
    reason:'default_monitor'
  };
  if(['entry','near_entry','monitor','diminishing','avoid'].includes(raw)){
    if(raw === 'near_entry' && canonical && !['near_entry','entry'].includes(canonical)){
      result.key = canonical === 'watch' ? 'monitor' : (canonical === 'avoid' ? 'avoid' : 'monitor');
      result.remapped = true;
      result.reason = canonical === 'watch'
        ? 'near_entry_visual_blocked_by_canonical_watch'
        : (canonical === 'avoid'
          ? 'near_entry_visual_blocked_by_canonical_avoid'
          : 'near_entry_visual_blocked_by_canonical_mismatch');
      return result;
    }
    result.key = raw;
    result.reason = 'already_canonical_visual_bucket';
    return result;
  }
  if(raw === 'tradeable_entry'){
    if(canonical === 'entry'){
      result.key = 'entry';
      result.remapped = true;
      result.reason = 'legacy_tradeable_entry_from_canonical_entry';
      return result;
    }
    if(canonical === 'near_entry'){
      result.key = 'near_entry';
      result.remapped = true;
      result.reason = 'legacy_tradeable_entry_from_canonical_near_entry';
      return result;
    }
    if(canonical === 'watch'){
      result.key = 'monitor';
      result.remapped = true;
      result.reason = 'legacy_tradeable_entry_from_canonical_watch';
      return result;
    }
    if(canonical === 'avoid'){
      result.key = 'avoid';
      result.remapped = true;
      result.reason = 'legacy_tradeable_entry_from_canonical_avoid';
      return result;
    }
    result.key = noCanonical ? 'monitor' : result.key;
    result.remapped = true;
    result.reason = noCanonical ? 'legacy_tradeable_entry_without_canonical' : 'legacy_tradeable_entry_unknown';
    return result;
  }
  if(['monitor_watch','active','scanner_watch','review_monitor','developing'].includes(raw)){
    result.key = 'monitor';
    result.remapped = true;
    result.reason = 'legacy_monitor_family';
    return result;
  }
  if(['avoid_dead','low_priority_avoid','lower_priority','dead','inactive'].includes(raw)){
    result.key = 'avoid';
    result.remapped = true;
    result.reason = 'legacy_avoid_family';
    return result;
  }
  if(canonical === 'entry'){
    result.key = 'entry';
    result.remapped = true;
    result.reason = 'fallback_from_canonical_entry';
    return result;
  }
  if(canonical === 'near_entry'){
    result.key = 'near_entry';
    result.remapped = true;
    result.reason = 'fallback_from_canonical_near_entry';
    return result;
  }
  if(canonical === 'avoid'){
    result.key = 'avoid';
    result.remapped = true;
    result.reason = 'fallback_from_canonical_avoid';
    return result;
  }
  result.key = 'monitor';
  result.remapped = true;
  result.reason = canonical === 'watch' ? 'fallback_from_canonical_watch' : 'fallback_monitor';
  return result;
}

function normalizeVisualBucketKey(bucket, canonicalVerdict = ''){
  return resolveVisualBucketFromInputs(bucket, canonicalVerdict).key;
}

function normalizeVisualBucketForPairing(bucket, canonicalVerdict = ''){
  return normalizeVisualBucketKey(bucket, canonicalVerdict);
}

function isAllowedCanonicalVisualPair(canonicalVerdict = '', visualBucket = ''){
  const canonical = normalizeGlobalVerdictKey(canonicalVerdict || '');
  const bucket = normalizeVisualBucketForPairing(visualBucket || '', canonical);
  if(!canonical || !bucket) return true;
  if(canonical === 'entry') return ['entry', 'near_entry'].includes(bucket);
  if(canonical === 'near_entry') return ['near_entry', 'entry', 'monitor'].includes(bucket);
  if(canonical === 'watch') return ['monitor', 'diminishing'].includes(bucket);
  if(canonical === 'avoid') return ['avoid', 'diminishing'].includes(bucket);
  if(canonical === 'dead') return ['avoid'].includes(bucket);
  return true;
}

function visualBucketLabel(bucket, canonicalVerdict = ''){
  const key = normalizeVisualBucketKey(bucket, canonicalVerdict);
  if(key === 'entry') return 'Entry';
  if(key === 'near_entry') return 'Near Entry';
  if(key === 'monitor') return 'Monitor';
  if(key === 'diminishing') return 'Diminishing';
  if(key === 'avoid') return 'Avoid';
  return 'Monitor';
}

function visualBucketReason(canonicalVerdict = '', visualBucket = '', context = {}){
  const canonical = normalizeGlobalVerdictKey(canonicalVerdict || '');
  const bucket = normalizeVisualBucketKey(visualBucket || '', canonical);
  const state = context && typeof context === 'object' ? context : {};
  const terminal = state.terminalAvoidApplied === true
    || state.hardTerminalAvoid === true
    || String(state.lifecycleState || '').toLowerCase() === 'dead'
    || String(state.viability || '').toLowerCase() === 'reject';
  if(bucket === 'avoid' && (terminal || canonical === 'avoid')) return 'terminal avoid';
  if(bucket === 'diminishing'){
    const location = String(state.setupLocationState || state.setup_location_state || '').trim().toLowerCase();
    const priceability = String(state.priceabilityState || state.priceability_state || '').trim().toLowerCase();
    const structure = String(state.structureState || state.structure_state || '').trim().toLowerCase();
    if(location === 'extended') return 'too extended to price reliably';
    if(location === 'volatile' || priceability === 'unpriceable') return 'too volatile to price reliably';
    if(['weak','weakening','developing_loose'].includes(structure)) return 'weakening but not terminal';
    if(String(state.viability || '').toLowerCase() === 'low_priority') return 'low-priority but structurally alive';
    return 'setup quality fading';
  }
  if(bucket === 'entry') return 'entry momentum';
  if(bucket === 'near_entry') return 'entry momentum';
  if(bucket === 'monitor'){
    const bounce = String(state.bounce || state.bounceState || '').trim().toLowerCase();
    if(['early','attempt','developing'].includes(bounce)) return 'developing monitor';
    return canonical === 'watch' ? 'developing monitor' : 'presentation monitor';
  }
  return 'presentation tone';
}

// Legacy Consumer 1 pipeline retained for diagnostic comparison only. It is
// deliberately not called by the exported surface bridge below.
function legacyResolveSimplifiedStateForSurfaceObserverOnly(record, surface = 'review', options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const ticker = normalizeTicker(item.ticker || item.symbol || '');
  const surfaceKey = String(surface || '').trim().toLowerCase();
  if(window.SimplifiedTradeState && typeof window.SimplifiedTradeState.resolveRecordState === 'function'){
    const publicationSource = resolveGlobalVerdict(item);
    const resolved = window.SimplifiedTradeState.resolveRecordState(item, {
      publication:publicationSource && publicationSource.canonicalPublication,
      surface,
      log:options.log !== false,
      renderPass:options.renderPass,
      source:options.source,
      reason:options.reason,
      mutationSource:options.mutationSource,
      deps:{
        effectivePlanForRecord,
        riskSettingsProvider:currentRiskSettings,
        analysisDerivedStatesFromRecord,
        applySetupConfirmationPlanGate,
        baseVerdictFromResolvedContract,
        resolvePreLifecycleStateContract,
        resolveFinalStateContract,
        evaluatePlanRealism,
        setupScoreForRecord,
        isHostileMarketStatus,
        scannerScoreGradientClass,
        state,
        normalizeGlobalVerdictKey,
        normalizeVerdict,
        getBadge,
          getActions,
          deriveTradeability,
          evaluateRiskFit
        }
      });
    if(resolved && resolved.debug && resolved.debug.source === 'canonical-publication-mapper'){
      return resolved;
    }
    const planVerdictContract = buildCanonicalPlanVerdictContract(item, {
      surface:surfaceKey,
      source:String(options.source || '').trim(),
      reason:String(options.reason || '').trim(),
      derivedStates:resolved && resolved.debug && resolved.debug.derivedStates,
      effectivePlan:resolved && resolved.debug && resolved.debug.effectivePlan,
      displayedPlan:{
        status:resolved && resolved.planStatus,
        tradeability:resolved && resolved.tradeability,
        entry:resolved && resolved.debug && resolved.debug.effectivePlan && resolved.debug.effectivePlan.entry,
        stop:resolved && resolved.debug && resolved.debug.effectivePlan && resolved.debug.effectivePlan.stop,
        firstTarget:resolved && resolved.debug && resolved.debug.effectivePlan && resolved.debug.effectivePlan.firstTarget
      },
      resolvedContract:resolved && resolved.debug && resolved.debug.resolvedState,
      visualState:resolved && resolved.debug && resolved.debug.visualState,
      setupScore:resolved && resolved.setupScore
    });
    const authoritativeScanSurface = surfaceKey === 'scan'
      ? authoritativePersistedScanSnapshotForScanSurface(item)
      : null;
    if(authoritativeScanSurface){
      const authoritativeScanPlanCandidate = reviewFallbackPlanCandidate(item)
        || (
          Number.isFinite(numericOrNull(item.plan && item.plan.entry))
          && Number.isFinite(numericOrNull(item.plan && item.plan.stop))
          && Number.isFinite(numericOrNull(item.plan && (item.plan.firstTarget != null ? item.plan.firstTarget : item.plan.target)))
            ? {
              entry:numericOrNull(item.plan && item.plan.entry),
              stop:numericOrNull(item.plan && item.plan.stop),
              firstTarget:numericOrNull(item.plan && (item.plan.firstTarget != null ? item.plan.firstTarget : item.plan.target))
            }
            : null
        );
      const resolvedVisualBucket = normalizeVisualBucketForPairing(resolved.visualBucket || resolved.presentationBucket || '');
      const shouldForceAuthoritativeVisualBucket = ['entry','near_entry','avoid'].includes(authoritativeScanSurface.canonicalVerdict)
        || !resolvedVisualBucket
        || !isAllowedCanonicalVisualPair(authoritativeScanSurface.canonicalVerdict, resolvedVisualBucket);
      resolved.canonicalVerdict = authoritativeScanSurface.canonicalVerdict;
      if(shouldForceAuthoritativeVisualBucket){
        resolved.visualBucket = authoritativeScanSurface.visualBucket;
        resolved.tone = authoritativeScanSurface.tone;
      }
      resolved.badgeLabel = authoritativeScanSurface.canonicalVerdict === 'watch'
        ? 'Watch'
        : globalVerdictLabel(authoritativeScanSurface.canonicalVerdict);
      resolved.actionLabel = String(
        authoritativeScanSurface.actionLabel
        || (authoritativeScanSurface.canonicalVerdict === 'watch'
          ? 'Wait for stronger confirmation before considering an entry.'
          : resolved.actionLabel
        )
        || ''
      ).trim();
      if(authoritativeScanSurface.canonicalVerdict === 'entry' && authoritativeScanPlanCandidate){
        resolved.planStatus = 'valid';
        resolved.planVisible = true;
      }
      if(authoritativeScanSurface.summary){
        resolved.mainBlocker = authoritativeScanSurface.summary;
      }
      resolved.debug = {
        ...(resolved.debug || {}),
        scanSurfaceAuthority:'scan.resolvedVerdict',
        authoritativeScanSurfaceSnapshot:{
          canonicalVerdict:authoritativeScanSurface.canonicalVerdict,
          contractCanonicalVerdict:authoritativeScanSurface.contractCanonicalVerdict,
          visualBucket:authoritativeScanSurface.visualBucket,
          score:Number.isFinite(Number(resolved.setupScore)) ? Number(resolved.setupScore) : null,
          summary:authoritativeScanSurface.summary,
          actionLabel:authoritativeScanSurface.actionLabel,
          scoutingOnly:authoritativeScanSurface.scoutingOnly === true,
          diagnostics:authoritativeScanSurface.diagnostics || {}
        }
      };
    }
    if(planVerdictContract){
      const decision = resolved && resolved.debug && resolved.debug.resolvedState && resolved.debug.resolvedState.canonicalDecisionProjection;
      resolved.contractFingerprint = String(planVerdictContract.contractFingerprint || '');
      if(surfaceKey === 'scan'){
        const contractBucket = normalizeVisualBucketForPairing(
          planVerdictContract.canonicalVisualBucket || '',
          resolved.canonicalVerdict || 'watch'
        );
        if(
          normalizeGlobalVerdictKey(resolved.canonicalVerdict || '') === 'watch'
          && contractBucket
        ){
          resolved.visualBucket = contractBucket;
          resolved.tone = String(contractBucket || resolved.tone || 'monitor').trim().toLowerCase() || 'monitor';
        }
      }
      // Copy authority is resolved once with the verdict. Do not let Scan,
      // Review, or Track reconstruct a conflicting blocker from their local
      // presentation state.
      if(decision && typeof decision === 'object'){
        resolved.canonicalDecisionProjection = decision;
        const decisiveBlocker = String(decision.decisiveBlocker || '').trim();
        const semanticReason = String(decision.primaryReason || '').trim();
        if(decisiveBlocker || semanticReason){
          resolved.mainBlocker = decisiveBlocker || semanticReason;
          resolved.decisionSummary = semanticReason || decisiveBlocker;
        }
        if(String(decision.nextAction || '').trim()){
          resolved.actionLabel = String(decision.nextAction).trim();
        }
      }
      resolved.debug = {
        ...(resolved.debug || {}),
        planVerdictContract:{
          canonicalVerdict:planVerdictContract.canonicalVerdict,
          canonicalVisualBucket:planVerdictContract.canonicalVisualBucket,
          planAuthority:planVerdictContract.planAuthority,
          lifecycleAuthority:planVerdictContract.lifecycleAuthority,
          canonicalDecisionProjection:decision || null,
          contractFingerprint:planVerdictContract.contractFingerprint
        }
      };
    }
    return resolved;
  }
  return {
    ticker,
    canonicalVerdict:'watch',
    visualBucket:'monitor',
    tone:'monitor',
    badgeLabel:'Watch',
    actionLabel:'WATCH',
    planVisible:false,
    planStatus:'missing',
    mainBlocker:'Simplified pipeline unavailable.',
    entryGatePass:false,
    nearEntryGatePass:false,
    blockers:['Simplified pipeline unavailable.'],
    debug:{safeFallback:true}
  };
}

// Consumer 1 surface bridge. Decision-bearing values are passed through from
// the one validated publication snapshot; only surface identity/copy metadata
// is appended here.
function resolveSimplifiedStateForSurface(record, surface = 'review', options = {}){
  const item = record && typeof record === 'object' ? record : {};
  // Render paths consume a scan publication; they never invoke the resolver.
  const publication = canonicalPublicationForRecord(item);
  if(window.SimplifiedTradeState && typeof window.SimplifiedTradeState.resolveRecordState === 'function'){
    const mapped = window.SimplifiedTradeState.resolveRecordState(item, {
      publication,
      surface,
      baseScore:rawSetupScoreForRecord(item),
      log:false
    });
    return {
      ...mapped,
      presentation:{
        surface:String(surface || 'review').trim().toLowerCase() || 'review',
        deviationCategory:'A',
        compatibilityOnly:true,
        mayFeedDecisionLogic:false,
        sourceCanonicalFields:['verdict.value','verdict.actionable','verdict.decisiveBlocker','plan.visibility','publicationStatus']
      }
    };
  }
  return {
    ticker:normalizeTicker(item.ticker || item.symbol || ''),
    publicationStatus:'validation_failed',
    canonicalNormVersion:'canonical-norm-v1.1',
    canonicalResultVersion:'',
    evidenceId:'',
    canonicalVerdict:'watch', finalVerdict:'watch', actionable:false,
    entryGatePass:false, nearEntryGatePass:false,
    entryEligibility:null, nearEntryEligibility:null,
    planState:'unavailable', planStatus:'unavailable', planVisible:false,
    canonicalPlan:null,
    entry:null, stop:null, target:null, resolvedRR:null,
    decisiveBlocker:'Canonical publication unavailable.',
    decisiveBlockerCode:'canonical_publication_missing',
    decisiveBlockerCategory:'validation',
    visualBucket:'watch', tone:'watch', badgeLabel:'Watch',
    actionLabel:'Decision unavailable - validation failed.',
    debug:{source:'canonical-publication-bridge', safeFallback:true, compatibilityOnly:true}
  };
}

function runVerdictDriftParityChecks(record){
  if(!isPerfDebugEnabled()) return;
  const item = normalizeTickerRecord(record);
  if(!item.ticker) return;
  const trackContract = resolveCanonicalTickerVerdict(item, {context:'track', silentTrace:true});
  const diaryContract = resolveCanonicalTickerVerdict(item, {context:'diary_snapshot', silentTrace:true});
  if(trackContract.canonicalVerdictKey !== diaryContract.canonicalVerdictKey){
    console.warn('[VerdictDriftTrace] canonical parity mismatch', {
      ticker:item.ticker,
      trackVerdict:trackContract.canonicalVerdictKey,
      diaryVerdict:diaryContract.canonicalVerdictKey,
      trackSource:trackContract.sourceTrace,
      diarySource:diaryContract.sourceTrace
    });
  }
  const diminishingLabel = verdictPresentationLabelForKey('diminishing');
  if(diminishingLabel !== 'Diminishing'){
    console.warn('[VerdictDriftTrace] diminishing label mapping mismatch', {
      ticker:item.ticker,
      mappedLabel:diminishingLabel
    });
  }
}

function logVerdictDriftTrace(record, context, contract = null){
  if(!isPerfDebugEnabled()) return;
  const summary = getOrCreateVerdictDriftSummary();
  const surfaceKey = String(context || 'unknown');
  summary.count += 1;
  summary.surfaces[surfaceKey] = Number(summary.surfaces[surfaceKey] || 0) + 1;
  if(!isPerfDebugVerbose()){
    if(!summary.timer){
      summary.timer = setTimeout(() => {
        const state = logVerdictDriftTrace._summary;
        if(!state || state.count <= 0) return;
        const durationMs = Math.max(0, Date.now() - Number(state.startedAt || Date.now()));
        console.info('[VerdictDriftSummary]', {
          count:state.count,
          surfaces:state.surfaces,
          mismatches:state.mismatches,
          durationMs
        });
        state.count = 0;
        state.surfaces = {};
        state.mismatches = 0;
        state.startedAt = Date.now();
        state.timer = null;
      }, 1200);
    }
    return;
  }
  const item = normalizeTickerRecord(record);
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const rawDisplayedPlan = deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const effectivePlan = effectivePlanForRecord(item, {allowScannerFallback:true});
  const canonicalDisplayedPlan = deriveCurrentPlanState(
    effectivePlan.entry,
    effectivePlan.stop,
    effectivePlan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const globalVerdict = resolveGlobalVerdict(item);
  const resolved = contract && typeof contract === 'object' ? contract : {};
  if(
    resolved
    && resolved.canonicalVerdictKey
    && normalizeGlobalVerdictKey(resolved.canonicalVerdictKey) !== normalizeGlobalVerdictKey(globalVerdict.final_verdict || '')
  ){
    summary.mismatches += 1;
  }
  console.info('[VerdictDriftTrace]', {
    ticker:item.ticker,
    surface:String(context || ''),
    input:{
      final_verdict:globalVerdict.final_verdict || '',
      global_verdict:globalVerdict.final_verdict || '',
      reviewVerdict:String(item.review && item.review.savedVerdict || ''),
      lifecycle:String(item.watchlist && item.watchlist.lifecycleState || ''),
      display_stage:displayStageForRecord(item),
      analysisVerdict:analysisVerdictForRecord(item),
      savedReviewVerdict:savedReviewVerdictForRecord(item),
      diaryVerdict:item.diary && Array.isArray(item.diary.records) && item.diary.records[0] ? String(item.diary.records[0].verdict || '') : ''
    },
    derived:{
      structureState:String(derivedStates.structureState || ''),
      bounceState:String(derivedStates.bounceState || ''),
      volumeState:String(derivedStates.volumeState || ''),
      planValidity:String(getPlanUiState(item, {displayedPlan:canonicalDisplayedPlan}).state || ''),
      tradeability:String(resolved.tradeabilityVerdict || resolved.finalVerdict || ''),
      capitalFit:String(canonicalDisplayedPlan.capitalFit && canonicalDisplayedPlan.capitalFit.capital_fit || canonicalDisplayedPlan.capitalFit || ''),
      canonicalPlanSource:String(effectivePlan.source || ''),
      canonicalPlan:{
        entry:effectivePlan.entry || '',
        stop:effectivePlan.stop || '',
        target:effectivePlan.firstTarget || ''
      },
      rawPlan:{
        entry:item.plan && item.plan.entry != null ? String(item.plan.entry) : '',
        stop:item.plan && item.plan.stop != null ? String(item.plan.stop) : '',
        target:item.plan && item.plan.firstTarget != null ? String(item.plan.firstTarget) : ''
      },
      rawPlanUiState:String(getPlanUiState(item, {displayedPlan:rawDisplayedPlan}).state || '')
    },
    output:{
      canonicalVerdictKey:String(resolved.canonicalVerdictKey || ''),
      presentationLabel:String(resolved.presentationLabel || ''),
      lifecycleState:String(resolved.lifecycleState || ''),
      bucket:String(normalizeVisualBucketKey(resolved.bucket || '', resolved.canonicalVerdictKey || '')),
      bucketLabel:String(resolved.bucketLabel || visualBucketLabel(resolved.bucket || 'monitor', resolved.canonicalVerdictKey || '')),
      legacyBucketInput:String(resolved.legacyBucketInput || ''),
      legacyBucketRemapped:resolved.legacyBucketRemapped === true,
      remapReason:String(resolved.bucketRemapReason || ''),
      reason:String(resolved.reason || ''),
      blockers:Array.isArray(resolved.blockers) ? resolved.blockers : []
    }
  });
}

function resolveCanonicalTickerVerdict(record, options = {}){
  const item = normalizeTickerRecordReadOnly(record);
  const context = String(options.context || 'track');
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const effectivePlan = options.effectivePlan || effectivePlanForRecord(item, {allowScannerFallback:true});
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    effectivePlan.entry,
    effectivePlan.stop,
    effectivePlan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const qualityAdjustments = options.qualityAdjustments || evaluateSetupQualityAdjustments(item, {displayedPlan, derivedStates});
  const resolved = resolveFinalStateContract(item, {
    context,
    derivedStates,
    displayedPlan,
    qualityAdjustments
  });
  const canonicalVerdictKey = normalizeGlobalVerdictKey(
    resolved.finalVerdict
    || resolved.final_verdict_rendered
    || resolved.final_verdict
    || 'watch'
  );
  const visualBucketResolution = resolveVisualBucketFromInputs(resolved.bucket || '', canonicalVerdictKey);
  const output = {
    canonicalVerdictKey,
    presentationLabel:verdictPresentationLabelForKey(canonicalVerdictKey),
    lifecycleState:String(resolved.structuralState || ''),
    bucket:visualBucketResolution.key,
    bucketLabel:visualBucketLabel(visualBucketResolution.key, canonicalVerdictKey),
    legacyBucketInput:visualBucketResolution.legacyInput || '',
    legacyBucketRemapped:visualBucketResolution.remapped === true,
    bucketRemapReason:visualBucketResolution.reason || '',
    tone:String(resolved.actionTone || ''),
    reason:String((resolved.reasonParts && resolved.reasonParts[0]) || resolved.actionLabel || ''),
    blockers:Array.isArray(resolved.reasonParts) ? resolved.reasonParts.slice(0, 3) : [],
    sourceTrace:{
      context,
      resolver:'resolveFinalStateContract',
      planSource:String(effectivePlan.source || '')
    }
  };
  if(options.silentTrace !== true){
    logVerdictDriftTrace(item, context, output);
  }
  return output;
}

function currentRuntimeSummaryForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const scan = item.scan && typeof item.scan === 'object' ? item.scan : {};
  const reasons = Array.isArray(scan.reasons) ? scan.reasons : [];
  return String(scan.summary || reasons[0] || '').trim();
}

function currentRuntimeScoreForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const canonicalSetupScore = setupScoreForRecord(item);
  if(Number.isFinite(numericOrNull(canonicalSetupScore))){
    return Number(canonicalSetupScore);
  }
  const scan = item.scan && typeof item.scan === 'object' ? item.scan : {};
  const runtimeScore = numericOrNull(scan.score);
  const hasUsableMarketData = !!(
    Number.isFinite(numericOrNull(item.marketData && item.marketData.price))
    || Number.isFinite(numericOrNull(item.marketData && item.marketData.ma20))
    || Number.isFinite(numericOrNull(item.marketData && item.marketData.ma50))
    || Number.isFinite(numericOrNull(item.marketData && item.marketData.ma200))
  );
  const summary = String(scan.summary || scan.lastError || '').trim().toLowerCase();
  const scannerDataFailed = /request failed temporarily|manual review|market data pending/.test(summary);
  if(!hasUsableMarketData && scannerDataFailed) return setupScoreForRecord(item);
  return runtimeScore;
}

function preferredReviewRrDisplay(record, displayedPlan, fallbackText = 'No actionable plan yet.'){
  const manualReview = record && record.review && record.review.manualReview && typeof record.review.manualReview === 'object'
    ? record.review.manualReview
    : null;
  const reviewDraft = record && record.review && record.review.draft && typeof record.review.draft === 'object'
    ? record.review.draft
    : null;
  const submittedPaperTradePlan = hasSubmittedPaperTradeCanonicalPlan(record) === true;
  const displayedPlanStatus = String(displayedPlan && displayedPlan.status || '').trim().toLowerCase();
  const planValidationState = String(record && record.plan && record.plan.planValidationState || '').trim().toLowerCase();
  if(submittedPaperTradePlan && displayedPlanStatus !== 'valid'){
    return fallbackText;
  }
  const rrRatio = numericOrNull(displayedPlan && displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio);
  if(Number.isFinite(rrRatio)) return `${Number(rrRatio).toFixed(2)}R`;
  const entry = numericOrNull(
    (displayedPlan && (displayedPlan.entry != null ? displayedPlan.entry : (displayedPlan.plan && displayedPlan.plan.entry)))
    ?? (manualReview && manualReview.entry)
    ?? (reviewDraft && reviewDraft.entry)
    ?? (record && record.plan && record.plan.entry)
  );
  const stop = numericOrNull(
    (displayedPlan && (displayedPlan.stop != null ? displayedPlan.stop : (displayedPlan.plan && displayedPlan.plan.stop)))
    ?? (manualReview && manualReview.stop)
    ?? (reviewDraft && reviewDraft.stop)
    ?? (record && record.plan && record.plan.stop)
  );
  const target = numericOrNull(
    (displayedPlan && (
      displayedPlan.target != null
        ? displayedPlan.target
        : (displayedPlan.firstTarget != null
          ? displayedPlan.firstTarget
          : (displayedPlan.plan && displayedPlan.plan.firstTarget))
    ))
    ?? (manualReview && (manualReview.firstTarget != null ? manualReview.firstTarget : manualReview.target))
    ?? (reviewDraft && (reviewDraft.firstTarget != null ? reviewDraft.firstTarget : reviewDraft.target))
    ?? (record && record.plan && (record.plan.firstTarget != null ? record.plan.firstTarget : record.plan.target))
  );
  const computedRr = evaluateRewardRisk(entry, stop, target);
  const computedRrValue = numericOrNull(computedRr && computedRr.rrRatio);
  if(Number.isFinite(computedRrValue)) return `${Number(computedRrValue).toFixed(2)}R`;
  if(planValidationState === 'pending_validation') return fallbackText;
  const projectedRr = numericOrNull(
    record
    && record.scan
    && record.scan.analysisProjection
    && record.scan.analysisProjection.rr_ratio
  );
  if(Number.isFinite(projectedRr)) return `${Number(projectedRr).toFixed(2)}R`;
  return fallbackText;
}

function reviewFallbackPlanCandidate(record){
  const item = record && typeof record === 'object' ? record : {};
  const safeReview = item.review && typeof item.review === 'object' ? item.review : {};
  const candidates = [
    safeReview.manualReview && typeof safeReview.manualReview === 'object' ? safeReview.manualReview : null,
    safeReview.draft && typeof safeReview.draft === 'object' ? safeReview.draft : null
  ].filter(Boolean);
  for(const candidate of candidates){
    const entry = numericOrNull(candidate.entry);
    const stop = numericOrNull(candidate.stop);
    const firstTarget = numericOrNull(candidate.firstTarget != null ? candidate.firstTarget : candidate.target);
    if(Number.isFinite(entry) && Number.isFinite(stop) && Number.isFinite(firstTarget)){
      return {entry, stop, firstTarget};
    }
  }
  return null;
}

function reviewFallbackDisplayedPlan(record, derivedStates = null){
  const item = record && typeof record === 'object' ? record : {};
  const candidate = reviewFallbackPlanCandidate(item);
  if(!candidate) return null;
  return applySetupConfirmationPlanGate(
    item,
    deriveCurrentPlanState(candidate.entry, candidate.stop, candidate.firstTarget, item.marketData && item.marketData.currency),
    derivedStates || analysisDerivedStatesFromRecord(item)
  );
}

function preferredVerdictForRecord(record){
  return displayStageForRecord(record);
}

function preferredScoreForRecord(record){
  const setupScore = setupScoreForRecord(record);
  if(Number.isFinite(setupScore)) return setupScore;
  const currentScore = currentRuntimeScoreForRecord(record);
  if(Number.isFinite(currentScore)) return currentScore;
  const savedScore = savedReviewScoreForRecord(record);
  if(Number.isFinite(savedScore)) return savedScore;
  return null;
}

function preferredSummaryForRecord(record){
  return currentRuntimeSummaryForRecord(record) || savedReviewSummaryForRecord(record) || '';
}

function reviewSnapshotTimestampForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const review = item.review && typeof item.review === 'object' ? item.review : {};
  const manualReview = review.manualReview && typeof review.manualReview === 'object' ? review.manualReview : null;
  const savedAt = String((manualReview && manualReview.savedAt) || review.lastReviewedAt || '').trim();
  return savedAt || '';
}

function currentRuntimeTimestampForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const scan = item.scan && typeof item.scan === 'object' ? item.scan : {};
  const watchlist = item.watchlist && typeof item.watchlist === 'object' ? item.watchlist : {};
  const candidates = [
    scan.updatedAt,
    watchlist.updatedAt
  ].map(value => String(value || '').trim()).filter(Boolean);
  return candidates.sort().slice(-1)[0] || '';
}

function analysisVerdictForRecord(record, options = {}){
  const fallbackVerdict = options.includeRuntimeFallback === false
    ? ''
    : normalizeAnalysisVerdict(runtimeFallbackVerdictForRecord(record) || '');

  const candidates = [];
  if(['Entry','Near Entry','Watch','Avoid'].includes(fallbackVerdict)){
    const baseVerdict = baseVerdictForRecord(record, options);
    candidates.push(mostConservativeVerdict(baseVerdict, fallbackVerdict));
  }

  if(!candidates.length) return '';
  return mostConservativeVerdict(...candidates);
}

function verdictRank(verdict){
  const safeVerdict = normalizeAnalysisVerdict(verdict || '');
  if(safeVerdict === 'Avoid') return 0;
  if(safeVerdict === 'Watch') return 1;
  if(safeVerdict === 'Near Entry') return 2;
  if(safeVerdict === 'Entry') return 3;
  return null;
}

function normalizeReviewPresentationVerdict(value){
  const raw = String(value || '').trim().toLowerCase();
  if(!raw) return 'watch';
  if(['entry'].includes(raw)) return 'entry';
  if(['near_entry','near entry'].includes(raw)) return 'near_entry';
  if(['watch'].includes(raw)) return 'watch';
  if(['monitor'].includes(raw)) return 'monitor';
  if(['diminishing'].includes(raw)) return 'diminishing';
  if(['avoid'].includes(raw)) return 'avoid';
  if(['dead'].includes(raw)) return 'dead';
  return normalizeGlobalVerdictKey(raw || 'watch');
}

function reviewVerdictLabel(verdictKey){
  const key = normalizeReviewPresentationVerdict(verdictKey);
  if(key === 'near_entry') return 'Near Entry';
  if(key === 'entry') return 'Entry';
  if(key === 'monitor' || key === 'diminishing') return 'Watch';
  if(key === 'avoid') return 'Avoid';
  if(key === 'dead') return 'Avoid';
  return 'Watch';
}

function reviewVerdictRank(verdict){
  const key = normalizeReviewPresentationVerdict(verdict);
  if(key === 'dead') return 0;
  if(key === 'avoid') return 1;
  if(key === 'diminishing') return 2;
  if(key === 'monitor') return 3;
  if(key === 'watch') return 4;
  if(key === 'near_entry') return 5;
  if(key === 'entry') return 6;
  return null;
}

function reviewVerdictKeyToAnalysisVerdict(value){
  const key = normalizeReviewPresentationVerdict(value);
  if(key === 'near_entry') return 'Near Entry';
  if(key === 'entry') return 'Entry';
  if(key === 'watch' || key === 'monitor' || key === 'diminishing') return 'Watch';
  if(key === 'avoid') return 'Avoid';
  if(key === 'dead') return 'Avoid';
  return '';
}

function verdictFromScore(score){
  const roundedScore = Number.isFinite(Number(score)) ? Math.max(0, Math.min(10, Math.round(Number(score)))) : null;
  if(!Number.isFinite(roundedScore)) return 'Watch';
  if(roundedScore <= 3) return 'Avoid';
  if(roundedScore <= 5) return 'Watch';
  if(roundedScore <= 7) return 'Near Entry';
  return 'Entry';
}

function mostConservativeVerdict(...verdicts){
  const normalized = verdicts
    .map(value => normalizeAnalysisVerdict(value || ''))
    .filter(value => verdictRank(value) != null);
  if(!normalized.length) return 'Watch';
  return normalized.reduce((lowest, current) => verdictRank(current) < verdictRank(lowest) ? current : lowest);
}

function currentHardFailVerdictForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const trendState = String(derivedStates.trendState || '').toLowerCase();
  const structureState = String(derivedStates.structureState || '').toLowerCase();
  const price = numericOrNull(item.marketData && item.marketData.price);
  const ma50 = numericOrNull(item.marketData && item.marketData.ma50);
  const ma200 = numericOrNull(item.marketData && item.marketData.ma200);
  const brokenTrend = trendState === 'broken'
    || structureState === 'broken'
    || (Number.isFinite(price) && Number.isFinite(ma200) && price < ma200)
    || (Number.isFinite(ma50) && Number.isFinite(ma200) && ma50 < ma200);
  if(brokenTrend) return 'Avoid';
  return '';
}

function baseVerdictForRecord(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const scoreVerdict = verdictFromScore(setupScoreForRecord(item));
  const hardFailVerdict = currentHardFailVerdictForRecord(item);
  const candidates = [scoreVerdict];
  if(hardFailVerdict) candidates.push(hardFailVerdict);
  if(options.includeRuntimeFallback !== false){
    const runtimeVerdict = normalizeAnalysisVerdict(runtimeFallbackVerdictForRecord(item) || '');
    if(runtimeVerdict) candidates.push(runtimeVerdict);
  }
  return mostConservativeVerdict(...candidates);
}

function executionDowngradeVerdictForRecord(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const planUiState = options.planUiState || getPlanUiState(item, {displayedPlan});
  const positionSize = numericOrNull(displayedPlan.riskFit && displayedPlan.riskFit.position_size);
  const riskStatus = String(displayedPlan.riskFit && displayedPlan.riskFit.risk_status || '');
  const planValidationState = String(item.plan && item.plan.planValidationState || '');
  const currentHardBlockers = currentScannerEstimateHardBlockers(item, {displayedPlan, globalVerdict:options.globalVerdict});
  const provisionalVerdict = normalizeAnalysisVerdict(
    options.provisionalVerdict
    || mostConservativeVerdict(
      baseVerdictForRecord(item, {includeRuntimeFallback:false}),
      analysisVerdictForRecord(item, {includeRuntimeFallback:false}) || ''
    )
  );

  if(currentHardBlockers.isScannerEstimate ? currentHardBlockers.currentInvalidated : (item.plan && item.plan.invalidatedState)) return 'Watch';
  if(executionCapitalBlocked(displayedPlan)) return provisionalVerdict === 'Entry' ? 'Near Entry' : 'Watch';
  if(executionCapitalHeavy(displayedPlan)){
    if(provisionalVerdict === 'Entry') return 'Near Entry';
    if(provisionalVerdict === 'Near Entry') return 'Watch';
    return provisionalVerdict || 'Watch';
  }
  if(['too_wide','settings_missing'].includes(riskStatus)) return 'Watch';
  if(planUiState.state === 'invalid' || planUiState.state === 'unrealistic_rr') return 'Watch';
  if(!Number.isFinite(positionSize) || positionSize < 1) return 'Watch';
  if(displayedPlan.tradeability === 'too_expensive' || displayedPlan.affordability === 'not_affordable') return 'Watch';
  if(displayedPlan.status !== 'valid' || planValidationState === 'needs_replan') return 'Watch';
  return '';
}

// LEGACY RESOLVER SUPPORT BLOCK DISABLED
// Shadowed by the canonical resolver-support block later in app.js.
function legacyFinalVerdictForRecord(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const planUiState = options.planUiState || getPlanUiState(item, {displayedPlan});
  const baseVerdict = baseVerdictForRecord(item, options);
  const advisoryVerdict = analysisVerdictForRecord(item, options);
  const includeExecutionDowngrade = options.includeExecutionDowngrade !== false;
  const executionVerdict = includeExecutionDowngrade
    ? executionDowngradeVerdictForRecord(item, {displayedPlan, planUiState})
    : '';
  const finalVerdict = mostConservativeVerdict(baseVerdict, advisoryVerdict, executionVerdict);
  logDebug('DEBUG_AUDIT', 'FINAL_VERDICT_TRACE', {
    ticker:item.ticker,
    baseVerdict,
    advisoryVerdict,
    executionVerdict,
    finalVerdict
  });
  return finalVerdict;
}

function primaryVerdictBadge(verdict){
  const safeVerdict = normalizeAnalysisVerdict(verdict || '');
  if(safeVerdict === 'Entry') return {label:'🚀 Entry', className:'ready'};
  if(safeVerdict === 'Near Entry') return {label:'🎯 Near Entry', className:'near'};
  if(safeVerdict === 'Avoid') return {label:'⛔ Avoid', className:'avoid'};
  return {label:'🧐 Monitor', className:'watch'};
}

// LEGACY RESOLVER BLOCK DISABLED
// Shadowed by the canonical resolver block later in app.js.
function legacyResolveEmojiPresentation(record, options = {}){
  const item = normalizeTickerRecord(record);
  const finalVerdict = normalizeAnalysisVerdict(options.finalVerdict || displayStageForRecord(item));
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const effectivePlan = options.effectivePlan || effectivePlanForRecord(item, {allowScannerFallback:true});
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    effectivePlan.entry,
    effectivePlan.stop,
    effectivePlan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const qualityAdjustments = options.qualityAdjustments || evaluateSetupQualityAdjustments(item, {displayedPlan, derivedStates});
  const warningState = options.warningState || evaluateWarningState(item, getReviewAnalysisState(item).normalizedAnalysis);
  const planCheckState = options.planCheckState || planCheckStateForRecord(item, {effectivePlan, displayedPlan});
  const planUiState = options.planUiState || getPlanUiState(item, {displayedPlan, effectivePlan, planCheckState});
  const setupUiState = options.setupUiState || getSetupUiState(item, {displayStage:finalVerdict, derivedStates, planUiState});
  const avoidSubtype = options.avoidSubtype || avoidSubtypeForRecord(item, {
    derivedStates,
    displayedPlan,
    qualityAdjustments,
    finalVerdict
  });
  const deadCheck = options.deadCheck || isTerminalDeadSetup(item, {derivedStates, displayedPlan});
  const context = String(options.context || 'generic').toLowerCase();
  const currentHardBlockers = currentScannerEstimateHardBlockers(item, {displayedPlan, derivedStates});
  const invalidated = currentHardBlockers.isScannerEstimate
    ? (currentHardBlockers.currentInvalidated || currentHardBlockers.currentMissed)
    : !!(item.plan && (item.plan.invalidatedState || item.plan.missedState));
  const currentPrice = numericOrNull(item.marketData && item.marketData.price);
  const stop = numericOrNull(item.plan && item.plan.stop);
  const brokenBelowStop = hasAuthoritativeStopBreach(item, {currentPrice, stopPrice:stop});
  const volumeState = String(derivedStates.volumeState || '').toLowerCase();
  const warningReasons = warningState && Array.isArray(warningState.reasons) ? warningState.reasons : [];
  const weakConditionsPresent = !!(
    qualityAdjustments.weakRegimePenalty
    || item.setup.marketCaution
    || warningReasons.some(reason => /hostile market|weak market|borderline setup in weak market/i.test(String(reason || '')))
  );
  const weakVolumePresent = volumeState === 'weak'
    || warningReasons.some(reason => /weak volume/i.test(String(reason || '')));
  const tradeability = String(displayedPlan.tradeability || '').toLowerCase();
  const invalidAvoidGuard = !deadCheck.dead
    && (planUiState.state === 'invalid' || planUiState.state === 'missing')
    && (tradeability === 'avoid' || finalVerdict === 'Avoid');
  const hasReviewState = !!(
    hasAiStageForRecord(item)
    || String(item.review && item.review.savedVerdict || '').trim()
    || String(item.review && item.review.lastReviewedAt || '').trim()
    || (item.review && item.review.manualReview && Object.keys(item.review.manualReview).length)
    || (item.watchlist && item.watchlist.inWatchlist)
  );
  let primaryState = 'monitor';
  let primaryEmoji = '🧐';
  let primaryLabel = 'Monitor';
  let badgeClass = 'watch';

  if(finalVerdict === 'Entry'){
    primaryState = 'entry';
    primaryEmoji = '🚀';
    primaryLabel = 'Entry';
    badgeClass = 'ready';
  }else if(finalVerdict === 'Near Entry'){
    primaryState = 'near_entry';
    primaryEmoji = '🎯';
    primaryLabel = 'Near Entry';
    badgeClass = 'near';
  }else if(finalVerdict === 'Avoid' && deadCheck.dead){
    primaryState = 'dead';
    primaryEmoji = '💀';
    primaryLabel = 'Dead';
    badgeClass = 'avoid';
  }else if(invalidAvoidGuard){
    primaryState = 'inactive';
    primaryEmoji = '⛔';
    primaryLabel = 'Needs rebuild';
    badgeClass = 'avoid';
  }else if(finalVerdict === 'Avoid'){
    const structureState = String(derivedStates.structureState || '').toLowerCase();
    const bounceState = String(derivedStates.bounceState || '').toLowerCase();
    const developingSoftState = setupUiState.state === 'developing'
      || ['weak','weakening','developing_loose'].includes(structureState)
      || ['none','attempt','early'].includes(bounceState);
    primaryState = developingSoftState ? 'developing' : 'monitor';
    primaryEmoji = developingSoftState ? '🌱' : '🧐';
    primaryLabel = developingSoftState ? 'Developing' : 'Monitor';
    badgeClass = developingSoftState ? 'near' : 'watch';
  }else if(setupUiState.state === 'developing'){
    primaryState = 'developing';
    primaryEmoji = '🌱';
    primaryLabel = 'Developing';
    badgeClass = 'near';
  }

  const modifiers = [];
  const addModifier = (emoji, label, code, className = 'near') => {
    if(!emoji || !label || modifiers.some(item => item.code === code) || modifiers.length >= 2) return;
    modifiers.push({emoji, label, code, className});
  };
  if(context === 'scanner' && !hasReviewState){
    addModifier('👀', 'Scan candidate', 'scan_candidate', 'watch');
  }
  if(
    qualityAdjustments.lowControlSetup
    || qualityAdjustments.tooWideForQualityPullback
    || ['weakening','developing_loose'].includes(String(derivedStates.structureState || '').toLowerCase())
  ){
    addModifier('🔋', 'Weak control', 'low_control', 'near');
  }
  if(weakVolumePresent){
    addModifier('🫗', 'Weak volume', 'weak_volume', 'near');
  }
  if(weakConditionsPresent){
    addModifier('⚠️', 'Weak market', 'weak_conditions', 'near');
  }

  const primaryText = `${primaryEmoji} ${primaryLabel}`;

  if(['monitor','developing'].includes(primaryState) && primaryEmoji === '💀'){
    logDebugWarn('DEBUG_RENDER', 'EMOJI_STATE_MISMATCH', {ticker:item.ticker, finalVerdict, primaryState, primaryEmoji});
  }
  if(finalVerdict === 'Avoid' && deadCheck.dead && primaryEmoji !== '💀'){
    logDebugWarn('DEBUG_RENDER', 'EMOJI_STATE_MISMATCH', {ticker:item.ticker, finalVerdict, avoidSubtype, primaryEmoji, deadReasonCode:deadCheck.reasonCode});
  }
  if(primaryState === 'dead' && !deadCheck.dead){
    logDebugWarn('DEBUG_RENDER', 'DEAD_CLASSIFICATION_SOFT_BLOCKER', {
      ticker:item.ticker,
      finalVerdict,
      avoidSubtype,
      deadReasonCode:deadCheck.reasonCode,
      terminalTriggerUsed:deadCheck.terminalTriggerUsed,
      fallbackStateIfNotDead:deadCheck.fallbackStateIfNotDead || 'monitor',
      weakVolumePresent,
      weakConditionsPresent,
      lowControl:!!qualityAdjustments.lowControlSetup,
      tooWide:!!qualityAdjustments.tooWideForQualityPullback,
      invalidated,
      brokenBelowStop
    });
  }

  const seenModifierCodes = new Set();
  const seenModifierKeys = new Set();
  const uniqueModifiers = [];
  modifiers.forEach(modifier => {
    const code = String(modifier && modifier.code || '').trim();
    const key = `${String(modifier && modifier.emoji || '').trim()}|${String(modifier && modifier.label || '').trim()}`;
    if((code && seenModifierCodes.has(code)) || seenModifierKeys.has(key)){
      logDebugWarn('DEBUG_RENDER', 'EMOJI_MODIFIER_DUPLICATE', {ticker:item.ticker, code, key});
      return;
    }
    if(code) seenModifierCodes.add(code);
    seenModifierKeys.add(key);
    uniqueModifiers.push(modifier);
  });
  const combinedShortLabel = [primaryText].concat(uniqueModifiers.slice(0, 2).map(modifier => `${modifier.emoji} ${modifier.label}`)).join(' | ');

  return {
    primaryState,
    primaryEmoji,
    primaryLabel,
    primaryText,
    badgeClass,
    modifiers:uniqueModifiers.slice(0, 2),
    combinedShortLabel
  };
}

function emojiModifierMarkup(presentation){
  const sourceModifiers = presentation && Array.isArray(presentation.modifiers) ? presentation.modifiers : [];
  const seenCodes = new Set();
  const seenKeys = new Set();
  const modifiers = [];
  sourceModifiers.forEach(modifier => {
    const code = String(modifier && modifier.code || '').trim();
    const key = `${String(modifier && modifier.emoji || '').trim()}|${String(modifier && modifier.label || '').trim()}`;
    if((code && seenCodes.has(code)) || seenKeys.has(key)){
      logDebugWarn('DEBUG_RENDER', 'EMOJI_RENDER_DUPLICATE', {code, key});
      return;
    }
    if(code) seenCodes.add(code);
    seenKeys.add(key);
    modifiers.push(modifier);
  });
  const limitedModifiers = modifiers.slice(0, 2);
  const duplicateCodes = limitedModifiers.map(modifier => modifier.code).filter(Boolean);
  if(new Set(duplicateCodes).size !== duplicateCodes.length){
    logDebugWarn('DEBUG_RENDER', 'EMOJI_RENDER_DUPLICATE', {duplicateCodes});
  }
  if(!limitedModifiers.length) return '';
  return limitedModifiers.map(modifier => `<span class="pill ${escapeHtml(modifier.className || 'near')}">${escapeHtml(`${modifier.emoji} ${modifier.label}`)}</span>`).join('');
}

function prioritizedSignalModifiers(presentation, maxModifiers = 2){
  const sourceModifiers = presentation && Array.isArray(presentation.modifiers) ? presentation.modifiers : [];
  const allowedCodes = new Set(['weak_conditions', 'weak_volume', 'low_control']);
  const priorityOrder = {weak_conditions:0, weak_volume:1, low_control:2};
  const seenCodes = new Set();
  const seenKeys = new Set();
  const uniqueModifiers = [];
  sourceModifiers.forEach(modifier => {
    const code = String(modifier && modifier.code || '').trim();
    const key = `${String(modifier && modifier.emoji || '').trim()}|${String(modifier && modifier.label || '').trim()}`;
    if(!allowedCodes.has(code)) return;
    if(seenCodes.has(code) || seenKeys.has(key)) return;
    seenCodes.add(code);
    seenKeys.add(key);
    uniqueModifiers.push(modifier);
  });
  return uniqueModifiers
    .sort((a, b) => (priorityOrder[String(a && a.code || '').trim()] ?? 99) - (priorityOrder[String(b && b.code || '').trim()] ?? 99))
    .slice(0, Math.min(Math.max(maxModifiers, 0), 3));
}

function watchlistActionSummary(actionPresentation){
  return watchlistActionSummaryImpl(actionPresentation);
  const label = String(actionPresentation && (actionPresentation.shortLabel || actionPresentation.label) || '').trim();
  if(!label) return 'Monitor';
  if(/stronger volume/i.test(label)) return '🫗 Volume weak - monitor for expansion';
  if(/bounce confirmation/i.test(label)) return 'Wait for bounce confirmation';
  if(/better conditions/i.test(label)) return 'Weak market - wait for better conditions';
  if(/tighter structure|control is not good enough/i.test(label)) return '🔋 Weak control - wait for tighter structure';
  return label;
}

function watchlistReasonSummary(reasoning, actionText){
  return watchlistReasonSummaryImpl(reasoning, actionText);
  const actionLower = String(actionText || '').toLowerCase();
  const detailParts = String(reasoning && reasoning.detail || '')
    .split('|')
    .map(part => String(part || '').trim())
    .filter(Boolean);
  const filteredParts = detailParts.filter(part => {
    const text = part.toLowerCase();
    if(!text) return false;
    if(actionLower.includes(text)) return false;
    if(text.includes('volume') && actionLower.includes('volume')) return false;
    if(text.includes('bounce') && actionLower.includes('bounce')) return false;
    if(text.includes('market') && actionLower.includes('market')) return false;
    if(text.includes('control') && actionLower.includes('control')) return false;
    return true;
  });
  if(filteredParts.length) return filteredParts.slice(0, 2).join(' + ');
  return String(reasoning && reasoning.headline || '')
    .replace(/^(Monitor|Downgraded|Avoid|Ready|Prepare):\s*/i, '')
    .trim();
}

function normalizeStoredPlanSnapshot(snapshot){
  return normalizeStoredPlanSnapshotImpl(snapshot);
}

function storedPlanState(snapshot){
  return storedPlanStateImpl(snapshot);
}

function planSnapshotFromDisplayedPlan(displayedPlan){
  return planSnapshotFromDisplayedPlanImpl(displayedPlan, { numericOrNull });
}

function scannerEstimateAuthorityReasonPriority(reasonCode){
  const priorities = {
    target_too_close:7,
    invalidated:6,
    missed:5,
    expired:4,
    terminal:3,
    stale_trigger:2,
    broken_structure:1,
    resolver_block:0,
    unknown:-1
  };
  return priorities[String(reasonCode || '').trim().toLowerCase()] ?? -1;
}

function scannerEstimateAuthorityReasonFromText(reason){
  const raw = String(reason || '').trim().toLowerCase();
  if(!raw || !/^[a-z0-9_-]+$/.test(raw)) return '';
  const text = raw.replace(/-/g, '_');
  if(!text) return '';
  if(['target_too_close'].includes(text)) return 'target_too_close';
  if(['invalidated','technical_invalidation'].includes(text)) return 'invalidated';
  if(['missed','missed_setup'].includes(text)) return 'missed';
  if(['expired','closed','dead'].includes(text)) return 'expired';
  if(['terminal','terminal_avoid'].includes(text)) return 'terminal';
  if(['stale','stale_trigger','plan_premature_or_stale'].includes(text)) return 'stale_trigger';
  if(['broken_structure','broken_trend','stop_breach'].includes(text)) return 'broken_structure';
  if(['resolver_block','unpriceable','plan_missing','plan_incomplete'].includes(text)) return 'resolver_block';
  return '';
}

function resolveScannerEstimateStructuredAuthorityCode(globalVerdict){
  const resolvedVerdict = globalVerdict && typeof globalVerdict === 'object' ? globalVerdict : {};
  const explicitInvalidationCode = String(resolvedVerdict.explicit_invalidation_reason_code || '').trim().toLowerCase();
  if(explicitInvalidationCode){
    switch(explicitInvalidationCode.replace(/-/g, '_')){
      case 'setup_invalidated':
      case 'invalidated':
      case 'technical_invalidation':
        return 'invalidated';
      case 'broken_structure':
      case 'broken_trend':
      case 'stop_breach':
        return 'broken_structure';
      case 'missed':
      case 'missed_setup':
        return 'missed';
      case 'plan_premature_or_stale':
      case 'stale_trigger':
        return 'stale_trigger';
      case 'target_too_close':
        return 'target_too_close';
      default:
        return scannerEstimateAuthorityReasonFromText(explicitInvalidationCode);
    }
  }
  const blockerCode = String(
    resolvedVerdict.blockerCode
      || resolvedVerdict.blocker_code
      || resolvedVerdict.primary_blocker_code
      || resolvedVerdict.reasonCode
      || resolvedVerdict.reason_code
      || resolvedVerdict.downgrade_reason_code
      || ''
  ).trim().toLowerCase();
  switch(blockerCode){
    case 'setup_invalidated':
      return 'invalidated';
    case 'technical_invalidation':
      return 'technical_invalidation';
    case 'missed_setup':
      return 'missed';
    case 'plan_premature_or_stale':
      return 'stale_trigger';
    case 'broken_structure':
    case 'broken_trend':
    case 'stop_breach':
      return 'broken_structure';
    case 'target_too_close':
      return 'target_too_close';
    default:
      return '';
  }
}

function isCurrentTechnicalInvalidation(record, globalVerdict, displayedPlan){
  const item = record && typeof record === 'object' ? record : {};
  const resolvedVerdict = globalVerdict && typeof globalVerdict === 'object' ? globalVerdict : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const lifecycle = item.lifecycle && typeof item.lifecycle === 'object' ? item.lifecycle : {};
  const currentPlan = displayedPlan && typeof displayedPlan === 'object' ? displayedPlan : {};
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const structureState = String(derivedStates.structureState || '').trim().toLowerCase();
  const trendState = String(derivedStates.trendState || '').trim().toLowerCase();
  const planValidationState = String(currentPlan.planValidationState || plan.planValidationState || '').trim().toLowerCase();
  const triggerState = String(currentPlan.triggerState || plan.triggerState || '').trim().toLowerCase();
  const explicitInvalidationReasonCode = String(resolvedVerdict.explicit_invalidation_reason_code || '').trim().toLowerCase();
  const lifecycleStage = String(lifecycle.stage || '').trim().toLowerCase();
  const lifecycleStatus = String(lifecycle.status || '').trim().toLowerCase();
  const currentPrice = numericOrNull(item.marketData && item.marketData.price);
  const stopPrice = numericOrNull(currentPlan.stop ?? plan.stop);
  const brokenBelowStop = Number.isFinite(currentPrice)
    && Number.isFinite(stopPrice)
    && currentPrice <= (stopPrice * 0.995);
  return !!(
    ['invalidated','technical_invalidation','broken_structure','broken_trend','stop_breach'].includes(explicitInvalidationReasonCode)
    || planValidationState === 'invalidated'
    || triggerState === 'invalidated'
    || structureState === 'broken'
    || trendState === 'broken'
    || brokenBelowStop
    || ['dead','expired','entered','exited','cancelled'].includes(lifecycleStage)
    || ['dead','closed'].includes(lifecycleStatus)
  );
}

function currentScannerEstimateHardBlockers(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const source = String(plan.source || '').trim().toLowerCase();
  const persistedInvalidated = !!(plan.invalidatedState === true || String(plan.invalidatedState || '').trim() !== '');
  const persistedMissed = !!(plan.missedState === true || String(plan.missedState || '').trim() !== '');
  if(source !== 'scanner_estimate'){
    return {
      isScannerEstimate:false,
      currentInvalidated:persistedInvalidated,
      currentMissed:persistedMissed,
      currentTargetTooClose:plan.firstTargetTooClose === true,
      currentStopBreach:false,
      currentBrokenStructure:false,
      terminalLifecycle:false,
      currentHardBlock:persistedInvalidated || persistedMissed
    };
  }
  const displayedPlan = options.displayedPlan && typeof options.displayedPlan === 'object'
    ? options.displayedPlan
    : deriveCurrentPlanState(
      plan.entry,
      plan.stop,
      plan.firstTarget,
      item.marketData && item.marketData.currency
    );
  const derivedStates = options.derivedStates && typeof options.derivedStates === 'object'
    ? options.derivedStates
    : {};
  const lifecycle = item.lifecycle && typeof item.lifecycle === 'object' ? item.lifecycle : {};
  const explicitInvalidationReasonCode = String(
    (options.globalVerdict && options.globalVerdict.explicit_invalidation_reason_code)
    || options.explicitInvalidationReasonCode
    || ''
  ).trim().toLowerCase();
  const currentPrice = numericOrNull(item.marketData && item.marketData.price);
  const stopPrice = numericOrNull(displayedPlan.stop ?? plan.stop);
  const targetPrice = numericOrNull(displayedPlan.target ?? displayedPlan.firstTarget ?? plan.firstTarget ?? plan.target);
  const structureState = String(
    derivedStates.structureState
    || (item.setup && (item.setup.structureState || item.setup.structure_state))
    || (item.derivedStates && (item.derivedStates.structureState || item.derivedStates.structure_state))
    || ''
  ).trim().toLowerCase();
  const trendState = String(
    derivedStates.trendState
    || (item.setup && (item.setup.trendState || item.setup.trend_state))
    || (item.derivedStates && (item.derivedStates.trendState || item.derivedStates.trend_state))
    || ''
  ).trim().toLowerCase();
  const currentTargetTooClose = displayedPlan && displayedPlan.firstTargetTooClose === true;
  const currentStopBreach = hasAuthoritativeStopBreach(item, {currentPrice, stopPrice});
  const currentMissed = Number.isFinite(currentPrice)
    && Number.isFinite(targetPrice)
    && currentPrice >= (targetPrice * 0.98);
  const currentBrokenStructure = structureState === 'broken' || trendState === 'broken';
  const terminalLifecycle = ['expired','dead','entered','exited','cancelled'].includes(String(lifecycle.stage || '').trim().toLowerCase())
    || ['closed','dead'].includes(String(lifecycle.status || '').trim().toLowerCase());
  const currentInvalidated = currentStopBreach
    || currentBrokenStructure
    || ['invalidated','technical_invalidation','broken_structure','broken_trend','stop_breach'].includes(explicitInvalidationReasonCode);
  return {
    isScannerEstimate:true,
    currentInvalidated,
    currentMissed,
    currentTargetTooClose,
    currentStopBreach,
    currentBrokenStructure,
    terminalLifecycle,
    currentHardBlock:currentInvalidated || currentMissed || currentTargetTooClose || terminalLifecycle
  };
}

function scannerEstimateBlockedPlanSnapshotRecord(plan){
  const normalized = normalizeStoredPlanSnapshot(plan);
  return {
    ...normalized,
    blockedReasonCode:String(plan && plan.blockedReasonCode || ''),
    planValidationState:String(plan && plan.planValidationState || ''),
    triggerState:String(plan && plan.triggerState || ''),
    missedState:String(plan && plan.missedState || ''),
    invalidatedState:String(plan && plan.invalidatedState || ''),
    riskStatus:String(plan && plan.riskStatus || normalized.riskStatus || ''),
    tradeability:String(plan && plan.tradeability || normalized.tradeability || ''),
    firstTargetTooClose:plan && plan.firstTargetTooClose === true
  };
}

function resolveCurrentScannerEstimatePlanBlockers(record, globalVerdict, displayedPlan){
  const item = record && typeof record === 'object' ? record : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const lifecycle = item.lifecycle && typeof item.lifecycle === 'object' ? item.lifecycle : {};
  const resolvedVerdict = globalVerdict && typeof globalVerdict === 'object' ? globalVerdict : resolveGlobalVerdict(item);
  const currentPlan = displayedPlan && typeof displayedPlan === 'object' ? displayedPlan : {};
  const persistedPlanValidationState = String(plan.planValidationState || '').trim().toLowerCase();
  const persistedTriggerState = String(plan.triggerState || '').trim().toLowerCase();
  const currentPlanValidationState = String(currentPlan.planValidationState || '').trim().toLowerCase();
  const currentTriggerState = String(currentPlan.triggerState || '').trim().toLowerCase();
  const persistedMissedState = String(plan.missedState || '').trim();
  const persistedInvalidatedState = String(plan.invalidatedState || '').trim();
  const explicitInvalidationReasonCode = String(resolvedVerdict.explicit_invalidation_reason_code || '').trim().toLowerCase();
  const lifecycleStatus = String(lifecycle.status || '').trim().toLowerCase();
  const currentMissed = currentPlanValidationState === 'missed'
    || currentTriggerState === 'missed';
  const currentInvalidated = currentPlanValidationState === 'invalidated'
    || currentTriggerState === 'invalidated'
    || ['invalidated','technical_invalidation','broken_structure','broken_trend','stop_breach'].includes(explicitInvalidationReasonCode);
  const currentStale = currentPlanValidationState === 'stale'
    || currentTriggerState === 'stale'
    || lifecycleStatus === 'stale';

  return {
    currentPlanValidationState,
    currentTriggerState,
    persistedPlanValidationState,
    persistedTriggerState,
    currentMissed,
    currentInvalidated,
    currentStale,
    staleFields:{
      planValidationState:!!persistedPlanValidationState && !currentPlanValidationState,
      triggerState:!!persistedTriggerState && !currentTriggerState,
      missedState:!!persistedMissedState && !currentMissed,
      invalidatedState:!!persistedInvalidatedState && !currentInvalidated
    }
  };
}

function resolveScannerEstimatePlanAuthority(record, globalVerdict, displayedPlan){
  const item = record && typeof record === 'object' ? record : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const source = String(plan.source || '').trim().toLowerCase();
  if(source !== 'scanner_estimate'){
    return {
      mode:'ignore',
      constructive:false,
      specificBlock:false,
      reason:'',
      reasonCode:'',
      clearBlockedMetadata:false,
      preserveBlockedSnapshot:false
    };
  }
  const resolvedVerdict = globalVerdict && typeof globalVerdict === 'object' ? globalVerdict : resolveGlobalVerdict(item);
  const lifecycle = item.lifecycle && typeof item.lifecycle === 'object' ? item.lifecycle : {};
  const lifecycleStage = String(lifecycle.stage || '').trim().toLowerCase();
  const lifecycleStatus = String(lifecycle.status || '').trim().toLowerCase();
  const currentVerdict = normalizeGlobalVerdictKey(resolvedVerdict.final_verdict || resolvedVerdict.finalVerdict || '');
  const priceabilityState = String(resolvedVerdict.priceability_state || '').trim().toLowerCase();
  const planBlockState = String(resolvedVerdict.plan_status || resolvedVerdict.planStatusKey || '').trim().toLowerCase();
  const numericPlan = [plan.entry, plan.stop, plan.firstTarget].every(value => Number.isFinite(numericOrNull(value)));
  const currentPlan = displayedPlan || (
    numericPlan
      ? deriveCurrentPlanState(plan.entry, plan.stop, plan.firstTarget, item.marketData && item.marketData.currency)
      : null
  );
  const currentPlanBlockers = resolveCurrentScannerEstimatePlanBlockers(item, resolvedVerdict, currentPlan);
  const planMathValid = !!(currentPlan && currentPlan.status === 'valid');
  const firstTargetTooClose = currentPlan && currentPlan.firstTargetTooClose === true;
  const terminalAvoid = item.terminal_avoid_applied === true || resolvedVerdict.terminal_avoid_applied === true;
  const explicitInvalidationReason = String(resolvedVerdict.explicit_invalidation_reason || '').trim();
  const explicitInvalidationReasonCode = String(resolvedVerdict.explicit_invalidation_reason_code || '').trim().toLowerCase();
  const structuredAuthorityCode = resolveScannerEstimateStructuredAuthorityCode(resolvedVerdict);
  const corroboratedTechnicalInvalidation = structuredAuthorityCode === 'technical_invalidation'
    && isCurrentTechnicalInvalidation(item, resolvedVerdict, currentPlan);
  const staleState = structuredAuthorityCode === 'stale_trigger'
    || currentPlanBlockers.currentStale;
  const invalidatedState = structuredAuthorityCode === 'invalidated'
    || corroboratedTechnicalInvalidation
    || currentPlanBlockers.currentInvalidated;
  const missedState = structuredAuthorityCode === 'missed'
    || currentPlanBlockers.currentMissed;
  const expiredState = ['expired','dead','entered','exited','cancelled'].includes(lifecycleStage)
    || ['closed','dead'].includes(lifecycleStatus);
  const brokenStructure = ['broken_structure','broken_trend','stop_breach'].includes(explicitInvalidationReasonCode)
    || structuredAuthorityCode === 'broken_structure';
  let reasonCode = '';
  let reason = '';
  if(firstTargetTooClose){
    reasonCode = 'target_too_close';
    reason = String(plan.blockedReason || 'First target is too close for a usable reward-to-risk plan.').trim();
  }else if(invalidatedState){
    reasonCode = 'invalidated';
    reason = explicitInvalidationReason || String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || 'Setup invalidated.').trim();
  }else if(missedState){
    reasonCode = 'missed';
    reason = String(resolvedVerdict.reason || resolvedVerdict.downgrade_reason || plan.blockedReason || 'Setup already missed.').trim();
  }else if(expiredState){
    reasonCode = 'expired';
    reason = String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || 'Setup expired.').trim();
  }else if(terminalAvoid){
    reasonCode = 'terminal';
    reason = String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || 'Terminal avoid state.').trim();
  }else if(staleState){
    reasonCode = 'stale_trigger';
    reason = String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || 'Trigger state is stale.').trim();
  }else if(brokenStructure){
    reasonCode = 'broken_structure';
    reason = explicitInvalidationReason || String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || 'Structure is broken.').trim();
  }else if(resolvedVerdict.allow_plan !== true || priceabilityState === 'unpriceable' || !planMathValid || ['invalid','needs_adjustment','unrealistic_rr'].includes(planBlockState)){
    reasonCode = 'resolver_block';
    reason = String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || resolvedVerdict.unpriceableBlockReason || 'Blocked').trim();
  }else{
    reasonCode = 'unknown';
    reason = String(plan.blockedReason || resolvedVerdict.reason || resolvedVerdict.downgrade_reason || '').trim();
  }
  const specificBlock = ['target_too_close','invalidated','missed','expired','terminal','stale_trigger','broken_structure'].includes(reasonCode);
  const constructive = !!(
    numericPlan
    && planMathValid
    && resolvedVerdict.allow_plan === true
    && ['entry','near_entry'].includes(currentVerdict)
    && priceabilityState !== 'unpriceable'
    && !terminalAvoid
    && !invalidatedState
    && !missedState
    && !staleState
    && !expiredState
    && !brokenStructure
    && !firstTargetTooClose
  );
  return {
    mode:constructive ? 'recover' : 'blocked',
    constructive,
    specificBlock,
    reason,
    reasonCode,
    clearBlockedMetadata:constructive,
    preserveBlockedSnapshot:specificBlock,
    stalePlanBlockers:currentPlanBlockers.staleFields
  };
}

function blockedScannerEstimatePlanSnapshot(record){
  const item = record && typeof record === 'object' ? record : {};
  const plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
  const source = String(plan.source || '').trim().toLowerCase();
  const status = String(plan.status || '').trim().toLowerCase();
  const tradeability = String(plan.tradeability || '').trim().toLowerCase();
  const riskStatus = String(plan.riskStatus || '').trim().toLowerCase();
  const blockedReason = String(plan.blockedReason || '').trim();
  if(source !== 'scanner_estimate') return null;
  const blocked = status === 'invalid'
    || tradeability === 'invalid'
    || riskStatus === 'plan_blocked'
    || !!blockedReason
    || plan.firstTargetTooClose === true;
  const globalVerdict = resolveGlobalVerdict(item);
  const displayedPlan = deriveCurrentPlanState(plan.entry, plan.stop, plan.firstTarget, item.marketData && item.marketData.currency);
  const authority = resolveScannerEstimatePlanAuthority(item, globalVerdict, displayedPlan);
  return blocked && authority.preserveBlockedSnapshot ? scannerEstimateBlockedPlanSnapshotRecord(plan) : null;
}

function planSnapshotSummary(snapshot, options = {}){
  return planSnapshotSummaryImpl(snapshot, options);
}

function planSnapshotsEqual(a, b){
  return planSnapshotsEqualImpl(a, b);
}

function recomputeAttemptedForSource(source){
  return recomputeAttemptedForSourceImpl(source);
}

function tradeabilityRank(value){
  const ranks = {
    avoid:0,
    risk_only:1,
    too_expensive:1,
    watch:2,
    monitor:2,
    near_entry:3,
    action_now:4,
    entry:4
  };
  return ranks[String(value || '').trim().toLowerCase()] ?? 0;
}

function determineRecomputeResult(previousPlan, newPlan, attempted){
  return determineRecomputeResultImpl(previousPlan, newPlan, attempted, {
    numericOrNull,
    tradeabilityRank
  });
}

function renderRecomputeDiagnostics(debug, options = {}){
  const info = debug && typeof debug === 'object' ? debug : {};
  const previousPlan = normalizeStoredPlanSnapshot(info.previousPlan);
  const newPlan = normalizeStoredPlanSnapshot(info.newPlan);
  const identical = planSnapshotsEqual(previousPlan, newPlan);
  const previousSummary = planSnapshotSummary(previousPlan, {emptyLabel:'None'});
  const newSummary = identical
    ? `Same as previous | ${planSnapshotSummary(newPlan, {emptyLabel:'None'})}`
    : planSnapshotSummary(newPlan, {emptyLabel:'None'});
  const wrapperClass = String(options.wrapperClass || '').trim();
  return `<div class="${escapeHtml(wrapperClass || 'watchlist-debug-block tiny')}"><strong>Plan Recompute</strong><div>Plan recomputed: ${escapeHtml(info.planRecomputed ? 'Yes' : 'No')}</div><div>Recompute result: ${escapeHtml(info.recomputeResult || 'Skipped')}</div><div>Previous plan: ${escapeHtml(previousSummary)}</div><div>New plan: ${escapeHtml(newSummary)}</div>${info.planSnapshotMismatch ? `<div>Snapshot warning: ${escapeHtml(info.planSnapshotMismatch)}</div>` : ''}</div>`;
}

function watchlistDecisionPresentation(resolvedContract, lifecycleSnapshot, reasoning, fallbackAction){
  const blockerReason = String(resolvedContract && resolvedContract.blockerReason || '').trim();
  const reasonSummary = String(resolvedContract && resolvedContract.reasonSummary || '').trim();

  const actionStateKey = String(resolvedContract && resolvedContract.actionStateKey || '').trim().toLowerCase();
  const rebuildState = actionStateKey === 'rebuild_setup';
  const recalculateState = actionStateKey === 'recalculate_plan';
  let badgeText = String(resolvedContract && (resolvedContract.actionStateLabel || resolvedContract.actionLabel) || '').trim() || 'Hold for confirmation';
  let badgeClass = actionStateKey === 'rebuild_setup'
    ? 'avoid'
    : (actionStateKey === 'recalculate_plan' ? 'near' : (String(resolvedContract && resolvedContract.badgeClass || '').trim() || 'watch'));
  let headline = String(resolvedContract && (resolvedContract.actionStateLabel || resolvedContract.actionLabel) || fallbackAction || '').trim() || 'Hold for confirmation';
  const conciseReason = reasonSummary || watchlistReasonSummary(reasoning, headline) || blockerReason;
  const tradeability = String(resolvedContract && (resolvedContract.tradeabilityVerdictLabel || resolvedContract.tradeabilityLabel) || 'Watch').trim();
  let reason = conciseReason ? `Tradeability: ${tradeability} | ${conciseReason}` : `Tradeability: ${tradeability}`;
  if(actionStateKey === 'rebuild_setup') badgeText = '\uD83D\uDC80 Rebuild setup';
  else if(actionStateKey === 'recalculate_plan') badgeText = '🟡 Hold for entry conditions';
  else if(actionStateKey === 'ready_to_act') badgeText = 'Ready to act';
  else if(actionStateKey === 'hold_confirmation') badgeText = 'Hold for confirmation';

  if(String(lifecycleSnapshot && lifecycleSnapshot.state || '').toLowerCase() === 'expired'){
    badgeText = 'Expired';
    badgeClass = 'avoid';
    headline = 'Rebuild setup';
    reason = 'Tradeability: Avoid | Watchlist window expired without a usable improvement';
  }else if(rebuildState){
    badgeText = '💀 Rebuild setup';
    badgeClass = 'avoid';
    headline = 'Rebuild setup before reconsidering entry';
    reason = reason || 'Invalid plan + weak structure';
  }else if(recalculateState){
    badgeText = '🟡 Hold for entry conditions';
    badgeClass = 'near';
    headline = 'Hold for entry conditions';
    reason = reason || 'Structure intact, but current plan is invalid.';
  }

  return {
    badgeText,
    badgeClass,
    headline,
    reason: String(reason || '').replace(/\.$/, '').trim()
  };
}

function reviewReasonSummary(reasoning, actionText){
  const shortReason = watchlistReasonSummary(reasoning, actionText);
  if(shortReason) return shortReason;
  return String(reasoning && reasoning.detail || '').trim();
}

function evaluateBouncePriceabilityGuard(context = {}){
  if(window.BouncePriceability && typeof window.BouncePriceability.isConfirmedBouncePriceable === 'function'){
    return window.BouncePriceability.isConfirmedBouncePriceable(context);
  }
  return {
    originalBounceState:String(context.originalBounceState || context.bounceState || 'none').trim().toLowerCase() || 'none',
    adjustedBounceState:String(context.originalBounceState || context.bounceState || 'none').trim().toLowerCase() || 'none',
    bouncePriceabilityGuardApplied:false,
    bouncePriceabilityGuardReason:'',
    hasClearInvalidationLevel:false,
    hasPriceablePlan:false,
    hasCredibleEntryTrigger:false,
    unpriceableBlockReason:''
  };
}

function evaluateEntryTrigger(record, options = {}){
  const rawRecord = record && typeof record === 'object' ? record : {};
  const derived = options.derivedStates || analysisDerivedStatesFromRecord(rawRecord);
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    rawRecord.plan && rawRecord.plan.entry,
    rawRecord.plan && rawRecord.plan.stop,
    rawRecord.plan && rawRecord.plan.firstTarget,
    rawRecord.marketData && rawRecord.marketData.currency
  );
  const trendState = String(derived.trendState || '').toLowerCase();
  const pullbackZone = String(derived.pullbackZone || '').toLowerCase();
  const structureState = String(derived.structureState || '').toLowerCase();
  const stabilisationState = String(derived.stabilisationState || '').toLowerCase();
  const bounceState = String(derived.bounceState || '').toLowerCase();
  const hostileMarket = isHostileMarketStatus((rawRecord.meta && rawRecord.meta.marketStatus) || state.marketStatus);
  const currentPrice = numericOrNull(rawRecord.marketData && rawRecord.marketData.price);
  const entry = displayedPlan.entry;
  const stop = displayedPlan.stop;
  const target = displayedPlan.target;
  const trendValid = trendState !== 'broken' && trendState !== 'weak';
  const pullbackValid = ['near_20ma','near_50ma'].includes(pullbackZone);
  const structureIntact = !['weak','weakening','broken'].includes(structureState);
  const noBounce = bounceState === 'none';
  const confirmedBounce = bounceState === 'confirmed';
  const clearStabilisation = stabilisationState === 'clear';
  const brokenBelowStop = hasAuthoritativeStopBreach(rawRecord, {
    currentPrice,
    stopPrice:stop,
    thresholdMultiplier:0.995
  });
  const hardFail = trendState === 'broken'
    || structureState === 'broken'
    || (['weak','weakening'].includes(structureState) && noBounce && hostileMarket)
    || brokenBelowStop;
  const hasReviewedPlan = displayedPlan.status === 'valid';
  const breakAboveTrigger = hasReviewedPlan && Number.isFinite(currentPrice) && Number.isFinite(entry) && currentPrice >= entry;
  const strongReversal = pullbackValid && structureIntact && confirmedBounce && clearStabilisation;
  const reclaimFollowThrough = pullbackValid && structureIntact && confirmedBounce && clearStabilisation && breakAboveTrigger;
  const bounceGuard = evaluateBouncePriceabilityGuard({
    originalBounceState:bounceState,
    structureState,
    pullbackZone,
    stabilisationState,
    trendState,
    currentPrice,
    entry,
    stop,
    target,
    rr:numericOrNull(displayedPlan && displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio),
    reclaimConfirmed:pullbackValid && clearStabilisation && (breakAboveTrigger || strongReversal),
    riskTooWide:false
  });
  const bounceConfirmedAndPriceable = bounceState === 'confirmed' && !bounceGuard.unpriceableBlockReason;
  const submittedCanonicalPlan = hasSubmittedPaperTradeCanonicalPlan(rawRecord) === true;
  const triggerReady = trendValid && pullbackValid && structureIntact && !hardFail && hasReviewedPlan
    && bounceConfirmedAndPriceable
    && clearStabilisation
    && !hostileMarket
    && (breakAboveTrigger || strongReversal || reclaimFollowThrough);
  const nearReady = !hardFail && pullbackValid && trendState !== 'broken' && structureIntact
    && bounceConfirmedAndPriceable;
  const extendedFromEntry = hasReviewedPlan && Number.isFinite(currentPrice) && Number.isFinite(entry) && currentPrice > (entry * 1.03);
  const clearlyMissed = hasReviewedPlan && Number.isFinite(currentPrice) && Number.isFinite(entry) && currentPrice > (entry * 1.06);
  if(submittedCanonicalPlan && hasReviewedPlan && !hardFail && !clearlyMissed){
    return {
      triggerState:'triggered',
      entryTriggerReady:true,
      nearReady:true,
      hardFail:false,
      trendValid,
      pullbackValid,
      structureIntact,
      confirmedBounce,
      clearStabilisation,
      hasReviewedPlan:true,
      hostileMarket,
      extendedFromEntry:false,
      clearlyMissed:false,
      breakAboveTrigger:true,
      strongReversal:true,
      reclaimFollowThrough:true,
      bouncePriceabilityGuardApplied:bounceGuard.bouncePriceabilityGuardApplied,
      bouncePriceabilityGuardReason:bounceGuard.bouncePriceabilityGuardReason
    };
  }
  return {
    triggerState:hardFail ? 'invalidated' : (clearlyMissed ? 'missed' : (triggerReady ? 'triggered' : (nearReady ? 'near_ready' : 'waiting_for_trigger'))),
    entryTriggerReady:triggerReady,
    nearReady,
    hardFail,
    trendValid,
    pullbackValid,
    structureIntact,
    confirmedBounce,
    clearStabilisation,
    hasReviewedPlan,
    hostileMarket,
    extendedFromEntry,
    clearlyMissed,
    breakAboveTrigger,
    strongReversal,
    reclaimFollowThrough,
    bouncePriceabilityGuardApplied:bounceGuard.bouncePriceabilityGuardApplied,
    bouncePriceabilityGuardReason:bounceGuard.bouncePriceabilityGuardReason
  };
}

function entryPromotionAuditCheckDefinitions(){
  return [
    {id:'structure_ok', label:'Structure intact/strong', classification:'structural', temporary:false, mode:'positive'},
    {id:'bounce_ok', label:'Buyer control confirmed and priceable', classification:'temporary', temporary:true, mode:'positive'},
    {id:'pullback_ok', label:'Pullback near 20MA/50MA', classification:'structural', temporary:false, mode:'positive'},
    {id:'market_ok', label:'Market supportive', classification:'market', temporary:true, mode:'positive'},
    {id:'volume_ok', label:'Volume at least normal', classification:'volume', temporary:true, mode:'positive'},
    {id:'plan_visible', label:'Actionable plan visible', classification:'pricing', temporary:true, mode:'positive'},
    {id:'has_entry', label:'Entry price defined', classification:'pricing', temporary:true, mode:'positive'},
    {id:'has_stop', label:'Stop price defined', classification:'pricing', temporary:true, mode:'positive'},
    {id:'plan_ok', label:'Plan valid and unblocked', classification:'pricing', temporary:true, mode:'positive'},
    {id:'risk_width_ok', label:'Risk width usable', classification:'risk', temporary:true, mode:'positive'},
    {id:'pullback_valid', label:'Pullback context valid', classification:'structural', temporary:false, mode:'positive'},
    {id:'rr_ok', label:'R:R at least 2.0', classification:'risk', temporary:true, mode:'positive'},
    {id:'entry_trigger_hit', label:'Entry trigger hit', classification:'trigger', temporary:true, mode:'positive'},
    {id:'tradeability_ok', label:'Tradeability priceable', classification:'pricing', temporary:true, mode:'positive'},
    {id:'capital_ok', label:'Capital fit acceptable', classification:'risk', temporary:true, mode:'positive'},
    {id:'has_clear_invalidation_level', label:'Clear invalidation level', classification:'pricing', temporary:true, mode:'positive'},
    {id:'has_priceable_plan', label:'Priceable plan available', classification:'pricing', temporary:true, mode:'positive'},
    {id:'reclaim_confirmed_independent', label:'Independent reclaim confirmation', classification:'trigger', temporary:true, mode:'positive'},
    {id:'unpriceable_block', label:'No unpriceable block', classification:'pricing', temporary:true, mode:'negative'},
    {id:'below_50_without_reclaim', label:'Not below 50MA without reclaim', classification:'structural', temporary:false, mode:'negative'}
  ];
}

function entryPromotionAuditEligible(snapshot = {}){
  const verdict = normalizeGlobalVerdictKey(snapshot.currentVerdict || snapshot.final_verdict || '');
  return verdict === 'near_entry'
    || verdict === 'entry'
    || snapshot.nearEntryGatePass === true
    || snapshot.entryGatePass === true
    || snapshot.circularTriggerSuspected === true;
}

function entryPromotionAuditCheckResult(definition, checks = {}){
  if(!definition || !definition.id) return null;
  const rawValue = checks[definition.id];
  const present = typeof rawValue === 'boolean';
  const passed = definition.mode === 'negative'
    ? rawValue === false
    : rawValue === true;
  return {
    id:definition.id,
    label:definition.label,
    classification:definition.classification,
    temporary:definition.temporary !== false,
    present,
    passed
  };
}

function entryPromotionAuditTriggerSource(record, globalVerdict = {}, resolvedContract = {}, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const trigger = options.trigger || evaluateEntryTrigger(item, {derivedStates, displayedPlan});
  const dependedOnReadyToAct = ['entry','ready_to_act'].includes(String(resolvedContract.actionStateKey || '').trim().toLowerCase());
  const dependedOnEntryLikeState = String(resolvedContract.structuralState || '').trim().toLowerCase() === 'entry';
  const independentSignals = {
    breakAboveTrigger:trigger.breakAboveTrigger === true,
    strongReversal:trigger.strongReversal === true,
    reclaimFollowThrough:trigger.reclaimFollowThrough === true,
    entryTriggerReady:trigger.entryTriggerReady === true,
    nearReady:trigger.nearReady === true,
    currentPriceAtOrAboveEntry:(() => {
      const currentPrice = numericOrNull(item.marketData && item.marketData.price);
      const entry = numericOrNull(displayedPlan && displayedPlan.entry);
      return Number.isFinite(currentPrice) && Number.isFinite(entry) && currentPrice >= entry;
    })(),
    recordReclaimsLevel:item.reclaimsLevel === true,
    recordStrongBullishContinuation:item.strongBullishContinuation === true,
    recordBreaksLocalHigh:item.breaksLocalHigh === true
  };
  const independentTriggerSignalExists = Object.values(independentSignals).some(value => value === true);
  const resolverDerived = globalVerdict && globalVerdict.entry_gate_checks && globalVerdict.entry_gate_checks.entry_trigger_hit === true;
  const source = resolverDerived
    ? (dependedOnReadyToAct || dependedOnEntryLikeState ? 'resolver_state_derived' : 'resolver_gate_pass')
    : (independentTriggerSignalExists ? 'independent_signal' : 'not_hit');
  return {
    entryTriggerHit:globalVerdict && globalVerdict.entry_gate_checks && globalVerdict.entry_gate_checks.entry_trigger_hit === true,
    source,
    dependedOnReadyToAct,
    dependedOnEntryLikeState,
    independentSignals,
    independentTriggerSignalExists,
    circularTriggerSuspected:!independentTriggerSignalExists && (dependedOnReadyToAct || dependedOnEntryLikeState)
  };
}

function buildEntryPromotionAuditSnapshot(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const globalVerdict = options.globalVerdict && typeof options.globalVerdict === 'object' ? options.globalVerdict : resolveGlobalVerdict(item);
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const resolvedContract = options.resolvedContract && typeof options.resolvedContract === 'object'
    ? options.resolvedContract
    : resolveFinalStateContract(item, {
      finalVerdict:globalVerdictLabel(globalVerdict.final_verdict || ''),
      derivedStates,
      displayedPlan
    });
  const visualBucket = normalizeVisualBucketForPairing(
    options.visualBucket
    || options.presentationBucket
    || (options.simplifiedState && options.simplifiedState.visualBucket)
    || ''
  ) || normalizeVisualBucketForPairing(resolveTrackCardVisibleModel(item, options.simplifiedState || {}).visibleBucket || 'monitor');
  const entryChecks = globalVerdict.entry_gate_checks && typeof globalVerdict.entry_gate_checks === 'object'
    ? globalVerdict.entry_gate_checks
    : {};
  const triggerAudit = entryPromotionAuditTriggerSource(item, globalVerdict, resolvedContract, {
    derivedStates,
    displayedPlan,
    trigger:options.trigger
  });
  const checkResults = entryPromotionAuditCheckDefinitions()
    .map(definition => entryPromotionAuditCheckResult(definition, entryChecks))
    .filter(Boolean);
  const passedEntryChecks = checkResults.filter(check => check.passed === true);
  const failedEntryChecks = checkResults.filter(check => check.present && check.passed === false);
  const deadCheck = options.deadCheck || isTerminalDeadSetup(item, {derivedStates, displayedPlan});
  const terminalBlockerExists = deadCheck.dead === true
    || ['avoid','dead'].includes(normalizeGlobalVerdictKey(globalVerdict.final_verdict || ''))
    || globalVerdict.terminal_avoid_applied === true
    || item.terminal_avoid_applied === true;
  const staleDataPreventedFreshPromotionPass = options.staleDataPreventedFreshPromotionPass === true;
  const source = String(options.source || 'unknown').trim().toLowerCase() || 'unknown';
  const snapshot = {
    ticker:normalizeTicker(item.ticker || ''),
    timestamp:String(options.timestamp || new Date().toISOString()),
    source,
    currentVerdict:normalizeGlobalVerdictKey(globalVerdict.final_verdict || 'watch'),
    visualBucket,
    entryGatePass:globalVerdict.entry_gate_pass === true,
    nearEntryGatePass:globalVerdict.near_entry_gate_pass === true,
    passedEntryChecks,
    failedEntryChecks,
    firstFailedEntryCheck:failedEntryChecks[0] || null,
    allFailedEntryChecks:failedEntryChecks,
    terminalBlockerExists,
    staleDataPreventedFreshPromotionPass,
    triggerAudit,
    circularTriggerSuspected:triggerAudit.circularTriggerSuspected === true,
    currentActionState:String(resolvedContract.actionStateKey || '').trim().toLowerCase(),
    currentStructuralState:String(resolvedContract.structuralState || '').trim().toLowerCase(),
    whyNotEntry:failedEntryChecks.slice(0, 3).map(check => check.label),
    nextRequiredAction:failedEntryChecks.length
      ? failedEntryChecks[0].label
      : (globalVerdict.entry_gate_pass === true ? 'Entry gate passed.' : 'Await next confirmation pass.')
  };
  return snapshot;
}

function updateEntryPromotionAudit(record, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return null;
  const snapshot = buildEntryPromotionAuditSnapshot(item, options);
  if(!entryPromotionAuditEligible(snapshot)) return null;
  item.entryPromotionAudit = item.entryPromotionAudit && typeof item.entryPromotionAudit === 'object'
    ? item.entryPromotionAudit
    : {latest:null, history:[]};
  const history = Array.isArray(item.entryPromotionAudit.history) ? item.entryPromotionAudit.history : [];
  item.entryPromotionAudit.latest = snapshot;
  item.entryPromotionAudit.history = [snapshot, ...history]
    .filter(entry => entry && typeof entry === 'object')
    .slice(0, 10);
  return snapshot;
}

