function repairChartGuruStoredText(value = ''){
  const safe = String(value || '');
  if(!/[ðâÃÂ]/.test(safe)) return safe;
  let repaired = safe;
  Object.entries(CHART_GURU_MOJIBAKE_REPAIRS).forEach(([broken, fixed]) => {
    repaired = repaired.split(broken).join(fixed);
  });
  return repaired;
}

function normalizeChartGuruSectionKey(value = ''){
  const normalized = String(value || '')
    .trim()
    .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
    .replace(/[^a-zA-Z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .toLowerCase();
  if(normalized === 'chart_story') return 'biggest_clue';
  if(normalized === 'why_it_matters') return 'why_it_matters';
  if(normalized === 'setup_location') return 'setup_location';
  if(normalized === 'learning_point') return 'learning_point';
  if(normalized === 'what_next') return 'what_next';
  return normalized;
}

function chartGuruSectionDisplayForKey(key = '', fallback = {}){
  const normalizedKey = normalizeChartGuruSectionKey(key);
  const canonical = CHART_GURU_SECTION_DISPLAY[normalizedKey] || null;
  if(canonical) return canonical;
  return {
    icon:repairChartGuruStoredText(String(fallback.icon || '').trim()),
    label:repairChartGuruStoredText(String(fallback.label || '').trim())
  };
}

function renderChartCoachMarkup(display = {}){
  const chartCoach = display && display.chartCoach && typeof display.chartCoach === 'object'
    ? display.chartCoach
    : null;
  const sections = chartCoach && Array.isArray(chartCoach.sections) ? chartCoach.sections : [];
  if(!sections.length){
    return escapeHtml(repairChartGuruStoredText(String(display && display.text || '').trim()));
  }
  return sections.map(section => {
    const lines = String(section.text || '').split('\n').map(line => String(line || '').trim()).filter(Boolean);
    const copy = lines.map((line, index) => `<div class="chart-coach-copy${index > 0 ? ' chart-coach-copy--lesson' : ''}">${escapeHtml(line)}</div>`).join('');
    const confidenceAttr = Number.isFinite(Number(section.confidence)) ? ` data-chart-coach-confidence="${escapeHtml(Number(section.confidence).toFixed(2))}"` : '';
    return `<div class="chart-coach-section${section.teachingFocus === true ? ' chart-coach-section--teaching' : ''}" data-chart-coach-key="${escapeHtml(String(section.key || ''))}"${confidenceAttr}><div class="chart-coach-heading">${escapeHtml(`${section.icon} ${section.label}`)}</div>${copy}</div>`;
  }).join('');
}

function chartGuruNarrationDebugMarkup(analysis = {}, chartCoach = null){
  const safeAnalysis = analysis && typeof analysis === 'object' ? analysis : {};
  const safeCoach = chartCoach && typeof chartCoach === 'object' ? chartCoach : {};
  const narration = safeCoach.diagnostics && safeCoach.diagnostics.narration && typeof safeCoach.diagnostics.narration === 'object'
    ? safeCoach.diagnostics.narration
    : {};
  const eventPacket = safeAnalysis.deterministicEventPacket && typeof safeAnalysis.deterministicEventPacket === 'object'
    ? safeAnalysis.deterministicEventPacket
    : {};
  if(!Object.keys(narration).length) return '';
  const source = String(narration.narrationSource || narration.proseSource || 'unknown').trim().toLowerCase() === 'openai'
    ? 'canonical_llm'
    : String(narration.narrationSource || narration.proseSource || 'unknown').trim();
  const validation = String(narration.validationStatus || '').trim()
    || (['valid', 'recovered'].includes(String(narration.validationOutcome || '').trim()) ? 'passed' : 'failed');
  const codes = Array.isArray(narration.validationErrors) ? narration.validationErrors.map(code => String(code || '').trim()).filter(Boolean) : [];
  const rows = [
    ['Narration source', source || 'unknown'],
    ['Validation', validation],
    ['Validation codes', codes.length ? `[${codes.join(', ')}]` : '[]'],
    ['Retry count', Number(narration.retryCount || 0) ? '1' : '0'],
    // These values are a server response-boundary snapshot. Never fall back to
    // a rehydrated/stored analysis contract here: that would mix generations.
    ['Contract phase', String(narration.contractPhase ?? 'unavailable')],
    ['Packet phase', String(eventPacket.currentPhase || 'unknown')],
    ['Dominant event', String(narration.dominantEvent ?? 'unavailable')],
    ['Next required event', String(narration.nextRequiredEvent ?? 'unavailable')],
    ['Contract version', String(narration.contractVersion || 'unavailable')],
    ['Prose request ID', String(narration.requestId || 'unavailable')],
    ['Prose timestamp', String(narration.completedAt || 'unavailable')]
  ];
  const phaseRepair = narration.phaseRepair && typeof narration.phaseRepair === 'object' ? narration.phaseRepair : {};
  if(Object.keys(phaseRepair).length){
    rows.push(
      ['Phase repair', `${String(phaseRepair.before || 'unknown')} → ${String(phaseRepair.after || 'unknown')} (${String(phaseRepair.source || 'unknown')})`],
      ['Function version', String(narration.functionVersion || 'unavailable')],
      ['Function endpoint', String(narration.functionEndpoint || 'unavailable')],
      ['Request origin', String(narration.requestOrigin || 'unavailable')],
      ['Request host', String(narration.requestHost || 'unavailable')],
      ['Deploy URL', String(narration.deployUrl || 'unavailable')],
      ['Deploy ID', String(narration.deployId || 'unavailable')],
      ['Commit ref', String(narration.commitRef || 'unavailable')],
      ['Netlify context', String(narration.context || 'unavailable')]
    );
  }
  return renderDebugSectionMarkup('Chart Guru Narration', rows.map(([label, value]) => ({label, value})));
}

function canonicalPhaseDecisionDebugMarkup(analysis = {}, chartCoach = null){
  const safeCoach = chartCoach && typeof chartCoach === 'object' ? chartCoach : {};
  const story = safeCoach.storyContext && typeof safeCoach.storyContext === 'object'
    ? safeCoach.storyContext
    : (safeCoach.diagnostics && safeCoach.diagnostics.storyContext && typeof safeCoach.diagnostics.storyContext === 'object'
      ? safeCoach.diagnostics.storyContext
      : {});
  const decision = story.diagnostics && story.diagnostics.phaseDecision && typeof story.diagnostics.phaseDecision === 'object'
    ? story.diagnostics.phaseDecision
    : {};
  if(!Object.keys(decision).length) return '';
  const pct = value => Number.isFinite(Number(value)) ? `${(Number(value) * 100).toFixed(2)}%` : 'unavailable';
  const averages = decision.movingAverages && typeof decision.movingAverages === 'object' ? decision.movingAverages : {};
  const distances = averages.distancePct && typeof averages.distancePct === 'object' ? averages.distancePct : {};
  const support = decision.activeSupport && typeof decision.activeSupport === 'object' ? decision.activeSupport : {};
  const supportEvent = decision.supportEvent && typeof decision.supportEvent === 'object' ? decision.supportEvent : {};
  const latestSupportEpisode = decision.latestSupportEpisode && typeof decision.latestSupportEpisode === 'object' ? decision.latestSupportEpisode : {};
  const latestSupportEvent = latestSupportEpisode.supportEvent && typeof latestSupportEpisode.supportEvent === 'object' ? latestSupportEpisode.supportEvent : {};
  const postSupportHighDetails = decision.postSupportHighDetails && typeof decision.postSupportHighDetails === 'object' ? decision.postSupportHighDetails : {};
  const laterSupportRevisits = Array.isArray(decision.laterSupportRevisits) ? decision.laterSupportRevisits : [];
  const narration = safeCoach.diagnostics && safeCoach.diagnostics.narration && typeof safeCoach.diagnostics.narration === 'object'
    ? safeCoach.diagnostics.narration
    : {};
  const validationCodes = Array.isArray(narration.validationErrors) ? narration.validationErrors.map(value => String(value || '').trim()).filter(Boolean) : [];
  const validationConflictFields = validationCodes.length
    ? validationCodes.map(code => {
      if(code === 'away_phase_active_support_conflict') return `phase=${String(story.currentPhase || 'unknown')}, support.currentlyActive=${String(story.support && story.support.currentlyActive)}, support.interaction=${String(story.support && story.support.interaction || 'unknown')}`;
      if(/away_from_active_support|not_near_active_support|return_to_active_support/.test(code)) return `phase=${String(story.currentPhase || 'unknown')}, support.label=${String(story.support && story.support.label || 'unknown')}, support.currentlyActive=${String(story.support && story.support.currentlyActive)}`;
      return `${code}: see canonical narration contract and rendered prose`;
    }).join('\n')
    : 'none';
  const candidates = (Array.isArray(decision.candidates) ? decision.candidates : []).map(candidate => {
    const value = candidate && typeof candidate === 'object' ? candidate : {};
    return `${String(value.phase || 'unknown')}: ${value.accepted === true ? 'accepted' : 'rejected'} — ${String(value.reason || 'unavailable')}`;
  });
  return renderDebugSectionMarkup('Canonical Phase Decision', [
    {label:'Current price', value:decision.currentPrice ?? 'unavailable'},
    {label:'20MA', value:averages.ma20 ?? 'unavailable'},
    {label:'Distance from 20MA', value:pct(distances.ma20)},
    {label:'Absolute distance from 20MA', value:pct(Math.abs(Number(distances.ma20)))},
    {label:'50MA', value:averages.ma50 ?? 'unavailable'},
    {label:'Distance from 50MA', value:pct(distances.ma50)},
    {label:'Absolute distance from 50MA', value:pct(Math.abs(Number(distances.ma50)))},
    {label:'200MA', value:averages.ma200 ?? 'unavailable'},
    {label:'Distance from 200MA', value:pct(distances.ma200)},
    {label:'Absolute distance from 200MA', value:pct(Math.abs(Number(distances.ma200)))},
    {label:'Selected active support', value:support.label || 'unavailable'},
    {label:'Active-support source', value:support.source || 'unavailable'},
    {label:'Support interaction', value:support.interaction || 'unavailable'},
    {label:'Support-interaction source', value:support.interactionSource || 'unavailable'},
    {label:'Raw/proposed phase', value:decision.rawPhase || 'unavailable'},
    {label:'Final canonical phase', value:decision.finalPhase || 'unavailable'},
    {label:'Phase authority/source', value:decision.phaseSource || 'unavailable'},
    {label:'Dominant event', value:decision.dominantEvent || 'unavailable'},
    {label:'Dominant-event source', value:decision.dominantEventSource || 'unavailable'},
    {label:'Buyer response', value:decision.buyerResponse || 'unavailable'},
    {label:'Buyer-response source', value:decision.buyerResponseSource || 'unavailable'},
    {label:'Buyer control', value:decision.buyerControl || 'unavailable'},
    {label:'Follow-through', value:decision.followThrough || 'unavailable'},
    {label:'Next required event', value:decision.nextRequiredEvent || 'unavailable'},
    {label:'History ordering used', value:decision.historyOrdering || 'unavailable'},
    {label:'Support episode identifier', value:decision.supportEpisodeId || 'unavailable'},
    {label:'Latest support episode identifier', value:latestSupportEpisode.id || 'unavailable'},
    {label:'Latest support-event timestamp/index', value:latestSupportEvent.timestamp ? `${latestSupportEvent.timestamp} / ${latestSupportEvent.index ?? 'unavailable'}` : (latestSupportEvent.index ?? 'unavailable')},
    {label:'Latest episode response detected', value:latestSupportEpisode.responseDetected === true ? 'true' : (latestSupportEpisode.responseDetected === false ? 'false' : 'unavailable')},
    {label:'Selected support-event timestamp/index', value:supportEvent.timestamp ? `${supportEvent.timestamp} / ${supportEvent.index ?? 'unavailable'}` : (supportEvent.index ?? 'unavailable')},
    {label:'Selected support-event price', value:supportEvent.price ?? 'unavailable'},
    {label:'Support-event MA value', value:supportEvent.maValue ?? 'unavailable'},
    {label:'Support-event selection reason', value:decision.supportEventSelectionReason || 'unavailable'},
    {label:'Later MA revisits', value:laterSupportRevisits.length ? laterSupportRevisits.map(revisit => `${revisit.timestamp || 'undated'} / ${revisit.index ?? 'unavailable'}: ${revisit.reason || 'unavailable'}`).join('\n') : 'none'},
    {label:'Post-support high timestamp/index/value', value:postSupportHighDetails.timestamp ? `${postSupportHighDetails.timestamp} / ${postSupportHighDetails.index ?? 'unavailable'} / ${postSupportHighDetails.value ?? 'unavailable'}` : (postSupportHighDetails.value ?? 'unavailable')},
    {label:'Recent high (chart context only)', value:decision.recentHigh ?? 'unavailable'},
    {label:'Anchored post-support high', value:decision.anchoredPostSupportHigh ?? 'unavailable'},
    {label:'Post-support high', value:decision.postSupportHigh ?? 'unavailable'},
    {label:'Post-support-high authority', value:decision.postSupportHighSource || 'unavailable'},
    {label:'Support episode established', value:decision.supportEpisodeEstablished === true ? 'true' : 'false'},
    {label:'Maximum extension', value:pct(decision.maximumExtensionPct)},
    {label:'Current extension', value:pct(decision.currentExtensionPct)},
    {label:'Retracement from high', value:pct(decision.retracementFromPostSupportHighPct)},
    {label:'Retracement available', value:decision.retracementAvailable === true ? 'true' : 'false'},
    {label:'Retracement unavailable reason', value:decision.retracementUnavailableReason || 'none'},
    {label:'Retracement phase override applied', value:decision.retracementPhaseOverrideApplied === true ? 'true' : 'false'},
    {label:'Historical events used', value:decision.historicalEventsUsed === true ? 'true' : 'false'},
    {label:'Candle geometry influenced', value:decision.imageEvidenceInfluenced === true ? 'true' : 'false'},
    {label:'Volume evidence influenced', value:decision.volumeEvidenceInfluenced === true ? 'true' : 'false'},
    {label:'Field resolution order', value:decision.resolutionOrder || 'unavailable'},
    {label:'Transition candidates', value:candidates.length ? candidates.join('\n') : 'unavailable'},
    {label:'Narration validation codes', value:validationCodes.length ? `[${validationCodes.join(', ')}]` : '[]'},
    {label:'Validation conflict fields', value:validationConflictFields}
  ]);
}

function sanitizeChartCoachForDisplay(chartCoach = null, setup = {}){
  const safe = chartCoach && typeof chartCoach === 'object' ? chartCoach : null;
  if(!safe) return null;
  const sections = Array.isArray(safe.sections)
    ? safe.sections.map(section => {
      const item = section && typeof section === 'object' ? section : {};
      const key = normalizeChartGuruSectionKey(item.key || '');
      const display = chartGuruSectionDisplayForKey(key, item);
      return {
        ...item,
        key,
        icon:display.icon,
        label:display.label,
        text:repairChartGuruStoredText(sanitizeAliveWatchSemanticCopy(String(item.text || '').trim(), setup))
      };
    }).filter(section => section.icon && section.label && section.text)
    : [];
  const primaryStoryDisplay = chartGuruSectionDisplayForKey('biggest_clue', safe.primaryStory || {});
  const primaryStory = safe.primaryStory && typeof safe.primaryStory === 'object'
    ? {
      ...safe.primaryStory,
      key:normalizeChartGuruSectionKey(safe.primaryStory.key || '') || String(safe.primaryStory.key || '').trim(),
      icon:primaryStoryDisplay.icon,
      label:primaryStoryDisplay.label,
      text:repairChartGuruStoredText(sanitizeAliveWatchSemanticCopy(String(safe.primaryStory.text || '').trim(), setup))
    }
    : null;
  return {
    ...safe,
    primaryStory,
    sections,
    summaryText:sections.length
      ? sections.map(section => `${section.icon} ${section.label}: ${section.text}`).join('\n')
      : repairChartGuruStoredText(sanitizeAliveWatchSemanticCopy(String(safe.summaryText || '').trim(), setup))
  };
}

function chartGuruNarrationSourceLabel(value = ''){
  const normalized = String(value || '').trim().toLowerCase();
  if(normalized === 'openai_two_step_chart_guru' || normalized === 'openai_narrator') return 'openai_narrator';
  if(normalized === 'deterministic' || normalized === 'deterministic_chart_coach' || normalized === 'deterministic_narrator') return 'deterministic_narrator';
  if(normalized === 'validation_fallback') return 'validation_fallback';
  if(normalized === 'persisted_restored_result') return 'persisted_restored_result';
  return normalized || 'unknown';
}

function chartGuruChartCoachFreshness(chartCoach = null){
  const safe = chartCoach && typeof chartCoach === 'object' ? chartCoach : null;
  const diagnostics = safe && safe.diagnostics && typeof safe.diagnostics === 'object' ? safe.diagnostics : {};
  const meta = diagnostics.meta && typeof diagnostics.meta === 'object' ? diagnostics.meta : {};
  const renderVersion = String(safe && safe.renderVersion || '').trim();
  const contractVersion = String(meta.deterministicContractVersion || '').trim();
  const interpretationPromptVersion = String(meta.interpretationPromptVersion || '').trim();
  const finalPromptVersion = String(meta.finalPromptVersion || '').trim();
  let staleReason = '';
  if(!renderVersion) staleReason = 'missing_render_version';
  else if(renderVersion !== CHART_GURU_RENDER_VERSION) staleReason = 'render_version_mismatch';
  else if(!contractVersion) staleReason = 'missing_deterministic_contract_version';
  else if(contractVersion !== CHART_GURU_DETERMINISTIC_CONTRACT_VERSION) staleReason = 'deterministic_contract_version_mismatch';
  else if(meta.narrationSource === 'openai_narrator' && (!interpretationPromptVersion || !finalPromptVersion)) staleReason = 'missing_prompt_version';
  return {
    fresh:!staleReason,
    staleReason,
    renderVersion,
    contractVersion,
    interpretationPromptVersion,
    finalPromptVersion
  };
}

function chartGuruNarrationSourceForAnalysis(analysis = {}, selectedSummarySource = '', options = {}){
  const safe = analysis && typeof analysis === 'object' ? analysis : {};
  const fallbackReason = String(safe.chartGuruOpenAiFallbackReason || '').trim();
  const chartCoach = safe.chartCoach && typeof safe.chartCoach === 'object' ? safe.chartCoach : null;
  const freshness = chartGuruChartCoachFreshness(chartCoach);
  if(!freshness.fresh) return 'validation_fallback';
  if(options.restored === true) return 'persisted_restored_result';
  if(chartCoach && String(chartCoach.source || '').trim() === 'openai_two_step_chart_guru') return 'openai_narrator';
  if(fallbackReason) return 'validation_fallback';
  if(/^openai_/i.test(String(selectedSummarySource || ''))) return 'openai_narrator';
  if(/^deterministic/i.test(String(selectedSummarySource || ''))) return 'deterministic_narrator';
  return chartGuruNarrationSourceLabel(chartCoach && chartCoach.source || selectedSummarySource);
}

function describeCandleBodyDirection(candle = {}){
  const open = numericOrNull(candle.open);
  const close = numericOrNull(candle.close);
  if(!Number.isFinite(open) || !Number.isFinite(close)) return 'unknown';
  if(close > open) return 'green';
  if(close < open) return 'red';
  return 'flat';
}

function candleWickRejectionState(candle = {}){
  const open = numericOrNull(candle.open);
  const high = numericOrNull(candle.high);
  const low = numericOrNull(candle.low);
  const close = numericOrNull(candle.close);
  if(!Number.isFinite(open) || !Number.isFinite(high) || !Number.isFinite(low) || !Number.isFinite(close)) return 'none';
  const bodyTop = Math.max(open, close);
  const bodyBottom = Math.min(open, close);
  const body = Math.abs(close - open);
  const upperWick = Math.max(0, high - bodyTop);
  const lowerWick = Math.max(0, bodyBottom - low);
  const baseline = body > 0 ? body : Math.max(0.01, (high - low) * 0.15);
  if(upperWick >= baseline * 1.5 && upperWick > lowerWick * 1.1) return 'upper_rejection';
  if(lowerWick >= baseline * 1.5 && lowerWick > upperWick * 1.1) return 'lower_rejection';
  return 'none';
}

function isGenericAiCandleCommentary(text = ''){
  const safe = String(text || '').trim().toLowerCase();
  if(!safe) return true;
  const hasConcreteSignal = /20ma|50ma|200ma|below 20|below 50|above 200|above 20|above 50|below 200|wick|candle|close|open|higher|lower|rejection|follow-?through|bounce|failed bounce|green|red|buyers|sellers|reclaim/i.test(safe);
  const boilerplateOnly = /looks constructive|mixed picture|monitor closely|wait for confirmation|needs confirmation|not ready yet|caution is warranted|uncertain setup|developing setup|watch for follow-through|keep watching|worth monitoring|interesting setup|something to watch/i.test(safe);
  if(hasConcreteSignal) return false;
  return boilerplateOnly || !/[0-9]/.test(safe);
}

function normalizeCandleSequenceOrder(candles = []){
  const rows = Array.isArray(candles) ? candles.slice() : [];
  const parsed = rows.map((candle, index) => {
    const item = candle && typeof candle === 'object' ? candle : {};
    const rawDate = String(item.datetime || item.timestamp || item.date || '').trim();
    const timeValue = rawDate ? Date.parse(rawDate) : NaN;
    return {
      candle:item,
      index,
      timestamp:Number.isFinite(timeValue) ? timeValue : null
    };
  });
  const datedCount = parsed.filter(entry => entry.timestamp !== null).length;
  const allDated = datedCount === parsed.length && parsed.length > 0;
  if(!datedCount){
    return {
      candles:rows,
      orderConfidence:'low'
    };
  }
  parsed.sort((a, b) => {
    if(a.timestamp === null && b.timestamp === null) return a.index - b.index;
    if(a.timestamp === null) return 1;
    if(b.timestamp === null) return -1;
    if(b.timestamp !== a.timestamp) return b.timestamp - a.timestamp;
    return a.index - b.index;
  });
  return {
    candles:parsed.map(entry => entry.candle),
    orderConfidence:allDated ? 'high' : 'medium'
  };
}

function aiCandleCommentaryContradictsCanonical(text = '', facts = {}){
  const safe = String(text || '').trim().toLowerCase();
  if(!safe) return false;
  const ma = facts.maRelation || {};
  if(ma.above20 === false && /\babove (?:the )?20\s*ma\b|\breclaim(?:ing|ed)? (?:the )?20\s*ma\b/i.test(safe)) return true;
  if(ma.above50 === false && /\babove (?:the )?50\s*ma\b|\breclaim(?:ing|ed)? (?:the )?50\s*ma\b/i.test(safe)) return true;
  if(ma.above200 === false && /\babove (?:the )?200\s*ma\b/i.test(safe)) return true;
  if(ma.above200 === true && /\bbelow (?:the )?200\s*ma\b/i.test(safe)) return true;
  if(facts.followThroughConfirmed === false && /\bconfirmed follow-?through\b|\bbounce confirmed\b/i.test(safe)) return true;
  if(facts.failedBounce === true && /\bclean bounce\b|\bhealthy reclaim\b/i.test(safe)) return true;
  return false;
}

function isGenericTradePlanCommentary(text = ''){
  const safe = String(text || '').trim().toLowerCase();
  if(!safe) return true;
  const hasConcreteSignal = /entry|stop|target|reward|risk|math|confirmation|follow-?through|trigger|priceable|plan|usable|invalidat/i.test(safe);
  if(hasConcreteSignal) return false;
  return /interesting setup|monitor closely|worth monitoring|observe|wait and see|mixed picture|something to watch/i.test(safe);
}

function canonicalCandleContext(record = {}, analysis = {}){
  const item = normalizeTickerRecord(record || {});
  const state = analysis && typeof analysis === 'object' ? analysis : {};
  const trusted = state.trustedMarketContext && typeof state.trustedMarketContext === 'object' ? state.trustedMarketContext : {};
  const canonical = state.canonicalValues && typeof state.canonicalValues === 'object' ? state.canonicalValues : {};
  const marketData = item.marketData && typeof item.marketData === 'object' ? item.marketData : {};
  const recentInput = Array.isArray(trusted.recentCandleSequence)
    ? trusted.recentCandleSequence
    : (Array.isArray(marketData.history) ? marketData.history.slice(0, 6) : []);
  const normalizedOrder = normalizeCandleSequenceOrder(recentInput);
  const recent = normalizedOrder.candles.slice(0, 6);
  const latest = recent[0] || {};
  const prior = recent[1] || {};
  const currentPrice = numericOrNull(canonical.price ?? trusted.currentPrice ?? marketData.price);
  const ma20 = numericOrNull(canonical.ma20 ?? trusted.ma20 ?? marketData.ma20 ?? marketData.sma20);
  const ma50 = numericOrNull(canonical.ma50 ?? trusted.ma50 ?? marketData.ma50 ?? marketData.sma50);
  const ma200 = numericOrNull(canonical.ma200 ?? trusted.ma200 ?? marketData.ma200 ?? marketData.sma200);
  const latestClose = numericOrNull(latest.close);
  const priorClose = numericOrNull(prior.close);
  const latestDirection = describeCandleBodyDirection(latest);
  const priorDirection = describeCandleBodyDirection(prior);
  const latestWickRejection = candleWickRejectionState(latest);
  const higherClose = Number.isFinite(latestClose) && Number.isFinite(priorClose) ? latestClose > priorClose : false;
  const lowerClose = Number.isFinite(latestClose) && Number.isFinite(priorClose) ? latestClose < priorClose : false;
  const bounceAttempt = !!(
    recent.length >= 2
    && higherClose
    && latestDirection === 'green'
    && (priorDirection === 'red' || latestWickRejection === 'lower_rejection')
  );
  const followThroughConfirmed = !!(
    recent.length >= 3
    && latestDirection === 'green'
    && priorDirection === 'green'
    && higherClose
    && Number.isFinite(priorClose)
    && Number.isFinite(numericOrNull(recent[2] && recent[2].close))
    && priorClose > numericOrNull(recent[2].close)
  );
  const failedBounce = !!(
    recent.length >= 2
    && lowerClose
    && (latestDirection === 'red' || latestWickRejection === 'upper_rejection')
    && priorDirection === 'green'
  );
  return {
    currentPrice,
    ma20,
    ma50,
    ma200,
    recent,
    latest,
    prior,
    latestDirection,
    priorDirection,
    latestWickRejection,
    higherClose,
    lowerClose,
    bounceAttempt,
    followThroughConfirmed,
    failedBounce,
    orderConfidence:normalizedOrder.orderConfidence,
    maRelation:{
      above20:Number.isFinite(currentPrice) && Number.isFinite(ma20) ? currentPrice > ma20 : null,
      above50:Number.isFinite(currentPrice) && Number.isFinite(ma50) ? currentPrice > ma50 : null,
      above200:Number.isFinite(currentPrice) && Number.isFinite(ma200) ? currentPrice > ma200 : null
    }
  };
}

function buildDeterministicReviewProse({storyContext = {}, decisionContext = {}} = {}){
  const support = storyContext.support && typeof storyContext.support === 'object' ? storyContext.support : {};
  const storyDiagnostics = storyContext.diagnostics && typeof storyContext.diagnostics === 'object' ? storyContext.diagnostics : {};
  const supportLabel = String(support.label || 'support').trim() || 'support';
  const supportPhrase = supportLabel === 'support' ? 'support' : `the ${supportLabel}`;
  const dominantStory = String(storyContext.dominantStory || '').trim();
  const currentPhase = String(storyContext.currentPhase || '').trim();
  const volumeState = String(storyContext.volume && storyContext.volume.state || '').trim();
  const recentIndecision = storyDiagnostics.recentIndecision === true;
  const decisionVerdict = (() => {
    const normalized = String(decisionContext.verdict || 'watch').trim().toLowerCase().replace(/\s+/g, '_');
    if(['watch', 'near_entry', 'entry', 'avoid'].includes(normalized)) return normalized;
    if(normalized.includes('near') && normalized.includes('entry')) return 'near_entry';
    if(normalized.includes('entry')) return 'entry';
    if(normalized.includes('avoid')) return 'avoid';
    return 'watch';
  })();

  let chartRead = 'The recent candles look indecisive, so neither buyers nor sellers proved much control yet.';
  if(
    dominantStory === 'doji_indecision'
    || (
      recentIndecision
      && dominantStory === 'healthy_trend'
      && !['extended_from_support', 'stalled_after_response', 'responding_from_support', 'at_support', 'support_failed'].includes(currentPhase)
    )
  ){
    chartRead = 'The latest candle was small, so neither buyers nor sellers proved much control by the close.';
  }else if(
    dominantStory === 'extended_after_support_rebound'
    || currentPhase === 'extended_from_support'
    || currentPhase === 'away_from_support'
  ){
    chartRead = `Buyers did defend ${supportPhrase}, but the rebound has already extended away from that area, so this is no longer an active support test.`;
  }else if(dominantStory === 'stalled_after_support_response' || currentPhase === 'stalled_after_response'){
    chartRead = `Buyers responded around ${supportPhrase}, but the rebound has stalled and still needs cleaner follow-through.`;
  }else if(dominantStory === 'confirmed_support_rebound'){
    chartRead = `Buyers defended ${supportPhrase} and have started to confirm the rebound, although the setup still depends on the next proper trigger.`;
  }else if(dominantStory === 'initial_support_response' || currentPhase === 'responding_from_support'){
    chartRead = `Price is reacting from ${supportPhrase}, but the response is still early and needs another sign of control.`;
  }else if(dominantStory === 'support_test_in_progress' || currentPhase === 'at_support'){
    chartRead = `Price is sitting at ${supportPhrase}, so the key question is whether buyers can actually hold this support test.`;
  }else if(dominantStory === 'failed_support_test' || dominantStory === 'structure_breaking_down' || currentPhase === 'support_failed'){
    chartRead = `Support has failed around ${supportPhrase}, so the chart is still in repair mode rather than acting like a healthy pullback.`;
  }else if(dominantStory === 'healthy_trend'){
    chartRead = 'The bigger trend still looks constructive, but the recent candles are not yet creating a clearer pullback decision.';
  }

  if(volumeState === 'weak' && !/volume/i.test(chartRead)){
    chartRead += ' Volume is still light, so the move has less backing behind it.';
  }
  if(recentIndecision && !/neither buyers nor sellers proved much control|neither side showed clear control/i.test(chartRead)){
    chartRead += ' The latest candle was small, so neither buyers nor sellers proved much control by the close.';
  }

  let whatNext = 'Wait for the next clear improvement in price action before upgrading the read.';
  if(
    dominantStory === 'doji_indecision'
    || (
      recentIndecision
      && dominantStory === 'healthy_trend'
      && !['extended_from_support', 'stalled_after_response', 'responding_from_support', 'at_support', 'support_failed'].includes(currentPhase)
    )
  ){
    whatNext = 'Wait for a clearer directional candle before treating the pause as meaningful progress.';
  }else if(currentPhase === 'extended_from_support' || currentPhase === 'away_from_support'){
    whatNext = 'Wait for a calmer pullback or consolidation rather than chasing the rebound away from support.';
  }else if(currentPhase === 'stalled_after_response'){
    whatNext = 'Wait for cleaner follow-through before treating the rebound as more than an initial response.';
  }else if(currentPhase === 'support_failed'){
    whatNext = 'Wait for the chart to repair and rebuild support before treating any bounce as meaningful.';
  }else if(currentPhase === 'at_support' || currentPhase === 'responding_from_support'){
    whatNext = `Watch for buyers to hold ${supportPhrase} and add a firmer follow-through candle.`;
  }

  let verdictLine = '';
  if(decisionVerdict === 'near_entry'){
    verdictLine = 'This can support Near Entry monitoring, but the chart story does not create an entry trigger on its own.';
  }else if(decisionVerdict === 'watch'){
    verdictLine = 'This still belongs in Watch until the chart story improves further.';
  }else if(decisionVerdict === 'avoid'){
    verdictLine = 'This chart story does not repair the current Avoid state.';
  }else{
    verdictLine = 'This chart story is descriptive only and does not change the resolver state.';
  }

  return {
    chartRead,
    whatNext,
    verdictLine,
    text:[
      `🧭 Chart Story: ${chartRead}`,
      `🎯 What next?: ${whatNext}`,
      verdictLine
    ].filter(Boolean).join(' ').trim()
  };
}

function deterministicCandleStructureSummary(record = {}, analysis = {}, options = {}){
  const globalVerdict = options.globalVerdict && typeof options.globalVerdict === 'object' ? options.globalVerdict : resolveGlobalVerdict(record);
  const authoritativeDerivedStates = options.derivedStates && typeof options.derivedStates === 'object'
    ? options.derivedStates
    : null;
  const facts = canonicalCandleContext(record, analysis);
  const hasContext = Number.isFinite(facts.currentPrice)
    && (Number.isFinite(facts.ma20) || Number.isFinite(facts.ma50) || Number.isFinite(facts.ma200))
    && facts.latest && typeof facts.latest === 'object';
  const aiText = String(
    analysis && (
      analysis.plain_english_chart_read
      || analysis.chart_read
      || analysis.coach_summary
      || analysis.candleStructureAnalysis && (analysis.candleStructureAnalysis.summary || analysis.candleStructureAnalysis.noviceFriendlyCandleRead || analysis.candleStructureAnalysis.novice_friendly_candle_read)
    ) || ''
  ).trim();
  if(!hasContext){
    return {
      available:false,
      text:'',
      reason:'insufficient canonical candle context',
      aiMissing:!aiText,
      aiGeneric:false,
      aiContradictsCanonical:false,
      facts:null
    };
  }
  const positionBits = [];
  if(facts.maRelation.above20 === true) positionBits.push('above the 20MA');
  else if(facts.maRelation.above20 === false) positionBits.push('below the 20MA');
  if(facts.maRelation.above50 === true) positionBits.push('above the 50MA');
  else if(facts.maRelation.above50 === false) positionBits.push('below the 50MA');
  if(facts.maRelation.above200 === true) positionBits.push('above the 200MA');
  else if(facts.maRelation.above200 === false) positionBits.push('below the 200MA');
  const positionLine = positionBits.length ? `Price is ${positionBits.join(', ')}.` : 'Price is moving around key moving averages.';
  let candleLine = facts.latestDirection === 'green'
    ? 'The latest candle closed green.'
    : (facts.latestDirection === 'red' ? 'The latest candle closed red.' : 'The latest candle closed flat.');
  if(facts.higherClose) candleLine += ' It closed above the prior candle.';
  else if(facts.lowerClose) candleLine += ' It closed below the prior candle.';
  if(facts.latestWickRejection === 'lower_rejection') candleLine += ' There is lower-wick rejection, which shows buyers defended the low.';
  else if(facts.latestWickRejection === 'upper_rejection') candleLine += ' There is upper-wick rejection, which shows sellers pushed it back down.';
  let bounceLine = 'Follow-through is still missing.';
  if(facts.followThroughConfirmed){
    bounceLine = 'Recent candles show follow-through after the bounce attempt.';
  }else if(facts.failedBounce){
    bounceLine = 'The recent bounce attempt has faded and looks like a failed bounce.';
  }else if(facts.bounceAttempt){
    bounceLine = 'Recent candles show a bounce attempt, but confirmation is still missing.';
  }
  const verdictKey = normalizeGlobalVerdictKey(globalVerdict.final_verdict || 'watch');
  let verdictLine = '';
  if(verdictKey === 'near_entry'){
    verdictLine = facts.followThroughConfirmed
      ? 'This can support Near Entry monitoring, but candle structure alone does not create an entry signal.'
      : 'This can stay in Near Entry monitoring only if buyers add stronger follow-through.';
  }else if(verdictKey === 'watch'){
    verdictLine = 'This still belongs in Watch until the candles show cleaner confirmation.';
  }else if(verdictKey === 'avoid'){
    verdictLine = 'This candle read does not repair the resolver Avoid state.';
  }else{
    verdictLine = 'This candle read is descriptive only and does not change the resolver state.';
  }
  const text = [positionLine, candleLine, bounceLine, verdictLine].filter(Boolean).join(' ').trim();
  const aiMissing = !aiText;
  const aiGeneric = isGenericAiCandleCommentary(aiText);
  const aiContradictsCanonical = aiCandleCommentaryContradictsCanonical(aiText, facts);
  const explicitStoryContext = options.storyContext && typeof options.storyContext === 'object'
    ? options.storyContext
    : null;
  const storyContext = explicitStoryContext
    || (typeof buildCanonicalStoryContextForRecord === 'function'
      ? buildCanonicalStoryContextForRecord(record, {
        analysis,
        globalVerdict,
        derivedStates:authoritativeDerivedStates,
        facts
      })
      : null);
  const reviewProse = storyContext && typeof buildDeterministicReviewProse === 'function'
    ? buildDeterministicReviewProse({
      storyContext,
      decisionContext:{verdict:globalVerdict.final_verdict || globalVerdict.finalVerdict || 'watch'}
    })
    : '';
  const reason = aiMissing
    ? 'AI candle commentary missing'
    : (aiGeneric
      ? 'AI candle commentary was too generic'
      : (aiContradictsCanonical ? 'AI candle commentary contradicted canonical values' : 'fallback available'));
  return {
    available:true,
    text,
    reason,
    aiMissing,
    aiGeneric,
    aiContradictsCanonical,
    facts,
    storyContext,
    reviewProse
  };
}

function chartCoachWordCount(text = ''){
  return String(text || '').trim().split(/\s+/).filter(Boolean).length;
}

const CHART_COACH_SECTION_PRIORITY = Object.freeze({
  candle:100,
  indecision:96,
  trend:90,
  wicks:85,
  support:82,
  resistance:82,
  volume:75,
  strength:70,
  weakness:70,
  what_next:0
});

function chartCoachConfidenceSentence(confidence, strongText, softText){
  return Number(confidence) >= 0.8 ? strongText : softText;
}

function chartCoachBodyDescriptor(candle = {}){
  const open = numericOrNull(candle.open);
  const high = numericOrNull(candle.high);
  const low = numericOrNull(candle.low);
  const close = numericOrNull(candle.close);
  if(![open, high, low, close].every(Number.isFinite)) return 'normal';
  const range = Math.max(0, high - low);
  if(range <= 0) return 'small';
  const body = Math.abs(close - open);
  const ratio = body / range;
  if(ratio >= 0.65) return 'strong';
  if(ratio <= 0.2) return 'small';
  return 'normal';
}

function chartCoachStructureSignals(sequence = []){
  const recent = Array.isArray(sequence) ? sequence.slice(0, 4) : [];
  const highs = recent.map(item => numericOrNull(item && item.high));
  const lows = recent.map(item => numericOrNull(item && item.low));
  let higherHighs = 0;
  let higherLows = 0;
  let lowerHighs = 0;
  let lowerLows = 0;
  for(let index = 0; index < recent.length - 1; index += 1){
    const currentHigh = highs[index];
    const nextHigh = highs[index + 1];
    const currentLow = lows[index];
    const nextLow = lows[index + 1];
    if(Number.isFinite(currentHigh) && Number.isFinite(nextHigh)){
      if(currentHigh > nextHigh) higherHighs += 1;
      if(currentHigh < nextHigh) lowerHighs += 1;
    }
    if(Number.isFinite(currentLow) && Number.isFinite(nextLow)){
      if(currentLow > nextLow) higherLows += 1;
      if(currentLow < nextLow) lowerLows += 1;
    }
  }
  return {higherHighs, higherLows, lowerHighs, lowerLows};
}

function chartCoachPrimaryOpportunityScore(section = {}){
  const key = String(section.key || '').trim();
  if(key === 'biggest_clue') return 120;
  if(key === 'why_it_matters') return 110;
  if(key === 'wicks') return 104;
  if(key === 'indecision') return 102;
  if(key === 'strength') return 98;
  if(key === 'volume') return 94;
  if(key === 'support' || key === 'resistance') return 92;
  if(key === 'weakness') return 88;
  if(key === 'trend') return 74;
  if(key === 'learning_point') return 6;
  return 10;
}

function chartCoachPriorityForKey(key = ''){
  const normalized = String(key || '').trim();
  const priorityMap = {
    biggest_clue:120,
    why_it_matters:108,
    indecision:102,
    wicks:100,
    strength:98,
    volume:94,
    support:92,
    resistance:92,
    weakness:88,
    trend:74,
    learning_point:4,
    what_next:0
  };
  return Object.prototype.hasOwnProperty.call(priorityMap, normalized)
    ? priorityMap[normalized]
    : 10;
}

function chartCoachProximityLabel(price, level, tolerancePct = 0.015){
  if(!Number.isFinite(price) || !Number.isFinite(level) || level === 0) return '';
  const distancePct = Math.abs(price - level) / Math.abs(level);
  return distancePct <= tolerancePct ? 'near' : '';
}

function finalizeChartCoachSections(sections = []){
  const input = (Array.isArray(sections) ? sections : [])
    .map((section, index) => ({
      key:String(section && section.key || '').trim(),
      icon:String(section && section.icon || '').trim(),
      label:String(section && section.label || '').trim(),
      text:String(section && section.text || '').trim(),
      confidence:Number.isFinite(Number(section && section.confidence)) ? Number(section.confidence) : 0.65,
      teachingFocus:section && section.teachingFocus === true,
      source:String(section && section.source || 'deterministic').trim(),
      evidenceFactIds:Array.isArray(section && section.evidenceFactIds)
        ? section.evidenceFactIds.map(item => String(item || '').trim()).filter(Boolean)
        : [],
      _index:index
    }))
    .filter(section => section.icon && section.label && section.text);
  const sortSections = list => list.slice().sort((left, right) => {
    const priorityDelta = chartCoachPriorityForKey(right.key) - chartCoachPriorityForKey(left.key);
    if(priorityDelta !== 0) return priorityDelta;
    const scoreDelta = chartCoachPrimaryOpportunityScore(right) - chartCoachPrimaryOpportunityScore(left);
    if(scoreDelta !== 0) return scoreDelta;
    return left._index - right._index;
  });
  const biggestClue = sortSections(input.filter(section => section.key === 'biggest_clue')).slice(0, 1);
  const supportSections = sortSections(input.filter(section => !['biggest_clue', 'learning_point', 'what_next'].includes(section.key))).slice(0, 2);
  const learningPoint = sortSections(input.filter(section => section.key === 'learning_point')).slice(0, 1);
  const whatNext = sortSections(input.filter(section => section.key === 'what_next')).slice(0, 1);
  return [...biggestClue, ...supportSections, ...learningPoint, ...whatNext]
    .slice(0, 5)
    .map(section => {
      const cloned = {...section};
      delete cloned._index;
      cloned.teachingFocus = cloned.key === 'learning_point';
      return cloned;
    });
}

function chartCoachDiagnosticsForSections(sections = [], recentStory = null, primaryStory = null){
  const finalSections = Array.isArray(sections) ? sections : [];
  return {
    meta:{
      buildInfo:currentBuildInfo(),
      deterministicContractVersion:CHART_GURU_DETERMINISTIC_CONTRACT_VERSION,
      interpretationPromptVersion:CHART_GURU_INTERPRETATION_PROMPT_VERSION,
      finalPromptVersion:CHART_GURU_FINAL_PROMPT_VERSION,
      renderVersion:CHART_GURU_RENDER_VERSION
    },
    sectionConfidence:finalSections.map(section => ({
      key:String(section && section.key || '').trim(),
      confidence:Number.isFinite(Number(section && section.confidence)) ? Number(section.confidence) : null,
      teachingFocus:section && section.teachingFocus === true
    })),
    priorityOrder:finalSections.map(section => String(section && section.key || '').trim()),
    storyContract:recentStory && typeof recentStory === 'object' ? {
      primaryStoryKey:String(primaryStory && primaryStory.key || '').trim(),
      storyKey:String(recentStory.key || '').trim(),
      toneMode:String(recentStory.toneMode || '').trim(),
      confidenceMode:String(recentStory.confidenceMode || '').trim(),
      supportSemantic:String(recentStory.supportSemantic || '').trim(),
      buyerResponseSemantic:String(recentStory.buyerResponseSemantic || '').trim(),
      confirmationSemantic:String(recentStory.confirmationSemantic || '').trim(),
      steps:Array.isArray(recentStory.steps) ? recentStory.steps.map(step => String(step || '').trim()).filter(Boolean) : [],
      stepDetails:Array.isArray(recentStory.stepDetails) ? recentStory.stepDetails.map(detail => ({
        key:String(detail && detail.key || '').trim(),
        evidenceFactIds:Array.isArray(detail && detail.evidenceFactIds) ? detail.evidenceFactIds.map(id => String(id || '').trim()).filter(Boolean) : [],
        derivedFromSteps:Array.isArray(detail && detail.derivedFromSteps) ? detail.derivedFromSteps.map(value => String(value || '').trim()).filter(Boolean) : [],
        derivedFromConditions:Array.isArray(detail && detail.derivedFromConditions) ? detail.derivedFromConditions.map(value => String(value || '').trim()).filter(Boolean) : []
      })).filter(detail => detail.key) : []
    } : null
  };
}

function chartCoachRecentColorRun(sequence = [], direction = ''){
  const normalizedDirection = String(direction || '').trim();
  if(!normalizedDirection) return 0;
  let run = 0;
  for(const candle of (Array.isArray(sequence) ? sequence : []).slice(0, 5)){
    if(describeCandleBodyDirection(candle) !== normalizedDirection) break;
    run += 1;
  }
  return run;
}

function chartCoachLargeBodyRun(sequence = []){
  let run = 0;
  for(const candle of (Array.isArray(sequence) ? sequence : []).slice(0, 5)){
    if(chartCoachBodyDescriptor(candle) !== 'strong') break;
    run += 1;
  }
  return run;
}

function chartNarratorDeterministicPick(options = [], seed = 0){
  const list = Array.isArray(options) ? options.filter(Boolean) : [];
  if(!list.length) return '';
  const normalizedSeed = Number.isFinite(Number(seed)) ? Math.abs(Number(seed)) : 0;
  return list[normalizedSeed % list.length];
}

function chartNarratorSupportLabel(context = {}){
  if(context.near20 === 'near' || context.pullbackNear20 === true) return '20-day average';
  if(context.near50 === 'near' || context.pullbackNear50 === true) return '50-day average';
  if(context.recentSupportType === '20ma') return '20-day average';
  if(context.recentSupportType === '50ma') return '50-day average';
  return 'support';
}

function chartGuruBuyerResponsePresent(context = {}){
  const bounceState = String(context.bounceState || '').trim().toLowerCase();
  const stabilisationState = String(context.stabilisationState || '').trim().toLowerCase();
  const responseStates = new Set(['attempt', 'early', 'developing', 'improving', 'rebound', 'stabilising', 'stabilizing', 'constructive', 'present', 'clear', 'confirmed']);
  return context.bounceAttempt === true
    || responseStates.has(bounceState)
    || responseStates.has(stabilisationState);
}

function chartGuruRecentSupportType(context = {}){
  const evaluationScanType = String(context.evaluationScanType || context.scanType || '').trim().toLowerCase();
  if(context.pullbackNear20 === true || context.near20 === 'near' || evaluationScanType === '20ma') return '20ma';
  if(context.pullbackNear50 === true || context.near50 === 'near' || evaluationScanType === '50ma') return '50ma';
  return '';
}

function chartGuruResolvedSupportType(context = {}, supportType = ''){
  const normalizeSupportType = (value = '') => {
    const normalizedValue = String(value || '').trim().toLowerCase();
    if(['20ma', '20ma_support'].includes(normalizedValue)) return '20ma';
    if(['50ma', '50ma_support'].includes(normalizedValue)) return '50ma';
    return '';
  };
  const explicitSupportType = normalizeSupportType(supportType);
  if(explicitSupportType) return explicitSupportType;
  const explicitSupportContext = normalizeSupportType(
    context.supportContext
    || context.support_context
    || context.recentSupportType
    || ''
  );
  if(explicitSupportContext) return explicitSupportContext;
  return normalizeSupportType(chartGuruRecentSupportType(context));
}

function chartGuruRecentSupportResponsePresent(context = {}){
  const supportType = chartGuruResolvedSupportType(context);
  const bounceState = String(context.bounceState || '').trim().toLowerCase();
  const stabilisationState = String(context.stabilisationState || '').trim().toLowerCase();
  const recentlyLeftSupportZone = context.recentlyLeftSupportZone === true
    || ['off_level', 'extended', 'extended_from_support'].includes(String(context.setupLocationState || '').trim().toLowerCase());
  const reclaimEvidencePresent = context.reclaimConfirmed === true
    || context.followThroughConfirmed === true
    || context.candleEvidenceReclaimedPriorDayHigh === true
    || context.candleEvidenceReclaimRangeMeaningful === true
    || context.candleEvidenceHigherLowHold === true
    || Number(context.candleEvidenceUpClosesAfterLow) >= 1
    || ['improving', 'rebound', 'confirmed'].includes(bounceState)
    || ['clear', 'present'].includes(stabilisationState);
  return !!(
    supportType
    && recentlyLeftSupportZone
    && context.structureIntact === true
    && context.failedBounce !== true
    && chartGuruBuyerResponsePresent(context)
    && reclaimEvidencePresent
  );
}

function chartGuruSupportReferenceLevel(context = {}, supportType = ''){
  const resolvedSupportType = chartGuruResolvedSupportType(context, supportType);
  const rawLevel = resolvedSupportType === '20ma'
    ? context.ma20
    : (resolvedSupportType === '50ma' ? context.ma50 : null);
  if(rawLevel === null || rawLevel === undefined || rawLevel === '') return null;
  const level = Number(rawLevel);
  return Number.isFinite(level) ? level : null;
}

function chartGuruSupportDistancePct(context = {}, supportType = ''){
  const rawPrice = context.currentPrice;
  if(rawPrice === null || rawPrice === undefined || rawPrice === '') return null;
  const price = Number(rawPrice);
  const level = chartGuruSupportReferenceLevel(context, supportType);
  if(!Number.isFinite(price) || !Number.isFinite(level) || level === 0) return null;
  return Math.abs(price - level) / Math.abs(level);
}

function chartGuruSemanticEnvelopeFromNarrativeContext(narrativeContext = {}){
  const context = narrativeContext && typeof narrativeContext === 'object' ? narrativeContext : {};
  const support = context.support && typeof context.support === 'object' ? context.support : {};
  const buyerResponse = context.buyerResponse && typeof context.buyerResponse === 'object' ? context.buyerResponse : {};
  const confirmation = context.confirmation && typeof context.confirmation === 'object' ? context.confirmation : {};
  return {
    supportSemantic:String(
      support.semantic
      || ''
    ).trim().toLowerCase() || 'support_unknown',
    buyerResponseSemantic:String(
      buyerResponse.semantic
      || ''
    ).trim().toLowerCase() || 'response_unknown',
    confirmationSemantic:String(
      confirmation.semantic
      || ''
    ).trim().toLowerCase() || 'follow_through_unknown'
  };
}

function chartGuruSemanticEnvelopeCompatibilityForStoryKey(storyKey = ''){
  const normalizedKey = String(storyKey || '').trim().toLowerCase();
  const map = {
    early_rebound_from_20ma:{
      supportSemantic:'support_present',
      buyerResponseSemantic:'response_present',
      confirmationSemantic:'follow_through_unconfirmed'
    },
    constructive_pullback_near_20ma:{
      supportSemantic:'support_present'
    },
    constructive_pullback_near_50ma:{
      supportSemantic:'support_present'
    },
    bounce_confirmation_pending:{
      supportSemantic:'support_present',
      buyerResponseSemantic:'response_present',
      confirmationSemantic:'follow_through_confirmed'
    },
    off_level_wait_for_clearer_support:{
      supportSemantic:'support_absent',
      buyerResponseSemantic:'response_absent'
    },
    extended_after_run:{
      supportSemantic:'support_absent',
      buyerResponseSemantic:'response_absent'
    },
    bounce_attempt:{
      supportSemantic:'support_reclaimed',
      buyerResponseSemantic:'response_present',
      confirmationSemantic:'follow_through_unconfirmed'
    },
    long_lower_wick_support_test:{
      supportSemantic:'support_reclaimed'
    },
    failed_bounce:{
      supportSemantic:'support_failed',
      buyerResponseSemantic:'response_failed',
      confirmationSemantic:'follow_through_failed'
    },
    pullback_still_repairing:{
      supportSemantic:'support_failed'
    },
    structure_breaking_down:{
      supportSemantic:'support_failed',
      buyerResponseSemantic:'response_failed',
      confirmationSemantic:'follow_through_failed'
    },
    sharp_selloff:{
      buyerResponseSemantic:'response_failed',
      confirmationSemantic:'follow_through_failed'
    }
  };
  return Object.prototype.hasOwnProperty.call(map, normalizedKey)
    ? {...map[normalizedKey]}
    : null;
}

function chartGuruSupportAuthority(globalVerdict = {}, derivedStates = {}, canonicalPullback = {}){
  const explicit = globalVerdict && typeof globalVerdict === 'object' ? globalVerdict : {};
  const projection = canonicalPullback && typeof canonicalPullback === 'object' ? canonicalPullback : {};
  const derived = derivedStates && typeof derivedStates === 'object' ? derivedStates : {};
  const text = value => String(value || '').trim().toLowerCase();
  const firstUsable = (values, allowed) => values.map(text).find(value => allowed.includes(value)) || '';
  const firstFinite = values => values.map(numericOrNull).find(Number.isFinite) ?? null;
  const explicitInteraction = firstUsable([
    explicit.support_interaction_state,
    explicit.supportInteractionState
  ], ['active_20ma_support', 'active_50ma_support']);
  const projectionInteraction = firstUsable([
    projection.support_interaction_state,
    projection.supportInteractionState
  ], ['active_20ma_support', 'active_50ma_support']);
  const interaction = [explicitInteraction, projectionInteraction].find(value => value && value !== 'none') || '';
  const supportType = chartGuruResolvedSupportType({
    supportContext:firstUsable([
      explicit.supportContext, explicit.support_context, explicit.supportType, explicit.support_type,
      projection.supportContext, projection.support_context, projection.supportType, projection.support_type,
      derived.supportContext, derived.support_context
    ], ['20ma', '20ma_support', '50ma', '50ma_support']),
    pullbackNear20:/20ma/.test(interaction),
    pullbackNear50:/50ma/.test(interaction)
  });
  const supportTestState = firstUsable([
    explicit.supportTestState, explicit.support_test_state,
    projection.supportTestState, projection.support_test_state,
    derived.supportTestState, derived.support_test_state
  ], ['held', 'testing', 'failed']);
  const buyerControlState = firstUsable([
    explicit.buyerControlState, explicit.buyer_control_state,
    projection.buyerControlState, projection.buyer_control_state,
    derived.buyerControlState, derived.buyer_control_state
  ], ['confirmed', 'emerging']);
  const explicitActive = typeof explicit.supportCurrentlyActive === 'boolean'
    ? explicit.supportCurrentlyActive
    : (typeof explicit.support_currently_active === 'boolean' ? explicit.support_currently_active : null);
  const projectedActive = typeof projection.supportCurrentlyActive === 'boolean'
    ? projection.supportCurrentlyActive
    : (typeof projection.support_currently_active === 'boolean' ? projection.support_currently_active : null);
  const explicitSupportEvidence = !!(
    chartGuruResolvedSupportType({
      supportContext:firstUsable([explicit.supportContext, explicit.support_context, explicit.supportType, explicit.support_type], ['20ma', '20ma_support', '50ma', '50ma_support']),
      pullbackNear20:/20ma/.test(explicitInteraction),
      pullbackNear50:/50ma/.test(explicitInteraction)
    })
    && ['held', 'testing'].includes(firstUsable([explicit.supportTestState, explicit.support_test_state], ['held', 'testing', 'failed']))
  );
  let active = false;
  if(supportTestState === 'failed'){
    active = false;
  }else if(explicitActive !== null){
    active = explicitActive;
  }else if(explicitSupportEvidence || /^active_(?:20|50)ma_support$/.test(explicitInteraction)){
    active = true;
  }else if(projectedActive !== null){
    active = projectedActive;
  }else{
    active = /^active_(?:20|50)ma_support$/.test(interaction)
      || (supportTestState !== 'failed' && ['held', 'testing'].includes(supportTestState));
  }
  const usable = !!(
    supportType
    && (active || ['testing', 'held', 'failed'].includes(supportTestState))
  );
  if(usable){
    return {
      authoritative:true,
      supportType,
      supportContext:`${supportType}_support`,
      supportTestState,
      supportCurrentlyActive:active,
      buyerControlState,
      distanceFromSupportPct:firstFinite([
        explicit.distanceFromSupportPct, explicit.distance_from_support_pct, explicit.supportDistancePct, explicit.support_distance_pct,
        projection.distanceFromSupportPct, projection.distance_from_support_pct, projection.supportDistancePct, projection.support_distance_pct
      ]),
      currentPhase:firstUsable([
        explicit.currentPhase, explicit.current_phase,
        projection.currentPhase, projection.current_phase
      ], ['at_support', 'responding_from_support', 'stalled_after_response', 'extended_from_support', 'away_from_support', 'support_failed', 'repairing_structure'])
    };
  }
  return {
    authoritative:false,
    supportType:'',
    supportContext:text(derived.supportContext || derived.support_context),
    supportTestState:text(derived.supportTestState || derived.support_test_state),
    supportCurrentlyActive:false,
    buyerControlState:text(derived.buyerControlState || derived.buyer_control_state),
    distanceFromSupportPct:null,
    currentPhase:''
  };
}

function chartGuruExplicitResolverSupportContext(record = {}, globalVerdict = {}){
  const explicit = globalVerdict && typeof globalVerdict === 'object' ? globalVerdict : {};
  const usable = (value, allowed) => {
    const normalized = String(value || '').trim().toLowerCase();
    return allowed.includes(normalized) ? normalized : '';
  };
  const explicitSupportContext = usable(explicit.support_context, ['20ma_support', '50ma_support'])
    || usable(explicit.supportContext, ['20ma_support', '50ma_support'])
    || usable(explicit.support_type, ['20ma_support', '50ma_support'])
    || usable(explicit.supportType, ['20ma_support', '50ma_support']);
  const explicitSupportTestState = usable(explicit.support_test_state, ['held', 'testing', 'failed'])
    || usable(explicit.supportTestState, ['held', 'testing', 'failed']);
  const explicitBuyerControlState = usable(explicit.buyer_control_state, ['confirmed', 'emerging'])
    || usable(explicit.buyerControlState, ['confirmed', 'emerging']);
  return {
    ...explicit,
    ...(explicitSupportContext ? {support_context:explicitSupportContext} : {}),
    ...(explicitSupportTestState ? {support_test_state:explicitSupportTestState} : {}),
    ...(explicitBuyerControlState ? {buyer_control_state:explicitBuyerControlState} : {})
  };
}

function chartGuruValidatedCanonicalPhase(phase = '', {supportInteraction = '', supportCurrentlyActive = false, buyerResponsePresent = false, buyerControlState = '', reboundStalled = false} = {}){
  const policy = globalThis.ChartGuruPhasePolicy;
  return policy && typeof policy.validatedCanonicalPhase === 'function'
    ? policy.validatedCanonicalPhase(phase, {supportInteraction, supportCurrentlyActive, buyerResponsePresent, buyerControlState, reboundStalled})
    : '';
}

function chartGuruSupportEpisodeFromHistory(context = {}, supportReferenceLevel = null){
  const explicitHigh = numericOrNull(context.postSupportHigh ?? context.maximumPriceSinceSupport ?? context.maximumExtensionPrice);
  if(Number.isFinite(explicitHigh)){
    return {
      historyOrdering:'explicit_high_only',
      supportEvent:null,
      postSupportHigh:{index:null, timestamp:null, value:explicitHigh},
      selectionReason:'explicit post-support high',
      laterRevisits:[]
    };
  }
  const supportType = chartGuruResolvedSupportType(context);
  const maPeriod = supportType === '20ma' ? 20 : (supportType === '50ma' ? 50 : null);
  if(!maPeriod) return null;
  const history = Array.isArray(context.historySequence) ? context.historySequence : [];
  // normalizeCandleSequenceOrder sorts dated production history newest-first:
  // index 0 is now, and increasing indexes move backward in time.
  const ordered = normalizeCandleSequenceOrder(history).candles;
  if(!ordered.length) return null;
  const supportTolerance = 0.04;
  const maKey = supportType === '20ma' ? 'ma20' : 'ma50';
  const suppliedMaKeys = supportType === '20ma' ? ['ma20', 'sma20', 'sma_20'] : ['ma50', 'sma50', 'sma_50'];
  const rollingMaAt = index => {
    const closes = ordered.slice(index, index + maPeriod).map(candle => numericOrNull(candle && candle.close));
    return closes.length === maPeriod && closes.every(Number.isFinite)
      ? closes.reduce((sum, close) => sum + close, 0) / maPeriod
      : null;
  };
  const contacts = ordered.map((candle, index) => {
    const suppliedMa = suppliedMaKeys.map(key => numericOrNull(candle && candle[key])).find(Number.isFinite);
    const derivedMa = Number.isFinite(suppliedMa) ? null : rollingMaAt(index);
    const maValue = Number.isFinite(suppliedMa) ? suppliedMa : derivedMa;
    const maSource = Number.isFinite(suppliedMa) ? 'per_candle' : (Number.isFinite(derivedMa) ? 'derived_rolling' : 'unavailable');
    const close = numericOrNull(candle && candle.close);
    const low = numericOrNull(candle && candle.low);
    // Historical interaction is evaluated against the MA that existed on this
    // candle. Today's support level is only relevant to current location and
    // must never choose which historical OHLC value represents the touch.
    const price = Number.isFinite(maValue)
      ? [close, low]
        .filter(Number.isFinite)
        .sort((left, right) => Math.abs(left - maValue) - Math.abs(right - maValue))[0] ?? null
      : null;
    return {
      candle,
      index,
      price,
      maValue,
      maSource,
      distancePct:Number.isFinite(price) && Number.isFinite(maValue) && maValue !== 0 ? Math.abs(price - maValue) / Math.abs(maValue) : null,
      isContact:Number.isFinite(price) && Number.isFinite(maValue) && Math.abs(price - maValue) / Math.abs(maValue) <= supportTolerance
    };
  });
  const episodes = [];
  contacts.forEach(contact => {
    if(!contact.isContact) return;
    const previous = episodes[episodes.length - 1];
    if(previous && contact.index === previous.endIndex + 1){
      previous.endIndex = contact.index;
      previous.contacts.push(contact);
      return;
    }
    episodes.push({startIndex:contact.index, endIndex:contact.index, contacts:[contact]});
  });
  const supportEpisodeMaSource = contacts.some(contact => contact.maSource === 'per_candle')
    ? 'per_candle'
    : (contacts.some(contact => contact.maSource === 'derived_rolling') ? 'derived_rolling' : 'unavailable');
  const candidates = episodes.map((episode, ordinal) => {
    // Contacts are stored newest-first. The oldest contact is the initial test
    // that began this episode; a rebound candle can still wick into the MA and
    // must not replace that origin merely because it is the newest contact.
    const supportEvent = episode.contacts[episode.contacts.length - 1];
    // `ordered` is newest-first: lower indexes are later in time. Exclude the
    // complete contact episode (startIndex through endIndex) so the response
    // window begins with the first true post-episode candle at startIndex - 1.
    const postSupport = ordered.slice(0, episode.startIndex)
      .map((candle, index) => ({candle, index, high:numericOrNull(candle && candle.high)}))
      .filter(entry => Number.isFinite(entry.high));
    const postSupportHigh = postSupport.reduce((best, entry) => !best || entry.high > best.high ? entry : best, null);
    // `ordered` is newest-first, so reverse this local slice before validating
    // the departure. Only an uninterrupted qualifying run immediately after
    // the support episode can establish that episode's response.
    const consecutiveResponseCandles = [];
    for(const entry of postSupport.slice().reverse()){
      const close = numericOrNull(entry.candle && entry.candle.close);
      if(!Number.isFinite(close) || close < supportEvent.maValue * 1.015) break;
      consecutiveResponseCandles.push(entry);
    }
    // A single candle after a later MA revisit is not enough to replace the
    // established rebound episode. Require an ordered, multi-candle departure
    // from the touch so a retracement back into the MA cannot erase its own
    // preceding rally high.
    const responseDetected = !!(postSupportHigh
      && postSupportHigh.high >= supportEvent.maValue * 1.035
      && consecutiveResponseCandles.length >= 2);
    return {
      id:`support_episode_${ordinal + 1}`,
      supportEvent,
      contactStartIndex:episode.startIndex,
      contactEndIndex:episode.endIndex,
      responseWindowStartIndex:episode.startIndex > 0 ? episode.startIndex - 1 : null,
      responseThreshold:supportEvent.maValue * 1.015,
      postSupportHigh,
      responseDetected,
      responseCandleCount:consecutiveResponseCandles.length,
      qualifyingResponseIndexes:consecutiveResponseCandles.map(entry => entry.index),
      selectionReason:responseDetected
        ? 'MA contact followed by a material multi-candle rebound'
        : 'rejected: later MA revisit has no material multi-candle post-touch response'
    };
  });
  const timestampFor = candle => String(candle && (candle.datetime || candle.timestamp || candle.date) || '').trim() || null;
  const projectEpisode = candidate => candidate ? {
    id:candidate.id,
    supportEvent:{
      id:candidate.id,
      index:candidate.supportEvent.index,
      timestamp:timestampFor(candidate.supportEvent.candle),
      price:candidate.supportEvent.price,
      maValue:candidate.supportEvent.maValue,
      maSource:candidate.supportEvent.maSource,
      distancePct:candidate.supportEvent.distancePct,
      selectionReason:candidate.selectionReason
    },
    contactStartIndex:candidate.contactStartIndex,
    contactEndIndex:candidate.contactEndIndex,
    responseWindowStartIndex:candidate.responseWindowStartIndex,
    postSupportHigh:candidate.postSupportHigh ? {
      index:candidate.postSupportHigh.index,
      timestamp:timestampFor(candidate.postSupportHigh.candle),
      value:candidate.postSupportHigh.high
    } : null,
    responseDetected:candidate.responseDetected === true,
    responseThreshold:candidate.responseThreshold,
    responseCandleCount:candidate.responseCandleCount,
    qualifyingResponseIndexes:candidate.qualifyingResponseIndexes,
    selectionReason:candidate.selectionReason
  } : null;
  // Episodes are newest-first. The first with a real response is the current
  // rebound episode; a newer unresponsive revisit cannot replace its origin.
  const selected = candidates.find(candidate => candidate.responseDetected);
  const latestEpisode = projectEpisode(candidates[0]);
  if(!selected) return {
    historyOrdering:'newest_first',
    supportEpisodeMaSource,
    historicalInferenceSkipped:supportEpisodeMaSource === 'unavailable',
    supportEvent:null,
    postSupportHigh:null,
    selectionReason:'unresolved: no qualifying support episode',
    laterRevisits:[],
    latestEpisode
  };
  const selectedEpisode = projectEpisode(selected);
  return {
    historyOrdering:'newest_first',
    supportEpisodeMaSource,
    historicalInferenceSkipped:false,
    supportEvent:selectedEpisode.supportEvent,
    contactStartIndex:selectedEpisode.contactStartIndex,
    contactEndIndex:selectedEpisode.contactEndIndex,
    responseWindowStartIndex:selectedEpisode.responseWindowStartIndex,
    qualifyingResponseIndexes:selectedEpisode.qualifyingResponseIndexes,
    postSupportHigh:selectedEpisode.postSupportHigh,
    selectionReason:selected.selectionReason,
    laterRevisits:candidates
      .filter(candidate => candidate.supportEvent.index < selected.supportEvent.index)
      .map(candidate => ({
        id:candidate.id,
        index:candidate.supportEvent.index,
        timestamp:timestampFor(candidate.supportEvent.candle),
        price:candidate.supportEvent.price,
        reason:candidate.selectionReason
      })),
    latestEpisode
  };
}

function chartGuruPostSupportHigh(context = {}, supportReferenceLevel = null){
  const episode = chartGuruSupportEpisodeFromHistory(context, supportReferenceLevel);
  return numericOrNull(episode && episode.postSupportHigh && episode.postSupportHigh.value);
}

function buildCanonicalChartStoryContext(context = {}){
  const supportType = chartGuruResolvedSupportType(context);
  const supportContext = String(context.supportContext || '').trim().toLowerCase();
  const supportLabel = supportType === '20ma'
    ? '20-day average'
    : (supportType === '50ma' ? '50-day average' : 'support');
  const supportReferenceLevel = chartGuruSupportReferenceLevel(context, supportType);
  const supportDistancePct = chartGuruSupportDistancePct(context, supportType);
  const supportDistanceMeasured = Number.isFinite(supportDistancePct);
  const currentPrice = numericOrNull(context.currentPrice);
  const supportDistanceThresholdPct = supportType === '50ma' ? 0.03 : 0.025;
  const materiallyAwayFromSupport = supportDistanceMeasured && supportDistancePct > supportDistanceThresholdPct;
  const currentExtensionPct = Number.isFinite(currentPrice) && Number.isFinite(supportReferenceLevel) && supportReferenceLevel !== 0
    ? (currentPrice - supportReferenceLevel) / Math.abs(supportReferenceLevel)
    : null;
  const recentHighs = (Array.isArray(context.recentSequence) ? context.recentSequence : [])
    .map(candle => numericOrNull(candle && candle.high))
    .filter(Number.isFinite);
  const recentHigh = recentHighs.length ? Math.max(...recentHighs) : null;
  const supportEpisode = chartGuruSupportEpisodeFromHistory(context, supportReferenceLevel);
  const historyPostSupportHigh = numericOrNull(supportEpisode && supportEpisode.postSupportHigh && supportEpisode.postSupportHigh.value);
  const historyWasProvided = Array.isArray(context.historySequence) && context.historySequence.length > 0;
  const explicitPostSupportHigh = numericOrNull(context.postSupportHigh ?? context.maximumPriceSinceSupport ?? context.maximumExtensionPrice);
  const supportEpisodeEstablished = !!(
    supportEpisode
    && supportEpisode.supportEvent
    && Number.isFinite(historyPostSupportHigh)
  );
  // A generic recent maximum is chart context, not support chronology. Extension
  // and retracement calculations require either the selected episode's measured
  // high or a trusted explicit post-support high from the canonical pipeline.
  const postSupportHighSource = Number.isFinite(explicitPostSupportHigh)
    ? 'explicit_post_support_high'
    : (supportEpisodeEstablished ? 'validated_support_episode' : 'unavailable');
  const anchoredPostSupportHigh = postSupportHighSource === 'explicit_post_support_high'
    ? explicitPostSupportHigh
    : (postSupportHighSource === 'validated_support_episode' ? historyPostSupportHigh : null);
  const postSupportHigh = anchoredPostSupportHigh;
  const maximumExtensionPct = Number.isFinite(anchoredPostSupportHigh) && Number.isFinite(supportReferenceLevel) && supportReferenceLevel !== 0
    ? (anchoredPostSupportHigh - supportReferenceLevel) / Math.abs(supportReferenceLevel)
    : null;
  const retracementAvailable = Number.isFinite(anchoredPostSupportHigh)
    && Number.isFinite(currentPrice)
    && Number.isFinite(supportReferenceLevel)
    && anchoredPostSupportHigh > supportReferenceLevel;
  const retracementUnavailableReason = retracementAvailable
    ? ''
    : (!Number.isFinite(anchoredPostSupportHigh)
      ? (supportEpisode && supportEpisode.historicalInferenceSkipped
        ? 'insufficient contemporaneous MA history and no explicit post-support high'
        : (historyWasProvided ? 'no validated support episode or explicit post-support high' : 'no validated support episode or explicit post-support high'))
      : (!Number.isFinite(currentPrice) ? 'current price unavailable' : (!Number.isFinite(supportReferenceLevel) ? 'support reference unavailable' : 'anchored post-support high is not above support')));
  const retracementFromPostSupportHighPct = retracementAvailable
    ? Math.max(0, (anchoredPostSupportHigh - currentPrice) / (anchoredPostSupportHigh - supportReferenceLevel))
    : null;
  const historicalExtensionObserved = Number.isFinite(maximumExtensionPct) && maximumExtensionPct >= 0.035;
  // Historical scanner location is chronology. A material retracement means the
  // current phase must be derived from today's price and candle evidence instead.
  const extensionMateriallyRetraced = historicalExtensionObserved
    && Number.isFinite(retracementFromPostSupportHighPct)
    && retracementFromPostSupportHighPct >= 0.5;
  const latestSupportEpisode = supportEpisode && supportEpisode.latestEpisode && typeof supportEpisode.latestEpisode === 'object'
    ? supportEpisode.latestEpisode
    : null;
  const historicalResponseFromLatestEpisode = !!(
    latestSupportEpisode
    && latestSupportEpisode.responseDetected === true
    && supportEpisode
    && supportEpisode.supportEvent
    && latestSupportEpisode.supportEvent
    && latestSupportEpisode.supportEvent.id === supportEpisode.supportEvent.id
  );
  const explicitBuyerResponsePresent = chartGuruBuyerResponsePresent(context);
  let buyerResponsePresent = explicitBuyerResponsePresent;
  let buyerResponseSource = explicitBuyerResponsePresent ? 'explicit_current_evidence' : 'none';
  let buyerResponseValidity = explicitBuyerResponsePresent ? 'explicit_current_evidence' : 'not_observed';
  let buyerResponseInvalidationReason = '';
  const buyerControlState = String(context.buyerControlState || '').trim().toLowerCase();
  const supportTestState = String(context.supportTestState || '').trim().toLowerCase();
  const recentSupportResponsePresent = chartGuruRecentSupportResponsePresent(context);
  const terminalCurrentFailure = context.structureBroken === true || context.failedBounce === true || supportTestState === 'failed';
  const confirmedContinuationEvidence = !!(
    context.followThroughConfirmed === true
    || (
      recentSupportResponsePresent
      && supportDistanceMeasured
      && supportDistancePct >= 0.035
      && (
        Number(context.candleEvidenceUpClosesAfterLow) >= 2
        || (
          context.candleEvidenceReclaimedPriorDayHigh === true
          && context.candleEvidenceHigherLowHold === true
        )
        || context.candleEvidenceReclaimRangeMeaningful === true
      )
    )
  );
  const supportContextRecognized = !!(
    supportType
    || (supportContext && supportContext !== 'none')
  );
  const supportInteraction = (() => {
    if(supportTestState === 'failed') return 'failed';
    if(supportTestState === 'held') return 'held';
    if(confirmedContinuationEvidence) return 'held';
    if(supportTestState === 'testing') return 'testing';
    if(context.failedBounce === true || context.structureBroken === true) return 'failed';
    if(!supportContextRecognized) return 'not_tested';
    if(recentSupportResponsePresent) return 'held';
    if(
      context.pullbackNear20 === true
      || context.pullbackNear50 === true
      || context.near20 === 'near'
      || context.near50 === 'near'
      // The exact proximity hint is deliberately tighter than the active
      // support band. A measured price inside that wider, established band is
      // still a live support context, not an away-from-support state.
      || (supportDistanceMeasured && !materiallyAwayFromSupport)
      || buyerResponsePresent
    ) return 'testing';
    if(supportTestState === 'not_tested') return 'not_tested';
    return 'not_tested';
  })();
  const supportCurrentlyActive = !!(
    supportContextRecognized
    && !context.recentlyLeftSupportZone
    && !context.offLevelWithoutStructureDamage
    // A legacy extension label describes prior location. When today's price can
    // be measured back inside the active-support threshold, current location
    // must win; keep the legacy guard only for callers without a measurement.
    && (!context.extendedAfterRun || (supportDistanceMeasured && !materiallyAwayFromSupport))
    && !materiallyAwayFromSupport
    && ['testing', 'held'].includes(supportInteraction)
  );
  const episodeResponseThreshold = numericOrNull(latestSupportEpisode && latestSupportEpisode.responseThreshold);
  const episodeResponsePriceValid = Number.isFinite(currentPrice)
    && Number.isFinite(episodeResponseThreshold)
    && currentPrice >= episodeResponseThreshold;
  const episodeResponseCurrentValid = historicalResponseFromLatestEpisode
    && episodeResponsePriceValid
    && supportCurrentlyActive
    && supportTestState !== 'failed'
    && context.failedBounce !== true
    && context.structureBroken !== true;
  if(episodeResponseCurrentValid){
    buyerResponsePresent = true;
    buyerResponseSource = 'latest_support_episode_history';
    buyerResponseValidity = 'current_valid';
  }else if(historicalResponseFromLatestEpisode && !explicitBuyerResponsePresent){
    buyerResponseValidity = 'chronology_only';
    buyerResponseInvalidationReason = !episodeResponsePriceValid
      ? 'current_price_below_episode_response_threshold'
      : (!supportCurrentlyActive ? 'support_not_currently_active' : (supportTestState === 'failed' || context.failedBounce === true || context.structureBroken === true ? 'terminal_support_or_structure_failure' : 'response_not_current'));
  }
  const extensionEvidencePresent = !!(
    Number.isFinite(currentExtensionPct)
    && currentExtensionPct >= 0.035
    && !extensionMateriallyRetraced
    && recentSupportResponsePresent
    && (
      confirmedContinuationEvidence
      || context.candleEvidenceReclaimedPriorDayHigh === true
      || context.candleEvidenceReclaimRangeMeaningful === true
      || Number(context.candleEvidenceUpClosesAfterLow) >= 2
    )
  );
  const reboundExtended = !!(
    supportContextRecognized
    && !supportCurrentlyActive
    && !context.failedBounce
    && context.structureIntact === true
    && (
      extensionEvidencePresent
      // Only use a legacy extension label when no current price can resolve it.
      || (context.extendedAfterRun === true && !supportDistanceMeasured)
    )
  );
  const reboundStalled = !!(
    supportContextRecognized
    && !supportCurrentlyActive
    && !reboundExtended
    && !context.failedBounce
    && context.structureIntact === true
    && buyerResponsePresent
    && (
      buyerControlState !== 'confirmed'
      || context.latestDirection === 'flat'
      || context.bodyDescriptor === 'small'
      || context.latestWickRejection === 'upper_rejection'
      || context.lowerClose === true
      || context.weakVolume === true
    )
  );
  // Canonical buyer control is explicit state first. Candle evidence can fill a
  // missing value, but must not silently promote an explicitly developing state.
  const buyerControlSemantic = terminalCurrentFailure
    ? 'failed'
    : (buyerControlState === 'confirmed'
    ? 'confirmed'
    : (['emerging', 'developing'].includes(buyerControlState)
      ? 'emerging'
      : (confirmedContinuationEvidence ? 'confirmed' : (buyerResponsePresent ? 'emerging' : 'none'))));
  const volumeState = String(context.volumeParticipation || chartGuruVolumeParticipationLabel(context) || '').trim().toLowerCase() || 'constructive';
  const pullbackQuality = context.failedBounce === true
    || context.structureBroken === true
    || context.structureWeakening === true
    ? 'damaging'
    : (chartGuruControlledPullbackPresent(context) ? 'controlled' : 'unknown');
  const supportEvents = [];
  if(context.structureIntact === true && context.structureBroken !== true) supportEvents.push('trend_remained_intact');
  else if(context.structureBroken === true) supportEvents.push('trend_broke_down');
  if(supportType === '20ma') supportEvents.push('price_approached_20ma_support');
  else if(supportType === '50ma') supportEvents.push('price_approached_50ma_support');
  if(['testing', 'held', 'failed'].includes(supportInteraction)){
    supportEvents.push(
      supportType === '20ma'
        ? `support_${supportInteraction}_at_20ma`
        : (supportType === '50ma'
          ? `support_${supportInteraction}_at_50ma`
          : `support_${supportInteraction}`)
    );
  }
  if(buyerResponsePresent) supportEvents.push('buyers_responded');
  if(buyerControlSemantic === 'emerging') supportEvents.push('buyer_control_emerging');
  if(buyerControlSemantic === 'confirmed') supportEvents.push('buyer_control_confirmed');
  if(historicalExtensionObserved) supportEvents.push('historical_rebound_extended');
  if(reboundExtended) supportEvents.push('rebound_extended');
  if(reboundStalled) supportEvents.push('rebound_stalled');
  if(context.failedBounce === true) supportEvents.push('failed_bounce');
  const storyEvents = [...new Set(supportEvents.filter(Boolean))];
  const supportSemantic = (() => {
    if(!supportContextRecognized) return 'support_unknown';
    if(supportInteraction === 'failed' || context.failedBounce === true || context.structureBroken === true) return 'support_failed';
    if(supportCurrentlyActive) return 'support_present';
    if(reboundExtended && supportDistanceMeasured) return 'support_absent';
    if(!supportDistanceMeasured) return 'support_unknown';
    return materiallyAwayFromSupport ? 'support_absent' : 'support_unknown';
  })();
  const buyerResponseSemantic = (() => {
    if(context.failedBounce === true && !buyerResponsePresent) return 'response_failed';
    if(context.structureBroken === true && !buyerResponsePresent) return 'response_failed';
    if(buyerResponsePresent) return 'response_present';
    if(supportInteraction === 'failed') return 'response_failed';
    if(supportContextRecognized) return 'response_absent';
    return 'response_unknown';
  })();
  const confirmationSemantic = (() => {
    if(terminalCurrentFailure) return 'follow_through_failed';
    if(reboundStalled) return 'follow_through_stalled';
    if(confirmedContinuationEvidence) return 'follow_through_confirmed';
    if(context.failedBounce === true) return 'follow_through_failed';
    if(supportInteraction === 'failed' && !buyerResponsePresent) return 'follow_through_failed';
    if(buyerControlSemantic === 'confirmed') return 'follow_through_developing';
    if(buyerResponsePresent) return 'follow_through_not_started';
    return 'follow_through_unknown';
  })();
  const deterministicCurrentPhase = context.failedBounce === true || supportInteraction === 'failed'
    ? 'support_failed'
    : (reboundExtended
      ? 'extended_from_support'
      : (reboundStalled
        ? 'stalled_after_response'
        : (supportCurrentlyActive
          ? (buyerResponsePresent ? 'responding_from_support' : 'at_support')
          : (!supportDistanceMeasured && supportContextRecognized
            ? 'current_location_unresolved'
            : (context.structureIntact === true ? 'away_from_support' : 'repairing_structure')))));
  const validatedExplicitPhase = chartGuruValidatedCanonicalPhase(context.authoritativeCurrentPhase, {
    supportInteraction,
    supportCurrentlyActive,
    buyerResponsePresent,
    buyerControlState,
    reboundStalled
  });
  const explicitPhaseSupersededByRetracement = validatedExplicitPhase === 'extended_from_support'
    && extensionMateriallyRetraced;
  const retracementPhaseOverrideApplied = explicitPhaseSupersededByRetracement;
  const currentPhase = explicitPhaseSupersededByRetracement
    ? deterministicCurrentPhase
    : (validatedExplicitPhase || deterministicCurrentPhase);
  const dominantEvent = context.failedBounce === true || supportInteraction === 'failed'
    ? 'support_failed'
    : (context.structureBroken === true
      ? 'structure_breaking_down'
      : (reboundStalled
        ? 'rebound_stalled'
        : (reboundExtended
          ? 'rebound_extended'
          : (buyerControlSemantic === 'confirmed'
            ? 'buyer_control_confirmed'
            : (buyerResponsePresent
              ? 'buyers_responded'
              : (supportInteraction === 'testing'
                ? 'support_testing'
                : (supportInteraction === 'held' ? 'support_held' : 'trend_remained_intact')))))));
  const dominantStory = dominantEvent === 'support_failed'
    ? (context.structureBroken === true ? 'structure_breaking_down' : 'failed_support_test')
    : (dominantEvent === 'structure_breaking_down'
      ? 'structure_breaking_down'
      : (dominantEvent === 'rebound_stalled'
        ? 'stalled_after_support_response'
        : (dominantEvent === 'rebound_extended'
          ? 'extended_after_support_rebound'
          : (dominantEvent === 'buyer_control_confirmed'
            ? 'confirmed_support_rebound'
            : (dominantEvent === 'buyers_responded'
              ? 'initial_support_response'
              : (supportInteraction === 'testing'
                ? 'support_test_in_progress'
                : (supportInteraction === 'held' ? 'support_held_without_follow_through' : 'healthy_trend')))))));
  const supportRelationship = supportInteraction === 'failed'
    ? 'failed'
    : (reboundExtended
      ? 'extended_above'
      : (reboundStalled
        ? 'response_stalled'
        : (supportCurrentlyActive
          ? supportInteraction
          : (!supportDistanceMeasured && supportContextRecognized
            ? 'away_unresolved'
            : (materiallyAwayFromSupport ? 'away_from_support' : 'unknown')))));
  const support = {
    level:supportType ? `${supportType}_support` : (supportContext || 'none'),
    label:supportLabel,
    type:supportType || '',
    referenceLevel:supportReferenceLevel,
    relationship:supportRelationship,
    interaction:supportInteraction,
    currentlyActive:supportCurrentlyActive,
    recentlyTested:['testing', 'held', 'failed'].includes(supportInteraction),
    testOutcome:supportInteraction || 'not_tested',
    distanceFromSupportPct:supportDistancePct,
    distancePct:supportDistancePct,
    distanceMeasured:supportDistanceMeasured,
    semantic:supportSemantic
  };
  return {
    ...context,
    version:'chart-story-v1',
    dominantStory,
    dominantEvent,
    currentPhase,
    structure:{
      state:context.structureBroken === true ? 'broken' : (context.structureWeakening === true ? 'weakening' : (context.structureIntact === true ? 'intact' : 'unknown'))
    },
    support,
    pullback:{
      occurred:!!(context.pullbackNear20 === true || context.pullbackNear50 === true || supportContextRecognized),
      quality:pullbackQuality
    },
    buyerResponse:{
      state:buyerResponsePresent ? 'present' : (supportInteraction === 'failed' ? 'failed' : (supportContextRecognized ? 'absent' : 'unknown')),
      semantic:buyerResponseSemantic,
      source:buyerResponseSource,
      validity:buyerResponseValidity,
      invalidationReason:buyerResponseInvalidationReason
    },
    buyerControl:{
      state:buyerControlSemantic
    },
    followThrough:{
      state:confirmationSemantic === 'follow_through_confirmed'
        ? 'confirmed'
        : (confirmationSemantic === 'follow_through_failed'
          ? 'failed'
          : (confirmationSemantic === 'follow_through_developing'
            ? 'developing'
            : (confirmationSemantic === 'follow_through_not_started' ? 'not_started' : (reboundStalled ? 'stalled' : 'unknown'))))
    },
    confirmation:{
      state:confirmationSemantic === 'follow_through_confirmed'
        ? 'confirmed'
        : (confirmationSemantic === 'follow_through_failed'
          ? 'failed'
          : (confirmationSemantic === 'follow_through_developing' ? 'developing' : (confirmationSemantic === 'follow_through_not_started' ? 'not_started' : 'unknown'))),
      semantic:confirmationSemantic
    },
    sellerPressure:{
      state:context.structureBroken === true || context.failedBounce === true || String(context.latestDirection || '').trim() === 'red'
        ? 'active'
        : (String(context.latestDirection || '').trim() === 'green' ? 'normal' : 'unknown')
    },
    volume:{
      state:volumeState || 'unknown'
    },
    storyEvents,
    nextChartNeed:dominantEvent === 'support_failed' || dominantEvent === 'structure_breaking_down'
      ? 'repair'
      : (reboundExtended
        ? 'pullback_or_reset'
        : (reboundStalled || buyerResponsePresent ? 'follow_through' : (supportCurrentlyActive ? 'support_hold' : 'none'))),
    evidenceQuality:{
      supportKnown:supportContextRecognized,
      distanceKnown:supportDistanceMeasured,
      candleOrderNormalized:true,
      currentLocationKnown:supportDistanceMeasured
    },
    diagnostics:{
      resolvedSupportType:supportType || '',
      supportReferenceLevel,
      supportDistanceThresholdPct:Number.isFinite(supportDistanceThresholdPct) ? supportDistanceThresholdPct : null,
      latestDirection:String(context.latestDirection || '').trim(),
      bodyDescriptor:String(context.bodyDescriptor || '').trim(),
      recentIndecision:context.bodyDescriptor === 'small' || context.latestDirection === 'flat',
      extensionEvidencePresent,
      reboundExtended,
      reboundStalled,
      phaseDecision:{
        currentPrice,
        movingAverages:{
          ma20:numericOrNull(context.ma20),
          ma50:numericOrNull(context.ma50),
          ma200:numericOrNull(context.ma200),
          distancePct:{
            ma20:Number.isFinite(currentPrice) && Number.isFinite(numericOrNull(context.ma20)) && numericOrNull(context.ma20) !== 0 ? (currentPrice - numericOrNull(context.ma20)) / Math.abs(numericOrNull(context.ma20)) : null,
            ma50:Number.isFinite(currentPrice) && Number.isFinite(numericOrNull(context.ma50)) && numericOrNull(context.ma50) !== 0 ? (currentPrice - numericOrNull(context.ma50)) / Math.abs(numericOrNull(context.ma50)) : null,
            ma200:Number.isFinite(currentPrice) && Number.isFinite(numericOrNull(context.ma200)) && numericOrNull(context.ma200) !== 0 ? (currentPrice - numericOrNull(context.ma200)) / Math.abs(numericOrNull(context.ma200)) : null
          }
        },
        activeSupport:{
          type:supportType || null,
          label:supportType ? supportLabel : null,
          source:String(context.activeSupportAuthoritySource || 'deterministic_derivation'),
          interaction:supportInteraction || null,
          interactionSource:String(context.supportInteractionAuthoritySource || 'deterministic_derivation'),
          currentlyActive:supportCurrentlyActive
        },
        rawPhase:String(context.authoritativeCurrentPhase || '') || null,
        rawPhaseSource:String(context.phaseAuthoritySource || 'deterministic_derivation'),
        finalPhase:currentPhase,
        phaseSource:explicitPhaseSupersededByRetracement ? 'deterministic_derivation_after_retracement' : (validatedExplicitPhase ? String(context.phaseAuthoritySource || 'explicit_canonical') : 'deterministic_derivation'),
        dominantEvent,
        dominantEventSource:'deterministic_derivation',
        buyerResponse:buyerResponsePresent ? 'present' : 'none',
        buyerResponseSource,
        buyerResponseValidity,
        buyerResponseInvalidationReason,
        buyerControl:buyerControlSemantic,
        followThrough:confirmationSemantic.replace('follow_through_', ''),
        nextRequiredEvent:reboundExtended ? 'pullback_or_reset' : (reboundStalled || buyerResponsePresent ? 'follow_through' : (supportCurrentlyActive ? 'support_hold' : 'none')),
        recentHigh,
        anchoredPostSupportHigh,
        postSupportHigh,
        postSupportHighSource,
        supportEpisodeEstablished,
        postSupportHighDetails:postSupportHighSource === 'validated_support_episode' && supportEpisode && supportEpisode.postSupportHigh ? supportEpisode.postSupportHigh : null,
        supportEvent:supportEpisode && supportEpisode.supportEvent ? supportEpisode.supportEvent : null,
        supportEpisodeId:supportEpisode && supportEpisode.supportEvent ? supportEpisode.supportEvent.id : null,
        supportEventSelectionReason:supportEpisode && supportEpisode.selectionReason ? supportEpisode.selectionReason : (historyWasProvided ? 'unresolved: no qualifying support episode' : 'unavailable: history not supplied'),
        latestSupportEpisode,
        supportEpisodeMaSource:supportEpisode && supportEpisode.supportEpisodeMaSource ? supportEpisode.supportEpisodeMaSource : 'unavailable',
        historicalEpisodeInferenceSkipped:!!(supportEpisode && supportEpisode.historicalInferenceSkipped),
        supportEventMaValue:supportEpisode && supportEpisode.supportEvent ? supportEpisode.supportEvent.maValue : null,
        supportEventDistancePct:supportEpisode && supportEpisode.supportEvent ? supportEpisode.supportEvent.distancePct : null,
        episodeResponseThreshold,
        currentPriceVsEpisodeResponseThreshold:Number.isFinite(currentPrice) && Number.isFinite(episodeResponseThreshold) ? currentPrice - episodeResponseThreshold : null,
        historyOrdering:supportEpisode && supportEpisode.historyOrdering ? supportEpisode.historyOrdering : (historyWasProvided ? 'newest_first_unresolved' : 'unavailable'),
        laterSupportRevisits:supportEpisode && Array.isArray(supportEpisode.laterRevisits) ? supportEpisode.laterRevisits : [],
        maximumExtensionPct,
        currentExtensionPct,
        retracementFromPostSupportHighPct,
        retracementAvailable,
        retracementUnavailableReason,
        retracementPhaseOverrideApplied,
        historicalExtensionObserved,
        extensionMateriallyRetraced,
        historicalEventsUsed:context.historicalExtendedAfterRun === true || historicalExtensionObserved,
        imageEvidenceInfluenced:Array.isArray(context.recentSequence) && context.recentSequence.length > 0,
        volumeEvidenceInfluenced:context.weakVolume === true || context.activeVolume === true,
        resolutionOrder:'explicit canonical → canonical phase projection → deterministic derivation → legacy',
        candidates:[
          {phase:'extended_from_support', accepted:reboundExtended, reason:extensionMateriallyRetraced ? 'rejected: material retracement from post-support high' : (extensionEvidencePresent ? 'accepted: current extension remains material' : 'rejected: no current extension evidence')},
          {phase:'stalled_after_response', accepted:reboundStalled, reason:reboundStalled ? 'accepted: buyers responded and follow-through stalled after leaving support' : 'rejected: stalled-response evidence incomplete'},
          {phase:'responding_from_support', accepted:deterministicCurrentPhase === 'responding_from_support', reason:supportCurrentlyActive ? 'accepted when support is currently active and buyers responded' : 'rejected: support is not currently active'},
          {phase:'at_support', accepted:deterministicCurrentPhase === 'at_support', reason:supportCurrentlyActive ? 'accepted when support is currently active without buyer response' : 'rejected: support is not currently active'}
        ]
      }
    },
    reboundExtended,
    reboundStalled,
    extensionEvidencePresent
  };
}

function chartGuruNarrativeContext(context = {}){
  const storyContext = buildCanonicalChartStoryContext(context);
  return {
    support:{
      level:String(storyContext.support && storyContext.support.level || '').trim(),
      label:String(storyContext.support && storyContext.support.label || '').trim(),
      interaction:String(storyContext.support && storyContext.support.interaction || '').trim(),
      currentlyActive:storyContext.support && storyContext.support.currentlyActive === true,
      distanceFromSupportPct:Number.isFinite(storyContext.support && storyContext.support.distanceFromSupportPct)
        ? Number(storyContext.support.distanceFromSupportPct)
        : null,
      distanceMeasured:storyContext.support && storyContext.support.distanceMeasured === true,
      semantic:String(storyContext.support && storyContext.support.semantic || '').trim()
    },
    buyerResponse:{
      state:String(storyContext.buyerResponse && storyContext.buyerResponse.state || '').trim(),
      semantic:String(storyContext.buyerResponse && storyContext.buyerResponse.semantic || '').trim()
    },
    buyerControl:{
      state:String(storyContext.buyerControl && storyContext.buyerControl.state || '').trim()
    },
    confirmation:{
      semantic:String(storyContext.confirmation && storyContext.confirmation.semantic || '').trim()
    },
    currentState:{
      phase:String(storyContext.currentPhase || '').trim()
    },
    storyEvents:Array.isArray(storyContext.storyEvents) ? storyContext.storyEvents.slice() : [],
    reboundExtended:storyContext.reboundExtended === true,
    reboundStalled:storyContext.reboundStalled === true,
    extensionEvidencePresent:storyContext.extensionEvidencePresent === true
  };
}

function chartGuruSemanticEnvelopeFromStory(storyKey = '', context = {}){
  const normalizedKey = String(storyKey || '').trim().toLowerCase();
  const narrativeContext = chartGuruNarrativeContext(context);
  const buyerResponsePresent = chartGuruBuyerResponsePresent(context);
  const narrativeEnvelope = chartGuruSemanticEnvelopeFromNarrativeContext(narrativeContext);
  const keyCompatibilityEnvelope = chartGuruSemanticEnvelopeCompatibilityForStoryKey(normalizedKey) || {};
  const supportSemantic = (() => {
    if(narrativeEnvelope.supportSemantic && narrativeEnvelope.supportSemantic !== 'support_unknown') return narrativeEnvelope.supportSemantic;
    if(keyCompatibilityEnvelope.supportSemantic) return keyCompatibilityEnvelope.supportSemantic;
    if(['early_rebound_from_20ma', 'constructive_pullback_near_20ma', 'constructive_pullback_near_50ma', 'bounce_confirmation_pending'].includes(normalizedKey)){
      return 'support_present';
    }
    if(['off_level_wait_for_clearer_support', 'extended_after_run'].includes(normalizedKey)) return 'support_absent';
    if(['bounce_attempt', 'long_lower_wick_support_test'].includes(normalizedKey)) return 'support_reclaimed';
    if(context.pullbackNear20 === true || context.pullbackNear50 === true) return 'support_present';
    if(context.recentlyLeftSupportZone === true) return 'support_absent';
    return 'support_unknown';
  })();
  const buyerResponseSemantic = (() => {
    if(narrativeEnvelope.buyerResponseSemantic && narrativeEnvelope.buyerResponseSemantic !== 'response_unknown') return narrativeEnvelope.buyerResponseSemantic;
    if(keyCompatibilityEnvelope.buyerResponseSemantic) return keyCompatibilityEnvelope.buyerResponseSemantic;
    if(buyerResponsePresent) return 'response_present';
    if(['early_rebound_from_20ma', 'bounce_confirmation_pending', 'bounce_attempt'].includes(normalizedKey)) return 'response_present';
    if(['structure_breaking_down', 'sharp_selloff'].includes(normalizedKey)) return 'response_failed';
    if(['off_level_wait_for_clearer_support', 'extended_after_run'].includes(normalizedKey)) return 'response_absent';
    return 'response_unknown';
  })();
  const confirmationSemantic = (() => {
    if(narrativeEnvelope.confirmationSemantic && narrativeEnvelope.confirmationSemantic !== 'follow_through_unknown') return narrativeEnvelope.confirmationSemantic;
    if(keyCompatibilityEnvelope.confirmationSemantic) return keyCompatibilityEnvelope.confirmationSemantic;
    if(context.followThroughConfirmed === true || narrativeContext.buyerControl.state === 'confirmed' || normalizedKey === 'bounce_confirmation_pending') return 'follow_through_confirmed';
    if(['early_rebound_from_20ma', 'bounce_attempt'].includes(normalizedKey)) return 'follow_through_unconfirmed';
    if(context.failedBounce === true || normalizedKey === 'failed_bounce') return 'follow_through_failed';
    if(['structure_breaking_down', 'sharp_selloff'].includes(normalizedKey) && !buyerResponsePresent) return 'follow_through_failed';
    if(buyerResponseSemantic === 'response_present') return 'follow_through_unconfirmed';
    return 'follow_through_unknown';
  })();
  return {
    supportSemantic,
    buyerResponseSemantic,
    confirmationSemantic
  };
}

function chartNarratorTrendLabel(context = {}){
  if(context.structureBroken === true) return 'broken';
  if(context.structureWeakening === true) return 'weak';
  return 'healthy';
}

function chartNarratorBiasForStory(storyKey = '', context = {}){
  if(storyKey === 'structure_breaking_down' || storyKey === 'sharp_selloff' || storyKey === 'failed_bounce') return 'bad';
  if(storyKey === 'pullback_still_repairing' || storyKey === 'off_level_wait_for_clearer_support' || storyKey === 'doji_indecision') return 'neutral';
  if(context.structureBroken === true) return 'bad';
  if(context.structureWeakening === true) return 'neutral';
  return 'good';
}

function chartNarratorToneModeForStorySteps(steps = []){
  const set = new Set((Array.isArray(steps) ? steps : []).map(step => String(step || '').trim()).filter(Boolean));
  if(set.has('broken_structure') || set.has('avoid') || set.has('support_lost') || set.has('failed_bounce')) return 'broken_avoid';
  if(set.has('weak_structure') || set.has('repair_needed') || set.has('support_not_reclaimed')) return 'damaged_repairing';
  if(set.has('off_level') || set.has('wait_for_clearer_support') || set.has('pause') || set.has('direction_unclear')) return 'neutral_off_level';
  if(set.has('buyer_response') || set.has('buyers_in_control')) return 'constructive_buyer_response';
  if(set.has('support_test') || set.has('early_support_defense')) return 'cautious_support_test';
  return 'constructive_buyer_response';
}

function chartNarratorConfidenceModeForStorySteps(steps = []){
  const set = new Set((Array.isArray(steps) ? steps : []).map(step => String(step || '').trim()).filter(Boolean));
  if(set.has('broken_structure') || set.has('avoid') || set.has('support_lost') || set.has('failed_bounce')) return 'avoid_until_rebuilt';
  if(set.has('repair_needed') || set.has('support_not_reclaimed')) return 'repair_first';
  if(set.has('off_level') || set.has('wait_for_clearer_support')) return 'wait_for_better_location';
  if(set.has('pause') || set.has('direction_unclear') || set.has('wait_for_clearer_move')) return 'wait_for_clarity';
  if(set.has('buyer_response')){
    return set.has('weak_volume') ? 'buyer_response_needs_volume_proof' : 'buyer_response_needs_follow_through';
  }
  if(set.has('support_test') || set.has('early_support_defense')){
    return set.has('weak_volume') ? 'support_test_needs_buyer_proof' : 'support_test_needs_proof';
  }
  return 'context_only';
}

function chartNarratorStepEvidenceFactIds(step = '', context = {}){
  const normalized = String(step || '').trim();
  const supportEvidence = () => {
    if(context.near20 === 'near' || context.pullbackNear20 === true) return ['support_short_term_average'];
    if(context.near50 === 'near' || context.pullbackNear50 === true) return ['support_medium_term_average'];
    return [];
  };
  const map = {
    strong_uptrend:['trend_context', 'price_accelerating_higher'],
    pullback_to_20ma:['support_short_term_average'],
    pullback_to_50ma:['support_medium_term_average'],
    buyer_response:[
      ...(context.bounceAttempt === true ? ['bounce_attempt'] : []),
      ...((context.bounceAttempt !== true && chartGuruBuyerResponsePresent(context)) ? ['buyer_response_state'] : []),
      ...(['early', 'clear', 'present'].includes(String(context.stabilisationState || '').trim().toLowerCase()) ? ['stabilisation_present'] : []),
      ...(context.latestWickRejection === 'lower_rejection' ? ['lower_rejection_wick'] : [])
    ],
    sellers_pushed_back:[
      ...(context.latestWickRejection === 'upper_rejection' ? ['upper_rejection_wick', 'resistance_rejection'] : [])
    ],
    weak_volume:['low_volume'],
    volume_supports_move:['high_volume'],
    volume_not_a_problem:[],
    confirmation_needed:context.bounceAttempt === true ? ['bounce_attempt'] : [],
    support_still_unproven:supportEvidence(),
    intact_structure:['trend_context'],
    off_level:[],
    wait_for_clearer_support:[],
    weak_structure:['trend_context', 'weakness_signal'],
    support_not_reclaimed:supportEvidence(),
    repair_needed:['weakness_signal'],
    broken_structure:['trend_context', 'structure_broken'],
    failed_bounce:['failed_bounce'],
    support_lost:['weakness_signal'],
    avoid:[],
    buyers_in_control:['price_accelerating_higher'],
    volume_mixed:[],
    wait_for_calmer_pullback:['price_accelerating_higher'],
    weak_trend:['trend_context', 'price_accelerating_lower'],
    sellers_in_control:['price_accelerating_lower'],
    active_selling:['high_volume', 'price_accelerating_lower'],
    selling_pressure:['weakness_signal'],
    wait_for_damage_to_settle:['weakness_signal'],
    early_support_defense:supportEvidence(),
    extended_above_support:['price_accelerating_higher', 'extended_above_support'],
    wait_for_pullback:['extended_above_support'],
    support_test:supportEvidence(),
    buyers_pushed_back:[
      ...(context.latestWickRejection === 'lower_rejection' ? ['lower_rejection_wick'] : supportEvidence())
    ],
    follow_through_needed:context.latestWickRejection === 'upper_rejection'
      ? ['upper_rejection_wick', 'resistance_rejection']
      : (context.latestWickRejection === 'lower_rejection' ? ['lower_rejection_wick'] : []),
    resistance_test:[
      ...(context.latestWickRejection === 'upper_rejection' ? ['upper_rejection_wick', 'resistance_rejection'] : [])
    ],
    pause:['doji_or_small_body'],
    direction_unclear:['doji_or_small_body'],
    wait_for_clearer_move:['doji_or_small_body'],
    bounce_attempt:['bounce_attempt'],
    buyers_lost_control:['failed_bounce', 'weakness_signal'],
    weakness_still_active:['weakness_signal'],
    healthy_trend:['trend_context'],
    near_20ma:['support_short_term_average'],
    near_50ma:['support_medium_term_average'],
    support_context:[]
  };
  const evidence = Object.prototype.hasOwnProperty.call(map, normalized)
    ? map[normalized]
    : [];
  return [...new Set((Array.isArray(evidence) ? evidence : []).map(id => String(id || '').trim()).filter(Boolean))];
}

function chartNarratorStepDerivedSupport(step = '', context = {}, recentStory = null){
  const normalized = String(step || '').trim();
  const story = recentStory && typeof recentStory === 'object' ? recentStory : null;
  const hasStep = value => Array.isArray(story && story.steps) && story.steps.includes(String(value || '').trim());
  const supportZone = context.pullbackNear20 === true ? 'near_20ma' : (context.pullbackNear50 === true ? 'near_50ma' : 'support_context');
  const map = {
    confirmation_needed:{
      derivedFromSteps:hasStep('buyer_response') ? ['buyer_response'] : ['support_test'],
      derivedFromConditions:[context.bounceAttempt === true ? 'bounce_attempt_present' : 'bounce_attempt_absent', 'follow_through_missing']
    },
    support_still_unproven:{
      derivedFromSteps:['support_test'],
      derivedFromConditions:['buyer_response_absent', supportZone]
    },
    off_level:{
      derivedFromSteps:[],
      derivedFromConditions:['not_near_key_support']
    },
    follow_through_needed:{
      derivedFromSteps:[hasStep('buyers_pushed_back') ? 'buyers_pushed_back' : (hasStep('sellers_pushed_back') ? 'sellers_pushed_back' : '')].filter(Boolean),
      derivedFromConditions:['follow_through_missing']
    },
    wait_for_clearer_support:{
      derivedFromSteps:['off_level'],
      derivedFromConditions:['not_near_key_support']
    },
    avoid:{
      derivedFromSteps:[hasStep('broken_structure') ? 'broken_structure' : '', hasStep('support_lost') ? 'support_lost' : '', hasStep('failed_bounce') ? 'failed_bounce' : ''].filter(Boolean),
      derivedFromConditions:['negative_story_verdict']
    },
    wait_for_pullback:{
      derivedFromSteps:['extended_above_support'],
      derivedFromConditions:['price_extended_from_support']
    },
    wait_for_damage_to_settle:{
      derivedFromSteps:['weak_trend', hasStep('sellers_in_control') ? 'sellers_in_control' : 'selling_pressure'].filter(Boolean),
      derivedFromConditions:['damage_still_active']
    },
    wait_for_clearer_move:{
      derivedFromSteps:['pause', 'direction_unclear'],
      derivedFromConditions:['break_direction_unconfirmed']
    },
    repair_needed:{
      derivedFromSteps:[
        hasStep('support_lost') ? 'support_lost' : (hasStep('weak_structure') ? 'weak_structure' : ''),
        hasStep('buyer_response') ? 'buyer_response' : (hasStep('support_not_reclaimed') ? 'support_not_reclaimed' : '')
      ].filter(Boolean),
      derivedFromConditions:[hasStep('support_lost') ? 'support_failed' : 'structure_not_repaired']
    }
  };
  return Object.prototype.hasOwnProperty.call(map, normalized) ? map[normalized] : null;
}

function chartNarratorEvidenceForStorySteps(recentStory = null, steps = []){
  const story = recentStory && typeof recentStory === 'object' ? recentStory : null;
  const requested = Array.isArray(steps) ? steps.map(step => String(step || '').trim()).filter(Boolean) : [];
  const detailByKey = new Map(
    Array.isArray(story && story.stepDetails)
      ? story.stepDetails.map(detail => [String(detail && detail.key || '').trim(), Array.isArray(detail && detail.evidenceFactIds) ? detail.evidenceFactIds : []])
      : []
  );
  const evidence = requested.flatMap(step => detailByKey.get(step) || []);
  return [...new Set(evidence)].filter(Boolean);
}

function chartNarratorHasStep(recentStory = null, step = ''){
  const normalized = String(step || '').trim();
  if(!normalized) return false;
  return Array.isArray(recentStory && recentStory.steps) && recentStory.steps.includes(normalized);
}

function chartNarratorRecentStoryForPrimaryStory(primaryStory = {}, context = {}){
  const key = String(primaryStory && primaryStory.key || '').trim();
  const supportLabel = chartNarratorSupportLabel(context);
  const steps = [];
  if(key === 'early_rebound_from_20ma'){
    steps.push('strong_uptrend');
    steps.push('pullback_to_20ma');
    steps.push('buyer_response');
    steps.push(context.weakVolume === true ? 'weak_volume' : (context.activeVolume === true ? 'volume_supports_move' : 'volume_not_a_problem'));
    steps.push('confirmation_needed');
  }else if(key === 'constructive_pullback_near_20ma' || key === 'constructive_pullback_near_50ma'){
    steps.push('strong_uptrend');
    steps.push(key === 'constructive_pullback_near_20ma' ? 'pullback_to_20ma' : 'pullback_to_50ma');
    steps.push(context.bounceAttempt === true ? 'buyer_response' : 'support_test');
    if(context.latestWickRejection === 'upper_rejection') steps.push('sellers_pushed_back');
    steps.push(context.weakVolume === true ? 'weak_volume' : (context.activeVolume === true ? 'volume_supports_move' : 'volume_not_a_problem'));
    steps.push(context.bounceAttempt === true ? 'confirmation_needed' : 'support_still_unproven');
  }else if(key === 'off_level_wait_for_clearer_support'){
    steps.push('intact_structure', 'off_level', 'wait_for_clearer_support');
  }else if(key === 'pullback_still_repairing'){
    steps.push('weak_structure', 'support_not_reclaimed', 'repair_needed');
  }else if(key === 'structure_breaking_down'){
    steps.push('broken_structure');
    steps.push(context.failedBounce === true ? 'failed_bounce' : 'support_lost');
    if(chartGuruBuyerResponsePresent(context)) steps.push('buyer_response', 'repair_needed');
    steps.push('avoid');
  }else if(key === 'strong_upside_acceleration'){
    steps.push('strong_uptrend', 'buyers_in_control', context.activeVolume === true ? 'volume_supports_move' : 'volume_mixed', 'wait_for_calmer_pullback');
  }else if(key === 'sharp_selloff'){
    steps.push('weak_trend', 'sellers_in_control', context.activeVolume === true ? 'active_selling' : 'selling_pressure', 'wait_for_damage_to_settle');
  }else if(key === 'bounce_confirmation_pending'){
    steps.push('intact_structure');
    steps.push(context.pullbackNear20 === true ? 'pullback_to_20ma' : (context.pullbackNear50 === true ? 'pullback_to_50ma' : 'support_test'));
    steps.push(context.bounceAttempt === true ? 'buyer_response' : 'early_support_defense');
    steps.push('confirmation_needed');
  }else if(key === 'extended_after_run'){
    steps.push('strong_uptrend', 'extended_above_support', 'wait_for_pullback');
  }else if(key === 'long_lower_wick_support_test'){
    steps.push('support_test', 'buyers_pushed_back', 'follow_through_needed');
  }else if(key === 'long_upper_wick_rejection'){
    steps.push('resistance_test', 'sellers_pushed_back', 'follow_through_needed');
  }else if(key === 'doji_indecision'){
    steps.push('pause', 'direction_unclear', 'wait_for_clearer_move');
  }else if(key === 'failed_bounce'){
    steps.push('bounce_attempt', 'buyers_lost_control', 'weakness_still_active');
  }else if(key === 'bounce_attempt'){
    steps.push('support_test', 'buyer_response', 'confirmation_needed');
  }else{
    steps.push(`${chartNarratorTrendLabel(context)}_trend`, supportLabel === '20-day average' ? 'near_20ma' : (supportLabel === '50-day average' ? 'near_50ma' : 'support_context'));
  }
  const toneMode = chartNarratorToneModeForStorySteps(steps);
  const confidenceMode = chartNarratorConfidenceModeForStorySteps(steps);
  const provisionalStory = {steps};
  const stepDetails = steps.map(step => {
    const evidenceFactIds = chartNarratorStepEvidenceFactIds(step, context);
    const derived = chartNarratorStepDerivedSupport(step, context, provisionalStory);
    return {
      key:step,
      evidenceFactIds,
      derivedFromSteps:Array.isArray(derived && derived.derivedFromSteps) ? derived.derivedFromSteps.map(value => String(value || '').trim()).filter(Boolean) : [],
      derivedFromConditions:Array.isArray(derived && derived.derivedFromConditions) ? derived.derivedFromConditions.map(value => String(value || '').trim()).filter(Boolean) : []
    };
  });
  const evidenceFactIds = [
    ...(Array.isArray(primaryStory && primaryStory.evidenceFactIds) ? primaryStory.evidenceFactIds.slice() : []),
    ...stepDetails.flatMap(detail => Array.isArray(detail.evidenceFactIds) ? detail.evidenceFactIds : [])
  ];
  const semanticEnvelope = chartGuruSemanticEnvelopeFromStory(key, context);
  return {
    key:key || 'trend_context',
    bias:chartNarratorBiasForStory(key, context),
    toneMode,
    confidenceMode,
    trendLabel:chartNarratorTrendLabel(context),
    supportLabel,
    supportSemantic:semanticEnvelope.supportSemantic,
    buyerResponseSemantic:semanticEnvelope.buyerResponseSemantic,
    confirmationSemantic:semanticEnvelope.confirmationSemantic,
    steps,
    stepDetails,
    evidenceFactIds:[...new Set(evidenceFactIds.map(id => String(id || '').trim()).filter(Boolean))]
  };
}

function chartNarratorStoryTextForPrimaryStory(primaryStory = {}, context = {}, recentStory = null){
  const story = recentStory && typeof recentStory === 'object' ? recentStory : chartNarratorRecentStoryForPrimaryStory(primaryStory, context);
  const key = String(story && story.key || '').trim();
  const supportLabel = story.supportLabel || chartNarratorSupportLabel(context);
  const hasStep = step => chartNarratorHasStep(story, step);
  const confidenceMode = String(story && story.confidenceMode || '').trim();
  const seed = story.steps.length + (context.marketSupportive === true ? 1 : 0) + (context.weakVolume === true ? 2 : 0) + (context.bounceAttempt === true ? 3 : 0);
  if(key === 'early_rebound_from_20ma'){
    const opener = chartNarratorDeterministicPick([
      'After a controlled pullback into the 20-day average, buyers have started to push the stock higher again.',
      'Price pulled back into the 20-day average in a controlled way, and buyers have started to respond from that support area.'
    ], seed);
    const contextLine = chartNarratorDeterministicPick([
      'The trend still looks healthy, but this rebound now needs to prove it has enough strength to continue.',
      'The broader trend still looks healthy, but the rebound still needs follow-through before it means much.'
    ], seed + 1);
    const volumeLine = confidenceMode === 'buyer_response_needs_volume_proof'
      ? 'Volume is still a bit light, so the move needs more proof before traders can trust it more.'
      : '';
    return [opener, contextLine, volumeLine].filter(Boolean).join(' ');
  }
  if(key === 'constructive_pullback_near_20ma' || key === 'constructive_pullback_near_50ma'){
    const opener = chartNarratorDeterministicPick([
      'The bigger trend still looks healthy, so this recent dip reads more like a normal pause than a chart falling apart.',
      'The main trend is still in good shape, which means the recent pullback is happening inside strength rather than damage.'
    ], seed);
    const response = context.bounceAttempt === true
      ? chartNarratorDeterministicPick([
        `After pulling back toward the ${supportLabel}, buyers stepped back in and pushed price higher.`,
        `Price pulled back toward the ${supportLabel}, and buyers have started to respond from that area.`
      ], seed + 1)
      : chartNarratorDeterministicPick([
        `Price has pulled back toward the ${supportLabel}, which is where you want buyers to show up if the trend is still healthy.`,
        `The pullback has brought price back toward the ${supportLabel}, putting it near an area that matters.`
      ], seed + 1);
    const confidence = confidenceMode === 'buyer_response_needs_volume_proof'
      ? 'That is encouraging, but the volume is still a bit light, so the move needs more proof.'
      : (confidenceMode === 'buyer_response_needs_follow_through'
        ? 'That is encouraging, and it keeps the setup constructive as long as buyers can follow through.'
        : (confidenceMode === 'support_test_needs_buyer_proof'
          ? 'Price is in a useful area, but buyers still need to step in and the light volume means the setup still needs more proof.'
          : 'That keeps the setup constructive, but buyers still need to prove they can hold this area.'));
    const indecision = context.bodyDescriptor === 'small' || context.latestDirection === 'flat'
      ? 'The latest candle was small, so neither buyers nor sellers proved much control by the close.'
      : '';
    return [opener, response, indecision, confidence].filter(Boolean).join(' ');
  }
  if(key === 'off_level_wait_for_clearer_support'){
    return chartNarratorDeterministicPick([
      'The bigger trend still looks fine, but price has already drifted away from the area where a cleaner pullback would usually set up. Nothing is badly wrong here, but there is not much edge until price comes back into support.',
      'The chart still looks healthy overall, but price is not sitting near a support area right now. That makes this more of a wait-and-see spot than a clean pullback.'
    ], seed);
  }
  if(key === 'pullback_still_repairing'){
    return chartNarratorDeterministicPick([
      `The chart has weakened during this pullback. Instead of holding the first support area cleanly, price is still trying to climb back above the ${supportLabel}, so the setup needs repair before it can improve.`,
      `This pullback is not settled yet. Price has slipped enough to show that buyers have not really taken control again, so the chart still needs to rebuild before it looks healthier.`
    ], seed);
  }
  if(key === 'structure_breaking_down'){
    if(chartGuruBuyerResponsePresent(context) && context.followThroughConfirmed !== true){
      return chartNarratorDeterministicPick([
        'Support has already failed, so the chart is still damaged. Buyers are trying to stabilise it, but they have not regained control yet, which keeps this in rebuild mode rather than turning it back into a healthy pullback.',
        'This is still a damaged chart because support has already given way. Buyers are attempting to steady the action, but the rebound has not repaired the structure or put them back in control yet.'
      ], seed + (context.failedBounce === true ? 1 : 0));
    }
    return chartNarratorDeterministicPick([
      'The bigger picture is no longer healthy. Price has lost support and sellers are still controlling the recent candles, so this looks more like a chart breaking down than a normal pullback.',
      'This is not a constructive pause anymore. Support has given way, and the recent action still shows sellers in charge.'
    ], seed + (context.failedBounce === true ? 1 : 0));
  }
  if(key === 'strong_upside_acceleration'){
    return chartNarratorDeterministicPick([
      'The stock has pushed higher for several candles in a row, and buyers have been clearly in control. That is strong action, but sharp runs are usually easier to trust after they pause and reset.',
      'Buyers have driven this move higher with several strong up days. The move looks powerful, even though it would be healthier to see it calm down before the next decision.'
    ], seed);
  }
  if(key === 'sharp_selloff'){
    return chartNarratorDeterministicPick([
      'Recent candles show sellers taking control quickly. Price is being pushed lower with little sign of support yet, so this is still weak action.',
      'The latest move has turned into a sharp drop rather than a calm pullback. Sellers are still in charge, which keeps the chart in a weak position.'
    ], seed);
  }
  if(key === 'bounce_confirmation_pending'){
    return context.bounceAttempt === true
      ? `Price has reached an area that could matter, and buyers have started to respond, but one good day on its own is not enough yet. ${(context.bodyDescriptor === 'small' || context.latestDirection === 'flat') ? 'The latest candle was small, so neither buyers nor sellers proved much control by the close. ' : ''}The bounce has started to form, but it still needs follow-through before it means much.`
      : `Price is testing an area that could matter, and buyers pushed it off the lows, but the move is still early. ${(context.bodyDescriptor === 'small' || context.latestDirection === 'flat') ? 'The latest candle was small, so neither buyers nor sellers proved much control by the close. ' : ''}It needs a stronger follow-through day before the chart looks more convincing.`;
  }
  if(key === 'extended_after_run'){
    return 'The trend still looks strong, but price has already run away from support. That usually leaves less room for error until the stock pulls back and settles down again.';
  }
  if(key === 'long_lower_wick_support_test'){
    return 'Price dipped lower during the day, but buyers pushed it back up before the close. That can be an encouraging sign, although it matters more if the next candle also stays firm.';
  }
  if(key === 'long_upper_wick_rejection'){
    return 'The stock tried to move higher, but it could not hold those gains. That tells you sellers were still active near the top of the move.';
  }
  if(key === 'doji_indecision'){
    return 'The latest candle shows a pause more than a decision. Neither side showed clear control by the close, so the chart is still waiting for a clearer move.';
  }
  if(key === 'failed_bounce'){
    return 'The stock tried to recover, but buyers could not hold the move. That keeps the recent action weak because sellers are still taking back control.';
  }
  if(key === 'bounce_attempt'){
    return 'Buyers are trying to push the stock back up from support. That is a start, but it still needs another solid day before the bounce looks trustworthy.';
  }
  return 'The recent candles matter most when you read them in sequence, not one by one, and right now the chart still needs a clearer next step.';
}

function chartNarratorWhyItMattersForStory(primaryStory = {}, context = {}, recentStory = null){
  const story = recentStory && typeof recentStory === 'object' ? recentStory : chartNarratorRecentStoryForPrimaryStory(primaryStory, context);
  const key = String(story && story.key || '').trim();
  const supportLabel = story.supportLabel || chartNarratorSupportLabel(context);
  if(key === 'early_rebound_from_20ma'){
    return `The first rebound from the ${supportLabel} is encouraging, but one strong response does not confirm the pullback is complete.`;
  }
  if(key === 'constructive_pullback_near_20ma' || key === 'constructive_pullback_near_50ma'){
    return context.bounceAttempt === true
      ? `If buyers can keep holding around the ${supportLabel}, this can turn into a cleaner continuation of the trend instead of just a one-day pop.`
      : `If buyers defend the ${supportLabel}, the pullback can stay healthy. If they do not, the chart can drift from constructive into messy quite quickly.`;
  }
  if(key === 'off_level_wait_for_clearer_support') return 'Good charts are usually easier to manage when they pull back into a level that clearly matters. Away from support, the reward-to-risk picture is usually less clear.';
  if(key === 'pullback_still_repairing') return 'When price cannot quickly retake a support area, it tells you the pullback is still doing damage instead of settling down.';
  if(key === 'structure_breaking_down'){
    return chartGuruBuyerResponsePresent(context) && context.followThroughConfirmed !== true
      ? 'Even when buyers try to stabilise a damaged chart, that attempt matters only if it can rebuild the structure and take control back.'
      : 'Once support starts failing, small bounce attempts are less trustworthy because the chart first needs time to rebuild.';
  }
  if(key === 'strong_upside_acceleration') return 'Big up moves can keep going, but they also become easier to mis-time if you chase them after they are already extended.';
  if(key === 'sharp_selloff') return 'Fast weakness usually matters because it shows buyers are stepping back, not because one red candle is magical on its own.';
  if(key === 'bounce_confirmation_pending') return 'Early support reactions are useful, but the chart only improves if buyers can add another sign of strength.';
  if(key === 'failed_bounce') return 'Failed recoveries often matter because they show sellers were strong enough to take control back quickly.';
  return 'The important part is not the label. It is whether the recent candles are helping the chart improve, stall, or break down.';
}

function chartNarratorSupportSectionsForStory(recentStory = null, context = {}){
  const story = recentStory && typeof recentStory === 'object' ? recentStory : null;
  if(!story) return [];
  const supportLabel = String(story.supportLabel || chartNarratorSupportLabel(context)).trim();
  const hasStep = step => chartNarratorHasStep(story, step);
  const sections = [];
  const addSection = section => {
    if(!section || !section.key || !section.label || !section.text) return;
    sections.push({
      key:String(section.key || '').trim(),
      icon:String(section.icon || '').trim(),
      label:String(section.label || '').trim(),
      text:String(section.text || '').trim(),
      confidence:Number.isFinite(Number(section.confidence)) ? Number(section.confidence) : 0.7,
      teachingFocus:false,
      source:'deterministic',
      evidenceFactIds:chartNarratorEvidenceForStorySteps(story, Array.isArray(section.storySteps) ? section.storySteps : [])
    });
  };
  if(hasStep('pullback_to_20ma') || hasStep('pullback_to_50ma')){
    if(!hasStep('sellers_pushed_back')){
      addSection({
        key:'support',
        icon:'➕',
        label:'Support',
        text:hasStep('buyer_response')
          ? `Price pulled back toward the ${supportLabel}, and buyers have started to respond from that area.`
          : `Price has pulled back toward the ${supportLabel}, so this is the area where buyers still need to show they can hold the chart up.`,
        confidence:hasStep('buyer_response') ? 0.84 : 0.8,
        storySteps:hasStep('pullback_to_20ma') ? ['pullback_to_20ma', hasStep('buyer_response') ? 'buyer_response' : 'support_test'] : ['pullback_to_50ma', hasStep('buyer_response') ? 'buyer_response' : 'support_test']
      });
    }
  }else if(hasStep('off_level')){
    addSection({
      key:'support',
      icon:'🟡',
      label:'Setup location',
      text:`Price is still away from the ${supportLabel === 'support' ? 'main support areas' : supportLabel}, so the chart is not in the cleaner pullback zone you would usually want to see.`,
      confidence:0.78,
      storySteps:['off_level', 'wait_for_clearer_support']
    });
  }else if(hasStep('support_not_reclaimed')){
    addSection({
      key:'weakness',
      icon:'📉',
      label:'Weakness',
      text:`Price is still struggling to get back above the ${supportLabel}, which tells you the pullback has not repaired itself yet.`,
      confidence:0.84,
      storySteps:['support_not_reclaimed', 'repair_needed']
    });
  }else if(hasStep('support_lost')){
    addSection({
      key:'weakness',
      icon:'📉',
      label:'Weakness',
      text:hasStep('buyer_response')
        ? `Price has already lost the ${supportLabel}, so the chart is damaged. Buyers are trying to stabilise it, but they still need to reclaim control before the setup can improve.`
        : `Price has already lost the ${supportLabel}, so this has moved from a normal pullback into clear damage.`,
      confidence:hasStep('buyer_response') ? 0.88 : 0.9,
      storySteps:hasStep('buyer_response')
        ? ['support_lost', 'buyer_response', 'repair_needed']
        : ['support_lost', 'broken_structure']
    });
  }else if(hasStep('buyers_in_control')){
    addSection({
      key:'trend',
      icon:'📈',
      label:'Trend',
      text:'Several recent candles have pushed higher in a row, which shows buyers have been controlling the move rather than just winning one day.',
      confidence:0.88,
      storySteps:['strong_uptrend', 'buyers_in_control']
    });
  }else if(hasStep('sellers_in_control')){
    addSection({
      key:'weakness',
      icon:'📉',
      label:'Weakness',
      text:'Recent candles have kept pushing lower, so sellers are still driving the move rather than just winning one red day.',
      confidence:0.88,
      storySteps:['weak_trend', 'sellers_in_control']
    });
  }
  if(hasStep('buyers_pushed_back') && !sections.some(section => section.key === 'support')){
    addSection({
      key:'support',
      icon:'🕯',
      label:'Buyer response',
      text:'Buyers pushed the stock back up after it traded lower during the day, which is a useful early sign near support.',
      confidence:0.82,
      storySteps:['support_test', 'buyers_pushed_back']
    });
  }
  if(hasStep('sellers_pushed_back')){
    addSection({
      key:'resistance',
      icon:'🕯',
      label:'Resistance',
      text:'The stock tried to move higher, but sellers pushed it back before the close, which shows the move is still running into pressure.',
      confidence:0.82,
      storySteps:['resistance_test', 'sellers_pushed_back']
    });
  }else if(hasStep('direction_unclear')){
    addSection({
      key:'indecision',
      icon:'⚪',
      label:'Indecision',
      text:'The latest candle is more of a pause than a decision, so the chart is still waiting for one side to take clearer control.',
      confidence:0.8,
      storySteps:['pause', 'direction_unclear']
    });
  }

  if(hasStep('weak_volume')){
    addSection({
      key:'volume',
      icon:'📊',
      label:'Volume',
      text:'Volume is still lighter than normal, so the move has less backing behind it for now.',
      confidence:0.8,
      storySteps:['weak_volume']
    });
  }else if(hasStep('volume_supports_move')){
    addSection({
      key:'volume',
      icon:'📊',
      label:'Volume',
      text:'Volume is active, which makes the move more convincing.',
      confidence:0.83,
      storySteps:['volume_supports_move']
    });
  }else if(hasStep('active_selling')){
    addSection({
      key:'volume',
      icon:'📊',
      label:'Volume',
      text:'Volume is active on the selloff, which makes the recent weakness harder to dismiss.',
      confidence:0.83,
      storySteps:['active_selling']
    });
  }

  if((hasStep('strong_uptrend') || hasStep('intact_structure')) && !sections.some(section => section.key === 'trend') && !hasStep('off_level')){
    addSection({
      key:'trend',
      icon:'📈',
      label:'Trend',
      text:'The bigger trend is still in good shape, which is why this chart still deserves a constructive read for now.',
      confidence:0.78,
      storySteps:[hasStep('strong_uptrend') ? 'strong_uptrend' : 'intact_structure']
    });
  }
  if(hasStep('weak_structure') && !sections.some(section => section.key === 'weakness')){
    addSection({
      key:'weakness',
      icon:'📉',
      label:'Weakness',
      text:'The bigger trend has already softened, so the chart needs repair rather than a quick decision.',
      confidence:0.8,
      storySteps:['weak_structure']
    });
  }
  if(hasStep('broken_structure') && !sections.some(section => section.key === 'weakness')){
    addSection({
      key:'weakness',
      icon:'📉',
      label:'Weakness',
      text:'The bigger trend is broken, so small bounce attempts matter less until the chart builds a new base.',
      confidence:0.88,
      storySteps:['broken_structure']
    });
  }
  return sections;
}

function buildChartNarrator(primaryStory = {}, context = {}){
  const recentStory = chartNarratorRecentStoryForPrimaryStory(primaryStory, context);
  const story = chartNarratorStoryTextForPrimaryStory(primaryStory, context, recentStory);
  const whatNext = chartCoachWhatNextForStory(String(recentStory && recentStory.key || '').trim(), context);
  const learningPoint = chartCoachLearningPointForStory(String(recentStory && recentStory.key || '').trim(), context);
  return {
    story,
    whyItMatters:chartNarratorWhyItMattersForStory(primaryStory, context, recentStory),
    whatNext,
    learningPoint,
    readerTest:{
      whatJustHappened:story,
      tone:recentStory.bias,
      whatToWaitForNext:whatNext
    },
    recentStory
  };
}

function chartCoachLearningPointForStory(storyKey = '', context = {}){
  const volumeRatio = Number(context.volumeRatio);
  if(storyKey === 'early_rebound_from_20ma'){
    return 'Strong trends often resume from the 20-day average, but waiting for buyers to follow through can reduce the risk of chasing a failed rebound.';
  }
  if(storyKey === 'constructive_pullback_near_20ma' || storyKey === 'constructive_pullback_near_50ma'){
    return volumeRatio <= 0.8
      ? 'A pullback looks healthier when the selling stays controlled instead of getting heavier as price dips.'
      : 'A healthy pullback becomes more useful when buyers hold support first and then add a stronger response.';
  }
  if(storyKey === 'pullback_still_repairing') return 'If price cannot get back above support quickly, the pullback is still doing damage rather than settling down.';
  if(storyKey === 'off_level_wait_for_clearer_support') return 'A strong chart is usually easier to trust when price pulls back into an area where buyers have shown up before.';
  if(storyKey === 'bounce_confirmation_pending'){
    return context.bounceAttempt === true
      ? 'One good day can start a bounce, but it usually means more when buyers can back it up on the next day as well.'
      : 'A push off the low matters more when the next candle also closes stronger instead of slipping back again.';
  }
  if(storyKey === 'structure_breaking_down'){
    return chartGuruBuyerResponsePresent(context) && context.followThroughConfirmed !== true
      ? 'Once support fails, a small rebound only matters if it keeps building and starts repairing the structure.'
      : 'When support stops holding, the chart usually needs time to rebuild before a safer setup can appear.';
  }
  if(storyKey === 'extended_after_run') return 'A strong trend is easier to manage after it pulls back into support than when price is still stretched well above it.';
  if(storyKey === 'strong_upside_acceleration'){
    return volumeRatio >= 1.05
      ? 'Big moves on higher volume are usually more believable than big moves on quiet volume.'
      : 'Several strong up days are more useful when volume also supports the move.';
  }
  if(storyKey === 'sharp_selloff') return 'Fast selling matters more when the candles stay large and the closes keep getting weaker.';
  if(storyKey === 'long_lower_wick_support_test') return 'A strong push off the low often shows buyers were not willing to accept those lower prices.';
  if(storyKey === 'long_upper_wick_rejection') return 'A stock that cannot hold its push higher is often running into sellers before the move is ready.';
  if(storyKey === 'doji_indecision') return 'Very small candles often appear when the market is pausing and waiting for a clearer push either way.';
  if(storyKey === 'failed_bounce') return 'A recovery attempt matters less when sellers can quickly wipe it out.';
  if(storyKey === 'bounce_attempt') return 'An early bounce matters more when the next candle also closes firmly higher.';
  return 'The clearest chart lessons usually come from the biggest visual clue, not from any single indicator.';
}

function chartCoachWhatNextForStory(storyKey = '', context = {}){
  const maRelation = context.maRelation && typeof context.maRelation === 'object' ? context.maRelation : {};
  const supportLabel = context.near20 === 'near' || context.pullbackNear20 === true
    ? '20-day average'
    : ((context.near50 === 'near' || context.pullbackNear50 === true) ? '50-day average' : 'support');
  if(storyKey === 'early_rebound_from_20ma'){
    return `Watch for price to hold above the ${supportLabel} and build on the recent rebound. A decisive move back below support would weaken the setup.`;
  }
  if(storyKey === 'strong_upside_acceleration'){
    return `After a strong run, a calm pullback that holds above the 20-day average would be healthier than the price racing straight up.`;
  }
  if(storyKey === 'constructive_pullback_near_20ma' || storyKey === 'constructive_pullback_near_50ma'){
    return `Watch for buyers to confirm support with a firmer close from the ${supportLabel}. A decisive close below that area would weaken the setup.`;
  }
  if(storyKey === 'pullback_still_repairing'){
    return `Watch for price to reclaim the ${supportLabel} and hold it before trusting the pullback. Another decisive loss of support would keep the chart in repair mode.`;
  }
  if(storyKey === 'off_level_wait_for_clearer_support'){
    return 'Watch for price to move back into the 20-day average, the 50-day average, or another clear support area before treating the setup as lower risk.';
  }
  if(storyKey === 'bounce_confirmation_pending'){
    return context.bounceAttempt === true
      ? `Watch for buyers to defend the ${supportLabel} and add a second stronger close. A decisive break below support would tell you the bounce is not ready yet.`
      : `Watch for buyers to defend the ${supportLabel} and close stronger on the next candle. A decisive break below support would show that defence has failed.`;
  }
  if(storyKey === 'structure_breaking_down'){
    return chartGuruBuyerResponsePresent(context) && context.followThroughConfirmed !== true
      ? 'Watch for the chart to build a firmer base, hold up better on the next pullback, and reclaim control before treating this rebound as meaningful.'
      : 'Watch for the chart to stop making weaker closes and rebuild a proper base before treating any bounce as meaningful.';
  }
  if(storyKey === 'extended_after_run'){
    return 'Watch for a calmer pullback into the 20-day average or another clear support area before treating the move as lower risk.';
  }
  if(storyKey === 'sharp_selloff'){
    return 'Watch for selling to slow down, or for the price to stop closing near the low before trusting any bounce attempt.';
  }
  if(storyKey === 'long_lower_wick_support_test'){
    return 'Watch for the next candle to hold above support and close stronger to show buyers are following through.';
  }
  if(storyKey === 'long_upper_wick_rejection'){
    return 'Watch for price to avoid another close near the latest high unless buyers can push cleanly through that ceiling.';
  }
  if(storyKey === 'doji_indecision'){
    return 'Watch for the next candle to break clearly above or below this small range before treating the move as meaningful.';
  }
  if(storyKey === 'failed_bounce'){
    return 'Watch for the price to avoid closing below the latest low, or this failed bounce could turn into fresh weakness.';
  }
  if(storyKey === 'bounce_attempt'){
    return maRelation.above20 === false
      ? 'Watch for the price to reclaim the 20-day average with another firm close.'
      : 'Watch for another strong green candle or a higher low to show the bounce is gaining support.';
  }
  return maRelation.above20 === false
    ? 'Watch for the price to reclaim the 20-day average with a stronger close.'
    : 'Watch for a controlled pullback that holds above support rather than a rushed move higher.';
}

function chartGuruControlledPullbackPresent(context = {}){
  const recentSequence = Array.isArray(context.recentSequence) ? context.recentSequence : [];
  const redRun = chartCoachRecentColorRun(recentSequence, 'red');
  return !!(
    context.candleEvidenceDownsideMomentumSlowing === true
    || context.candleEvidenceTighterRanges === true
    || context.candleEvidenceSmallerBodies === true
    || context.candleEvidenceHigherLowHold === true
    || (
      String(context.latestDirection || '').trim() !== 'red'
      && String(context.bodyDescriptor || '').trim() !== 'strong'
      && redRun < 2
      && context.failedBounce !== true
    )
  );
}

function chartGuruVolumeParticipationLabel(context = {}){
  if(context.activeVolume === true) return 'expanding';
  if(context.weakVolume === true) return 'weak';
  return 'constructive';
}

