  const globalVerdict = options.globalVerdict && typeof options.globalVerdict === 'object' ? options.globalVerdict : resolveGlobalVerdict(item);
  const facts = canonicalCandleContext(item, state);
  const derivedStates = options.derivedStates && typeof options.derivedStates === 'object' ? options.derivedStates : analysisDerivedStatesFromRecord(item);
  const sections = [];
  const explanationFacts = [];
  const latest = facts.latest && typeof facts.latest === 'object' ? facts.latest : {};
  const latestDirection = facts.latestDirection || 'unknown';
  const bodyDescriptor = chartCoachBodyDescriptor(latest);
  const recentSequence = Array.isArray(facts.recent) ? facts.recent : [];
  const volume = numericOrNull((state.canonicalValues && state.canonicalValues.volume) || (state.trustedMarketContext && state.trustedMarketContext.volume) || (item.marketData && item.marketData.volume));
  const avgVolume30d = numericOrNull((item.marketData && (item.marketData.avgVolume30d || item.marketData.avgVolume)) || (state.trustedMarketContext && state.trustedMarketContext.avgVolume30d));
  const volumeRatio = Number.isFinite(volume) && Number.isFinite(avgVolume30d) && avgVolume30d > 0 ? volume / avgVolume30d : null;
  const structureSignals = chartCoachStructureSignals(recentSequence);
  const recentHigh = numericOrNull(latest.high);
  const recentLow = numericOrNull(latest.low);
  const near20 = chartCoachProximityLabel(facts.currentPrice, facts.ma20);
  const near50 = chartCoachProximityLabel(facts.currentPrice, facts.ma50);
  const lower = value => String(value || '').trim().toLowerCase();
  const resolvedStructureState = lower(derivedStates.structureState || globalVerdict.structure_state || globalVerdict.structureState);
  const resolvedStructureEligibility = lower(derivedStates.structureEligibility || globalVerdict.structure_eligibility || globalVerdict.structureEligibility);
  const resolvedSetupLocationState = lower(derivedStates.setupLocationState || globalVerdict.setup_location_state || globalVerdict.setupLocationState);
  const resolvedPullbackZone = lower(derivedStates.pullbackZone || globalVerdict.pullback_zone || globalVerdict.pullbackZone);
  const resolvedBounceState = lower(derivedStates.bounceState || globalVerdict.bounce_state || globalVerdict.bounceState);
  const resolvedVolumeState = lower(derivedStates.volumeState || globalVerdict.volume_state || globalVerdict.volumeState);
  const resolvedPriceabilityState = lower(derivedStates.priceabilityState || globalVerdict.priceability_state || globalVerdict.priceabilityState);
  const resolvedFinalVerdict = lower(globalVerdict.final_verdict || globalVerdict.finalVerdict || '');
  const evaluationScanType = String(derivedStates.evaluationScanType || derivedStates.evaluation_scan_type || '').trim();
  const canonicalPullback = options.canonicalPullback && typeof options.canonicalPullback === 'object'
    ? options.canonicalPullback
    : (typeof resolveCanonicalPullbackState === 'function' ? resolveCanonicalPullbackState({record:item, globalVerdict, derivedStates}) : {});
  const chartGuruResolverContext = chartGuruExplicitResolverSupportContext(item, globalVerdict);
  const supportAuthority = chartGuruSupportAuthority(chartGuruResolverContext, derivedStates, canonicalPullback);
  const authoritativeSupportActive = supportAuthority.authoritative && supportAuthority.supportCurrentlyActive;
  const authoritativePullbackZone = authoritativeSupportActive
    ? (supportAuthority.supportType === '50ma' ? 'near_50ma' : 'near_20ma')
    : resolvedPullbackZone;
  const authoritativeSetupLocationState = authoritativeSupportActive ? 'usable_pullback' : resolvedSetupLocationState;
  const marketStatusText = lower(item.marketStatus || state.marketStatus || '');
