function chartAiSummaryRenderGuard(record, analysisState = {}, chartTrace = null){
  const item = record && typeof record === 'object' ? record : {};
  const safeState = analysisState && typeof analysisState === 'object' ? analysisState : {};
  const pipeline = getReviewChartAnalysisPipeline(item) || {};
  const currentTicker = normalizeTicker(item.ticker || '');
  const currentImageId = chartImageIdForReview(item.review || {});
  const currentRequestId = String(pipeline.requestId || '');
  const summaryTicker = normalizeTicker(safeState.ticker || '');
  const summaryImageId = String(safeState.analysisChartImageId || safeState.chartImageId || '');
  const summaryRequestId = String(safeState.analysisRequestId || '');
  const pipelinePhase = String(pipeline.phase || '').trim();
  const verificationAllowsAi = !currentImageId || chartPipelineAllowsAi(pipelinePhase) || pipelinePhase === 'analysis_failed';
  let allowedToRender = true;
  let reason = 'accepted_current_analysis';
  if(!currentImageId){
    allowedToRender = false;
    reason = 'no_current_chart';
  }else if(
    currentImageId
    && summaryImageId
    && currentImageId === summaryImageId
    && !currentRequestId
    && !summaryRequestId
    && !pipelinePhase
  ){
    allowedToRender = false;
    reason = 'verification_context_unowned';
  }else if(
    pipelinePhase === 'verifying'
    && currentImageId
    && summaryImageId
    && currentImageId === summaryImageId
    && (!currentRequestId || !summaryRequestId || currentRequestId === summaryRequestId)
  ){
    allowedToRender = false;
    reason = 'quick_running';
  }else if(currentTicker && summaryTicker && currentTicker !== summaryTicker){
    allowedToRender = false;
    reason = 'ticker_mismatch';
  }else if(summaryImageId && summaryImageId !== currentImageId){
    allowedToRender = false;
    reason = 'image_mismatch';
  }else if(currentRequestId && summaryRequestId && currentRequestId !== summaryRequestId){
    allowedToRender = false;
    reason = 'request_mismatch';
  }else if(currentImageId && !verificationAllowsAi){
    allowedToRender = false;
    reason = 'verification_not_accepted';
  }
  if(typeof console !== 'undefined' && console.info){
    console.info('[CHART_AI_SUMMARY_GUARD]', {
      ticker:item.ticker || '',
      currentTicker,
      summaryTicker,
      pipelinePhase,
      currentImageId,
      summaryImageId,
      currentRequestId,
      summaryRequestId,
      allowedToRender,
      reason
    });
    if(!allowedToRender && reason !== 'quick_running'){
      console.info('[CHART_AI_SUMMARY_REJECTED_STALE_CONTEXT]', {
        currentTicker,
        summaryTicker,
        pipelinePhase,
        currentImageId,
        summaryImageId,
        currentRequestId,
        summaryRequestId,
        reason
      });
    }
  }
  return {
    currentTicker,
    summaryTicker,
    quickStatus:pipelinePhase,
    quickImageId:currentImageId,
    quickRequestId:currentRequestId,
    currentImageId,
    summaryImageId,
    currentRequestId,
    summaryRequestId,
    verificationStatus:pipelinePhase,
    allowedToRender,
    reason
  };
}

function renderSuppressedAiAnalysisPanel(suppression, rawResponse, options = {}){
  const safe = suppression && typeof suppression === 'object' ? suppression : {};
  const message = String(safe.message || 'AI analysis limited. The uploaded chart may not match the selected ticker, so technical analysis could be unreliable.').replace(/^AI analysis limited\.\s*/, '');
  const raw = String(rawResponse || '');
  if(options.legacy === true){
    return `<div class="responsegrid"><div class="mutebox warntext"><strong>AI analysis limited:</strong> ${escapeHtml(message)}</div>${raw ? `<details><summary>Raw Response</summary><div class="mutebox">${escapeHtml(raw)}</div></details>` : ''}</div>`;
  }
  return `<div class="responsegrid"><div class="summary tiny ai-summary-message ai-summary-message--warning"><strong>AI analysis limited</strong><div>${escapeHtml(message)}</div></div>${raw ? `<details class="compact-details"><summary>Raw Response</summary><div class="mutebox scrollbox">${escapeHtml(raw)}</div></details>` : ''}</div>`;
}

function isAnalysisStaleForRecord(record){
  const item = normalizeTickerRecord(record);
  const currentHardBlockers = currentScannerEstimateHardBlockers(item);
  if(currentHardBlockers.isScannerEstimate){
    if(currentHardBlockers.currentInvalidated) return true;
    if(currentHardBlockers.currentMissed) return true;
  }else{
    if(item.plan && item.plan.invalidatedState) return true;
    if(item.plan && item.plan.missedState) return true;
  }

  const currentPrice = numericOrNull(item.marketData && item.marketData.price);
  const stop = numericOrNull(item.plan && item.plan.stop);

  if(hasAuthoritativeStopBreach(item, {currentPrice, stopPrice:stop})){
    return true;
  }

  return false;
}

function statusRank(status){
  if(status === 'Strong Fit' || status === 'Ready' || status === 'Entry') return 0;
  if(status === 'Too Wide') return 1;
  if(status === 'Possible Fit' || status === 'Near Setup' || status === 'Near Entry') return 2;
  if(status === 'Manual Review' || status === 'Watch') return 2;
  return 3;
}

