function buildStableReviewProjectionSnapshot(record, context = 'review_open_during_refresh'){
  const item = normalizeTickerRecord(record);
  const journeyAuthority = typeof currentTickerJourneyAuthority === 'function'
    ? currentTickerJourneyAuthority(item)
    : {};
  const activeProjectionSnapshot = uiState.activeReviewSourceProjectionSnapshot
    && typeof uiState.activeReviewSourceProjectionSnapshot === 'object'
    && normalizeTicker(uiState.activeReviewSourceProjectionSnapshot.ticker || '') === normalizeTicker(item.ticker || '')
      ? uiState.activeReviewSourceProjectionSnapshot
      : null;
  const activeProjectionSource = normalizeReviewProjectionSource(
    String(uiState.activeReviewProjectionSource || '').trim().toLowerCase(),
    activeProjectionSnapshot
  );
  const simplifiedState = resolveSimplifiedStateForSurface(item, 'review', {log:false});
  const globalVerdict = resolveGlobalVerdict(item);
  const lifecycleSnapshot = watchlistLifecycleSnapshot(item);
  const effectiveSimplifiedState = applyReviewWatchlistSoftReadinessDisplayOverride(
    item,
    simplifiedState,
    globalVerdict,
    lifecycleSnapshot
  );
  const ticker = normalizeTicker(item.ticker || '');
  if(!ticker) return null;
  const projectionPreferred = hasPresentationAuthoritySnapshot(activeProjectionSnapshot, ticker)
    && ['clicked_card_snapshot', 'track_projection_updated'].includes(activeProjectionSource);
  const visualBucket = String(
    projectionPreferred
      ? (
        activeProjectionSnapshot.sourceOfTruthVisualBucket
        || activeProjectionSnapshot.visualBucket
        || activeProjectionSnapshot.renderedBucket
      )
      : effectiveSimplifiedState.visualBucket
    || ''
  ).trim();
  const canonicalVerdict = String(
    projectionPreferred
      ? (
        activeProjectionSnapshot.canonicalVerdict
        || activeProjectionSnapshot.finalVerdict
        || activeProjectionSnapshot.renderedVerdict
      )
      : effectiveSimplifiedState.canonicalVerdict
    || ''
  ).trim();
  const tone = String(
    projectionPreferred
      ? (
        activeProjectionSnapshot.tone
        || activeProjectionSnapshot.sourceOfTruthVisualBucket
        || activeProjectionSnapshot.visualBucket
      )
      : (effectiveSimplifiedState.tone || visualBucket)
    || ''
  ).trim();
  const decisionSummary = String(
    (projectionPreferred && (
      activeProjectionSnapshot.decisionSummary
      || activeProjectionSnapshot.headline
      || activeProjectionSnapshot.statusText
    ))
    || effectiveSimplifiedState.decisionSummary
    || effectiveSimplifiedState.mainBlocker
    || effectiveSimplifiedState.actionLabel
    || effectiveSimplifiedState.planStatus
    || ''
  ).trim();
  const actionGuidance = String(
    (projectionPreferred && (
      activeProjectionSnapshot.actionGuidance
      || activeProjectionSnapshot.actionLabel
      || activeProjectionSnapshot.actionShortLabel
    ))
    || effectiveSimplifiedState.actionLabel
    || ''
  ).trim();
  const resolvedSectionKey = resolveTrackSectionKey(
    effectiveSimplifiedState.sectionKey
    || effectiveSimplifiedState.renderedBucket
    || visualBucket
    || '',
    visualBucket
  );
  const projectionSnapshot = {
    ticker,
    context:String(context || 'review_open_during_refresh'),
    canonicalVerdict:normalizeGlobalVerdictKey(canonicalVerdict || 'watch'),
    finalVerdict:normalizeGlobalVerdictKey(canonicalVerdict || 'watch'),
    renderedVerdict:normalizeGlobalVerdictKey(canonicalVerdict || 'watch'),
    visualBucket:normalizeVisualBucketForPairing(visualBucket || canonicalVerdict || 'monitor'),
    sourceOfTruthVisualBucket:normalizeVisualBucketForPairing(visualBucket || canonicalVerdict || 'monitor'),
    renderedBucket:normalizeVisualBucketForPairing(visualBucket || canonicalVerdict || 'monitor'),
    tone:String(
      normalizeGlobalVerdictKey(canonicalVerdict || 'watch') === 'entry'
        ? 'entry'
        : (normalizeGlobalVerdictKey(canonicalVerdict || 'watch') === 'near_entry'
          ? 'near_entry'
          : tone)
    ).trim().toLowerCase(),
    sectionKey:resolvedSectionKey,
    resolvedSectionKey,
    decisionSummary:String(
      normalizeGlobalVerdictKey(canonicalVerdict || 'watch') === 'entry'
        ? 'Buyers are in control and the setup is ready to act on.'
        : decisionSummary
    ).trim(),
    actionGuidance:String(
      normalizeGlobalVerdictKey(canonicalVerdict || 'watch') === 'entry'
        ? 'Execute only if the trigger remains valid.'
        : actionGuidance
    ).trim(),
    setupScore:setupScoreForRecord(item),
    capturedAt:new Date().toISOString(),
    source:projectionPreferred ? 'active_review_projection_snapshot' : 'stable_record_snapshot',
    authority:journeyAuthority
  };
  return projectionSnapshot;
}

function buildTrackProjectionSnapshotFromPersistedPresentation(record, context = 'watchlist_add_projection'){
  { // Consumer 8: persisted data is archived context, never projection authority.
  const item = normalizeTickerRecord(record || {});
  const ticker = normalizeTicker(item.ticker || '');
  if(!ticker) return null;
  const publication = resolveSimplifiedStateForSurface(item, 'track', {log:false, source:context, reason:'canonical_projection'});
  const failed = publication.publicationStatus === 'validation_failed';
  const verdict = normalizeGlobalVerdictKey(publication.canonicalVerdict || 'watch');
  const visualBucket = verdict === 'watch' ? 'monitor' : verdict;
  return {
    ticker, context:String(context), canonicalVerdict:verdict, finalVerdict:verdict, renderedVerdict:verdict,
    publicationStatus:failed ? 'validation_failed' : 'valid', canonicalResultVersion:String(publication.canonicalResultVersion || ''), evidenceId:String(publication.evidenceId || ''),
    visualBucket, sourceOfTruthVisualBucket:visualBucket, renderedBucket:visualBucket, tone:visualBucket,
    sectionKey:String(watchlistRenderGroupForBucket(visualBucket) || visualBucket), resolvedSectionKey:String(watchlistRenderGroupForBucket(visualBucket) || visualBucket),
    decisionSummary:failed ? 'Decision unavailable - validation failed.' : String(publication.decisiveBlocker || publication.actionLabel || ''),
    actionGuidance:failed ? 'Current decision unavailable; setup remains non-actionable.' : String(publication.actionLabel || ''),
    persistedPresentationAvailable:!!(item.watchlist && item.watchlist.presentation), persistedPresentationCacheOnly:true,
    compatibilityOnly:true, mayFeedDecisionLogic:false,
    sourceCanonicalFields:['verdict.value','plan','eligibility','snapshot.evidenceId','publicationStatus'], capturedAt:new Date().toISOString(), source:'canonical_publication_projection'
  };
  }
  const item = normalizeTickerRecord(record || {});
  const journeyAuthority = typeof currentTickerJourneyAuthority === 'function'
    ? currentTickerJourneyAuthority(item)
    : {};
  const ticker = normalizeTicker(item.ticker || '');
  if(!ticker) return null;
  const persistedPresentation = item.watchlist
    && item.watchlist.presentation
    && typeof item.watchlist.presentation === 'object'
    ? item.watchlist.presentation
    : null;
  const persistedSharedPresentation = persistedPresentation
    && persistedPresentation.sharedPresentation
    && typeof persistedPresentation.sharedPresentation === 'object'
    ? persistedPresentation.sharedPresentation
    : null;
  /*
    Persisted projection authority map:
    - review.savedProjectionSnapshot / review.savedVerdict: reload convenience only.
    - watchlist/shared presentation and track projection fallback: display-only persisted context.
    - startup review restore may reopen the last review ticker, but must not recreate Entry authority.
    - projections/persisted presentation never create live authority.
    Precedence:
    fresh canonical/review authority > display-only persisted context > stale persisted verdict ignored.
  */
  const lifecycleSnapshot = watchlistLifecycleSnapshot(item);
  const globalVerdict = resolveGlobalVerdict(item);
  const simplifiedState = resolveSimplifiedStateForSurface(item, 'track', {
    log:false,
    source:context,
    reason:context
  });
  const renderModels = typeof buildCanonicalRenderModelsFromRecord === 'function'
    ? buildCanonicalRenderModelsFromRecord(item, {
      surface:'track',
      source:context,
      reason:context,
      derivedStates:simplifiedState && simplifiedState.debug && simplifiedState.debug.derivedStates
        ? simplifiedState.debug.derivedStates
        : analysisDerivedStatesFromRecord(item),
      effectivePlan:effectivePlanForRecord(item, {allowScannerFallback:true}),
      displayedPlan:applySetupConfirmationPlanGate(
        item,
        deriveCurrentPlanState(
          item.plan && item.plan.entry,
          item.plan && item.plan.stop,
          item.plan && item.plan.firstTarget,
          item.marketData && item.marketData.currency
        )
      ),
      resolvedContract:globalVerdict,
      globalVerdict,
      lifecycleSnapshot,
      setupScore:setupScoreForRecord(item)
    })
    : null;
  const planVerdictContract = renderModels && renderModels.contract && typeof renderModels.contract === 'object'
    ? renderModels.contract
    : null;
  const planVerdictContractApi = typeof window !== 'undefined' && window && window.PlanVerdictContract
    ? window.PlanVerdictContract
    : null;
  const canonicalTrackRenderModel = planVerdictContractApi && typeof planVerdictContractApi.buildTrackRenderModel === 'function'
    ? planVerdictContractApi.buildTrackRenderModel(planVerdictContract)
    : (renderModels && renderModels.trackRenderModel && typeof renderModels.trackRenderModel === 'object'
      ? renderModels.trackRenderModel
      : null);
  const sharedPresentation = buildSharedReviewTrackPresentation(item, {
    surface:'track',
    simplifiedState,
    lifecycleSnapshot,
    globalVerdict,
    sourceOfTruth:'live_recomputed_fallback',
    source:context,
    reason:context
  });
  const snapshotPresentation = persistedSharedPresentation && typeof persistedSharedPresentation === 'object'
    ? persistedSharedPresentation
    : null;
  const visualBucket = normalizeVisualBucketForPairing(
    canonicalTrackRenderModel && (canonicalTrackRenderModel.visibleBucket || canonicalTrackRenderModel.visualBucket)
    || sharedPresentation.visualBucket
    || 'monitor'
  );
  const canonicalVerdict = normalizeGlobalVerdictKey(
    canonicalTrackRenderModel && canonicalTrackRenderModel.canonicalVerdict
    || sharedPresentation.canonicalVerdict
    || sharedPresentation.finalVerdict
    || 'watch'
  );
  const tone = String(
    canonicalTrackRenderModel && canonicalTrackRenderModel.tone
    || sharedPresentation.tone
    || visualBucket
    || 'monitor'
  ).trim().toLowerCase() || 'monitor';
  const resolvedSectionKey = typeof resolveTrackSectionKey === 'function'
    ? resolveTrackSectionKey(
      watchlistRenderGroupForBucket(visualBucket) || visualBucket || '',
      visualBucket
    )
    : String(watchlistRenderGroupForBucket(visualBucket) || visualBucket || 'monitor').trim().toLowerCase();
  return {
    ticker,
    context:String(context || 'watchlist_add_projection'),
    canonicalVerdict,
    finalVerdict:canonicalVerdict,
    renderedVerdict:canonicalVerdict,
    visualBucket,
    sourceOfTruthVisualBucket:visualBucket,
    renderedBucket:visualBucket,
    tone,
    sectionKey:resolvedSectionKey,
    resolvedSectionKey,
    decisionSummary:String(
      canonicalTrackRenderModel && (canonicalTrackRenderModel.headline || canonicalTrackRenderModel.statusText)
      || sharedPresentation.trackDecisionSummary
      || sharedPresentation.headline
      || sharedPresentation.statusText
      || snapshotPresentation && (snapshotPresentation.trackDecisionSummary || snapshotPresentation.headline || snapshotPresentation.statusText)
      || ''
    ).trim(),
    actionGuidance:String(
      canonicalTrackRenderModel && (canonicalTrackRenderModel.nextAction || canonicalTrackRenderModel.actionLabel)
      || sharedPresentation.trackNextAction
      || sharedPresentation.nextAction
      || sharedPresentation.actionLabel
      || snapshotPresentation && (snapshotPresentation.trackNextAction || snapshotPresentation.nextAction || snapshotPresentation.actionLabel)
      || ''
    ).trim(),
    persistedPresentationAvailable:persistedSharedPresentation != null,
    persistedPresentationCacheOnly:persistedSharedPresentation != null,
    capturedAt:new Date().toISOString(),
    source:'persisted_track_presentation',
    authority:journeyAuthority
  };
}

function reviewStoredProjectionSnapshot(record){
  const item = normalizeTickerRecord(record || {});
  const ticker = normalizeTicker(item.ticker || '');
  if(!ticker) return null;
  const storedSnapshot = item.review
    && item.review.savedProjectionSnapshot
    && typeof item.review.savedProjectionSnapshot === 'object'
      ? item.review.savedProjectionSnapshot
      : null;
  if(!hasPresentationAuthoritySnapshot(storedSnapshot, ticker)) return null;
  return projectionSnapshotWithAuthority(storedSnapshot, item);
}

function withReviewProjectionSuppressed(callback){
  if(typeof callback !== 'function') return null;
  const stateRef = typeof uiState !== 'undefined' && uiState && typeof uiState === 'object'
    ? uiState
    : null;
  if(!stateRef) return callback();
  const previousProjectionSnapshot = stateRef.activeReviewSourceProjectionSnapshot;
  const previousProjectionSource = stateRef.activeReviewProjectionSource;
  try{
    delete stateRef.activeReviewSourceProjectionSnapshot;
    stateRef.activeReviewProjectionSource = '';
    return callback();
  }finally{
    if(previousProjectionSnapshot === undefined) delete stateRef.activeReviewSourceProjectionSnapshot;
    else stateRef.activeReviewSourceProjectionSnapshot = previousProjectionSnapshot;
    if(previousProjectionSource === undefined) delete stateRef.activeReviewProjectionSource;
    else stateRef.activeReviewProjectionSource = previousProjectionSource;
  }
}

function clearPersistedReviewProjectionState(record, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return false;
  let changed = false;
  if(item.review.savedProjectionSnapshot){
    writeSavedReviewAuthority(item, {savedProjectionSnapshot:null}, {clearProjectionWhenNonEntry:false});
    changed = true;
  }
  if(options.clearSavedVerdict !== false && normalizeGlobalVerdictKey(item.review.savedVerdict || '') === 'entry'){
    writeSavedReviewAuthority(item, {savedVerdict:''}, {clearProjectionWhenNonEntry:false});
    changed = true;
  }
  if(changed) commitTickerState();
  return changed;
}

function evaluatePersistedReviewProjectionValidity(record, snapshot, context = 'startup_review_projection'){
  const item = normalizeTickerRecordReadOnly(record || {});
  const ticker = normalizeTicker(item.ticker || '');
  const projectionVerdict = normalizeGlobalVerdictKey(
    snapshot && (
      snapshot.canonicalVerdict
      || snapshot.finalVerdict
      || snapshot.renderedVerdict
    ) || ''
  );
  const reviewVerdictFallback = normalizeGlobalVerdictKey(item.review && item.review.savedVerdict || '');
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const globalVerdict = resolveGlobalVerdict(item);
  const projectionSuppressedReviewState = withReviewProjectionSuppressed(() => resolveSimplifiedStateForSurface(item, 'review', {
    log:false,
    source:context,
    reason:'persisted_review_projection_validation'
  })) || {};
  const reviewResolverVerdict = normalizeGlobalVerdictKey(projectionSuppressedReviewState.canonicalVerdict || '');
  const validationAnalysisState = typeof getReviewAnalysisState === 'function'
    ? getReviewAnalysisState(item)
    : null;
  const validationStoryContext = typeof buildCanonicalStoryContextForRecord === 'function'
    ? buildCanonicalStoryContextForRecord(item, {
      analysis:validationAnalysisState && validationAnalysisState.normalizedAnalysis && typeof validationAnalysisState.normalizedAnalysis === 'object'
        ? validationAnalysisState.normalizedAnalysis
        : {},
      globalVerdict,
      derivedStates
    })
    : null;
  const validationCurrentPhase = String(validationStoryContext && validationStoryContext.currentPhase || '').trim().toLowerCase();
  const validationDominantStory = String(validationStoryContext && validationStoryContext.dominantStory || '').trim().toLowerCase();
  const effectivePlan = effectivePlanForRecord(item, {allowScannerFallback:true});
  let displayedPlan = applySetupConfirmationPlanGate(
    item,
    deriveCurrentPlanState(
      effectivePlan.entry,
      effectivePlan.stop,
      effectivePlan.firstTarget,
      item.marketData && item.marketData.currency
    ),
    derivedStates
  );
  const explicitInvalidationAuthorityCode = resolveStructuredExplicitInvalidationAuthorityCode(globalVerdict);
  const scannerEstimateHardBlockers = currentScannerEstimateHardBlockers(item, {
    displayedPlan,
    derivedStates,
    globalVerdict,
    explicitInvalidationReasonCode:explicitInvalidationAuthorityCode
  });
  const technicalInvalidation = isCurrentTechnicalInvalidation(item, globalVerdict, displayedPlan);
  const structureState = String(derivedStates.structureState || '').trim().toLowerCase();
  const structureEligibility = String(derivedStates.structureEligibility || globalVerdict.structure_eligibility || '').trim().toLowerCase();
  const scanVerdict = normalizeGlobalVerdictKey(item.scan && (item.scan.resolvedVerdict || item.scan.verdict) || '');
  const scanUpdatedAt = String(item.scan && (item.scan.updatedAt || item.scan.lastScannedAt) || '').trim();
  const projectionCapturedAtMs = Date.parse(String(snapshot && snapshot.capturedAt || ''));
  const scanUpdatedAtMs = Date.parse(scanUpdatedAt);
  const fresherScannerInvalidation = Number.isFinite(projectionCapturedAtMs)
    && Number.isFinite(scanUpdatedAtMs)
    && scanUpdatedAtMs > projectionCapturedAtMs
    && !!scanVerdict
    && scanVerdict !== 'entry';
  const precedence = [
    'fresh canonical authority',
    'current review resolver',
    'valid persisted review projection',
    'stale saved verdict fallback'
  ];

  if(!projectionVerdict){
    return {valid:false, reason:'missing_projection_verdict', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(projectionVerdict !== 'entry'){
    return {valid:true, reason:'non_entry_projection', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(normalizeGlobalVerdictKey(globalVerdict.final_verdict || '') === 'avoid'){
    return {valid:false, reason:'fresh_canonical_avoid', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(
    validationCurrentPhase === 'support_failed'
    || ['failed_support_test', 'structure_breaking_down'].includes(validationDominantStory)
  ){
    return {valid:false, reason:'failed_support_story', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(['broken','dead','failed'].includes(structureState) || structureEligibility === 'broken'){
    return {valid:false, reason:'structural_damage', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(technicalInvalidation || scannerEstimateHardBlockers.currentInvalidated){
    return {valid:false, reason:'explicit_invalidation', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(scannerEstimateHardBlockers.currentMissed){
    return {valid:false, reason:'missed_setup', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(scannerEstimateHardBlockers.currentTargetTooClose){
    return {valid:false, reason:'target_too_close', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(scannerEstimateHardBlockers.terminalLifecycle){
    return {valid:false, reason:'terminal_lifecycle', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(
    String(displayedPlan.status || '').trim().toLowerCase() !== 'valid'
    && (fresherScannerInvalidation || reviewVerdictFallback && reviewVerdictFallback !== 'entry')
  ){
    return {valid:false, reason:'missing_actionable_plan', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(
    reviewResolverVerdict === 'avoid'
    && (fresherScannerInvalidation || reviewVerdictFallback && reviewVerdictFallback !== 'entry')
  ){
    return {valid:false, reason:'current_review_resolver_avoid', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(reviewVerdictFallback && reviewVerdictFallback !== 'entry'){
    return {valid:false, reason:'explicit_review_downgrade', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  if(fresherScannerInvalidation){
    return {valid:false, reason:'fresher_scanner_downgrade', precedence, reviewResolverVerdict, reviewVerdictFallback};
  }
  return {
    valid:true,
    reason:'no_fresher_invalidating_state',
    precedence,
    reviewResolverVerdict,
    reviewVerdictFallback
  };
}

function persistReviewProjectionSnapshotOnRecord(record, snapshot){
  const item = record && typeof record === 'object' ? record : null;
  const safeSnapshot = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(!item || !safeSnapshot) return false;
  const ticker = normalizeTicker(item.ticker || '');
  if(!ticker || !hasPresentationAuthoritySnapshot(safeSnapshot, ticker)) return false;
  item.review = item.review && typeof item.review === 'object' ? item.review : {};
  const nextSnapshot = projectionSnapshotWithAuthority(cloneData(safeSnapshot, null), item);
  const previousSerialized = JSON.stringify(item.review.savedProjectionSnapshot || null);
  const nextSerialized = JSON.stringify(nextSnapshot || null);
  if(previousSerialized === nextSerialized) return false;
  writeSavedReviewAuthority(item, {savedProjectionSnapshot:nextSnapshot}, {clearProjectionWhenNonEntry:false});
  commitTickerState();
  return true;
}

function syncPersistedReviewEntryVerdict(record, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return false;
  const ticker = normalizeTicker(item.ticker || '');
  if(!ticker) return false;
  const explicitSnapshot = options.snapshot && typeof options.snapshot === 'object'
    ? options.snapshot
    : null;
  const snapshot = projectionSnapshotWithAuthority(
    explicitSnapshot || buildStableReviewProjectionSnapshot(item, 'watchlist_add_projection'),
    item
  );
  const snapshotVerdict = normalizeGlobalVerdictKey(
    options.savedVerdict
    || (
    snapshot && (
      snapshot.canonicalVerdict
      || snapshot.finalVerdict
      || snapshot.renderedVerdict
    )
    )
  );
  if(snapshotVerdict !== 'entry') return false;
  const previousSavedVerdict = String(item.review && item.review.savedVerdict || '').trim();
  const previousSnapshotSerialized = JSON.stringify(item.review && item.review.savedProjectionSnapshot || null);
  const nextSnapshotSerialized = JSON.stringify(snapshot || null);
  writeSavedReviewAuthority(item, {
    savedVerdict:'Entry',
    savedProjectionSnapshot:snapshot
  }, {
    clearProjectionWhenNonEntry:false
  });
  return previousSavedVerdict !== 'Entry' || previousSnapshotSerialized !== nextSnapshotSerialized;
}

function persistedReviewProjectionSnapshot(record, context = 'startup_review_projection'){
  const item = record && typeof record === 'object' ? record : null;
  const normalizedItem = normalizeTickerRecordReadOnly(record || {});
  const evaluationTarget = item || normalizedItem;
  const ticker = normalizeTicker(normalizedItem.ticker || '');
  if(!ticker) return null;
  const savedReviewVerdict = normalizeGlobalVerdictKey(
    normalizedItem.review && normalizedItem.review.savedVerdict || ''
  );
  if(savedReviewVerdict && savedReviewVerdict !== 'entry'){
    clearPersistedReviewProjectionState(item || evaluationTarget, {clearSavedVerdict:false});
    return null;
  }
  const storedSnapshot = reviewStoredProjectionSnapshot(evaluationTarget);
  if(storedSnapshot){
    const validity = evaluatePersistedReviewProjectionValidity(evaluationTarget, storedSnapshot, context);
    if(validity.valid){
      return projectionSnapshotWithAuthority(storedSnapshot, evaluationTarget, {
        restoreAuthorityMode:'persisted_display_context'
      });
    }
    clearPersistedReviewProjectionState(item || evaluationTarget, {clearSavedVerdict:true});
  }
  return null;
}

function logReviewOpenMutationTrace(ticker, writerPath, beforeSnapshot, afterSnapshot){
  if(!isPerfDebugVerbose()) return;
  const watchedKeys = [
    'canonicalVerdictKey',
    'reviewSavedVerdict',
    'reviewSavedSummary',
    'reviewSavedScore',
    'manualReviewStatus',
    'finalVerdict',
    'globalVerdict',
    'displayStage',
    'lifecycleState',
    'planEntry',
    'planStop',
    'planTarget',
    'structureState',
    'bounceState'
  ];
  const changed = watchedKeys.filter(key => String(beforeSnapshot && beforeSnapshot[key]) !== String(afterSnapshot && afterSnapshot[key]));
  console.info('[VerdictDriftTrace]', {
    ticker:normalizeTicker(ticker),
    surface:String((afterSnapshot && afterSnapshot.context) || (beforeSnapshot && beforeSnapshot.context) || 'review_open'),
    context:String((afterSnapshot && afterSnapshot.context) || (beforeSnapshot && beforeSnapshot.context) || 'review_open'),
    writerPath:String(writerPath || ''),
    canonicalBefore:String(beforeSnapshot && beforeSnapshot.canonicalVerdictKey || ''),
    canonicalAfter:String(afterSnapshot && afterSnapshot.canonicalVerdictKey || ''),
    changedFields:changed,
    before:beforeSnapshot || {},
    after:afterSnapshot || {}
  });
}

function setActiveReviewSourceProjectionSnapshot(ticker, snapshot, sourceContext){
  const symbol = normalizeTicker(ticker);
  uiState.activeReviewSourceProjectionSnapshot = null;
  uiState.activeReviewProjectionSource = 'non_watchlist_direct_resolve';
  if(!symbol) return;
  const context = String(sourceContext || '').trim().toLowerCase();
  const provided = snapshot && typeof snapshot === 'object' ? snapshot : null;
  if(provided){
    const snapshotTicker = normalizeTicker(provided.ticker || '');
    if(snapshotTicker && snapshotTicker === symbol){
      const hasPresentationAuthority = hasPresentationAuthoritySnapshot(provided, symbol);
      const hasCurrentProjectionMetadata = (
        Number.isFinite(Number(provided.setupScore))
        && !!String(provided.capturedAt || '').trim()
      ) || ['stable_record_snapshot'].includes(String(provided.source || '').trim().toLowerCase());
      uiState.activeReviewSourceProjectionSnapshot = {
        ...provided,
        ticker:symbol
      };
      uiState.activeReviewProjectionSource = hasPresentationAuthority && hasCurrentProjectionMetadata
        ? 'clicked_card_snapshot'
        : 'scanner_score_snapshot';
      return;
    }
    console.warn('[TickerStateSource][Warning]', {
      ticker:symbol,
      code:'stale_review_projection_snapshot_discarded',
      snapshotTicker:snapshotTicker || '(none)',
      sourceContext:context || '(none)'
    });
  }
  if(context === 'watchlist'){
    uiState.activeReviewProjectionSource = 'snapshot_missing_fallback';
    console.warn('[TickerStateSource][Warning]', {
      ticker:symbol,
      code:'missing_review_projection_snapshot',
      sourceContext:'watchlist'
    });
  }
}

function maybeInvalidateActiveReviewProjectionFromTrack(ticker, nextProjectionSnapshot, reason = 'track_projection_changed'){
  void ticker;
  void nextProjectionSnapshot;
  void reason;
  /*
    Track/shared presentation is display-only.
    It must never invalidate, repaint, or soften active Review authority.
  */
  return {invalidated:false, rerendered:false, reason:'track_presentation_display_only'};
}

function loadTickerIntoReview(ticker, options = {}){
  const symbol = normalizeTicker(ticker);
  if(!symbol) return;
  const summarizeReviewOpenRequestStack = () => {
    try{
      const rawStack = String(new Error().stack || '');
      if(!rawStack) return '';
      return rawStack
        .split('\n')
        .slice(2, 8)
        .map(line => line.trim())
        .filter(Boolean)
        .join(' | ');
    }catch(_error){
      return '';
    }
  };
  const currentPending = uiState.pendingReviewRequest && typeof uiState.pendingReviewRequest === 'object'
    ? uiState.pendingReviewRequest
    : null;
  const currentPendingTicker = normalizeTicker(currentPending && currentPending.ticker || '');
  const currentPendingToken = String(currentPending && currentPending.reviewRequestToken || '');
  if(currentPending && !currentPending.superseded && currentPendingTicker === symbol){
    if(typeof console !== 'undefined' && console.info){
      console.info('[REVIEW_PENDING_DUPLICATE_SUPPRESSED]', {
        requestedTicker:symbol,
        reviewRequestToken:currentPendingToken,
        loadStarted:currentPending.loadStarted === true,
        source:String(options.sourceContext || ''),
        activeTicker:activeReviewTicker() || '',
        pendingTicker:pendingReviewTicker() || '',
        queuedTicker:uiState.queuedReviewTicker || ''
      });
    }
    reviewTickerOwnershipTrace('duplicate_pending_review_suppressed', {
      requestedTicker:symbol,
      renderedTicker:activeReviewTicker() || '',
      statusText:'duplicate_pending_review_request'
    });
    return;
  }
  const reviewRequestToken = String(options.reviewRequestToken || nextReviewRequestToken());
  uiState.activeReviewScoreTransportSnapshot = null;
  uiState.activeTrackScoreTransportToken = '';
  setActiveWorkspaceTab('review', {focusTop:false});
  const reviewSeq = nextReviewRenderSeq();
  uiState.reviewLoadToken = Number(uiState.reviewLoadToken || 0) + 1;
  const reviewLoadToken = Number(uiState.reviewLoadToken || 0);
  setScannerCardClickTrace(symbol, 'loadTickerIntoReview.enter', `includeInScannerUniverse=${options.includeInScannerUniverse === true} recompute=${options.recompute === true}`);
  reviewTickerOwnershipTrace('review_open_request', {
    requestedTicker:symbol,
    renderedTicker:activeReviewTicker() || '',
    statusText:String(uiState.liveProcessStatus && uiState.liveProcessStatus.message || '')
  });
  if(typeof console !== 'undefined' && console.info){
    const pendingError = uiState.reviewPendingLoadError && typeof uiState.reviewPendingLoadError === 'object'
      ? uiState.reviewPendingLoadError
      : null;
    const previousTerminalErrorTicker = normalizeTicker(pendingError && pendingError.ticker || '');
    const previousTerminalErrorToken = String(pendingError && pendingError.reviewRequestToken || '');
    const queuedReviewTickerBefore = normalizeTicker(uiState.queuedReviewTicker || '');
    const pendingBefore = uiState.pendingReviewRequest && typeof uiState.pendingReviewRequest === 'object'
      ? uiState.pendingReviewRequest
      : null;
    const openTrigger = options.openTrigger && typeof options.openTrigger === 'object'
      ? options.openTrigger
      : {};
    console.info('[REVIEW_OPEN_REQUEST]', {
      requestedTicker:symbol,
      source:String(options.sourceContext || ''),
      isUserInitiated:openTrigger.userInitiated === true ? true : (openTrigger.userInitiated === false ? false : null),
      fromRetryButton:openTrigger.kind === 'retry_button',
      existingPendingTicker:currentPendingTicker || '',
      existingPendingToken:currentPendingToken || '',
      activeReviewTicker:activeReviewTicker() || '',
      pendingReviewTicker:pendingReviewTicker() || '',
      reviewRequestToken,
      liveStatus:String(uiState.liveProcessStatus && uiState.liveProcessStatus.state || ''),
      statusText:String(uiState.liveProcessStatus && uiState.liveProcessStatus.message || ''),
      source:String(options.sourceContext || ''),
      triggerKind:String(openTrigger.kind || ''),
      triggerEventType:String(openTrigger.eventType || ''),
      triggerIsTrusted:openTrigger.isTrusted === true ? true : (openTrigger.isTrusted === false ? false : null),
      userInitiated:openTrigger.userInitiated === true ? true : (openTrigger.userInitiated === false ? false : null),
      retryButtonClicked:openTrigger.kind === 'retry_button',
      previousTerminalErrorTicker,
      previousTerminalErrorToken,
      hadQueuedReviewTicker:!!queuedReviewTickerBefore,
      queuedReviewTickerBefore,
      pendingRequestTickerBefore:normalizeTicker(pendingBefore && pendingBefore.ticker || ''),
      pendingRequestTokenBefore:String(pendingBefore && pendingBefore.reviewRequestToken || ''),
      openRequestStack:summarizeReviewOpenRequestStack()
    });
  }
  const currentLiveState = uiState.liveProcessStatus && typeof uiState.liveProcessStatus === 'object'
    ? String(uiState.liveProcessStatus.state || '')
    : '';
  const refreshBusy = ['refreshing_watchlist','waiting_for_refresh_before_scan'].includes(currentLiveState)
    || startupCoordinator.startupWatchlistRefreshRunning === true;
  if(refreshBusy){
    const stableRecord = getTickerRecord(symbol) || upsertTickerRecord(symbol);
    const stableSnapshot = options.sourceProjectionSnapshot && typeof options.sourceProjectionSnapshot === 'object'
      ? options.sourceProjectionSnapshot
      : buildStableReviewProjectionSnapshot(stableRecord, 'review_open_during_refresh');
    if(stableSnapshot && !options.sourceProjectionSnapshot){
      options.sourceProjectionSnapshot = stableSnapshot;
    }
    if(typeof console !== 'undefined' && console.info){
      console.info('[REVIEW_OPEN_DURING_REFRESH]', {
        requestedTicker:symbol,
        source:String(options.sourceContext || ''),
        activeTicker:activeReviewTicker() || '',
        pendingTicker:pendingReviewTicker() || '',
        liveState:currentLiveState,
        hasStableSnapshot:!!stableSnapshot,
        sourceProjectionSnapshot:!!options.sourceProjectionSnapshot
      });
      if(stableSnapshot){
        console.info('[REVIEW_LOAD_FROM_STABLE_SNAPSHOT]', {
          requestedTicker:symbol,
          source:String(options.sourceContext || ''),
          activeTicker:activeReviewTicker() || '',
          pendingTicker:pendingReviewTicker() || '',
          snapshotTicker:normalizeTicker(stableSnapshot.ticker || ''),
          snapshotSource:String(stableSnapshot.source || 'stable_record_snapshot'),
          snapshotCapturedAt:String(stableSnapshot.capturedAt || '')
        });
      }
    }
  }
  if(!options.forceNow && isLiveProcessBusyState(currentLiveState)){
    queuePendingReviewRequest(symbol, {...options, reviewRequestToken});
    setScannerCardClickTrace(symbol, 'loadTickerIntoReview.deferred', `busy=${currentLiveState || '(none)'}`);
    return;
  }
  queuePendingReviewRequest(symbol, {...options, reviewRequestToken});
  const allowReviewLoadingStatus = !['running_scan','refreshing_watchlist','waiting_for_refresh_before_scan'].includes(currentLiveState);
  if(allowReviewLoadingStatus){
    setLiveProcessStatus('action', `Review pending: ${symbol}`, {deferPendingReviewFlush:true});
  }
  if(typeof console !== 'undefined' && console.info){
    console.info('[REVIEW_PENDING_WAIT]', {
      ticker:symbol,
      reviewRequestToken,
      reviewLoadToken,
      activeTicker:activeReviewTicker() || '',
      pendingTicker:pendingReviewTicker() || '',
      queuedTicker:uiState.queuedReviewTicker || '',
      currentLiveState
    });
  }
  const pendingForLoad = uiState.pendingReviewRequest && typeof uiState.pendingReviewRequest === 'object'
    ? uiState.pendingReviewRequest
    : null;
  if(pendingForLoad && normalizeTicker(pendingForLoad.ticker || '') === symbol && String(pendingForLoad.reviewRequestToken || '') === reviewRequestToken){
    pendingForLoad.loadStarted = true;
    pendingForLoad.loadStartedAt = new Date().toISOString();
  }
  const runReviewLoad = () => {
    if(reviewLoadToken !== Number(uiState.reviewLoadToken || 0)){
      if(String(options.sourceContext || '') === 'watchlist'){
        settleScannerSelectionStatusReviewPending(symbol, {superseded:true, reviewRequestToken});
      }
      clearPendingReviewRequest({
        reason:'stale',
        requestedTicker:symbol,
        reviewRequestToken
      });
      setScannerCardClickTrace(symbol, 'loadTickerIntoReview.stale_run_skipped', `token=${reviewLoadToken}`);
      return;
    }
    const record = upsertTickerRecord(symbol);
    uiState.pendingReviewCandidate = {
      ticker:symbol,
      reviewRequestToken,
      currentReviewRecordTicker:normalizeTicker(record.ticker || ''),
      chartTicker:normalizeTicker((record.review && record.review.chartRef && record.review.chartRef.ticker) || record.ticker || ''),
      source:String(options.sourceContext || ''),
      createdAt:new Date().toISOString()
    };
    if(typeof console !== 'undefined' && console.info){
      console.info('[REVIEW_PENDING_CANDIDATE_CREATED]', {
        ticker:symbol,
        reviewRequestToken,
        currentReviewRecordTicker:uiState.pendingReviewCandidate.currentReviewRecordTicker || '',
        chartTicker:uiState.pendingReviewCandidate.chartTicker || '',
        source:uiState.pendingReviewCandidate.source || '',
        activeTicker:activeReviewTicker() || '',
        pendingTicker:pendingReviewTicker() || ''
      });
    }
    reviewTickerOwnershipTrace('review_record_selected', {
      requestedTicker:symbol,
      renderedTicker:symbol,
      currentReviewRecordTicker:record.ticker || '',
      chartTicker:normalizeTicker((record.review && record.review.chartRef && record.review.chartRef.ticker) || record.ticker || ''),
      statusText:'review record selected'
    });
    if(typeof console !== 'undefined' && console.info){
      console.info('[REVIEW_RECORD_SELECTED]', {
        requestedTicker:symbol,
        activeReviewTicker:activeReviewTicker() || '',
        currentReviewRecordTicker:record.ticker || '',
        chartTicker:normalizeTicker((record.review && record.review.chartRef && record.review.chartRef.ticker) || record.ticker || ''),
        reviewRequestToken
      });
    }
    const simplifiedState = resolveSimplifiedStateForSurface(record, 'review', {log:false});
    uiState.activeReviewSimplifiedStatePreview = {
      ticker:simplifiedState.ticker || symbol,
      canonicalVerdict:simplifiedState.canonicalVerdict,
      visualBucket:simplifiedState.visualBucket,
      tone:simplifiedState.tone,
      badgeLabel:simplifiedState.badgeLabel,
      mainBlocker:simplifiedState.mainBlocker
    };
    const openBeforeSnapshot = reviewOpenMutationSnapshot(record, 'review_open');
    const readOnlyReviewOpen = options.recompute !== true;
    const inWatchlist = !!(record && record.watchlist && record.watchlist.inWatchlist);
    const sourceContext = String(options.sourceContext || '');
    const skipAutoScroll = options.skipAutoScroll === true;
    uiState.activeReviewAddsToScannerUniverse = options.includeInScannerUniverse !== false;
    uiState.activeReviewVerdictOverride = !readOnlyReviewOpen && options.useSourceVerdict !== false
      ? reviewVerdictOverrideFromLabel(options.sourceVerdict || '')
      : '';
    setActiveReviewSourceProjectionSnapshot(symbol, options.sourceProjectionSnapshot, sourceContext);
    setActiveReviewTicker(symbol);
    record.review.cardOpen = true;
    refreshTrackedTickerState(symbol, {
      source:'review',
      reason:'review_open',
      force:true,
      persist:true,
      emitTrace:true
    });
    if(options.includeInScannerUniverse === true && !state.tickers.includes(symbol)) state.tickers.push(symbol);
    const selectedBefore = !!uiState.selectedScanner[symbol];
    delete uiState.selectedScanner[symbol];
    const shouldRefreshScannerSurfaces = (
      options.includeInScannerUniverse === true
      || sourceContext === 'scanner'
      || selectedBefore
    );
    updateTickerInputFromState();
    commitTickerState();
    try{
      if(shouldRefreshScannerSurfaces){
        renderTickerQuickLists();
        renderScannerResults();
      }
      setScannerCardClickTrace(
        symbol,
        'loadTickerIntoReview.before_loadCard',
        `activeReviewTicker=${uiState.activeReviewTicker || '(none)'} scanner_refresh=${shouldRefreshScannerSurfaces ? 'yes' : 'no'}`
      );
      let requestSettled = false;
      const settleReviewOwnershipPromotion = () => {
        const liveRecord = getTickerRecord(symbol) || record;
        const currentReviewRecordTicker = normalizeTicker((liveRecord && liveRecord.ticker) || '');
        const chartTicker = normalizeTicker((liveRecord && liveRecord.review && liveRecord.review.chartRef && liveRecord.review.chartRef.ticker) || currentReviewRecordTicker || '');
        const pendingNow = uiState.pendingReviewRequest && typeof uiState.pendingReviewRequest === 'object'
          ? uiState.pendingReviewRequest
          : null;
        const pendingTokenNow = String(pendingNow && pendingNow.reviewRequestToken || '');
        const pendingTickerNow = normalizeTicker((pendingNow && pendingNow.ticker) || pendingReviewTicker() || '');
        const tokenValidation = canPromoteRequestedReviewFromPending(symbol, reviewRequestToken);
        const tokenStillCurrent = (
          reviewLoadToken === Number(uiState.reviewLoadToken || 0)
          && tokenValidation.ok
        );
        const hasReviewRecord = !!liveRecord && !!currentReviewRecordTicker;
        const recordMatchesRequestedTicker = currentReviewRecordTicker === symbol;
        if(!hasReviewRecord || !recordMatchesRequestedTicker || !tokenStillCurrent){
          if(typeof console !== 'undefined' && console.info){
            console.info('[REVIEW_RECORD_READY_REJECTED]', {
              requestedTicker:symbol,
              currentReviewRecordTicker,
              chartTicker,
              hasReviewRecord,
              recordMatchesRequestedTicker,
              tokenStillCurrent,
              pendingExists:!!pendingNow,
              pendingFailed:!!(pendingNow && pendingNow.failedAt),
              pendingSuperseded:!!(pendingNow && pendingNow.superseded),
              tokenValidationReason:tokenValidation.reason || '',
              reviewRequestToken,
              pendingToken:pendingTokenNow || '',
              reviewLoadToken,
              activeTicker:activeReviewTicker() || '',
              pendingTicker:pendingTickerNow || ''
            });
          }
          return false;
        }
        if(typeof console !== 'undefined' && console.info){
          console.info('[REVIEW_RECORD_READY]', {
            requestedTicker:symbol,
            currentReviewRecordTicker,
            chartTicker,
            hasReviewRecord,
            recordMatchesRequestedTicker,
            tokenStillCurrent,
            reviewRequestToken,
            reviewLoadToken,
            activeTicker:activeReviewTicker() || '',
            pendingTicker:pendingTickerNow || ''
          });
        }
        if(typeof console !== 'undefined' && console.info){
          console.info('[REVIEW_OWNERSHIP_PROMOTION_START]', {
            requestedTicker:symbol,
            currentReviewRecordTicker,
            chartTicker,
            hasReviewRecord,
            reviewRequestToken,
            reviewLoadToken,
            activeTicker:activeReviewTicker() || '',
            pendingTicker:pendingTickerNow || ''
          });
        }
        setActiveReviewTicker(symbol);
        uiState.lastResolvedReviewTicker = symbol;
        uiState.lastResolvedReviewRequestToken = reviewRequestToken;
        const candidate = pendingReviewCandidate();
        clearPendingReviewRequest({
          reason:'completed',
          requestedTicker:symbol,
          reviewRequestToken
        });
        if(typeof console !== 'undefined' && console.info){
          console.info('[REVIEW_PENDING_CANDIDATE_PROMOTED]', {
            ticker:symbol,
            reviewRequestToken,
            candidateTicker:normalizeTicker(candidate && candidate.ticker || ''),
            candidateToken:String(candidate && candidate.reviewRequestToken || ''),
            activeTicker:activeReviewTicker() || ''
          });
        }
        requestSettled = true;
        clearReviewPendingTimeout();
        if(typeof console !== 'undefined' && console.info){
          console.info('[REVIEW_TIMEOUT_CANCELLED]', {
            requestedTicker:symbol,
            reviewRequestToken,
            reviewLoadToken
          });
          console.info('[REVIEW_OWNERSHIP_PROMOTED]', {
            ticker:symbol,
            reviewRequestToken,
            reviewLoadToken,
            activeTicker:activeReviewTicker() || '',
            pendingTicker:pendingReviewTicker() || '',
            currentReviewRecordTicker
          });
        }
        return true;
      };
      const completeLoad = () => {
        if(!isCurrentReviewRender(reviewSeq)){
          if(sourceContext === 'watchlist'){
            settleScannerSelectionStatusReviewPending(symbol, {superseded:true, reviewRequestToken});
          }
          clearPendingReviewRequest({
            reason:'stale',
            requestedTicker:symbol,
            reviewRequestToken
          });
          setScannerCardClickTrace(symbol, 'loadTickerIntoReview.stale_complete_skipped', `reviewSeq=${reviewSeq}`);
          return;
        }
        if(reviewLoadToken !== Number(uiState.reviewLoadToken || 0)){
          if(sourceContext === 'watchlist'){
            settleScannerSelectionStatusReviewPending(symbol, {superseded:true, reviewRequestToken});
          }
          clearPendingReviewRequest({
            reason:'stale',
            requestedTicker:symbol,
            reviewRequestToken
          });
          setScannerCardClickTrace(symbol, 'loadTickerIntoReview.stale_complete_skipped', `token=${reviewLoadToken}`);
          return;
        }
        try{
          settleReviewOwnershipPromotion();
          if(typeof console !== 'undefined' && console.info){
            const renderStartPayload = {
              ticker:symbol,
              reviewRequestToken,
              reviewLoadToken,
              activeTicker:activeReviewTicker() || '',
              pendingTicker:pendingReviewTicker() || '',
              currentReviewRecordTicker:(getTickerRecord(symbol) || record).ticker || ''
            };
            if(requestSettled){
              console.info('[REVIEW_RENDER_START_AFTER_PROMOTION]', renderStartPayload);
            }else{
              console.info('[REVIEW_RENDER_START_WITHOUT_PROMOTION]', {
                ...renderStartPayload,
                promoted:false
              });
            }
          }
          loadCard(symbol, {
            touchLifecycle:options.recompute === true,
            recompute:options.recompute === true,
            skipAutoScroll,
            preScrolled:true,
            reviewRenderSeq:reviewSeq
          });
          const stillCurrentToken = reviewLoadToken === Number(uiState.reviewLoadToken || 0);
          const pendingError = uiState.reviewPendingLoadError && typeof uiState.reviewPendingLoadError === 'object'
            ? uiState.reviewPendingLoadError
            : null;
          const pendingErrorMatches = !!(pendingError && normalizeTicker(pendingError.ticker || '') === symbol && String(pendingError.reviewRequestToken || '') === reviewRequestToken);
          if(!stillCurrentToken || pendingErrorMatches){
            if(typeof console !== 'undefined' && console.info){
              console.info('[REVIEW_PENDING_SUCCESS_IGNORED_STALE]', {
                ticker:symbol,
                reviewRequestToken,
                reviewLoadToken,
                currentReviewLoadToken:Number(uiState.reviewLoadToken || 0),
                pendingError:pendingErrorMatches ? pendingError.message || '' : '',
                activeTicker:activeReviewTicker() || '',
                pendingTicker:pendingReviewTicker() || ''
              });
            }
            if(!pendingErrorMatches){
              if(sourceContext === 'watchlist'){
                settleScannerSelectionStatusReviewPending(symbol, {failed:true, reviewRequestToken});
              }
              clearPendingReviewRequest({
                reason:'stale',
                requestedTicker:symbol,
                reviewRequestToken
              });
            }
            setScannerCardClickTrace(symbol, 'loadTickerIntoReview.stale_success_skipped', `token=${reviewLoadToken}`);
            return;
          }
          if(!requestSettled) clearReviewPendingTimeout();
          uiState.reviewPendingLoadError = null;
          if(typeof console !== 'undefined' && console.info){
            console.info('[REVIEW_PENDING_SUCCESS_WON]', {
              ticker:symbol,
              reviewRequestToken,
              reviewLoadToken,
              activeTicker:activeReviewTicker() || '',
              pendingTicker:pendingReviewTicker() || ''
            });
          }
          if(!requestSettled) settleReviewOwnershipPromotion();
          if(typeof console !== 'undefined' && console.info){
            console.info('[REVIEW_RENDER_POST_PROMOTION_ATTEMPT]', {
              ticker:symbol,
              reviewRequestToken,
              reviewLoadToken,
              activeTicker:activeReviewTicker() || '',
              pendingTicker:pendingReviewTicker() || '',
              currentReviewRecordTicker:(getTickerRecord(symbol) || record).ticker || '',
              promoted:requestSettled
            });
          }
          const openAfterSnapshot = reviewOpenMutationSnapshot(getTickerRecord(symbol) || record, 'review_open');
          logReviewOpenMutationTrace(symbol, 'loadTickerIntoReview.completeLoad.loadCard', openBeforeSnapshot, openAfterSnapshot);
          if(allowReviewLoadingStatus && !(inWatchlist && sourceContext === 'scanner')){
            scheduleReviewLoadedStatus(symbol);
          }
          if(sourceContext === 'watchlist'){
            settleScannerSelectionStatusReviewPending(symbol, {failed:false, reviewRequestToken});
          }
          if(inWatchlist && sourceContext === 'scanner'){
            setLiveProcessStatus('action', 'item already in watchlist', {autoIdleMs:LIVE_PROCESS_IDLE_FADE_MS});
            setScannerCardClickTrace(symbol, 'loadTickerIntoReview.watchlist_status', 'item already in watchlist');
          }
          setScannerCardClickTrace(symbol, 'loadTickerIntoReview.post_loadCard', 'review_loaded');
        }catch(error){
          if(sourceContext === 'watchlist'){
            settleScannerSelectionStatusReviewPending(symbol, {failed:true, reviewRequestToken});
          }
          clearPendingReviewRequest({
            reason:'failed',
            requestedTicker:symbol,
            reviewRequestToken
          });
          if(allowReviewLoadingStatus){
            setLiveProcessStatus('error', 'Review load failed.', {autoIdleMs:LIVE_PROCESS_IDLE_FADE_MS});
          }
          setScannerCardClickTrace(symbol, 'loadTickerIntoReview.post_render_error', error && error.message ? error.message : 'unknown_error');
        }
      };
      completeLoad();
    }catch(error){
      if(sourceContext === 'watchlist'){
        settleScannerSelectionStatusReviewPending(symbol, {failed:true, reviewRequestToken});
      }
      clearPendingReviewRequest({
        reason:'failed',
        requestedTicker:symbol,
        reviewRequestToken
      });
      if(allowReviewLoadingStatus){
        setLiveProcessStatus('error', 'Review load failed.', {autoIdleMs:LIVE_PROCESS_IDLE_FADE_MS});
      }
      setScannerCardClickTrace(symbol, 'loadTickerIntoReview.post_render_error', error && error.message ? error.message : 'unknown_error');
      throw error;
    }
  };
  if(typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function'){
    window.requestAnimationFrame(() => {
      if(!isCurrentReviewRender(reviewSeq)) return;
      runReviewLoad();
    });
  }else{
    setTimeout(() => {
      if(!isCurrentReviewRender(reviewSeq)) return;
      runReviewLoad();
    }, 0);
  }
}

function scheduleReviewLoadedStatus(ticker){
  const symbol = normalizeTicker(ticker);
  if(!symbol) return;
  const applyLoadedStatus = () => {
    const current = uiState.liveProcessStatus && typeof uiState.liveProcessStatus === 'object'
      ? uiState.liveProcessStatus
      : {state:'', message:''};
    const currentState = String(current.state || '');
    const currentMessage = String(current.message || '');
    if(isLiveProcessBusyState(currentState)) return;
    if(!/^review pending:/i.test(currentMessage)) return;
    setLiveProcessStatus('action', `Review loaded: ${symbol}`, {autoIdleMs:LIVE_PROCESS_IDLE_FADE_MS});
  };
  if(typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function'){
    window.requestAnimationFrame(() => applyLoadedStatus());
  }else{
    setTimeout(() => applyLoadedStatus(), 0);
  }
}

function openRankedResultInReview(ticker, options = {}){
  setScannerCardClickTrace(ticker, 'openRankedResultInReview.enter', `sourceVerdict=${options.sourceVerdict || '(none)'}`);
  const symbol = normalizeTicker(ticker);
  uiState.activeReviewScoreTransportSnapshot = null;
  uiState.activeTrackScoreTransportToken = '';
  loadTickerIntoReview(ticker, {
    includeInScannerUniverse:options.includeInScannerUniverse === true,
    recompute:options.recompute === true,
    sourceVerdict:options.sourceVerdict || '',
    sourceContext:'scanner',
    openTrigger:options.openTrigger && typeof options.openTrigger === 'object'
      ? options.openTrigger
      : null
  });
}

function resumeSavedReviewTicker(ticker){
  const symbol = normalizeTicker(ticker);
  if(typeof console !== 'undefined' && console.info){
    console.info('[REVIEW_RESUME_CLICK]', {
      requestedTicker:symbol,
      activeReviewTicker:activeReviewTicker() || '',
      pendingReviewTicker:pendingReviewTicker() || ''
    });
  }
  if(!symbol){
    if(typeof console !== 'undefined' && console.warn){
      console.warn('[REVIEW_RESUME_LOAD_BLOCKED]', {
        requestedTicker:'',
        reason:'invalid_ticker'
      });
    }
    return;
  }
  const record = getTickerRecord(symbol);
  if(!record || normalizeTicker(record.ticker || '') !== symbol){
    if(typeof console !== 'undefined' && console.warn){
      console.warn('[REVIEW_RESUME_RECORD_MISSING]', {
        requestedTicker:symbol,
        activeReviewTicker:activeReviewTicker() || '',
        pendingReviewTicker:pendingReviewTicker() || '',
        currentRecordTicker:record && record.ticker || ''
      });
      console.warn('[REVIEW_RESUME_LOAD_BLOCKED]', {
        requestedTicker:symbol,
        reason:'missing_saved_review_record'
      });
    }
    uiState.reviewPendingLoadError = {
      ticker:symbol,
      reviewRequestToken:'',
      message:`Saved review for ${symbol} is missing or unavailable. Remove it and reopen the ticker.`,
      setAt:new Date().toISOString()
    };
    setLiveProcessStatus('error', uiState.reviewPendingLoadError.message, {autoIdleMs:LIVE_PROCESS_IDLE_FADE_MS});
    renderReviewWorkspace({source:'review_resume_missing_record', requestedTicker:symbol});
    return;
  }
  if(typeof console !== 'undefined' && console.info){
    console.info('[REVIEW_RESUME_RECORD_FOUND]', {
      requestedTicker:symbol,
      currentRecordTicker:record.ticker || '',
      activeReviewTicker:activeReviewTicker() || '',
      pendingReviewTicker:pendingReviewTicker() || ''
    });
    console.info('[REVIEW_RESUME_LOAD_STARTED]', {
      requestedTicker:symbol,
      activeReviewTicker:activeReviewTicker() || '',
      pendingReviewTicker:pendingReviewTicker() || '',
      reviewLoadToken:Number(uiState.reviewLoadToken || 0)
    });
  }
  uiState.reviewPendingLoadError = null;
  setActiveReviewTicker(symbol);
  loadTickerIntoReview(symbol, {
    includeInScannerUniverse:false,
    recompute:false,
    sourceContext:'review_resume',
    forceNow:true,
    openTrigger:{
      kind:'resume_saved_review',
      eventType:'resume',
      userInitiated:true,
      isTrusted:null
    }
  });
}

function reviewWatchlistTicker(ticker, options = {}){
  const symbol = normalizeTicker(ticker);
  if(!symbol) return;
  const record = getTickerRecord(symbol) || upsertTickerRecord(symbol);
  const simplifiedState = resolveSimplifiedStateForSurface(record, 'review', {log:false});
  uiState.activeReviewSimplifiedStatePreview = {
    ticker:simplifiedState.ticker || symbol,
    canonicalVerdict:simplifiedState.canonicalVerdict,
    visualBucket:simplifiedState.visualBucket,
    tone:simplifiedState.tone,
    badgeLabel:simplifiedState.badgeLabel,
    mainBlocker:simplifiedState.mainBlocker
  };
  const sourceVerdict = reviewVerdictOverrideFromView(projectTickerForCard(record));
  const providedSnapshot = options.sourceProjectionSnapshot && typeof options.sourceProjectionSnapshot === 'object'
    ? options.sourceProjectionSnapshot
    : null;
  const sourceProjectionSnapshot = providedSnapshot
    ? {...providedSnapshot}
    : null;
  const reviewRequestToken = nextReviewRequestToken();
  setScannerSelectionStatusReviewPending(symbol, {reviewRequestToken, sourceContext:'watchlist'});
  loadTickerIntoReview(symbol, {
    includeInScannerUniverse:false,
    recompute:false,
    sourceVerdict,
    sourceContext:'watchlist',
    reviewRequestToken,
    sourceProjectionSnapshot,
    openTrigger:options.openTrigger && typeof options.openTrigger === 'object'
      ? options.openTrigger
      : {
        kind:'watchlist_review',
        eventType:'click',
        userInitiated:true,
        isTrusted:null
      }
  });
}

const trackedTickerRefreshRuntime = {
  inFlight:new Set(),
  lastRunAt:new Map()
};
const TRACKED_TICKER_REFRESH_COOLDOWN_MS = 450;

function buildResolvedStateBundleFromRecord(record, options = {}){
  const liveRecord = record && typeof record === 'object' ? record : upsertTickerRecord(normalizeTicker(record && record.ticker));
  const item = normalizeDetachedTickerRecord(liveRecord && typeof liveRecord === 'object' ? liveRecord : {});
  const source = String(options.source || 'track');
  const sourceSurface = String(options.sourceSurface || source || 'track');
  const reason = String(options.reason || source);
  const context = 'shared_refresh';
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const effectivePlan = effectivePlanForRecord(item, {allowScannerFallback:true});
  const displayedPlan = deriveCurrentPlanState(
    effectivePlan.entry,
    effectivePlan.stop,
    effectivePlan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const qualityAdjustments = evaluateSetupQualityAdjustments(item, {displayedPlan, derivedStates});
  const warningState = evaluateWarningState(item);
  const preserveScanAuthorityPath = shouldPreserveScanAuthorityCanonicalPath(item);
  const resolvedContract = preserveScanAuthorityPath
    ? resolvePreLifecycleStateContract(item, {
      context,
      derivedStates,
      effectivePlan,
      displayedPlan
    })
    : resolveFinalStateContract(item, {
      context,
      derivedStates,
      displayedPlan,
      qualityAdjustments,
      warningState
    });
  const setupScore = setupScoreForRecord(item);
  const globalVerdict = resolveGlobalVerdict(item);
  const visualState = resolveVisualState(item, 'watchlist', {
    resolvedContract,
    derivedStates,
    displayedPlan,
    setupScore
  });
  const provisionalLifecycleSnapshot = watchlistLifecycleSnapshot(item);
  const planVerdictContract = buildCanonicalPlanVerdictContract(item, {
    surface:sourceSurface,
    source,
    reason,
    derivedStates,
    effectivePlan,
    displayedPlan,
    resolvedContract,
    visualState,
    globalVerdict,
    lifecycleSnapshot:provisionalLifecycleSnapshot,
    setupScore
  });
  const canonicalVerdictKey = normalizeGlobalVerdictKey(planVerdictContract && planVerdictContract.canonicalVerdict || 'watch');
  const visualBucketForCheck = String(visualState.visualBucket || visualState.presentationBucket || '').trim().toLowerCase();
  if(!isAllowedCanonicalVisualPair(canonicalVerdictKey, visualBucketForCheck)){
    console.warn('[STATE_CONTRADICTION]', {
      ticker:item.ticker,
      source:'buildResolvedStateBundleFromRecord',
      canonicalVerdict:canonicalVerdictKey,
      visualBucket:visualBucketForCheck
    });
  }
  const canonicalContract = {
    canonicalVerdictKey,
    presentationLabel:verdictPresentationLabelForKey(canonicalVerdictKey),
    lifecycleState:String(planVerdictContract && planVerdictContract.lifecycleAuthority && planVerdictContract.lifecycleAuthority.state || resolvedContract && resolvedContract.structuralState || ''),
    bucket:String(planVerdictContract && planVerdictContract.canonicalVisualBucket || resolvedContract && resolvedContract.bucket || ''),
    tone:String(visualState && visualState.tone || resolvedContract && resolvedContract.actionTone || ''),
    reason:String(
      (resolvedContract && resolvedContract.reasonParts && resolvedContract.reasonParts[0])
      || (resolvedContract && resolvedContract.actionLabel)
      || ''
    ),
    blockers:Array.isArray(resolvedContract && resolvedContract.reasonParts)
      ? resolvedContract.reasonParts.slice(0, 3)
      : [],
    sourceTrace:{
      context,
      sourceSurface,
      resolver:'resolveFinalStateContract',
      planSource:String(effectivePlan && effectivePlan.source || '')
    },
    planVerdictContract,
    contractFingerprint:String(planVerdictContract && planVerdictContract.contractFingerprint || '')
  };
  const simplifiedStateSurface = String(sourceSurface || '').trim().toLowerCase() === 'review'
    ? 'review'
    : 'track';
  const resolvedSimplifiedState = resolveSimplifiedStateForSurface(item, simplifiedStateSurface, {
    log:false,
    source,
    reason
  });
  const simplifiedState = simplifiedStateSurface === 'review'
    ? applyReviewWatchlistSoftReadinessDisplayOverride(
      item,
      resolvedSimplifiedState,
      globalVerdict,
      watchlistLifecycleSnapshot(item)
    )
    : resolvedSimplifiedState;
  const persistedPresentation = persistTrackPresentationOnRecord(liveRecord, {
    resolvedContract,
    visualState,
    globalVerdict,
    derivedStates,
    effectivePlan,
    displayedPlan,
    qualityAdjustments,
    warningState,
    simplifiedState,
    presentationProjectionSnapshot:options.presentationProjectionSnapshot || null,
    presentationProjectionSource:options.presentationProjectionSource || '',
    allowTrackProjection:options.allowTrackProjection === true,
    source,
    sourceSurface,
    reason
  }, {source, sourceSurface, reason});
  const lifecycleSnapshot = syncWatchlistLifecycle(liveRecord) || watchlistLifecycleSnapshot(liveRecord);
  if(canonicalContract.planVerdictContract && canonicalContract.planVerdictContract.lifecycleAuthority){
    canonicalContract.planVerdictContract.lifecycleAuthority = {
      ...canonicalContract.planVerdictContract.lifecycleAuthority,
      stage:String(lifecycleSnapshot.stage || canonicalContract.planVerdictContract.lifecycleAuthority.stage || ''),
      status:String(lifecycleSnapshot.status || canonicalContract.planVerdictContract.lifecycleAuthority.status || ''),
      state:String(lifecycleSnapshot.state || canonicalContract.planVerdictContract.lifecycleAuthority.state || '')
    };
  }
  return {
    record:liveRecord,
    normalizedRecordSnapshot:item,
    canonicalContract,
    resolvedContract,
    visualState,
    globalVerdict,
    lifecycleSnapshot,
    simplifiedState,
    persistedPresentation,
    derivedStates,
    effectivePlan,
    displayedPlan,
    qualityAdjustments,
    warningState,
    source,
    sourceSurface,
    reason
  };
}

function toResolvedStateBundleCache(bundle){
  const safeBundle = bundle && typeof bundle === 'object' ? bundle : {};
  const cacheRecord = safeBundle.record && typeof safeBundle.record === 'object'
    ? safeBundle.record
    : {};
  return {
    schemaVersion:'resolved-state-bundle-cache-v2',
    inputFingerprint:resolvedStateBundleInputFingerprint(cacheRecord, {
      surface:safeBundle.sourceSurface || safeBundle.source || 'track',
      source:safeBundle.source || 'track',
      reason:safeBundle.reason || 'track'
    }),
    contractFingerprint:String(
      safeBundle.canonicalContract
      && safeBundle.canonicalContract.planVerdictContract
      && safeBundle.canonicalContract.planVerdictContract.contractFingerprint
      || ''
    ),
    canonicalContract:safeBundle.canonicalContract || null,
    resolvedContract:safeBundle.resolvedContract || null,
    visualState:safeBundle.visualState || null,
    globalVerdict:safeBundle.globalVerdict || null,
    lifecycleSnapshot:safeBundle.lifecycleSnapshot || null,
    effectivePlan:safeBundle.effectivePlan || null,
    displayedPlan:safeBundle.displayedPlan || null,
    qualityAdjustments:safeBundle.qualityAdjustments || null,
    warningState:safeBundle.warningState || null,
    derivedStates:safeBundle.derivedStates || null,
    source:String(safeBundle.source || ''),
    sourceSurface:String(safeBundle.sourceSurface || ''),
    reason:String(safeBundle.reason || '')
  };
}

