function syncReviewDomToCanonicalAuthority(record){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return;
  const health = currentReviewStateHealthSnapshot(item);
  if(!health || typeof health !== 'object') return;
  const verdictKey = normalizeGlobalVerdictKey(health.canonicalVerdict || 'watch');
  const badgeNode = document.querySelector('#reviewWorkspace .review-summary-badges .badge');
  const tradePlanInputs = $('tradePlanInputs');
  const capitalFitMetric = $('capitalFitMetric');
  const positionSizeStat = $('positionSizeStat');
  const fxBasisBox = $('fxBasisBox');
  const rrValueNode = $('rrValue');
  const entryInputValue = $('entryPrice') ? String($('entryPrice').value || '') : '';
  const stopInputValue = $('stopPrice') ? String($('stopPrice').value || '') : '';
  const targetInputValue = $('targetPrice') ? String($('targetPrice').value || '') : '';
  const canonicalEntryValue = item.plan && item.plan.entry != null ? String(item.plan.entry) : '';
  const canonicalStopValue = item.plan && item.plan.stop != null ? String(item.plan.stop) : '';
  const canonicalTargetValue = item.plan && item.plan.firstTarget != null ? String(item.plan.firstTarget) : '';
  const livePlannerInputsDiverged = entryInputValue !== canonicalEntryValue
    || stopInputValue !== canonicalStopValue
    || targetInputValue !== canonicalTargetValue;
  const livePlannerDisplayedPlan = applySetupConfirmationPlanGate(
    item,
    deriveCurrentPlanState(entryInputValue, stopInputValue, targetInputValue, item.marketData && item.marketData.currency)
  );
  const livePlannerNeedsReplan = livePlannerInputsDiverged && String(livePlannerDisplayedPlan.status || '').trim().toLowerCase() !== 'valid';
  if(badgeNode){
    const bucket = normalizeVisualBucketForPairing(health.visualBucket || verdictKey || 'monitor');
    const className = ({
      entry:'badge--entry ready',
      near_entry:'badge--near-entry near',
      monitor:'badge--monitor watch',
      diminishing:'badge--diminishing',
      avoid:'badge--avoid avoid'
    })[bucket] || 'badge--monitor watch';
    badgeNode.className = `badge ${className}`.trim();
    badgeNode.textContent = globalVerdictLabel(verdictKey || 'watch');
  }
  if(verdictKey === 'entry'){
    if(livePlannerNeedsReplan){
      if(rrValueNode) rrValueNode.textContent = 'No actionable plan yet.';
      return;
    }
    if($('tradeStatusBox')){
      $('tradeStatusBox').innerHTML = renderTradeStatusMarkup({
        line1:'Entry Ready',
        line2:'Execute only if the trigger remains valid.'
      });
    }
    if(tradePlanInputs) tradePlanInputs.classList.remove('review-hidden');
    if(capitalFitMetric) capitalFitMetric.classList.remove('review-hidden');
    if(positionSizeStat) positionSizeStat.classList.remove('review-hidden');
    if(fxBasisBox) fxBasisBox.classList.remove('review-hidden');
    if(rrValueNode){
      const displayedPlan = deriveCurrentPlanState(
        item.plan && item.plan.entry,
        item.plan && item.plan.stop,
        item.plan && item.plan.firstTarget,
        item.marketData && item.marketData.currency
      );
      rrValueNode.textContent = preferredReviewRrDisplay(item, displayedPlan, rrValueNode.textContent || 'No actionable plan yet.');
    }
    return;
  }
  if(verdictKey === 'near_entry' && String(health.planStatus || '').trim().toLowerCase() === 'valid'){
    if($('tradeStatusBox')){
      $('tradeStatusBox').innerHTML = renderTradeStatusMarkup({
        line1:'Near Entry - plan is defined, but confirmation is still required.',
        line2:'Wait for confirmation before entry.'
      });
    }
    if(tradePlanInputs) tradePlanInputs.classList.remove('review-hidden');
  }
}

function readImageDataUrlDimensions(dataUrl){
  return new Promise(resolve => {
    if(!dataUrl || typeof Image === 'undefined'){
      resolve({width:null, height:null});
      return;
    }
    const img = new Image();
    img.onload = () => resolve({
      width:Number.isFinite(img.naturalWidth) ? img.naturalWidth : null,
      height:Number.isFinite(img.naturalHeight) ? img.naturalHeight : null
    });
    img.onerror = () => resolve({width:null, height:null});
    img.src = dataUrl;
  });
}

function handleChartSelection(ticker, file, source = 'change_chart'){
  const statusBox = $('reviewWorkspaceStatus') || $(`cardStatus-${ticker}`);
  if(!file){
    if(statusBox) statusBox.innerHTML = '<span class="warntext">No chart selected.</span>';
    return;
  }
  if(!['image/png','image/jpeg'].includes(file.type)){
    if(statusBox) statusBox.innerHTML = '<span class="badtext">Use a PNG or JPG chart screenshot.</span>';
    return;
  }
  if(file.size > MAX_CHART_BYTES){
    if(statusBox) statusBox.innerHTML = `<span class="badtext">That image is ${escapeHtml(formatApproxBytes(file.size))}. Keep chart uploads under ${escapeHtml(formatApproxBytes(MAX_CHART_BYTES))}.</span>`;
    return;
  }
  const reader = new FileReader();
  reader.onload = async () => {
    const dataUrl = String(reader.result || '');
    const dimensions = await readImageDataUrlDimensions(dataUrl);
    const uploadedAt = new Date().toISOString();
    const imageId = simpleStableHash(dataUrl);
    const symbol = normalizeTicker(ticker || '');
    const activeTickerBeforeUpload = activeReviewTicker();
    const pendingTickerBeforeUpload = pendingReviewTicker();
    if(typeof console !== 'undefined' && console.info){
      console.info('[CHART_ACTIVE_CONTEXT_BEFORE_UPLOAD]', {
        source:String(source || 'change_chart'),
        requestedTicker:symbol,
        activeTicker:activeTickerBeforeUpload || '',
        pendingTicker:pendingTickerBeforeUpload || '',
        activeRequestTicker:String(uiState.analysisActiveRequest && uiState.analysisActiveRequest.ticker || ''),
        activeRequestId:String(uiState.analysisActiveRequest && uiState.analysisActiveRequest.id || '')
      });
    }
    if(symbol && activeTickerBeforeUpload !== symbol){
      setActiveReviewTicker(symbol);
    }
    if(pendingTickerBeforeUpload && pendingTickerBeforeUpload !== symbol){
      clearPendingReviewRequest({
        reason:'chart_upload_focus_handoff',
        requestedTicker:pendingTickerBeforeUpload
      });
      clearPendingReviewCandidate({
        requestedTicker:pendingTickerBeforeUpload
      });
    }
    const record = upsertTickerRecord(symbol || ticker);
    const previousImageId = chartImageIdForReview(record.review || {});
    const activeRequest = uiState.analysisActiveRequest && typeof uiState.analysisActiveRequest === 'object'
      ? uiState.analysisActiveRequest
      : null;
    const matchingActiveRequest = activeRequest && normalizeTicker(activeRequest.ticker || '') === normalizeTicker(record.ticker || '')
      ? activeRequest
      : null;
    if(activeRequest && normalizeTicker(activeRequest.ticker || '') === normalizeTicker(ticker) && activeRequest.controller && typeof activeRequest.controller.abort === 'function'){
      activeRequest.cancelReason = 'chart_replaced';
      try{
        activeRequest.controller.abort('chart_replaced');
      }catch(_error){}
    }
    clearLegacyChartAnalysisState(record.review);
    record.review.chartAnalysisPipeline = null;
    record.review.cardOpen = true;
    const attachmentRequestId = String(matchingActiveRequest && matchingActiveRequest.id || '');
    record.review.chartAttachmentContext = {
      expectedTicker:record.ticker,
      imageId,
      requestId:attachmentRequestId,
      name:file.name,
      type:file.type,
      uploadedAt,
      source:String(source || 'change_chart')
    };
    record.review.chartRef = {
      name:file.name,
      type:file.type,
      dataUrl,
      width:dimensions.width,
      height:dimensions.height,
      bytes:file.size,
      ticker:record.ticker,
      requestId:attachmentRequestId,
      source:'file_upload',
      uploadedAt,
      imageId
    };
    record.review.chartImageOriginal = {
      name:file.name,
      type:file.type,
      width:dimensions.width,
      height:dimensions.height,
      bytes:file.size,
      ticker:record.ticker,
      requestId:attachmentRequestId,
      source:'file_upload',
      dataUrlField:'chartRef.dataUrl',
      uploadedAt,
      imageId
    };
    record.review.chartImagePreview = {
      name:file.name,
      type:file.type,
      width:dimensions.width,
      height:dimensions.height,
      ticker:record.ticker,
      requestId:attachmentRequestId,
      sourceField:'chartRef.dataUrl',
      displayMode:'thumb_object_fit_cover',
      objectFit:'cover',
      croppedByCssOnly:true,
      uploadedAt,
      imageId
    };
    record.review.chartImageVerificationSource = {
      source:'chartImageOriginal',
      sourceField:'chartRef.dataUrl',
      width:dimensions.width,
      height:dimensions.height,
      ticker:record.ticker,
      requestId:attachmentRequestId,
      cropOrResizeOccurred:false,
      limited:false,
      uploadedAt,
      imageId
    };
    record.review.chartAvailable = true;
    record.review.importedFromScreenshot = true;
    const preAiVerificationRequestId = nextReviewAiAnalysisRequestId();
    if(record.review.chartAttachmentContext) record.review.chartAttachmentContext.requestId = preAiVerificationRequestId;
    if(record.review.chartRef) record.review.chartRef.requestId = preAiVerificationRequestId;
    if(record.review.chartImageOriginal) record.review.chartImageOriginal.requestId = preAiVerificationRequestId;
    if(record.review.chartImagePreview) record.review.chartImagePreview.requestId = preAiVerificationRequestId;
    if(record.review.chartImageVerificationSource) record.review.chartImageVerificationSource.requestId = preAiVerificationRequestId;
    upsertReviewChartAnalysisPipeline(record, {
      ticker:record.ticker,
      imageId,
      requestId:preAiVerificationRequestId,
      source:'chart_pipeline_quick_check',
      phase:'verifying',
      expectedFacts:buildChartPipelineExpectedFacts(record),
      readFacts:{},
      missing:['visible ticker', 'visible timeframe', 'latest price'],
      evidence:[],
      aiAllowed:false,
      manualConfirmed:false,
      chartImageSource:buildChartImageSourceTrace(record.review),
      updatedAt:new Date().toISOString()
    });
    setReviewAnalysisState(record, {raw:'', normalized:null, error:'', reviewedAt:'', chartImageId:imageId, requestId:'', ticker:record.ticker});
    record.review.lastReviewedAt = new Date().toISOString();
    record.meta.updatedAt = record.review.lastReviewedAt;
    commitTickerState();
    if(typeof console !== 'undefined' && console.info){
      console.info(previousImageId ? '[CHART_ATTACHMENT_REPLACED]' : '[CHART_ATTACHMENT_CREATED]', {
        source:String(source || 'change_chart'),
        ticker:record.ticker,
        expectedTicker:record.ticker,
        name:file.name,
        imageId,
        requestId:preAiVerificationRequestId,
        previousImageId:previousImageId || ''
      });
      console.info('[CHART_UPLOAD_ENTRY]', {
        source:String(source || 'change_chart'),
        ticker:record.ticker,
        imageId,
        hasOriginal:!!(record.review.chartImageOriginal && record.review.chartImageOriginal.imageId),
        hasPreview:!!(record.review.chartImagePreview && record.review.chartImagePreview.imageId)
      });
      console.info('[CHART_IMAGE_SOURCE]', {
        ticker:record.ticker,
        ...buildChartImageSourceTrace(record.review)
      });
      console.info('[CHART_SECOND_UPLOAD_CONTEXT]', {
        source:String(source || 'change_chart'),
        ticker:record.ticker,
        expectedTicker:record.ticker,
        imageId,
        requestId:String(preAiVerificationRequestId || ''),
        previousImageId:previousImageId || '',
        inheritedActiveRequestId:String(activeRequest && activeRequest.id || ''),
        reusedActiveRequestId:String(matchingActiveRequest && matchingActiveRequest.id || '')
      });
      console.info('[CHART_ACTIVE_CONTEXT_AFTER_UPLOAD]', {
        source:String(source || 'change_chart'),
        requestedTicker:symbol,
        activeTicker:activeReviewTicker() || '',
        pendingTicker:pendingReviewTicker() || '',
        activeRequestTicker:String(uiState.analysisActiveRequest && uiState.analysisActiveRequest.ticker || ''),
        activeRequestId:String(uiState.analysisActiveRequest && uiState.analysisActiveRequest.id || '')
      });
    }
    renderReviewWorkspace({source:'chart_upload', requestedTicker:symbol || record.ticker});
    runSimplifiedChartAnalysis(record, {
      source:String(source || 'chart_upload'),
      requestId:preAiVerificationRequestId,
      phase:'verifying'
    }).catch(() => {});
    const liveStatus = $('reviewWorkspaceStatus') || $(`cardStatus-${ticker}`);
    if(liveStatus){
      const liveRecord = getTickerRecord(ticker) || record;
      const currentPipeline = getReviewChartAnalysisPipeline(liveRecord);
      const currentChartDecision = currentPipeline ? buildSimplifiedChartPipelineDecision(liveRecord, currentPipeline) : null;
      liveStatus.innerHTML = renderReviewChartStatusLine(liveRecord, currentPipeline || null);
    }
  };
  reader.onerror = () => {
    if(statusBox) statusBox.innerHTML = '<span class="badtext">Could not read that chart file.</span>';
  };
  reader.readAsDataURL(file);
}

async function importLatestChart(ticker){
  const statusBox = $('reviewWorkspaceStatus') || $(`cardStatus-${ticker}`);
  try{
    if(navigator.clipboard && navigator.clipboard.read){
      const items = await navigator.clipboard.read();
      for(const item of items){
        const imageType = item.types.find(type => /^image\//i.test(type));
        if(!imageType) continue;
        const blob = await item.getType(imageType);
        const ext = imageType.includes('png') ? 'png' : 'jpg';
        const file = new File([blob], `latest-chart.${ext}`, {type:imageType});
        handleChartSelection(ticker, file, 'import_latest');
        return;
      }
    }
    const input = $(`chart-${ticker}`);
    if(input) input.click();
    if(statusBox) statusBox.innerHTML = '<span class="warntext">Clipboard image import is not available here. Choose the latest screenshot manually.</span>';
  }catch(error){
    const input = $(`chart-${ticker}`);
    if(input) input.click();
    if(statusBox) statusBox.innerHTML = '<span class="warntext">Could not read the latest screenshot automatically. Choose it manually instead.</span>';
  }
}

function loadCard(ticker, options = {}){
  const record = getTickerRecord(ticker);
  if(!record) return;
  const reviewSeq = reviewRenderSeqForOptions(options);
  if(!isCurrentReviewRender(reviewSeq)) return;
  const displayOnlyReviewOpen = options.recompute !== true && options.touchLifecycle !== true;
  traceScrollEvent('review:update:before', {
    caller:'loadCard',
    ticker:normalizeTicker(ticker),
    skipAutoScroll:options.skipAutoScroll === true,
    recompute:options.recompute === true
  });
  setScannerCardClickTrace(ticker, 'loadCard.enter', `touchLifecycle=${options.touchLifecycle === true} recompute=${options.recompute === true}`);
  logDebug('DEBUG_RENDER', 'RENDER_FROM_TICKER_RECORD', 'setupReview', ticker);
  setActiveReviewTicker(record.ticker);
  if(options.touchLifecycle === true){
    writeLifecycleState(record, {
      stage:'reviewed',
      tradingDays:REVIEW_EXPIRY_TRADING_DAYS,
      reason:'Ticker opened in Setup Review.',
      source:'review'
    }, {mode:'refresh'});
    commitTickerState();
  }
  renderReviewWorkspace({
    recompute:options.recompute === true,
    skipWatchlistLifecycle:displayOnlyReviewOpen,
    reviewRenderSeq:reviewSeq
  });
  setScannerCardClickTrace(ticker, 'loadCard.after_renderReviewWorkspace', 'workspace_rendered');
  const review = record.review && record.review.manualReview && typeof record.review.manualReview === 'object'
    ? record.review.manualReview
    : (record.review && record.review.draft && typeof record.review.draft === 'object' ? record.review.draft : null);
  const reviewChecks = review && review.checks ? review.checks : ((record.scan.flags && record.scan.flags.checks) || {});
  checklistIds.forEach(id => {
    const input = $(id);
    if(input) input.checked = !!reviewChecks[id];
  });
  setScannerCardClickTrace(ticker, 'loadCard.after_syncChecks', 'checks_synced');
  refreshReview({
    skipWatchlistLifecycle:displayOnlyReviewOpen,
    readOnlyReviewOpen:displayOnlyReviewOpen,
    persistDraft:displayOnlyReviewOpen ? false : options.persistDraft,
    reviewRenderSeq:reviewSeq
  });
  setScannerCardClickTrace(ticker, 'loadCard.after_refreshReview', 'review_refreshed');
  syncPlannerFromTicker(record.ticker);
  const hydratedPlan = getCanonicalTradeSnapshot(record.ticker);
  setScannerCardClickTrace(ticker, 'loadCard.after_syncPlanner', `planner_synced source=${(hydratedPlan && hydratedPlan.source) || String(record.plan && record.plan.source || 'none')} entry=${(hydratedPlan && hydratedPlan.entry) || '(blank)'}`);
  renderReviewLifecycleSummary(record.ticker);
  if(options.skipAutoScroll === true){
    setScannerCardClickTrace(ticker, 'loadCard.scroll_skipped', 'skipAutoScroll=true');
  }
  traceScrollEvent('review:update:after', {
    caller:'loadCard',
    ticker:normalizeTicker(ticker),
    skipAutoScroll:options.skipAutoScroll === true,
    recompute:options.recompute === true
  });
  setScannerCardClickTrace(ticker, 'loadCard.complete', `selectedTicker=${(($('selectedTicker') && $('selectedTicker').value) || '(none)')}`);
}

function refreshReview(options = {}){
  const reviewSeq = reviewRenderSeqForOptions(options);
  if(!isCurrentReviewRender(reviewSeq)) return;
  const rawChecks = currentChecks();
  const checklistContext = reviewChecklistContextForActiveTicker();
  const checks = resolvedReviewChecksForDisplay(rawChecks, checklistContext);
  const result = scoreAndStatusFromChecks(checks, checklistContext);
  const ticker = activeReviewTicker();
  const canonicalRecord = ticker && typeof getTickerRecord === 'function' ? getTickerRecord(ticker) : null;
  const canonicalSetupScore = canonicalRecord ? setupScoreForRecord(canonicalRecord) : result.score;
  const canonicalSetupQualityLabel = setupQualityLabelForScore(canonicalSetupScore);
  if(typeof window !== 'undefined' && typeof window.requestAnimationFrame === 'function'){
    window.requestAnimationFrame(() => {
      if(!isCurrentReviewRender(reviewSeq)) return;
      const setupQualityText = $('setupQualityText');
      const setupQualitySummary = $('setupQualitySummary');
      const setupQualityEvidence = $('setupQualityEvidence');
      checklistIds.forEach(id => {
        const input = $(id);
        if(input && typeof input.checked === 'boolean') input.checked = !!checks[id];
      });
      if(!refreshReview._missingTextTargetsLogged) refreshReview._missingTextTargetsLogged = new Set();
      if(setupQualityText){
        setupQualityText.textContent = `${canonicalSetupQualityLabel} (${canonicalSetupScore}/10)`;
      }else if(!refreshReview._missingTextTargetsLogged.has('setupQualityText')){
        refreshReview._missingTextTargetsLogged.add('setupQualityText');
        if(isPerfDebugEnabled()) console.debug('[Review] skipped text update; element missing', {label:'setupQualityText', selector:'#setupQualityText'});
      }
      if(setupQualitySummary){
        setupQualitySummary.textContent = reviewSetupQualitySummary(checks, result, checklistContext);
      }else if(!refreshReview._missingTextTargetsLogged.has('setupQualitySummary')){
        refreshReview._missingTextTargetsLogged.add('setupQualitySummary');
        if(isPerfDebugEnabled()) console.debug('[Review] skipped text update; element missing', {label:'setupQualitySummary', selector:'#setupQualitySummary'});
      }
      if(setupQualityEvidence){
        setupQualityEvidence.textContent = 'Weighted by resolver state, current structure, bounce, plan validity, and priceability. Raw checklist evidence is kept internally only.';
      }
      const liveRecord = ticker ? (getTickerRecord(ticker) || upsertTickerRecord(ticker)) : null;
      if(liveRecord){
        const reviewPresentation = buildCanonicalReviewPresentationModel(liveRecord);
        applyCanonicalReviewPresentationModelToDom(reviewPresentation);
      }
      syncPlanDisplayMeta({readOnlyReviewOpen:options.readOnlyReviewOpen === true, reviewRenderSeq:reviewSeq, canonicalDomOnly:true});
    });
  }else{
    const liveRecord = ticker ? (getTickerRecord(ticker) || upsertTickerRecord(ticker)) : null;
    if(liveRecord){
      const reviewPresentation = buildCanonicalReviewPresentationModel(liveRecord);
      applyCanonicalReviewPresentationModelToDom(reviewPresentation);
    }
    syncPlanDisplayMeta({readOnlyReviewOpen:options.readOnlyReviewOpen === true, reviewRenderSeq:reviewSeq, canonicalDomOnly:true});
  }
  if(options.persistDraft !== false){
    scheduleReviewDraftAutosave({reason:'refresh_review'});
  }
}

function persistActiveReviewDraft(options = {}){
  const ticker = activeReviewTicker();
  if(!ticker){
    return {saved:false, skipped:true, reason:'no_active_ticker'};
  }
  const source = String(options.source || 'review_draft');
  const isManualSave = options.manual === true || source === 'review_save';
  const rawChecks = currentChecks();
  const checklistContext = reviewChecklistContextForActiveTicker();
  const checks = resolvedReviewChecksForDisplay(rawChecks, checklistContext);
  const fallbackMeta = getReviewChecklistFallbackMeta(ticker);
  const activeRenderPass = Number(uiState && uiState.reviewRenderPass || 0);
  const fallbackAppliesToActiveTicker = !!(
    fallbackMeta
    && fallbackMeta.ticker === ticker
    && fallbackMeta.usedFallback === true
    && fallbackMeta.renderPass === activeRenderPass
  );
  if(fallbackAppliesToActiveTicker){
    if(isPerfDebugEnabled() && typeof console !== 'undefined' && console.warn){
      console.warn('[ReviewDraftPersistSkipped]', {
        ticker,
        source,
        reason:'checklist_fallback_active',
        manual:isManualSave,
        fallbackMeta
      });
    }
    if(isManualSave){
      return {saved:false, blocked:true, reason:'checklist_fallback', ticker, source, fallbackMeta};
    }
    return {saved:false, skipped:true, reason:'checklist_fallback', ticker, source, fallbackMeta};
  }
  const result = scoreAndStatusFromChecks(checks, checklistContext);
  const record = upsertTickerRecord(ticker);
  setActiveReviewTicker(ticker);
  record.review.cardOpen = true;
  if(uiState.activeReviewAddsToScannerUniverse !== false && !state.tickers.includes(ticker)) state.tickers.push(ticker);
  const manualReview = {
    checks,
    entry:($('entryPrice') && $('entryPrice').value) || '',
    stop:($('stopPrice') && $('stopPrice').value) || '',
    target:($('targetPrice') && $('targetPrice').value) || '',
    score:result.score,
    status:result.status,
    summary:reviewSetupQualitySummary(checks, result, checklistContext),
    savedAt:new Date().toISOString()
  };
  record.review.draft = manualReview;
  if(isManualSave){
    const persistSavedReviewAuthority = typeof writeSavedReviewAuthority === 'function'
      ? writeSavedReviewAuthority
      : function fallbackWriteSavedReviewAuthority(targetRecord, payload = {}){
        if(!targetRecord || typeof targetRecord !== 'object') return targetRecord;
        targetRecord.review = targetRecord.review && typeof targetRecord.review === 'object' ? targetRecord.review : {};
        if(Object.prototype.hasOwnProperty.call(payload, 'manualReview')){
          targetRecord.review.manualReview = payload.manualReview && typeof payload.manualReview === 'object'
            ? {...payload.manualReview}
            : null;
        }
        if(Object.prototype.hasOwnProperty.call(payload, 'lastReviewedAt')){
          targetRecord.review.lastReviewedAt = payload.lastReviewedAt || '';
        }
        if(Object.prototype.hasOwnProperty.call(payload, 'savedSummary')){
          targetRecord.review.savedSummary = payload.savedSummary || '';
        }
        if(Object.prototype.hasOwnProperty.call(payload, 'savedVerdict')){
          targetRecord.review.savedVerdict = payload.savedVerdict || '';
        }
        if(Object.prototype.hasOwnProperty.call(payload, 'savedScore')){
          targetRecord.review.savedScore = Number.isFinite(numericOrNull(payload.savedScore))
            ? Number(payload.savedScore)
            : null;
        }
        return targetRecord;
      };
    persistSavedReviewAuthority(record, {
      manualReview,
      lastReviewedAt:manualReview.savedAt,
      savedSummary:manualReview.summary,
      savedVerdict:'',
      savedProjectionSnapshot:null,
      savedScore:Number.isFinite(numericOrNull(result.score)) ? Number(result.score) : record.review.savedScore
    });
    if(activeReviewTicker() === ticker){
      uiState.activeReviewSourceProjectionSnapshot = null;
      uiState.activeReviewProjectionSource = 'non_watchlist_direct_resolve';
      uiState.activeReviewVerdictOverride = '';
    }
    if(typeof stampTickerJourneyAuthority === 'function'){
      stampTickerJourneyAuthority(record, 'review_save', {
        updatedAt:manualReview.savedAt,
        reason:String(options.source || 'review_save')
      });
    }
  }
  updateTickerInputFromState();
  if(isManualSave){
    refreshTrackedTickerState(ticker, {
      source:'review',
      reason:String(options.source || 'review_draft'),
      force:true,
      persist:false,
      emitTrace:true
    });
  }
  commitTickerState();
  if(activeWorkspaceTab() === 'track'){
    updateWatchlistCardForTicker(ticker);
  }else{
    markWatchlistDirty([ticker], 'review_update');
    startupCoordinator.trackNeedsFullRender = true;
  }
  if(options.render === true){
    renderWatchlist();
    renderFocusQueue();
    renderCards();
    renderReviewLifecycleSummary(ticker);
  }
  return {saved:true, skipped:false, blocked:false, ticker, source};
}

function scheduleReviewDraftAutosave(options = {}){
  const delayMs = Number.isFinite(Number(options.delayMs)) ? Math.max(0, Number(options.delayMs)) : 220;
  if(scheduleReviewDraftAutosave._timer){
    clearTimeout(scheduleReviewDraftAutosave._timer);
    scheduleReviewDraftAutosave._timer = null;
  }
  scheduleReviewDraftAutosave._timer = setTimeout(() => {
    scheduleReviewDraftAutosave._timer = null;
    persistActiveReviewDraft({source:options.source || 'review_autosave', manual:false});
  }, delayMs);
}

function saveReview(){
  const ticker = activeReviewTicker();
  if(!ticker){
    if($('selectedTicker')){
      traceScrollEvent('focus:before', {
        caller:'saveReview',
        target:'#selectedTicker'
      });
      suppressScrollMemoryForAppScroll('focus_selected_ticker', 500);
      $('selectedTicker').focus();
      traceScrollEvent('focus:after', {
        caller:'saveReview',
        target:'#selectedTicker'
      });
    }
    return;
  }
  const saveResult = persistActiveReviewDraft({source:'review_save', render:true, manual:true});
  if(saveResult && saveResult.saved === true){
    const record = getTickerRecord(ticker);
    if(record){
      refreshTrackedTickerState(ticker, {
        source:'review',
        reason:'review_save',
        force:true,
        persist:true,
        emitTrace:true
      });
      runVerdictDriftParityChecks(record);
    }
    setStatus('inputStatus', '<span class="ok">Manual review saved as optional notes only. Scanner ranking stays unchanged.</span>');
    return;
  }
  if(saveResult && (saveResult.skipped === true || saveResult.blocked === true) && saveResult.reason === 'checklist_fallback'){
    setStatus('inputStatus', '<span class="warntext">Review not saved yet - checklist still loading. Try again in a moment.</span>');
    return;
  }
  setStatus('inputStatus', '<span class="badtext">Review could not be saved right now. Please try again.</span>');
}

function resetReview(){
  uiState.activeReviewTicker = '';
  clearPersistedReviewSessionState();
  uiState.activeReviewAddsToScannerUniverse = true;
  uiState.activeReviewVerdictOverride = '';
  ['selectedTicker','planStateBox','planQualityBox','planSourceBox','exitModeBox','targetReviewStateBox','targetAlertBox','rrRealismBox','credibleRrBox','optimisticTargetBox','targetAssessmentBox','realisticTargetBox','extendedTargetBox','targetStretchBox','targetCapReasonBox','entryPrice','stopPrice','targetPrice'].forEach(id => { if($(id)) $(id).value = ''; });
  checklistIds.forEach(id => {
    const input = $(id);
    if(input) input.checked = false;
  });
  const setupQualityText = $('setupQualityText');
  const setupQualitySummary = $('setupQualitySummary');
  if(setupQualityText) setupQualityText.textContent = 'Pending (0/10)';
  if(setupQualitySummary) setupQualitySummary.textContent = 'No setup reviewed yet.';
  if($('calcNote')) $('calcNote').textContent = 'Enter planned entry, stop, and first target to calculate size.';
  ['riskPerShare','positionSize','rrValue'].forEach(id => {
    const el = $(id);
    if(el) el.textContent = '-';
  });
  renderPlannerPlanSummary('', '', '', 'fixed_target');
  renderReviewLifecycleSummary('');
  renderCards();
}

function syncPlanDisplayMeta(options = {}){
  const reviewSeq = reviewRenderSeqForOptions(options);
  if(!isCurrentReviewRender(reviewSeq)) return;
  const ticker = activeReviewTicker();
  const planStateBox = $('planStateBox');
  const planQualityBox = $('planQualityBox');
  const planSourceBox = $('planSourceBox');
  const exitModeBox = $('exitModeBox');
  const triggerStateBox = $('triggerStateBox');
  const planValidationBox = $('planValidationBox');
  const targetReviewStateBox = $('targetReviewStateBox');
  const targetAlertBox = $('targetAlertBox');
  if(!ticker){
    if(planStateBox) planStateBox.value = '';
    if(planQualityBox) planQualityBox.value = '';
    if(planSourceBox) planSourceBox.value = '';
    if(exitModeBox) exitModeBox.value = '';
    if(triggerStateBox) triggerStateBox.value = '';
    if(planValidationBox) planValidationBox.value = '';
    if(targetReviewStateBox) targetReviewStateBox.value = '';
    if(targetAlertBox) targetAlertBox.value = '';
    return;
  }
  const liveRecord = getTickerRecord(ticker) || upsertTickerRecord(ticker);
  const readOnlyReviewOpen = options.readOnlyReviewOpen === true;
  const canonicalPlanSynced = false;
  if(canonicalPlanSynced) commitTickerState();
  const record = liveRecord && typeof liveRecord === 'object' ? liveRecord : {};
  const metaSimplifiedState = resolveSimplifiedStateForSurface(record, 'review', {log:false});
  const metaGlobalVerdict = resolveGlobalVerdict(record);
  const effectiveMetaSimplifiedState = applyReviewWatchlistSoftReadinessDisplayOverride(
    record,
    metaSimplifiedState,
    metaGlobalVerdict,
    watchlistLifecycleSnapshot(record)
  );
  const effectivePlan = effectivePlanForRecord(record, {allowScannerFallback:true});
  const entryValue = $('entryPrice') ? $('entryPrice').value : effectivePlan.entry;
  const stopValue = $('stopPrice') ? $('stopPrice').value : effectivePlan.stop;
  const targetValue = $('targetPrice') ? $('targetPrice').value : effectivePlan.firstTarget;
  const displayedPlan = applySetupConfirmationPlanGate(
    record,
    deriveCurrentPlanState(entryValue, stopValue, targetValue, record.marketData.currency)
  );
  const derivedStates = analysisDerivedStatesFromRecord(record);
  const qualityAdjustments = evaluateSetupQualityAdjustments(record, {displayedPlan, derivedStates});
  const canonicalEntryValue = record && record.plan && record.plan.entry != null ? String(record.plan.entry) : '';
  const canonicalStopValue = record && record.plan && record.plan.stop != null ? String(record.plan.stop) : '';
  const canonicalTargetValue = record && record.plan && record.plan.firstTarget != null ? String(record.plan.firstTarget) : '';
  const plannerInputsDivergedFromCanonical = String(entryValue || '') !== canonicalEntryValue
    || String(stopValue || '') !== canonicalStopValue
    || String(targetValue || '') !== canonicalTargetValue;
  const computedPlanCheckState = planCheckStateForRecord(record, {
    effectivePlan:{
      entry:entryValue,
      stop:stopValue,
      firstTarget:targetValue
    },
    displayedPlan
  });
  const planCheckState = plannerInputsDivergedFromCanonical && displayedPlan.status !== 'valid'
    ? 'needs_replan'
    : computedPlanCheckState;
  const executionState = deriveExecutionPlanState(record, {
    exitMode:record.plan.exitMode,
    targetLevel:targetValue
  });
  const displayStage = plannerInputsDivergedFromCanonical && displayedPlan.status !== 'valid'
    ? 'Watch'
    : displayStageForRecord(record);
  const liveEffectivePlan = {
    entry:entryValue,
    stop:stopValue,
    firstTarget:targetValue
  };
  const planUiState = getPlanUiState(record, {
    displayedPlan,
    effectivePlan:liveEffectivePlan,
    planCheckState:planCheckState
  });
  const setupUiState = getSetupUiState(record, {displayStage, planUiState});
  const planRealism = evaluatePlanRealism(record, {
    displayedPlan,
    derivedStates,
    qualityAdjustments,
    displayStage,
    setupUiState
  });
  const warningState = warningStateFromInputs(record, null, derivedStates);
  const avoidSubtype = avoidSubtypeForRecord(record, {
    derivedStates,
    displayedPlan,
    qualityAdjustments,
    finalVerdict:displayStage
  });
  const emojiPresentation = resolveEmojiPresentation(record, {
    context:'review',
    finalVerdict:displayStage,
    derivedStates,
    displayedPlan,
    qualityAdjustments,
    warningState,
    planUiState,
    setupUiState,
    avoidSubtype
  });
  const resolvedContract = resolveFinalStateContract(record, {
    context:'review',
    finalVerdict:displayStage,
    derivedStates,
    displayedPlan,
    qualityAdjustments,
    warningState,
    planUiState,
    setupUiState,
    avoidSubtype,
    emojiPresentation
  });
  const visualState = resolveVisualState(record, 'review', {
    resolvedContract,
    derivedStates,
    displayedPlan,
    setupScore:setupScoreForRecord(record),
    analysis:(() => {
      const analysisState = getReviewAnalysisState(record);
      return analysisState && analysisState.normalizedAnalysis && typeof analysisState.normalizedAnalysis === 'object'
        ? analysisState.normalizedAnalysis
        : null;
    })()
  });
  const globalVerdict = metaGlobalVerdict;
  const metaDisplayBucket = normalizeVisualBucketForPairing(effectiveMetaSimplifiedState.visualBucket || 'monitor');
  const metaAccepted50MaSupportTestDisplay = isAccepted50MaSupportTestDisplayState({
    record,
    simplifiedState:effectiveMetaSimplifiedState,
    globalVerdict,
    derivedStates
  });
  const reviewDisplayBucket = metaAccepted50MaSupportTestDisplay && metaDisplayBucket === 'diminishing'
    ? 'monitor'
    : metaDisplayBucket;
  const reviewDisplayTone = metaAccepted50MaSupportTestDisplay && reviewDisplayBucket === 'monitor'
    ? 'monitor'
    : (String(effectiveMetaSimplifiedState.tone || reviewDisplayBucket || 'monitor').trim().toLowerCase() || 'monitor');
  const reviewLifecycleBias = {
    review_lifecycle_bias:reviewDisplayBucket,
    review_lifecycle_copy_override_applied:false,
    review_lifecycle_copy_reason:'',
    tradeStatusLine1:String(metaSimplifiedState.planStatus || '').trim(),
    tradeStatusLine2:'',
    trackPresentationBucket:reviewDisplayBucket,
    trackPresentationTone:reviewDisplayTone
  };
  const reviewTradeStatusVerdict = {
    ...visualState,
    structure_state:visualState.structure_state || globalVerdict.structure_state,
    structure_eligibility:visualState.structure_eligibility || globalVerdict.structure_eligibility,
    main_blocker:visualState.main_blocker || globalVerdict.main_blocker,
    is_extended:visualState.is_extended === true || globalVerdict.is_extended === true,
    terminal_avoid_applied:visualState.terminal_avoid_applied === true || globalVerdict.terminal_avoid_applied === true,
    avoid_trigger_source:globalVerdict.avoid_trigger_source || visualState.avoid_trigger_source || '',
    viability:globalVerdict.viability || visualState.viability || '',
    rejected_by_viability_gate:globalVerdict.rejected_by_viability_gate === true,
    hasPriceablePlan:globalVerdict.hasPriceablePlan === true,
    hasProvisionalPriceablePlan:globalVerdict.hasProvisionalPriceablePlan === true,
    entry_gate_pass:effectiveMetaSimplifiedState.entryGatePass === true
      || metaGlobalVerdict.entry_gate_pass === true
      || normalizeGlobalVerdictKey(effectiveMetaSimplifiedState.canonicalVerdict || '') === 'entry',
    near_entry_gate_pass:globalVerdict.near_entry_gate_pass === true,
    review_lifecycle_bias:reviewLifecycleBias.review_lifecycle_bias,
    review_lifecycle_copy_override_applied:reviewLifecycleBias.review_lifecycle_copy_override_applied,
    review_lifecycle_copy_reason:reviewLifecycleBias.review_lifecycle_copy_reason,
    review_lifecycle_line1:reviewLifecycleBias.tradeStatusLine1,
    review_lifecycle_line2:reviewLifecycleBias.tradeStatusLine2,
    track_presentation_bucket:reviewLifecycleBias.trackPresentationBucket,
    track_presentation_tone:reviewLifecycleBias.trackPresentationTone
  };
  const reviewSemanticStatus = buildReviewSemanticStatus({
    record,
    simplifiedState:effectiveMetaSimplifiedState,
    globalVerdict:reviewTradeStatusVerdict,
    derivedStates,
    displayedPlan,
    planRealism
  });
  const resolvedReviewDisplay = buildResolvedReviewDisplayModel({
    record,
    simplifiedState:effectiveMetaSimplifiedState,
    globalVerdict:reviewTradeStatusVerdict,
    reviewSemanticStatus,
    derivedStates,
    displayedPlan,
    planRealism
  });
  const planUI = resolvedReviewDisplay.planUI;
  if(planStateBox) planStateBox.value = planUiState.label;
  const planQuality = planQualityForRr(displayedPlan.rewardRisk.valid ? displayedPlan.rewardRisk.rrRatio : null);
  if(planQualityBox) planQualityBox.value = planQuality || 'N/A';
  if($('rrRealismBox')) $('rrRealismBox').value = planRealism.rr_realism_label || 'Unavailable';
  if($('credibleRrBox')) $('credibleRrBox').value = Number.isFinite(planRealism.credible_rr) ? `${planRealism.credible_rr.toFixed(2)}R` : 'N/A';
  if($('optimisticTargetBox')) $('optimisticTargetBox').value = planRealism.optimistic_target_flag ? 'Yes' : 'No';
  if($('targetAssessmentBox')) $('targetAssessmentBox').value = planRealism.credible_target_assessment || 'N/A';
  if($('realisticTargetBox')) $('realisticTargetBox').value = Number.isFinite(planRealism.realistic_target) ? fmtPrice(Number(planRealism.realistic_target)) : 'N/A';
  if($('extendedTargetBox')) $('extendedTargetBox').value = Number.isFinite(planRealism.extended_target) ? `${fmtPrice(Number(planRealism.extended_target))} (context only)` : 'N/A';
  if($('targetStretchBox')) $('targetStretchBox').value = Number.isFinite(planRealism.target_stretch_pct) ? `${Number(planRealism.target_stretch_pct * 100).toFixed(1)}%` : 'N/A';
  if($('targetCapReasonBox')) $('targetCapReasonBox').value = planRealism.target_cap_reason || 'N/A';
  if(planSourceBox) planSourceBox.value = planSourceForDiagnostics(record, effectivePlan);
  if(exitModeBox) exitModeBox.value = executionModeLabel(executionState.exitMode);
  if(triggerStateBox) triggerStateBox.value = triggerStateLabel(record.plan.triggerState);
  if(planValidationBox) planValidationBox.value = planValidationStateLabel(planCheckState);
  if(targetReviewStateBox) targetReviewStateBox.value = targetReviewStateLabel(executionState.targetReviewState);
  if(targetAlertBox){
    targetAlertBox.value = record.plan.targetAlert && record.plan.targetAlert.enabled
      ? `On @ ${Number.isFinite(executionState.targetAlertLevel) ? fmtPrice(Number(executionState.targetAlertLevel)) : 'n/a'}`
      : 'Off';
  }
  if(options.canonicalDomOnly === true){
    return;
  }
  const activeProjectionSnapshot = uiState.activeReviewSourceProjectionSnapshot
    && typeof uiState.activeReviewSourceProjectionSnapshot === 'object'
    && normalizeTicker(uiState.activeReviewSourceProjectionSnapshot.ticker || '') === normalizeTicker(record.ticker || '')
      ? uiState.activeReviewSourceProjectionSnapshot
      : null;
  const activeProjectionSource = String(
    uiState.activeReviewProjectionSource
    || (activeProjectionSnapshot ? 'clicked_card_snapshot' : 'non_watchlist_direct_resolve')
  ).trim().toLowerCase();
  const projectionEntryDisplayOverride = reviewProjectionCanDriveEntryDisplay(
    activeProjectionSnapshot,
    activeProjectionSource,
    record
  );
  const committedPlanEntryDisplayOverride = hasCanonicalTradePlanStamp(record.plan)
    && String(record.plan && record.plan.authoritySource || '').trim() === 'applyPlanCandidateToRecord'
    && normalizeGlobalVerdictKey(record.scan && (record.scan.resolvedVerdict || record.scan.verdict) || '') === 'entry';
  const resolvedContractEntryDisplayOverride = normalizeGlobalVerdictKey(
    visualState.finalVerdict
    || visualState.final_verdict
    || visualState.final_verdict_rendered
    || metaGlobalVerdict.final_verdict
    || metaGlobalVerdict.finalVerdict
    || ''
  ) === 'entry';
  const entryReadyRecord = normalizeGlobalVerdictKey(effectiveMetaSimplifiedState.canonicalVerdict || '') === 'entry';
  const livePlannerNeedsReplan = plannerInputsDivergedFromCanonical && displayedPlan.status !== 'valid';
  const authoritativeEntryDisplayOverride = !livePlannerNeedsReplan && (
    entryReadyRecord
    || projectionEntryDisplayOverride
    || committedPlanEntryDisplayOverride
    || resolvedContractEntryDisplayOverride
    || reviewSemanticStatus.planActionable === true
  );
  const authoritativeReviewNextActionLabel = authoritativeEntryDisplayOverride
    ? String(
      activeProjectionSnapshot && activeProjectionSnapshot.actionGuidance
      || activeProjectionSnapshot && activeProjectionSnapshot.actionLabel
      || activeProjectionSnapshot && activeProjectionSnapshot.actionShortLabel
      || 'Execute only if the trigger remains valid.'
    ).trim()
    : resolvedReviewDisplay.nextActionLabel;
  const authoritativeTradeStatus = authoritativeEntryDisplayOverride
    ? {
      line1:'Entry Ready',
      line2:authoritativeReviewNextActionLabel || 'Execute only if the trigger remains valid.'
    }
    : resolvedReviewDisplay.tradeStatus;
  if($('tradeStatusBox')){
    $('tradeStatusBox').innerHTML = renderTradeStatusMarkup(authoritativeTradeStatus);
  }
  const effectivePlanUi = authoritativeEntryDisplayOverride
    ? {
      ...planUI,
      showPlan:true,
      showRR:true,
      showCapital:true,
      showPositionSize:true
    }
    : planUI;
  if($('tradePlanInputs')) $('tradePlanInputs').classList.toggle('review-hidden', !effectivePlanUi.showPlan);
  if($('capitalFitMetric')) $('capitalFitMetric').classList.toggle('review-hidden', !effectivePlanUi.showCapital);
  if($('positionSizeStat')) $('positionSizeStat').classList.toggle('review-hidden', !effectivePlanUi.showPositionSize);
  if($('positionCostStat')) $('positionCostStat').classList.toggle('review-hidden', !resolvedReviewDisplay.positionCostVisible);
  if($('fxBasisBox')) $('fxBasisBox').classList.toggle('review-hidden', !effectivePlanUi.showCapital);
  if($('positionCostBox')) $('positionCostBox').textContent = resolvedReviewDisplay.positionCostText;
  if($('reviewNextActionInline')) $('reviewNextActionInline').textContent = `Action guidance: ${authoritativeReviewNextActionLabel}`;
  if($('reviewNextActionPrimary')) $('reviewNextActionPrimary').textContent = `Can I trade this now? ${authoritativeReviewNextActionLabel}`;
  if($('reviewTechnicalContextLine')) $('reviewTechnicalContextLine').textContent = resolvedReviewDisplay.technicalContextLine;
  if($('rrValue')){
    if(livePlannerNeedsReplan){
      $('rrValue').textContent = 'No actionable plan yet.';
      $('rrValue').className = 'big';
    }else{
      const authoritativeReviewPlanForDisplay = authoritativeEntryDisplayOverride
        ? deriveCurrentPlanState(
          record.plan && record.plan.entry,
          record.plan && record.plan.stop,
          record.plan && record.plan.firstTarget,
          record.marketData && record.marketData.currency
        )
        : displayedPlan;
      const authoritativeRrDisplay = authoritativeEntryDisplayOverride
        ? preferredReviewRrDisplay(record, authoritativeReviewPlanForDisplay, resolvedReviewDisplay.rrDisplay)
        : resolvedReviewDisplay.rrDisplay;
      $('rrValue').textContent = authoritativeRrDisplay || 'No actionable plan yet.';
      $('rrValue').className = `big ${effectivePlanUi.showRR ? rrDisplayClass(displayedPlan.rewardRisk && displayedPlan.rewardRisk.rrRatio) : ''}`.trim();
      if(entryReadyRecord && /no actionable plan yet/i.test(String($('rrValue').textContent || ''))){
        $('rrValue').textContent = preferredReviewRrDisplay(record, displayedPlan, 'No actionable plan yet.');
      }
    }
  }
  if($('planRealismSummary')){
    $('planRealismSummary').textContent = resolvedReviewDisplay.planSummary;
  }
}

function refreshSelectedTickerLifecycle(){
  const ticker = activeReviewTicker();
  if(!ticker) return;
  uiState.activeReviewVerdictOverride = '';
  const record = getTickerRecord(ticker);
  if(!record) return;
  const displayStage = normalizeAnalysisVerdict(displayStageForRecord(record));
  const stage = hasAuthoritativeLifecyclePlan(record)
    ? 'planned'
    : ((record.review.manualReview || record.review.cardOpen)
      ? 'reviewed'
      : (record.watchlist.inWatchlist
        ? 'watchlist'
        : ((displayStage && displayStage !== 'Avoid') ? 'shortlisted' : 'reviewed')));
  const days = stage === 'planned' ? PLAN_EXPIRY_TRADING_DAYS : (stage === 'reviewed' ? REVIEW_EXPIRY_TRADING_DAYS : WATCHLIST_EXPIRY_TRADING_DAYS);
  writeLifecycleState(record, {
    stage,
    tradingDays:days,
    reason:'Lifecycle refreshed manually.',
    source:'system'
  }, {mode:'refresh'});
  commitTickerState();
  renderReviewLifecycleSummary(ticker);
  renderWatchlist();
  renderCards();
}

function expireSelectedTickerLifecycle(){
  const ticker = activeReviewTicker();
  if(!ticker) return;
  const record = getTickerRecord(ticker);
  if(!record) return;
  writeLifecycleState(record, {
    stage:'expired',
    status:'stale',
    lockReason:'manual_expired',
    changedAt:new Date().toISOString(),
    expiresAt:todayIsoDate(),
    expiryReason:'Expired manually.',
    reason:'Expired manually.',
    source:'system'
  });
  commitTickerState();
  renderReviewLifecycleSummary(ticker);
  renderWatchlist();
  renderCards();
}

function reactivateSelectedTickerLifecycle(){
  const ticker = activeReviewTicker();
  if(!ticker) return;
  const record = getTickerRecord(ticker);
  if(!record) return;
  const stage = hasAuthoritativeLifecyclePlan(record) ? 'planned' : ((record.review.manualReview || record.review.cardOpen) ? 'reviewed' : (record.watchlist.inWatchlist ? 'watchlist' : 'shortlisted'));
  const days = stage === 'planned' ? PLAN_EXPIRY_TRADING_DAYS : (stage === 'reviewed' ? REVIEW_EXPIRY_TRADING_DAYS : WATCHLIST_EXPIRY_TRADING_DAYS);
  record.lifecycle.lockReason = '';
  writeLifecycleState(record, {
    stage,
    tradingDays:days,
    reason:'Lifecycle reactivated manually.',
    source:'system'
  }, {mode:'refresh'});
  commitTickerState();
  renderReviewLifecycleSummary(ticker);
  renderWatchlist();
  renderCards();
}

function calculate(options = {}){
  const persist = options.persist !== false;
  if(persist){
    saveState();
  }else if(options.skipStateSync !== true){
    syncStateFromDom();
  }
  const ticker = activeReviewTicker();
  const entry = numericOrNull($('entryPrice').value);
  const stop = numericOrNull($('stopPrice').value);
  const target = numericOrNull($('targetPrice').value);
  const entryInputValue = $('entryPrice') ? String($('entryPrice').value || '') : '';
  const stopInputValue = $('stopPrice') ? String($('stopPrice').value || '') : '';
  const targetInputValue = $('targetPrice') ? String($('targetPrice').value || '') : '';
  const activeRecord = ticker ? (getTickerRecord(ticker) || upsertTickerRecord(ticker)) : null;
  const plannerActiveProjectionSnapshot = uiState.activeReviewSourceProjectionSnapshot
    && typeof uiState.activeReviewSourceProjectionSnapshot === 'object'
    && normalizeTicker(uiState.activeReviewSourceProjectionSnapshot.ticker || '') === normalizeTicker(ticker || '')
      ? uiState.activeReviewSourceProjectionSnapshot
      : null;
  const plannerReviewProjectionSource = normalizeReviewProjectionSource(
    String(
      uiState.activeReviewProjectionSource
      || (plannerActiveProjectionSnapshot ? 'clicked_card_snapshot' : 'non_watchlist_direct_resolve')
    ).trim().toLowerCase(),
    plannerActiveProjectionSnapshot
  );
  const plannerProjectionEntryDisplayOverride = reviewProjectionCanDriveEntryDisplay(
    plannerActiveProjectionSnapshot,
    plannerReviewProjectionSource,
    activeRecord || {}
  );
  let displayedPlan = applySetupConfirmationPlanGate(
    activeRecord || {},
    deriveCurrentPlanState(entryInputValue, stopInputValue, targetInputValue, activeRecord && activeRecord.marketData ? activeRecord.marketData.currency : '')
  );
  const plannerDerivedStates = analysisDerivedStatesFromRecord(activeRecord || {});
  const canonicalEntryValue = activeRecord && activeRecord.plan && activeRecord.plan.entry != null ? String(activeRecord.plan.entry) : '';
  const canonicalStopValue = activeRecord && activeRecord.plan && activeRecord.plan.stop != null ? String(activeRecord.plan.stop) : '';
  const canonicalTargetValue = activeRecord && activeRecord.plan && activeRecord.plan.firstTarget != null ? String(activeRecord.plan.firstTarget) : '';
  const plannerInputsDivergedFromCanonical = entryInputValue !== canonicalEntryValue
    || stopInputValue !== canonicalStopValue
    || targetInputValue !== canonicalTargetValue;
  const plannerNeedsReplanState = plannerInputsDivergedFromCanonical && displayedPlan.status !== 'valid';
  if(plannerProjectionEntryDisplayOverride && displayedPlan.status !== 'valid' && !plannerInputsDivergedFromCanonical){
    const fallbackDisplayedPlan = reviewFallbackDisplayedPlan(activeRecord || {}, plannerDerivedStates);
    if(fallbackDisplayedPlan && fallbackDisplayedPlan.status === 'valid'){
      displayedPlan = fallbackDisplayedPlan;
    }
  }
  const qualityAdjustments = evaluateSetupQualityAdjustments(activeRecord || {}, {
    displayedPlan,
    derivedStates:plannerDerivedStates
  });
  const executionState = deriveExecutionPlanState(activeRecord || {}, {
    exitMode:activeRecord && activeRecord.plan ? activeRecord.plan.exitMode : 'fixed_target',
    targetLevel:$('targetPrice').value
  });
  renderPlannerPlanSummary($('entryPrice').value, $('stopPrice').value, $('targetPrice').value, executionState.exitMode);
  if(ticker && persist){
    const record = upsertTickerRecord(ticker);
    const preserveSubmittedPlan = hasSubmittedPaperTradeCanonicalPlan(record) === true;
    if(!preserveSubmittedPlan){
      applyPlanCandidateToRecord(record, {entry, stop, firstTarget:target}, {
        source:'planner',
        lastPlannedAt:new Date().toISOString()
      });
      if(record.watchlist && record.watchlist.inWatchlist){
        runWatchlistLifecycleEvaluation({
          source:'plan_update',
          tickers:[ticker],
          persist:false,
          render:false,
          force:true
        });
      }
    }
    commitTickerState();
    if(record.watchlist && record.watchlist.inWatchlist && !preserveSubmittedPlan){
      requestWatchlistRender({includeFocusQueue:true});
    }
    renderReviewLifecycleSummary(ticker);
    scheduleReviewDraftAutosave({reason:'calculate', source:'review_autosave_calculate'});
  }
  syncPlanDisplayMeta();
  const displayStage = plannerNeedsReplanState
    ? 'Watch'
    : (activeRecord ? displayStageForRecord(activeRecord) : 'Watch');
  const plannerPlanUiState = getPlanUiState(activeRecord || {}, {
    displayedPlan,
    planCheckState:plannerNeedsReplanState ? 'needs_replan' : undefined
  });
  const plannerSetupUiState = getSetupUiState(activeRecord || {}, {displayStage, planUiState:plannerPlanUiState});
  const planRealism = evaluatePlanRealism(activeRecord || {}, {
    displayedPlan,
    derivedStates:plannerDerivedStates,
    qualityAdjustments,
    displayStage,
    setupUiState:plannerSetupUiState
  });
  const warningState = warningStateFromInputs(activeRecord || {}, null, plannerDerivedStates);
  const avoidSubtype = avoidSubtypeForRecord(activeRecord || {}, {
    derivedStates:plannerDerivedStates,
    displayedPlan,
    qualityAdjustments,
    finalVerdict:displayStage
  });
  const emojiPresentation = resolveEmojiPresentation(activeRecord || {}, {
    context:'review',
    finalVerdict:displayStage,
    derivedStates:plannerDerivedStates,
    displayedPlan,
    qualityAdjustments,
    warningState,
    planUiState:plannerPlanUiState,
    setupUiState:plannerSetupUiState,
    avoidSubtype
  });
  const resolvedContract = resolveFinalStateContract(activeRecord || {}, {
    context:'review',
    finalVerdict:displayStage,
    derivedStates:plannerDerivedStates,
    displayedPlan,
    qualityAdjustments,
    warningState,
    planUiState:plannerPlanUiState,
    setupUiState:plannerSetupUiState,
    avoidSubtype,
    emojiPresentation
  });
  const globalVerdict = activeRecord ? resolveGlobalVerdict(activeRecord) : {allow_plan:false};
  const plannerSimplifiedState = activeRecord
    ? resolveSimplifiedStateForSurface(activeRecord, 'review', {log:false})
    : resolveSimplifiedStateForSurface({}, 'review', {log:false});
  const effectiveMetaSimplifiedState = activeRecord
    ? applyReviewWatchlistSoftReadinessDisplayOverride(
      activeRecord,
      plannerSimplifiedState,
      globalVerdict,
      watchlistLifecycleSnapshot(activeRecord)
    )
    : plannerSimplifiedState;
  const plannerVisualState = activeRecord ? resolveVisualState(activeRecord, 'review', {
    resolvedContract,
    derivedStates:plannerDerivedStates,
    displayedPlan,
    setupScore:setupScoreForRecord(activeRecord),
    analysis:(() => {
      const analysisState = getReviewAnalysisState(activeRecord);
      return analysisState && analysisState.normalizedAnalysis && typeof analysisState.normalizedAnalysis === 'object'
        ? analysisState.normalizedAnalysis
        : null;
    })()
  }) : {finalVerdict:'watch'};
  const plannerTradeStatusVerdict = {
    ...plannerVisualState,
    ...globalVerdict,
    main_blocker:plannerSimplifiedState.mainBlocker || globalVerdict.main_blocker || plannerVisualState.main_blocker || '',
    review_lifecycle_bias:(() => {
      const bucket = normalizeVisualBucketForPairing(plannerSimplifiedState.visualBucket || plannerVisualState.visualBucket || 'monitor');
      const accepted50MaSupportTest = isAccepted50MaSupportTestDisplayState({
        record:activeRecord || {},
        simplifiedState:plannerSimplifiedState,
        globalVerdict,
        derivedStates:plannerDerivedStates
      });
      return accepted50MaSupportTest && bucket === 'diminishing' ? 'monitor' : bucket;
    })(),
    track_presentation_bucket:(() => {
      const bucket = normalizeVisualBucketForPairing(plannerSimplifiedState.visualBucket || plannerVisualState.visualBucket || 'monitor');
      const accepted50MaSupportTest = isAccepted50MaSupportTestDisplayState({
        record:activeRecord || {},
        simplifiedState:plannerSimplifiedState,
        globalVerdict,
        derivedStates:plannerDerivedStates
      });
      return accepted50MaSupportTest && bucket === 'diminishing' ? 'monitor' : bucket;
    })()
  };
  const plannerSemanticStatus = buildReviewSemanticStatus({
    record:activeRecord || {},
    simplifiedState:plannerSimplifiedState,
    globalVerdict:plannerTradeStatusVerdict,
    derivedStates:plannerDerivedStates,
    displayedPlan,
    planRealism
  });
  const resolvedReviewDisplay = buildResolvedReviewDisplayModel({
    record:activeRecord || {},
    simplifiedState:plannerSimplifiedState,
    globalVerdict:plannerTradeStatusVerdict,
    reviewSemanticStatus:plannerSemanticStatus,
    derivedStates:plannerDerivedStates,
    displayedPlan,
    planRealism
  });
  const planUI = resolvedReviewDisplay.planUI;
  $('rewardPerShareBox').textContent = Number.isFinite(displayedPlan.rewardPerShare) ? displayedPlan.rewardPerShare.toFixed(2) : '-';
  const riskFitLabel = riskStatusLabel(displayedPlan.status === 'valid' ? displayedPlan.riskFit.risk_status : (displayedPlan.status === 'invalid' ? 'invalid_plan' : 'plan_missing'));
  const capitalUsage = capitalUsageAdvisory({
    positionCostGbp:displayedPlan.capitalFit.position_cost_gbp,
    positionCost:displayedPlan.capitalFit.position_cost,
    quoteCurrency:displayedPlan.capitalFit.quote_currency,
    accountSizeGbp:currentAccountSizeGbp()
  });
  const capitalComfort = capitalComfortSummary({
    capitalFit:displayedPlan.status === 'valid' ? displayedPlan.capitalFit.capital_fit : 'unknown',
    capitalNote:displayedPlan.capitalFit.capital_note,
    affordability:displayedPlan.status === 'valid' ? displayedPlan.affordability : '',
    capitalUsage,
    planStatus:displayedPlan.status,
    controlQuality:qualityAdjustments.controlQuality,
    capitalEfficiency:qualityAdjustments.capitalEfficiency
  });
  $('riskFitBox').textContent = `${riskFitLabel} / ${capitalComfort.label}`;
  if($('capitalComfortBox')) $('capitalComfortBox').textContent = capitalComfort.label;
  const capitalFitVisual = capitalFitPresentation({
    capitalFit:displayedPlan.capitalFit.capital_fit,
    affordability:displayedPlan.affordability,
    comfortLabel:capitalComfort.label
  });
  const reviewPresentation = buildCanonicalReviewPresentationModel(activeRecord || {}, {
    uiDraftState:{
      entry:entryInputValue,
      stop:stopInputValue,
      target:targetInputValue,
      firstTarget:targetInputValue
    },
    displayedPlan,
    derivedStates:plannerDerivedStates,
    simplifiedState:effectiveMetaSimplifiedState,
    globalVerdict,
    planRealism,
    qualityAdjustments,
    planUiState:plannerPlanUiState,
    setupUiState:plannerSetupUiState,
    resolvedContract,
    visualState:plannerVisualState,
    reviewSemanticStatus:plannerSemanticStatus,
    resolvedReviewDisplay,
    capitalComfort
  });
  const effectivePlanUi = reviewPresentation.planUI;
  applyCanonicalReviewPresentationModelToDom(reviewPresentation);
  if($('capitalFitBox')) $('capitalFitBox').textContent = capitalFitMetricText(capitalComfort.label);
  if($('fxBasisBox')) $('fxBasisBox').textContent = capitalComfort.note || 'No FX conversion note.';
  if($('capitalCheckBox')) $('capitalCheckBox').textContent = capitalComfort.note || 'Clear';
  if($('targetReviewStateBox')) $('targetReviewStateBox').value = targetReviewStateLabel(executionState.targetReviewState);
  if($('targetAlertBox')){
    $('targetAlertBox').value = executionState.exitMode === 'dynamic_exit'
      ? `On @ ${Number.isFinite(executionState.targetAlertLevel) ? fmtPrice(Number(executionState.targetAlertLevel)) : 'n/a'}`
      : 'Off';
  }
  if($('rrRealismBox')) $('rrRealismBox').value = planRealism.rr_realism_label || 'Unavailable';
  if($('credibleRrBox')) $('credibleRrBox').value = Number.isFinite(planRealism.credible_rr) ? `${planRealism.credible_rr.toFixed(2)}R` : 'N/A';
  if($('optimisticTargetBox')) $('optimisticTargetBox').value = planRealism.optimistic_target_flag ? 'Yes' : 'No';
  if($('targetAssessmentBox')) $('targetAssessmentBox').value = planRealism.credible_target_assessment || 'N/A';
  if(!effectivePlanUi.showPlan){
    $('riskPerShare').textContent = '-';
    $('positionSize').textContent = '-';
    if($('plannerBox')){
      const plannerBox = $('plannerBox');
      const reviewPanelTone = plannerBox && plannerBox.dataset ? String(plannerBox.dataset.reviewPanelTone || '').trim() : '';
      plannerBox.className = `panelbox plannerbox ${reviewPanelTone}`.trim();
    }
    return;
  }
  if(displayedPlan.status === 'missing'){
    $('riskPerShare').textContent = '-';
    $('positionSize').textContent = '-';
    if($('plannerBox')){
      const plannerBox = $('plannerBox');
      const reviewPanelTone = plannerBox && plannerBox.dataset ? String(plannerBox.dataset.reviewPanelTone || '').trim() : '';
      plannerBox.className = `panelbox plannerbox ${reviewPanelTone}`.trim();
    }
    return;
  }
  if(displayedPlan.status === 'invalid'){
    $('riskPerShare').textContent = '-';
    $('positionSize').textContent = '-';
    if($('plannerBox')){
      const plannerBox = $('plannerBox');
      const reviewPanelTone = plannerBox && plannerBox.dataset ? String(plannerBox.dataset.reviewPanelTone || '').trim() : '';
      plannerBox.className = `panelbox plannerbox ${reviewPanelTone}`.trim();
    }
    return;
  }
  $('riskPerShare').textContent = Number.isFinite(displayedPlan.riskFit.risk_per_share) ? displayedPlan.riskFit.risk_per_share.toFixed(2) : '-';
  $('positionSize').textContent = displayedPlan.riskFit.position_size > 0 ? `${displayedPlan.riskFit.position_size} shares` : '0 shares';
  if($('plannerBox')){
    const plannerBox = $('plannerBox');
    const reviewPanelTone = plannerBox && plannerBox.dataset ? String(plannerBox.dataset.reviewPanelTone || '').trim() : '';
    plannerBox.className = `panelbox plannerbox ${reviewPanelTone}`.trim();
  }
}

async function copyText(text){
  try{
    if(navigator.clipboard && window.isSecureContext){
      await navigator.clipboard.writeText(text);
      return true;
    }
  }catch(e){}
  try{
    const el = document.createElement('textarea');
    el.value = text;
    el.setAttribute('readonly', '');
    el.style.position = 'fixed';
    el.style.opacity = '0';
    document.body.appendChild(el);
    el.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(el);
    return ok;
  }catch(e){
    return false;
  }
}

