function resolvePreLifecycleStateContract(record, options = {}){
  const item = record && typeof record === 'object' ? record : {};
  const derivedStates = options.derivedStates || analysisDerivedStatesFromRecord(item);
  const effectivePlan = options.effectivePlan || effectivePlanForRecord(item, {allowScannerFallback:true});
  const displayedPlan = options.displayedPlan || deriveCurrentPlanState(
    effectivePlan.entry,
    effectivePlan.stop,
    effectivePlan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const structureState = String(derivedStates.structureState || '').toLowerCase();
  const trendState = String(derivedStates.trendState || '').toLowerCase();
  const bounceState = String(derivedStates.bounceState || '').toLowerCase();
  const volumeState = String(derivedStates.volumeState || '').toLowerCase();
  const marketWeak = !!(
    item.setup.marketCaution
    || isHostileMarketStatus((item.meta && item.meta.marketStatus) || state.marketStatus)
  );
  const weakStructure = ['weak','weakening','developing_loose'].includes(structureState);
  const nearReadyStructure = ['strong','intact','developing_clean'].includes(structureState);
  const bounceUnconfirmed = ['none','unconfirmed','attempt','early'].includes(bounceState);
  const hardStructureBroken = !!(
    structureState === 'broken'
    || trendState === 'broken'
  );
  const planStatusKey = String(displayedPlan.status || '').toLowerCase() || 'missing';
  const baseVerdict = hardStructureBroken
    ? 'avoid'
    : (displayedPlan.status === 'valid' && nearReadyStructure && !bounceUnconfirmed && !marketWeak && volumeState !== 'weak'
      ? 'near_entry'
      : 'watch');
  let structuralStateKey = 'developing';
  if(hardStructureBroken){
    structuralStateKey = 'dead';
  }else if(baseVerdict === 'near_entry'){
    structuralStateKey = 'near_entry';
  }else if(weakStructure){
    structuralStateKey = 'developing';
  }
  const actionStateKey = hardStructureBroken
    ? 'rebuild_setup'
    : (displayedPlan.status === 'valid' && !bounceUnconfirmed ? 'wait_for_confirmation' : 'recalculate_plan');
  const tradeabilityVerdict = hardStructureBroken
    ? 'Avoid'
    : (structuralStateKey === 'near_entry' ? 'Near Entry' : 'Watch');
  return {
    finalVerdict:baseVerdict === 'avoid' ? 'Avoid' : (baseVerdict === 'near_entry' ? 'Near Entry' : 'Watch'),
    structuralState:structuralStateKey,
    actionStateKey,
    planStatusKey:planStatusKey || 'missing',
    tradeabilityVerdict,
    blockerReason:hardStructureBroken ? 'Structure is broken' : (displayedPlan.status === 'valid' ? 'Needs stronger confirmation' : 'Plan not ready'),
    reasonSummary:hardStructureBroken ? 'Structure is broken' : (weakStructure ? 'Trend weakening' : 'Pre-watchlist setup'),
    terminal:hardStructureBroken,
    baseVerdict
  };
}

function canonicalPublicationIdentityForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const ticker = String(item.ticker || item.symbol || '').trim().toUpperCase();
  return {
    ticker,
    recordIdentity:`${ticker}:${String(item.meta && item.meta.createdAt || '')}`,
    refreshCycleId:String(item.scan && (item.scan.updatedAt || item.scan.lastScannedAt) || '')
  };
}

function persistableCanonicalPublicationAuthority(record){
  const item = record && typeof record === 'object' ? record : {};
  const authority = item.authority && typeof item.authority === 'object' ? item.authority : {};
  const publication = authority.canonicalPublication && typeof authority.canonicalPublication === 'object'
    ? cloneData(authority.canonicalPublication, null)
    : null;
  const projection = authority.canonicalResolverProjection && typeof authority.canonicalResolverProjection === 'object'
    ? cloneData(authority.canonicalResolverProjection, null)
    : null;
  const identity = canonicalPublicationIdentityForRecord(item);
  return {
    version:Number.isFinite(Number(authority.version)) ? Number(authority.version) : 0,
    source:String(authority.source || ''),
    updatedAt:String(authority.updatedAt || ''),
    reason:String(authority.reason || ''),
    canonicalPublication:publication,
    canonicalResolverProjection:projection,
    canonicalPublicationPersistence:{
      schemaVersion:CANONICAL_PUBLICATION_PERSISTENCE_SCHEMA_VERSION,
      publicationPersisted:!!publication,
      persistedPublicationId:String(publication && publication.publicationId || ''),
      persistedEvidenceId:String(publication && publication.evidenceId || ''),
      persistedCycleId:String(publication && publication.refreshCycleId || ''),
      recordIdentity:String(identity.recordIdentity || '')
    }
  };
}

function canonicalPublicationForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const publication = item.authority && item.authority.canonicalPublication;
  const identity = canonicalPublicationIdentityForRecord(item);
  const persistence = item.authority && item.authority.canonicalPublicationPersistence;
  if(!publication || !window.CanonicalDecisionResult || typeof window.CanonicalDecisionResult.publicationMatches !== 'function') return null;
  if(persistence && (
    persistence.schemaVersion !== CANONICAL_PUBLICATION_PERSISTENCE_SCHEMA_VERSION
    || persistence.publicationPersisted !== true
    || String(persistence.persistedPublicationId || '') !== String(publication.publicationId || '')
    || String(persistence.persistedEvidenceId || '') !== String(publication.evidenceId || '')
    || String(persistence.persistedCycleId || '') !== String(publication.refreshCycleId || '')
    || String(persistence.recordIdentity || '') !== String(identity.recordIdentity || '')
  )) return null;
  // A local fact edit invalidates the publication immediately. This is a
  // pure evidence comparison, not a resolver invocation: rendering remains
  // unavailable until the next authoritative scan/refresh republishes.
  const currentEvidence = window.CanonicalResolverInput
    && typeof window.CanonicalResolverInput.normaliseDecisionEvidence === 'function'
    ? window.CanonicalResolverInput.normaliseDecisionEvidence(item, {surface:'resolver-core'})
    : null;
  const publishedEvidence = publication.canonicalResult && publication.canonicalResult.evidence;
  if(currentEvidence && publishedEvidence && (
    JSON.stringify(currentEvidence.values || {}) !== JSON.stringify(publishedEvidence.values || {})
    || JSON.stringify(currentEvidence.factualStates || {}) !== JSON.stringify(publishedEvidence.factualStates || {})
  )) return null;
  return window.CanonicalDecisionResult.publicationMatches(publication, identity) ? publication : null;
}

function canonicalPublicationProjectionForRecord(record){
  const item = record && typeof record === 'object' ? record : {};
  const publication = canonicalPublicationForRecord(item);
  const snapshot = item.authority && item.authority.canonicalResolverProjection;
  if(!publication || !snapshot || typeof snapshot !== 'object') return null;
  if(['publicationId','evidenceId','refreshCycleId','canonicalResultVersion'].some(field => {
    const value = String(snapshot[field] || '');
    return value && value !== String(publication[field] || '');
  })) return null;
  return {
    ...snapshot,
    canonicalPublication:publication,
    canonicalDecisionResult:publication.canonicalResult,
    publicationStatus:publication.publicationStatus,
    publicationId:publication.publicationId,
    evidenceId:publication.evidenceId,
    refreshCycleId:publication.refreshCycleId,
    canonicalResultVersion:publication.canonicalResultVersion
  };
}

// The sole current-state publication boundary. Call this immediately after a
// scan/refresh has written its facts; render paths only read the result.
function publishCanonicalPublicationForRecord(record){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return null;
  const resolved = resolveGlobalVerdict(item, {forceResolve:true});
  const rawPublication = resolved && resolved.canonicalPublication;
  if(!rawPublication || !window.CanonicalDecisionResult || typeof window.CanonicalDecisionResult.identifyPublication !== 'function') return null;
  const identity = canonicalPublicationIdentityForRecord(item);
  const publication = window.CanonicalDecisionResult.identifyPublication(rawPublication, identity);
  item.authority = item.authority && typeof item.authority === 'object' ? item.authority : {};
  item.authority.canonicalPublication = publication;
  const snapshot = {...resolved};
  delete snapshot.canonicalPublication;
  delete snapshot.canonicalDecisionResult;
  snapshot.publicationId = publication.publicationId;
  snapshot.evidenceId = publication.evidenceId;
  snapshot.refreshCycleId = publication.refreshCycleId;
  snapshot.canonicalResultVersion = publication.canonicalResultVersion;
  snapshot.recordIdentity = publication.recordIdentity;
  snapshot.validationStatus = publication.validationStatus;
  item.authority.canonicalPublicationPersistence = {
    schemaVersion:CANONICAL_PUBLICATION_PERSISTENCE_SCHEMA_VERSION,
    publicationPersisted:true,
    persistedPublicationId:publication.publicationId,
    persistedEvidenceId:publication.evidenceId,
    persistedCycleId:publication.refreshCycleId,
    recordIdentity:publication.recordIdentity
  };
  item.authority.canonicalResolverProjection = snapshot;
  return canonicalPublicationProjectionForRecord(item);
}

function resolveGlobalVerdict(record, deps = {}){
  const item = record && typeof record === 'object' ? record : {};
  if(deps.forceResolve !== true && typeof canonicalPublicationProjectionForRecord === 'function'){
    const published = canonicalPublicationProjectionForRecord(item);
    if(published) return published;
  }
  const effectivePlanResolver = deps.effectivePlanForRecord || effectivePlanForRecord;
  const deriveDisplayedPlan = deps.deriveCurrentPlanState || deriveCurrentPlanState;
  const applyPlanGate = deps.applySetupConfirmationPlanGate || applySetupConfirmationPlanGate;
  // This wrapper supplies factual plan services only. Semantic state, verdict
  // contracts, Scan preservation, Review readiness, and lifecycle history are
  // intentionally excluded from ResolverCore authority.
  const derivedStates = {};
  const effectivePlan = effectivePlanResolver(item, {allowScannerFallback:true});
  let displayedPlan = applyPlanGate(
    item,
    deriveDisplayedPlan(
      effectivePlan.entry,
      effectivePlan.stop,
      effectivePlan.firstTarget,
      item.marketData && item.marketData.currency
    ),
    derivedStates
  );
  const resolverDeps = {
    applySetupConfirmationPlanGate:applyPlanGate,
    deriveCurrentPlanState:() => displayedPlan,
    evaluatePlanRealism:deps.evaluatePlanRealism || evaluatePlanRealism,
    // Resolver input retains its existing raw setup-quality signal. Published
    // presentation scores are derived only after the canonical result exists.
    setupScoreForRecord:deps.setupScoreForRecord || rawSetupScoreForRecord,
    canonicalSetupScoreForRecord:deps.canonicalSetupScoreForRecord || rawSetupScoreForRecord,
    buildCumulativePenaltyTrace:deps.buildCumulativePenaltyTrace || cumulativePenaltyTraceForRecord,
    isHostileMarketStatus:deps.isHostileMarketStatus || isHostileMarketStatus,
    state:deps.state || state,
    scannerScoreGradientClass:deps.scannerScoreGradientClass || scannerScoreGradientClass
  };
  const verdict = resolveGlobalVerdictImpl(record, resolverDeps);
  const authorityResolvedContract = null;
  const selectedAuthoritySource = 'canonical_selector';
  const canonicalAuthoritySource = 'canonical_selector';
  verdict.selected_authority_contract_source = selectedAuthoritySource;
  verdict.canonical_soft_readiness_alignment_source = canonicalAuthoritySource;
  verdict.contractDiagnostics = {authoritySelectionSource:selectedAuthoritySource, canonicalAuthoritySelectionSource:canonicalAuthoritySource, compatibilityOnly:true, mayFeedDecisionLogic:false};
  verdict.decision_summary = buildDecisionSummary({
    record:item,
    finalVerdict:verdict.final_verdict,
    displayedPlan,
    resolvedContract:null,
    derivedStates,
    globalVerdict:verdict
  });
  // Keep the resolver projection independent of Chart Guru. Story construction
  // consumes this output; it must never be needed to resolve a verdict.
  const resolverProjection = verdict.canonicalDecisionProjection && typeof verdict.canonicalDecisionProjection === 'object'
    ? verdict.canonicalDecisionProjection
    : {};
  const decisiveBlocker = normalizeGlobalVerdictKey(verdict.final_verdict || 'watch') === 'entry'
    ? ''
    : String(
      resolverProjection.decisiveBlocker
      || verdict.main_blocker
      || verdict.mainBlocker
      || verdict.reason
      || ''
    ).trim();
  const supportTestState = String(verdict.support_test_state || '').trim().toLowerCase();
  const nextRequiredEvent = supportTestState === 'failed'
    ? 'repair'
    : (verdict.entry_gate_pass === true
      ? 'execute_if_trigger_valid'
      : (verdict.confirmation_gate_pass === false
        ? 'confirmation'
        : (verdict.buyer_control_gate_pass === false ? 'buyer_control' : 'review_setup')));
  const nextAction = nextRequiredEvent === 'repair'
    ? 'Wait for the setup to repair before reviewing it again.'
    : (nextRequiredEvent === 'execute_if_trigger_valid'
      ? 'Execute only if the trigger remains valid.'
      : (nextRequiredEvent === 'buyer_control'
        ? 'Wait for buyers to prove control before considering an entry.'
        : (nextRequiredEvent === 'confirmation'
          ? 'Wait for stronger confirmation before considering an entry.'
          : 'Review setup inputs')));
  verdict.canonicalDecisionProjection = {
    ...resolverProjection,
    verdict:normalizeGlobalVerdictKey(verdict.final_verdict || 'watch'),
    canonicalVerdict:normalizeGlobalVerdictKey(verdict.final_verdict || 'watch'),
    decisiveBlocker,
    primaryReason:decisiveBlocker,
    nextRequiredEvent,
    nextAction
  };
  if(!verdict.cumulativePenaltyTrace || !Array.isArray(verdict.cumulativePenaltyTrace.sources)){
    verdict.cumulativePenaltyTrace = resolverDeps.buildCumulativePenaltyTrace(item, {
      analysis:authorityResolvedContract,
      derivedStates,
      displayedPlan,
      displayStage:globalVerdictLabel(verdict.final_verdict || '')
    });
  }
  try{
    if(debugFlagEnabled('PP_DEBUG_CANONICAL_INPUT')
      && typeof window !== 'undefined'
      && window.CanonicalResolverInput
      && typeof window.CanonicalResolverInput.buildCanonicalResolverInputComparison === 'function'){
      const canonicalComparison = window.CanonicalResolverInput.buildCanonicalResolverInputComparison(item, {
        surface:'live_resolver_entrypoint',
        mode:'diagnostic',
        derivedStates,
        effectivePlan,
        displayedPlan
      });
      window.__canonicalResolverInputDebugByTicker = window.__canonicalResolverInputDebugByTicker && typeof window.__canonicalResolverInputDebugByTicker === 'object'
        ? window.__canonicalResolverInputDebugByTicker
        : {};
      if(canonicalComparison && canonicalComparison.ticker){
        window.__canonicalResolverInputDebugByTicker[canonicalComparison.ticker] = canonicalComparison;
        const debugTickerKeys = Object.keys(window.__canonicalResolverInputDebugByTicker);
        if(debugTickerKeys.length > 50){
          debugTickerKeys
            .sort((left, right) => {
              const leftAt = String(window.__canonicalResolverInputDebugByTicker[left] && window.__canonicalResolverInputDebugByTicker[left].capturedAt || '');
              const rightAt = String(window.__canonicalResolverInputDebugByTicker[right] && window.__canonicalResolverInputDebugByTicker[right].capturedAt || '');
              return leftAt.localeCompare(rightAt);
            })
            .slice(0, debugTickerKeys.length - 50)
            .forEach(key => {
              delete window.__canonicalResolverInputDebugByTicker[key];
            });
        }
      }
      uiState.canonicalResolverInputLastComparison = canonicalComparison || null;
      if(canonicalComparison && canonicalComparison.hasDifferences && typeof console !== 'undefined' && console.info){
        console.info('[CANONICAL_RESOLVER_INPUT_DIFF]', canonicalComparison);
      }
    }
  }catch(error){
    if(debugFlagEnabled('PP_DEBUG_CANONICAL_INPUT') && typeof console !== 'undefined' && console.warn){
      console.warn('[CANONICAL_RESOLVER_INPUT_DIFF_FAILED]', {
        ticker:String(item.ticker || item.symbol || '').trim().toUpperCase(),
        message:String(error && error.message || error || 'canonical_input_diff_failed')
      });
    }
  }
  return verdict;
}

function watchlistRefreshStructureGate(record){
  const item = record && typeof record === 'object' ? record : {};
  const derivedStates = analysisDerivedStatesFromRecord(item);
  const displayedPlan = deriveCurrentPlanState(
    item.plan && item.plan.entry,
    item.plan && item.plan.stop,
    item.plan && item.plan.firstTarget,
    item.marketData && item.marketData.currency
  );
  const deadCheck = isTerminalDeadSetup(item, {derivedStates, displayedPlan});
  const structureState = String(derivedStates.structureState || '').toLowerCase();
  const trendState = String(derivedStates.trendState || '').toLowerCase();
  const currentHardBlockers = currentScannerEstimateHardBlockers(item, {displayedPlan, derivedStates});
  const explicitInvalidation = currentHardBlockers.isScannerEstimate
    ? currentHardBlockers.currentInvalidated
    : !!(item.plan && item.plan.invalidatedState);
  const currentPrice = numericOrNull(item.marketData && item.marketData.price);
  const stopPrice = numericOrNull(item.plan && item.plan.stop);
  const brokenBelowStop = hasAuthoritativeStopBreach(item, {currentPrice, stopPrice});
  const structuralBroken = deadCheck.dead || structureState === 'broken' || trendState === 'broken' || brokenBelowStop;
  const explicitInvalidationAllowed = explicitInvalidation && structuralBroken;
  const structuralAlive = !deadCheck.dead
    && structureState !== 'broken'
    && trendState !== 'broken'
    && !brokenBelowStop;
  return {
    structural_alive_at_refresh:structuralAlive,
    avoid_allowed_by_structure_gate:!structuralAlive,
    refresh_demote_reason:!structuralAlive
      ? (explicitInvalidationAllowed
        ? 'Explicit setup invalidation.'
        : (deadCheck.dead
          ? (deadCheck.reason || deadCheck.reasonCode || 'Dead setup rule triggered.')
          : 'Structure is broken.'))
      : 'Structurally alive; keep on monitor.',
    dead_trigger_source:explicitInvalidationAllowed
      ? 'explicit_invalidation'
      : (structuralBroken ? 'structure_broken' : null),
    explicit_invalidation_reason:explicitInvalidationAllowed ? 'Explicit invalidation with hard structural damage.' : '(none)',
    lifecycle_drop_reason:!structuralAlive ? 'watchlist_refresh_structure_gate' : '(none)'
  };
}

function applyGlobalVerdictGates(record, options = {}){
  const item = record && typeof record === 'object' ? record : null;
  if(!item) return {changed:false, globalVerdict:resolveGlobalVerdict({})};
  const globalVerdict = resolveGlobalVerdict(item);
  const structureGate = watchlistRefreshStructureGate(item);
  const source = String(options.source || '').toLowerCase();
  const deferWatchlistRemoval = options.deferWatchlistRemoval === true
    || ['manual_refresh','auto_recompute','plan_update','review','review_save','analyse_setup','scan','market_status'].includes(source)
    || uiState.watchlistLifecycleRunning;
  let changed = false;
  item.watchlist.debug = item.watchlist.debug && typeof item.watchlist.debug === 'object' ? item.watchlist.debug : {};
  item.watchlist.debug.refresh_demote_attempted = globalVerdict.allow_watchlist ? 'false' : 'true';
  item.watchlist.debug.refresh_demote_reason = structureGate.refresh_demote_reason || (globalVerdict.reason || globalVerdict.downgrade_reason || '(none)');
  item.watchlist.debug.structural_alive_at_refresh = structureGate.structural_alive_at_refresh ? 'true' : 'false';
  item.watchlist.debug.avoid_allowed_by_structure_gate = structureGate.avoid_allowed_by_structure_gate ? 'true' : 'false';
  item.watchlist.debug.explicit_invalidation_reason = structureGate.explicit_invalidation_reason || globalVerdict.explicit_invalidation_reason || '(none)';
  item.watchlist.debug.lifecycle_drop_reason = structureGate.lifecycle_drop_reason || globalVerdict.lifecycle_drop_reason || '(none)';
  item.watchlist.debug.avoid_allowed_by_structure_consistency_guard = globalVerdict.avoid_allowed_by_structure_consistency_guard ? 'true' : 'false';
  const stampedCanonicalPlan = typeof hasCanonicalTradePlanStamp === 'function'
    ? hasCanonicalTradePlanStamp(item.plan)
    : (
      item.plan
      && String(item.plan.authorityVersion || '').trim() === 'trade_plan_v1'
      && !!String(item.plan.authoritySource || '').trim()
      && !!String(item.plan.writtenBy || '').trim()
      && !!String(item.plan.writtenAt || '').trim()
    );
  const stampedCanonicalPlanComplete = stampedCanonicalPlan
    && Number.isFinite(numericOrNull(item.plan && item.plan.entry))
    && Number.isFinite(numericOrNull(item.plan && item.plan.stop))
    && Number.isFinite(numericOrNull(item.plan && item.plan.firstTarget));
  const stampedCanonicalPlanUnaffordable = stampedCanonicalPlanComplete && (
    String(item.plan && item.plan.tradeability || '').trim().toLowerCase() === 'too_expensive'
    || String(item.plan && item.plan.capitalFit || '').trim().toLowerCase() === 'too_expensive'
    || String(item.plan && item.plan.affordability || '').trim().toLowerCase() === 'not_affordable'
  );
  if(item.watchlist && item.watchlist.inWatchlist && !globalVerdict.allow_watchlist){
    if(!structureGate.avoid_allowed_by_structure_gate){
      appendWatchlistDebugEvent(item, {
        at:new Date().toISOString(),
        source:source || 'watchlist_gate_suppressed',
        result:`suppressed: structurally_alive | ${structureGate.refresh_demote_reason}`
      });
      return {changed:false, globalVerdict, deferred:false, suppressed:true};
    }
    const removalVerdictLabel = globalVerdictLabel(globalVerdict.final_verdict || 'avoid');
    const removalReason = globalVerdict.reason || globalVerdict.downgrade_reason || 'Setup is no longer watchlist-eligible.';
    item.watchlist.debug.watchlist_removed_by = 'global_verdict_gate';
    item.watchlist.debug.removal_global_verdict = globalVerdict.final_verdict || '';
    item.watchlist.debug.removal_allow_watchlist = globalVerdict.allow_watchlist ? 'true' : 'false';
    item.watchlist.debug.removal_source = source || 'applyGlobalVerdictGates';
    if(deferWatchlistRemoval){
      appendWatchlistDebugEvent(item, {
        at:new Date().toISOString(),
        source:source || 'watchlist_gate_deferred',
        result:`deferred: ${globalVerdict.final_verdict || 'avoid'} | ${removalReason}`
      });
      return {changed:false, globalVerdict, deferred:true};
    }
    item.watchlist.inWatchlist = false;
    item.watchlist.status = globalVerdict.final_verdict;
    item.watchlist.watchlist_priority_bucket = 'inactive';
    appendWatchlistDebugEvent(item, {
      at:new Date().toISOString(),
      source:'watchlist_gate',
      result:`removed: ${globalVerdict.final_verdict || 'avoid'} | ${removalReason}`
    });
    setStatus('inputStatus', `<span class="warntext">${escapeHtml(item.ticker || 'Ticker')} removed from Watchlist: downgraded to ${escapeHtml(removalVerdictLabel)}${removalReason ? ` | ${escapeHtml(removalReason)}` : ''}</span>`);
    if(activeReviewTicker() === item.ticker){
      setStatus('reviewWorkspaceStatus', `<span class="warntext">${escapeHtml(item.ticker || 'Ticker')} removed from Watchlist: downgraded to ${escapeHtml(removalVerdictLabel)}${removalReason ? ` | ${escapeHtml(removalReason)}` : ''}</span>`);
    }
    changed = true;
  }
  if(item.plan){
    const planSource = String(item.plan.source || '').trim().toLowerCase();
    const scannerEstimatePlan = planSource === 'scanner_estimate';
    const preserveScannerEstimatePlan = scannerEstimatePlan
      && [item.plan.entry, item.plan.stop, item.plan.firstTarget].every(value => Number.isFinite(numericOrNull(value)));
    const scannerEstimateDisplayedPlan = preserveScannerEstimatePlan
      ? deriveCurrentPlanState(item.plan.entry, item.plan.stop, item.plan.firstTarget, item.marketData && item.marketData.currency)
      : null;
    const scannerEstimateAuthority = scannerEstimatePlan
      ? resolveScannerEstimatePlanAuthority(item, globalVerdict, scannerEstimateDisplayedPlan)
      : null;
    const softReadinessOnlyDemotion = !!(
      globalVerdict
      && globalVerdict.contractDiagnostics
      && globalVerdict.contractDiagnostics.softReadinessOnlyDemotion === true
    );
    if(scannerEstimateAuthority){
      item.watchlist.debug.scanner_estimate_authority_mode = scannerEstimateAuthority.mode;
      item.watchlist.debug.scanner_estimate_authority_reason_code = scannerEstimateAuthority.reasonCode || '';
      item.watchlist.debug.scanner_estimate_authority_reason = scannerEstimateAuthority.reason || '';
    }
    const refreshStoredScannerEstimateMath = planState => {
      const safePlanState = planState && typeof planState === 'object' ? planState : null;
      if(!safePlanState) return;
      const nextEntry = numericOrNull(safePlanState.entry);
      const nextStop = numericOrNull(safePlanState.stop);
      const nextFirstTarget = numericOrNull(safePlanState.target ?? safePlanState.firstTarget);
      const nextPlannedRr = numericOrNull(safePlanState.rewardRisk && safePlanState.rewardRisk.rrRatio);
      const nextRiskPerShare = numericOrNull(safePlanState.riskFit && safePlanState.riskFit.risk_per_share);
      const nextPositionSize = numericOrNull(safePlanState.riskFit && safePlanState.riskFit.position_size);
      const nextPositionCost = numericOrNull(safePlanState.capitalFit && safePlanState.capitalFit.position_cost);
      const nextPositionCostGbp = numericOrNull(safePlanState.capitalFit && safePlanState.capitalFit.position_cost_gbp);
      const nextMaxLoss = numericOrNull(safePlanState.riskFit && safePlanState.riskFit.max_loss);
      const nextQuoteCurrency = String(safePlanState.capitalFit && safePlanState.capitalFit.quote_currency || '');
      const nextCapitalFit = String(safePlanState.capitalFit && safePlanState.capitalFit.capital_fit || 'unknown');
      const nextCapitalNote = String(safePlanState.capitalFit && safePlanState.capitalFit.capital_note || '');
      const nextAffordability = String(safePlanState.affordability || '');
      const unchanged = numericOrNull(item.plan.entry) === nextEntry
        && numericOrNull(item.plan.stop) === nextStop
        && numericOrNull(item.plan.firstTarget) === nextFirstTarget
        && numericOrNull(item.plan.plannedRR) === nextPlannedRr
        && numericOrNull(item.plan.riskPerShare) === nextRiskPerShare
        && numericOrNull(item.plan.positionSize) === nextPositionSize
        && numericOrNull(item.plan.positionCost) === nextPositionCost
        && numericOrNull(item.plan.positionCostGbp) === nextPositionCostGbp
        && numericOrNull(item.plan.maxLoss) === nextMaxLoss
        && String(item.plan.quoteCurrency || '') === nextQuoteCurrency
        && String(item.plan.capitalFit || '') === nextCapitalFit
        && String(item.plan.capitalNote || '') === nextCapitalNote
        && String(item.plan.affordability || '') === nextAffordability;
      if(unchanged) return;
      if(typeof applyPlanCandidateToRecord === 'function'){
        applyPlanCandidateToRecord(item, {
          entry:nextEntry,
          stop:nextStop,
          firstTarget:nextFirstTarget
        }, {
          source:'scanner_estimate',
          reason:'scanner_estimate_reference_refresh',
          writtenBy:'applyGlobalVerdictGates',
          updatedAt:new Date().toISOString(),
          lastPlannedAt:String(item.scan && item.scan.updatedAt || item.plan && item.plan.lastPlannedAt || new Date().toISOString())
        });
      }else{
        item.plan = item.plan && typeof item.plan === 'object' ? item.plan : {};
        item.plan.entry = nextEntry;
        item.plan.stop = nextStop;
        item.plan.firstTarget = nextFirstTarget;
      }
      changed = true;
    };
    if(scannerEstimateAuthority && scannerEstimateAuthority.mode === 'recover' && scannerEstimateDisplayedPlan){
      if(item.plan.hasValidPlan !== true){
        item.plan.hasValidPlan = true;
        changed = true;
      }
      if(item.plan.status !== String(scannerEstimateDisplayedPlan.status || '')){
        item.plan.status = String(scannerEstimateDisplayedPlan.status || '');
        changed = true;
      }
      if(item.plan.tradeability !== String(scannerEstimateDisplayedPlan.tradeability || '')){
        item.plan.tradeability = String(scannerEstimateDisplayedPlan.tradeability || '');
        changed = true;
      }
      if(item.plan.riskStatus !== String(scannerEstimateDisplayedPlan.riskFit && scannerEstimateDisplayedPlan.riskFit.risk_status || '')){
        item.plan.riskStatus = String(scannerEstimateDisplayedPlan.riskFit && scannerEstimateDisplayedPlan.riskFit.risk_status || '');
        changed = true;
      }
      refreshStoredScannerEstimateMath(scannerEstimateDisplayedPlan);
      if(scannerEstimateAuthority.stalePlanBlockers && scannerEstimateAuthority.stalePlanBlockers.planValidationState && item.plan.planValidationState){
        item.plan.planValidationState = '';
        changed = true;
      }
      if(scannerEstimateAuthority.stalePlanBlockers && scannerEstimateAuthority.stalePlanBlockers.triggerState && item.plan.triggerState){
        item.plan.triggerState = '';
        changed = true;
      }
      if(scannerEstimateAuthority.stalePlanBlockers && scannerEstimateAuthority.stalePlanBlockers.missedState && item.plan.missedState){
        item.plan.missedState = '';
        changed = true;
      }
      if(scannerEstimateAuthority.stalePlanBlockers && scannerEstimateAuthority.stalePlanBlockers.invalidatedState && item.plan.invalidatedState){
        item.plan.invalidatedState = '';
        changed = true;
      }
      if(item.plan.blockedReason){
        item.plan.blockedReason = '';
        changed = true;
      }
      if(item.plan.blockedReasonCode){
        item.plan.blockedReasonCode = '';
        changed = true;
      }
    }else if(globalVerdict.allow_plan !== true || (scannerEstimateAuthority && scannerEstimateAuthority.mode === 'blocked')){
      const planBlockState = String(globalVerdict.plan_status || globalVerdict.planStatusKey || '').trim().toLowerCase();
      const scannerEstimateSpecificBlock = !!(scannerEstimateAuthority && scannerEstimateAuthority.specificBlock);
      const scannerEstimateSoftBlock = !!(
        scannerEstimatePlan
        && preserveScannerEstimatePlan
        && scannerEstimateDisplayedPlan
        && scannerEstimateDisplayedPlan.status === 'valid'
        && !scannerEstimateSpecificBlock
        && (globalVerdict.allow_plan !== true || globalVerdict.priceability_state === 'unpriceable')
      );
      const scannerEstimateMustDemote = preserveScannerEstimatePlan && (
        (!!String(globalVerdict.unpriceableBlockReason || '').trim() && !scannerEstimateSoftBlock)
        || (globalVerdict.priceability_state === 'unpriceable' && !scannerEstimateSoftBlock)
        || ['invalid','needs_adjustment','unrealistic_rr'].includes(planBlockState)
        || (scannerEstimateDisplayedPlan && scannerEstimateDisplayedPlan.firstTargetTooClose === true)
        || scannerEstimateSpecificBlock
      );
      const hadPlan = !!(item.plan.entry || item.plan.stop || item.plan.firstTarget);
      if(hadPlan && !preserveScannerEstimatePlan && !stampedCanonicalPlanUnaffordable){
        item.plan.entry = '';
        item.plan.stop = '';
        item.plan.firstTarget = '';
        item.plan.hasValidPlan = false;
        item.plan.riskStatus = 'plan_blocked';
        changed = true;
      }else if(stampedCanonicalPlanUnaffordable){
        item.watchlist.debug.planAuthorityPreserved = 'canonical_unaffordable';
        item.watchlist.debug.planAuthorityPreservedReason = 'Stamped canonical plan remains valid but unaffordable.';
      }else if(scannerEstimateMustDemote){
        if(item.plan.hasValidPlan !== false){
          item.plan.hasValidPlan = false;
          changed = true;
        }
        if(item.plan.status !== 'invalid'){
          item.plan.status = 'invalid';
          changed = true;
        }
        if(item.plan.tradeability !== 'invalid'){
          item.plan.tradeability = 'invalid';
          changed = true;
        }
        if(item.plan.riskStatus !== 'plan_blocked'){
          item.plan.riskStatus = 'plan_blocked';
          changed = true;
        }
        if((!scannerEstimateAuthority || !scannerEstimateAuthority.specificBlock) && item.plan.planValidationState !== 'needs_replan'){
          item.plan.planValidationState = 'needs_replan';
          changed = true;
        }
      }else if(scannerEstimateSoftBlock && scannerEstimateDisplayedPlan){
        if(item.plan.hasValidPlan !== true){
          item.plan.hasValidPlan = true;
          changed = true;
        }
        if(item.plan.status !== String(scannerEstimateDisplayedPlan.status || '')){
          item.plan.status = String(scannerEstimateDisplayedPlan.status || '');
          changed = true;
        }
        if(item.plan.tradeability !== String(scannerEstimateDisplayedPlan.tradeability || '')){
          item.plan.tradeability = String(scannerEstimateDisplayedPlan.tradeability || '');
          changed = true;
        }
        const softBlockRiskStatus = String(scannerEstimateDisplayedPlan.riskFit && scannerEstimateDisplayedPlan.riskFit.risk_status || '');
        if(item.plan.riskStatus !== softBlockRiskStatus){
          item.plan.riskStatus = softBlockRiskStatus;
          changed = true;
        }
        refreshStoredScannerEstimateMath(scannerEstimateDisplayedPlan);
      }
      if(scannerEstimatePlan && softReadinessOnlyDemotion && !scannerEstimateSpecificBlock){
        if(item.plan.blockedReasonCode === 'resolver_block'){
          item.plan.blockedReasonCode = '';
          changed = true;
        }
        if(item.plan.blockedReason && /conditions are not strong enough for active focus/i.test(String(item.plan.blockedReason || ''))){
          item.plan.blockedReason = '';
          changed = true;
        }
      }
      const blockedMessage = globalVerdict.reason || globalVerdict.downgrade_reason || 'Blocked';
      const structuredPlanBlockCode = scannerEstimatePlan
        ? (
          softReadinessOnlyDemotion && !scannerEstimateSpecificBlock
            ? ''
            : String(scannerEstimateAuthority && scannerEstimateAuthority.reasonCode || '').trim().toLowerCase()
        )
        : (
          resolveScannerEstimateStructuredAuthorityCode(globalVerdict)
          || (
            (globalVerdict.allow_plan !== true
              || globalVerdict.priceability_state === 'unpriceable'
              || ['invalid','needs_adjustment','unrealistic_rr'].includes(planBlockState))
              ? 'resolver_block'
              : ''
          )
        );
      const existingReasonCode = scannerEstimatePlan
        ? String(item.plan.blockedReasonCode || '').trim().toLowerCase()
        : '';
      const nextReasonCode = scannerEstimatePlan
        ? String(scannerEstimateAuthority && scannerEstimateAuthority.reasonCode || '').trim().toLowerCase()
        : '';
      const preserveSpecificReason = scannerEstimatePlan
        && scannerEstimateAuthority
        && scannerEstimateAuthority.specificBlock
        && scannerEstimateAuthorityReasonPriority(existingReasonCode) >= scannerEstimateAuthorityReasonPriority(nextReasonCode);
      const allowGenericScannerEstimateBlockWrite = !(
        scannerEstimatePlan
        && softReadinessOnlyDemotion
        && !(scannerEstimateAuthority && scannerEstimateAuthority.specificBlock)
        && String(scannerEstimateAuthority && scannerEstimateAuthority.reasonCode || '').trim().toLowerCase() === 'resolver_block'
      );
      if(
        scannerEstimatePlan
        && scannerEstimateAuthority
        && scannerEstimateAuthority.reasonCode
        && !preserveSpecificReason
        && allowGenericScannerEstimateBlockWrite
      ){
        if(item.plan.blockedReason !== scannerEstimateAuthority.reason){
          item.plan.blockedReason = scannerEstimateAuthority.reason;
          changed = true;
        }
        if(item.plan.blockedReasonCode !== scannerEstimateAuthority.reasonCode){
          item.plan.blockedReasonCode = scannerEstimateAuthority.reasonCode;
          changed = true;
        }
      }else if(!scannerEstimatePlan && structuredPlanBlockCode){
        if(item.plan.blockedReasonCode !== structuredPlanBlockCode){
          item.plan.blockedReasonCode = structuredPlanBlockCode;
          changed = true;
        }
        if(blockedMessage && item.plan.blockedReason !== blockedMessage){
          item.plan.blockedReason = blockedMessage;
          changed = true;
        }
      }else if(scannerEstimatePlan && structuredPlanBlockCode && !scannerEstimateAuthority?.specificBlock){
        item.plan.blockedReason = blockedMessage;
        if(item.plan.blockedReasonCode !== structuredPlanBlockCode){
          item.plan.blockedReasonCode = structuredPlanBlockCode;
          changed = true;
        }
        if(item.plan.blockedReason !== blockedMessage){
          item.plan.blockedReason = blockedMessage;
          changed = true;
        }
      }
    }
  }
  return {changed, globalVerdict};
}

